import assert from "node:assert/strict";
import { test } from "vitest";

import {
  assignTerms,
  unassignTerms,
  createTaxonomy,
  createTerm,
  renameTerm,
  deleteTerm,
  deleteTaxonomy,
  TermHasAssignedContentError,
  TermHasChildTermsError,
  TaxonomyHasAssignedContentError,
  TermRecordNotFoundError,
  ContentRecordNotFoundError,
} from "../write-service.js";
import { TaxonomyNotApplicableError, ContentTypeMismatchError } from "../validation-chain.js";
import { ForbiddenError } from "../../core/commands/command.js";

/**
 * @file The taxonomy write-service's ordinary (non-gated) mutations.
 *
 * Assumed seam design (mirrors `core/commands/command.ts`'s established two-object,
 * authorize-then-write-then-revise-then-stamp-then-outbox pattern used elsewhere in this repo):
 *
 * ```ts
 * export interface WriteServiceDeps {
 * authorize: AuthorizeFn; reused AuthorizeFn shape from core/commands/command.ts —
 * these are ORDINARY mutations (per implementation-outline.md's
 * Module Map note "core/gated-mutations imported only for
 * mergeTerm"), so authorize-before-any-side-effect 
 * is the same ForbiddenError/ordering core/commands already
 * provides, not core/gated-mutations' own gateway ceremony.
 * clock: Clock; idGen: IdGenerator;
 * taxonomies: TaxonomyRepoPort; terms: TermRepoPort; entryTerms: EntryTermRepoPort;
 * revisions: TaxonomyRevisionRepoPort;.insert called for every op except assign/unassign
 * stampWatermark: (tx: unknown) => void; core/gated-mutations.stampWatermark, injected
 * outbox: { enqueue: (event: unknown) => Promise<void> };
 * validateHierarchy: typeof import("../validation-chain.js").validateHierarchyAssignment;
 * validateContentJoin: typeof import("../validation-chain.js").validateContentJoin;
 * }
 *
 * export async function createTaxonomy(required: { deps: WriteServiceDeps; principalId: string;
 * name: string; hierarchical: boolean }, optional?: {}): Promise<Taxonomy>;
 *
 * export async function createTerm(required: { deps: WriteServiceDeps; principalId: string;
 * taxonomyId: string; name: string; parentId?: string | null }, optional?: {}): Promise<Term>;
 *
 * export async function renameTerm(required: { deps: WriteServiceDeps; principalId: string;
 * termId: string; newName: string }, optional?: {}): Promise<Term>;
 *
 * export async function assignTerms(required: { deps: WriteServiceDeps; principalId: string;
 * contentType: string; contentId: string; termIds: string[] }, optional?: {}): Promise<void>;
 * ```
 * See docs/decisions/DR-005-ordered-taxonomy-validation.md.
 */

function baseDeps(overrides: Partial<Record<string, unknown>> = {}) {
  const revisionsInserted: unknown[] = [];
  const outboxEvents: unknown[] = [];
  let watermarkStamps = 0;
  return {
    authorize: async () => ({ allowed: true, reason: "matched" }),
    // This fixture checks write outputs; rename-atomicity.test.ts supplies rollback/isolation.
    transaction: async <T>({ fn }: { fn: () => Promise<T> }): Promise<T> => fn(),
    clock: { nowMs: () => Date.parse("2026-07-15T00:00:00.000Z")},
    idGen: (() => {
      let n = 0;
      return { newId: () => `id-${++n}` };
    })(),
    taxonomies: {
      async findById({ id }: { id: string }) {
        return { id, hierarchical: true };
      },
      async insert(row: unknown) {
        return row;
      },
    },
    terms: {
      async findById({ id }: { id: string }) {
        // Default: any `term-*` id resolves against `tax-1` — matches the. See docs/decisions/DR-005-ordered-taxonomy-validation.md.
        // assignTerms fixtures below, which don't override `terms` themselves.
        return id.startsWith("term-") ? { id, taxonomyId: "tax-1" } : null;
      },
      async insert(row: unknown) {
        return row;
      },
      async update(row: unknown) {
        return row;
      },
    },
    entryTerms: {
      async upsert() {
        return undefined;
      },
    },
    // Finding 1 fix (TM-adr041-043-044-045-audit-001) — `assignTerms` now validates via
    // `validateContentJoin`. Default: caller's own workspace, and a resolvable "post"/"post-1"
    // content row matching what the fixtures below assign terms to. See docs/decisions/DR-005-ordered-taxonomy-validation.md.
    workspaceId: "ws-1",
    contentLookup: {
      async resolve({ contentType, contentId }: { contentType: string; contentId: string }) {
        return contentType === "post" && contentId === "post-1" ? { workspaceId: "ws-1", kind: "post" } : null;
      },
    },
    revisions: {
      async insert(row: unknown) {
        revisionsInserted.push(row);
      },
    },
    get revisionsInserted() {
      return revisionsInserted;
    },
    stampWatermark: () => {
      watermarkStamps += 1;
    },
    get watermarkStamps() {
      return watermarkStamps;
    },
    outbox: {
      async enqueue({ event }: { event: unknown }) {
        outboxEvents.push(event);
      },
    },
    get outboxEvents() {
      return outboxEvents;
    },
    ...overrides,
  };
}

// ---------------------------------------------------------------------------
//. See docs/decisions/DR-005-ordered-taxonomy-validation.md.
// ---------------------------------------------------------------------------

test("AC-01: createTaxonomy stores both hierarchical and flat taxonomies in the same shared table (no separate category/tag table)", async () => {
  const deps = baseDeps();
  const category = await createTaxonomy({ deps, principalId: "u-1", name: "Category", hierarchical: true });
  const tag = await createTaxonomy({ deps, principalId: "u-1", name: "Tag", hierarchical: false });

  assert.equal(category.hierarchical, true);
  assert.equal(tag.hierarchical, false);
});

test("AC-13 / EC-04: createTerm rejects a non-null parentId on a flat (tag) taxonomy", async () => {
  const deps = baseDeps({
    taxonomies: { async findById() { return { id: "tax-1", hierarchical: false }; } },
  });

  await assert.rejects(
    createTerm({ deps, principalId: "u-1", taxonomyId: "tax-1", name: "urgent" }, { parentId: "term-x" })
  );
});

test("AC-03: createTerm accepts a valid same-taxonomy parentId on a hierarchical taxonomy", async () => {
  const deps = baseDeps({
    taxonomies: { async findById() { return { id: "tax-1", hierarchical: true }; } },
    terms: {
      async findById({ id }: { id: string }) {
        return id === "term-parent" ? { id: "term-parent", taxonomyId: "tax-1" } : null;
      },
      async insert(row: unknown) {
        return row;
      },
    },
  });

  const term = await createTerm({ deps, principalId: "u-1", taxonomyId: "tax-1", name: "Child" }, { parentId: "term-parent" });
  assert.ok(term);
});

// ---------------------------------------------------------------------------
// — revisioning with composite actor identity. See docs/decisions/DR-005-ordered-taxonomy-validation.md.
// ---------------------------------------------------------------------------

test("AC-15: renameTerm produces exactly one taxonomy_revisions row carrying the pre-rename state", async () => {
  const deps = baseDeps({
    terms: {
      async findById() {
        return { id: "term-1", name: "old-name", taxonomyId: "tax-1" };
      },
      async update(row: unknown) {
        return row;
      },
    },
  });

  await renameTerm({ deps, principalId: "u-1", termId: "term-1", newName: "new-name" });

  assert.equal(deps.revisionsInserted.length, 1);
  const revision = deps.revisionsInserted[0] as { previousState?: { name?: string } };
  assert.equal(revision.previousState?.name, "old-name");
});

// ---------------------------------------------------------------------------
// — assign/unassign never revisioned. See docs/decisions/DR-005-ordered-taxonomy-validation.md.
// ---------------------------------------------------------------------------

test("AC-17 / INV-05: assignTerms produces zero taxonomy_revisions rows", async () => {
  const deps = baseDeps({
    taxonomies: { async findById() { return { id: "tax-1", hierarchical: false, allowList: ["post", "page"] }; } },
  });

  await assignTerms({ deps, principalId: "u-1", contentType: "post", contentId: "post-1", termIds: ["term-1"] });

  assert.equal(deps.revisionsInserted.length, 0, "INV-05: assignTerms must never produce a taxonomy_revisions row");
});

// ---------------------------------------------------------------------------
// — same-transaction watermark + outbox. See docs/decisions/DR-005-ordered-taxonomy-validation.md.
// ---------------------------------------------------------------------------

test("AC-19: renameTerm's commit includes exactly one watermark stamp and one outbox enqueue", async () => {
  const deps = baseDeps({
    terms: {
      async findById() {
        return { id: "term-1", name: "old", taxonomyId: "tax-1" };
      },
      async update(row: unknown) {
        return row;
      },
    },
  });

  await renameTerm({ deps, principalId: "u-1", termId: "term-1", newName: "new" });

  assert.equal(deps.watermarkStamps, 1);
  assert.equal(deps.outboxEvents.length, 1);
});

test("AC-20: assignTerms' commit includes exactly one watermark stamp and one outbox enqueue per call", async () => {
  const deps = baseDeps();
  await assignTerms({ deps, principalId: "u-1", contentType: "post", contentId: "post-1", termIds: ["term-1", "term-2"] });

  assert.equal(deps.watermarkStamps, 1, "one call to assignTerms must stamp the watermark exactly once, not once per termId");
  assert.equal(deps.outboxEvents.length, 1);
});

// ---------------------------------------------------------------------------
// A1 (Job A, taxonomy plan) — per-content-type taxonomy policy for Collection entries.
// `contentTypeTaxonomyPolicy` is optional on `WriteServiceDeps`; `post`/`page` never consult it
// (: posts are unchanged). See docs/decisions/DR-005-ordered-taxonomy-validation.md.
// ---------------------------------------------------------------------------

test("A1: a Collection entry contentType resolves through contentTypeTaxonomyPolicy + contentLookup and assigns normally", async () => {
  let policyCalls = 0;
  const deps = baseDeps({
    contentTypeTaxonomyPolicy: {
      async taxonomiesFor() {
        policyCalls += 1;
        return "all" as const;
      },
    },
    contentLookup: {
      async resolve({ contentType, contentId }: { contentType: string; contentId: string }) {
        return contentType === "recipes" && contentId === "entry-1" ? { workspaceId: "ws-1", kind: "recipes" } : null;
      },
    },
  });

  await assignTerms({ deps, principalId: "u-1", contentType: "recipes", contentId: "entry-1", termIds: ["term-1"] });

  assert.equal(policyCalls, 1);
  assert.equal(deps.watermarkStamps, 1);
  assert.equal(deps.outboxEvents.length, 1);
});

test("A1: a Collection contentType the policy declares not applicable rejects with TaxonomyNotApplicableError, zero writes", async () => {
  const deps = baseDeps({
    contentTypeTaxonomyPolicy: {
      async taxonomiesFor() {
        return null;
      },
    },
    contentLookup: {
      async resolve() {
        throw new Error("must not be called: a not-applicable policy never resolves content");
      },
    },
  });

  await assert.rejects(
    assignTerms({ deps, principalId: "u-1", contentType: "recipes", contentId: "entry-1", termIds: ["term-1"] }),
    (err: unknown) => err instanceof TaxonomyNotApplicableError
  );
  assert.equal(deps.watermarkStamps, 0);
  assert.equal(deps.outboxEvents.length, 0);
});

test("A1: the policy applies but the entry lookup finds nothing rejects with ContentRecordNotFoundError", async () => {
  const deps = baseDeps({
    contentTypeTaxonomyPolicy: {
      async taxonomiesFor() {
        return "all" as const;
      },
    },
    contentLookup: {
      async resolve() {
        return null;
      },
    },
  });

  await assert.rejects(
    assignTerms({ deps, principalId: "u-1", contentType: "recipes", contentId: "entry-1", termIds: ["term-1"] }),
    (err: unknown) => err instanceof ContentRecordNotFoundError
  );
  assert.equal(deps.watermarkStamps, 0);
});

test("A1: an entry whose resolved kind doesn't match the supplied contentType rejects with ContentTypeMismatchError", async () => {
  const deps = baseDeps({
    contentTypeTaxonomyPolicy: {
      async taxonomiesFor() {
        return "all" as const;
      },
    },
    contentLookup: {
      async resolve() {
        return { workspaceId: "ws-1", kind: "books" };
      },
    },
  });

  await assert.rejects(
    assignTerms({ deps, principalId: "u-1", contentType: "recipes", contentId: "entry-1", termIds: ["term-1"] }),
    (err: unknown) => err instanceof ContentTypeMismatchError
  );
  assert.equal(deps.watermarkStamps, 0);
});

test("A1 / AC-08: contentType 'post' never consults contentTypeTaxonomyPolicy — posts are unchanged", async () => {
  let policyCalls = 0;
  const deps = baseDeps({
    contentTypeTaxonomyPolicy: {
      async taxonomiesFor() {
        policyCalls += 1;
        return "all" as const;
      },
    },
  });

  await assignTerms({ deps, principalId: "u-1", contentType: "post", contentId: "post-1", termIds: ["term-1"] });

  assert.equal(policyCalls, 0);
});

// ---------------------------------------------------------------------------
// A2 (Job A, taxonomy plan) — unassignTerms: spec. See docs/decisions/DR-005-ordered-taxonomy-validation.md.
// debt. Shares `validateAssignmentTarget` with assignTerms, so it rejects on the same errors.
// ---------------------------------------------------------------------------

/** Entry-terms double supporting both `upsert` (assignTerms) and `remove` (unassignTerms),
 * exposing `.rows` so a test can assert the row set directly rather than only side-channel counts. */
function removableEntryTermsDeps() {
  const rows: Array<{ contentType: string; contentId: string; termId: string; addedAt: string }> = [];
  return {
    rows,
    async upsert(row: { contentType: string; contentId: string; termId: string; addedAt: string }) {
      const idx = rows.findIndex((r) => r.contentType === row.contentType && r.contentId === row.contentId && r.termId === row.termId);
      if (idx >= 0) rows[idx] = row;
      else rows.push(row);
      return row;
    },
    async remove(row: { contentType: string; contentId: string; termId: string }) {
      const idx = rows.findIndex((r) => r.contentType === row.contentType && r.contentId === row.contentId && r.termId === row.termId);
      if (idx < 0) return 0;
      rows.splice(idx, 1);
      return 1;
    },
  };
}

// `Object.assign(baseDeps(), { entryTerms, ... })` rather than `baseDeps({ entryTerms, ... })` —
// same reason the `deleteTerm`/`deleteTaxonomy` tests above use it: `baseDeps`'s own `overrides`
// param is typed `Partial<Record<string, unknown>>`, which loses `removableEntryTermsDeps()`'s
// `remove` method statically, and `unassignTerms`'s own `deps` type requires it.

