import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { test } from "vitest";

import type { ToolExecutionContext } from "@jini-ai/core";

import { buildMediaRegistrations, type MediaToolDeps } from "../tool-registrations.js";
import { InMemoryAssetBlobRepo, InMemoryAssetRenditionRepo, InMemoryMediaRepo } from "../repo.memory.js";
import { InMemoryBlobStore } from "../blob-store.memory.js";
import { MEDIA_HTML_ATTRIBUTE_ALLOWED_NAMES } from "../html-attributes.js";
import type { MediaRecord } from "../types.js";
import { uploadMedia } from "../media-service.js";

/**
 * Covers `media_upload_asset`'s {@link MediaToolDeps.recordUploadContentType} hook — the fix for the
 * defect where an asset uploaded through this tool never had ANY content type recorded anywhere
 * (`uploadMedia`/`AssetBlobRecord` deliberately carry no such field — see `media-service.ts`'s own
 * file header), unlike `media_generate_asset` and the HTTP admin upload route, both of which record
 * one through a host-owned content-type store. See this file's sibling `resolvePublicUrls` coverage
 * pattern (`buildMediaRegistrations`'s own header) for why this is another OPTIONAL, host-injected
 * hook rather than a hard dependency: a host with no such store must keep compiling and behaving
 * exactly as before (hook omitted -> never called -> `publicUrl`'s own precedent for "omitted stays
 * silent, no throw").
 */

const WORKSPACE_ID = "ws-media-tool-registrations";
const PRINCIPAL_ID = "principal-under-test";
const NOW = "2026-09-02T00:00:00.000Z";

function executionContext(input: Record<string, unknown>): ToolExecutionContext {
  return { executionId: "exec-1", principal: { id: PRINCIPAL_ID }, run: { id: "run-1" }, input, signal: new AbortController().signal };
}

function fakeDeps(
  overrides: Partial<MediaToolDeps> = {}
): { deps: MediaToolDeps; mediaRepo: InMemoryMediaRepo; assetBlobRepo: InMemoryAssetBlobRepo; assetRenditionRepo: InMemoryAssetRenditionRepo } {
  const mediaRepo = new InMemoryMediaRepo({});
  const assetBlobRepo = new InMemoryAssetBlobRepo({});
  const assetRenditionRepo = new InMemoryAssetRenditionRepo({});
  let counter = 0;
  const deps: MediaToolDeps = {
    authorize: async () => ({ allowed: true, reason: "matched" }),
    workspaceId: WORKSPACE_ID,
    clock: { nowMs: () => Date.parse(NOW)},
    idGen: { newId: () => `id-${++counter}` },
    mediaRepo,
    assetBlobRepo,
    assetRenditionRepo,
    blobStore: new InMemoryBlobStore(),
    ...overrides,
  };
  return { deps, mediaRepo, assetBlobRepo, assetRenditionRepo };
}

// A real PNG signature so a future sniff-based assertion has genuine magic bytes to check, not an
// arbitrary string — mirrors `media-generation`'s own `FAKE_PNG_BYTES` convention, but with a real
// leading signature rather than an arbitrary string, since Defect 2's whole point is bytes vs.
// declared-string fidelity.
const PNG_BYTES = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 0xde, 0xad, 0xbe, 0xef]);

test("media_upload_asset calls recordUploadContentType with the uploaded bytes and the saved media row, when the hook is provided", async () => {
  const recorded: Array<{ media: MediaRecord; bytes: Uint8Array }> = [];
  const { deps } = fakeDeps({
    recordUploadContentType: async (params) => {
      recorded.push(params);
    },
  });
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const upload = registrations.find((r) => r.descriptor.id === "media_upload_asset");
  assert.ok(upload, "media_upload_asset must be wired");

  const result = (await upload.handler(
    executionContext({ dataBase64: PNG_BYTES.toString("base64"), filename: "logo.png", contentType: "image/png" })
  )) as { media: { id: string } };

  assert.equal(recorded.length, 1, "the hook must be called exactly once per upload");
  assert.equal(recorded[0]!.media.id, result.media.id, "the hook must receive the SAME media row the tool just saved");
  assert.deepEqual(Buffer.from(recorded[0]!.bytes), PNG_BYTES, "the hook must receive the exact uploaded bytes, not a re-derived or re-encoded copy");
});

test("media_upload_asset without the hook configured behaves exactly as before — no throw, upload still succeeds", async () => {
  const { deps } = fakeDeps(); // no recordUploadContentType at all
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const upload = registrations.find((r) => r.descriptor.id === "media_upload_asset");
  assert.ok(upload);

  const result = (await upload.handler(
    executionContext({ dataBase64: PNG_BYTES.toString("base64"), filename: "logo.png", contentType: "image/png" })
  )) as { media: { id: string } };

  assert.ok(result.media.id, "upload must still succeed when no host has opted into content-type recording");
});

test("a hook that throws propagates — an upload must not be silently reported successful if recording the type fails", async () => {
  const { deps } = fakeDeps({
    recordUploadContentType: async () => {
      throw new Error("content-type store unavailable");
    },
  });
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const upload = registrations.find((r) => r.descriptor.id === "media_upload_asset");
  assert.ok(upload);

  await assert.rejects(
    () => upload.handler(executionContext({ dataBase64: PNG_BYTES.toString("base64"), filename: "logo.png", contentType: "image/png" })),
    /content-type store unavailable/
  );
});

/**
 * Covers `MediaToolDeps.maxUploadBytes` (2026-09-21) — a host-supplied override of
 * `uploadMedia`'s own `DEFAULT_MAX_UPLOAD_BYTES` (10 MiB), forwarded from `media_upload_asset`'s
 * handler as `uploadMedia`'s third (`optional`) argument. Before this fix the handler called
 * `uploadMedia({ deps, input })` with no third argument at all, so every host's assistant upload
 * tool was hard-capped at 10 MiB regardless of what cap the host's own HTTP upload route enforced.
 */
const ELEVEN_MIB = 11 * 1024 * 1024;

test("media_upload_asset accepts a file over the 10 MiB default when the host supplies a higher maxUploadBytes cap", async () => {
  const { deps } = fakeDeps({ maxUploadBytes: 20 * 1024 * 1024 });
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const upload = registrations.find((r) => r.descriptor.id === "media_upload_asset");
  assert.ok(upload, "media_upload_asset must be wired");

  const bigBytes = Buffer.alloc(ELEVEN_MIB, 0xab);
  const result = (await upload.handler(
    executionContext({ dataBase64: bigBytes.toString("base64"), filename: "big.png", contentType: "image/png" })
  )) as { media: { id: string } };

  assert.ok(result.media.id, "an 11 MiB upload must succeed once the host's maxUploadBytes cap is 20 MiB");
});

test("media_upload_asset still rejects a file over 10 MiB when the host supplies no maxUploadBytes cap (today's default, unchanged)", async () => {
  const { deps } = fakeDeps(); // no maxUploadBytes override
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const upload = registrations.find((r) => r.descriptor.id === "media_upload_asset");
  assert.ok(upload);

  const bigBytes = Buffer.alloc(ELEVEN_MIB, 0xab);
  await assert.rejects(
    () => upload.handler(executionContext({ dataBase64: bigBytes.toString("base64"), filename: "big.png", contentType: "image/png" })),
    /exceeds/
  );
});

test("a hook that throws AFTER uploadMedia() commits does not leave the media/rendition/blob rows orphaned", async () => {
  let uploadedMediaId: string | undefined;
  const { deps, mediaRepo, assetBlobRepo, assetRenditionRepo } = fakeDeps({
    recordUploadContentType: async (params) => {
      uploadedMediaId = params.media.id;
      throw new Error("content-type store unavailable");
    },
  });
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const upload = registrations.find((r) => r.descriptor.id === "media_upload_asset");
  assert.ok(upload);

  await assert.rejects(
    () => upload.handler(executionContext({ dataBase64: PNG_BYTES.toString("base64"), filename: "logo.png", contentType: "image/png" })),
    /content-type store unavailable/
  );
  assert.ok(uploadedMediaId, "the hook must have run (and therefore uploadMedia() must have committed) before the throw");

  const sha256 = createHash("sha256").update(PNG_BYTES).digest("hex");

  assert.deepEqual(
    await mediaRepo.list({ workspaceId: WORKSPACE_ID }),
    [],
    "the media row uploadMedia() wrote must be rolled back when the post-upload hook fails"
  );

  assert.deepEqual(
    await assetRenditionRepo.listByAsset({ workspaceId: WORKSPACE_ID, assetId: uploadedMediaId! }),
    [],
    "the rendition row uploadMedia() wrote must be rolled back too"
  );

  const blob = await assetBlobRepo.findByHash({ workspaceId: WORKSPACE_ID, sha256 });
  assert.ok(
    blob === null || blob.status === "tombstoned",
    "the orphaned blob must be removed or tombstoned, never left 'active' with nothing pointing at it"
  );
});

/**
 * Covers `media_update_metadata`'s 2026-09-16 `cssClass`/`htmlAttributes` fields (item 1 — an
 * assistant can set a media asset's presentation, enforced through the same allowlist
 * `html-attributes.ts` gives the render path).
 */
async function seedAsset(deps: MediaToolDeps): Promise<string> {
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const upload = registrations.find((r) => r.descriptor.id === "media_upload_asset");
  assert.ok(upload, "media_upload_asset must be wired");
  const result = (await upload.handler(
    executionContext({ dataBase64: PNG_BYTES.toString("base64"), filename: "logo.png", contentType: "image/png" })
  )) as { media: { id: string } };
  return result.media.id;
}

test("media_update_metadata writes htmlAttributes through the allowlist and returns it on the view", async () => {
  const { deps, mediaRepo } = fakeDeps();
  const mediaId = await seedAsset(deps);
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const update = registrations.find((r) => r.descriptor.id === "media_update_metadata");
  assert.ok(update, "media_update_metadata must be wired");

  const result = (await update.handler(
    executionContext({ mediaId, htmlAttributes: "autoplay muted loop playsinline" })
  )) as { media: { htmlAttributes: string | null } };

  assert.equal(result.media.htmlAttributes, "autoplay muted loop playsinline");
  const row = await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: mediaId });
  assert.equal(row?.htmlAttributes, "autoplay muted loop playsinline");
});

test("media_update_metadata rejects an on* handler and writes nothing", async () => {
  const { deps, mediaRepo } = fakeDeps();
  const mediaId = await seedAsset(deps);
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const update = registrations.find((r) => r.descriptor.id === "media_update_metadata");
  assert.ok(update);
  const before = await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: mediaId });

  await assert.rejects(() => update.handler(executionContext({ mediaId, htmlAttributes: 'onerror="x"' })), (error: unknown) => {
    const message = (error as Error).message;
    assert.match(message, /event handler attributes like 'onerror'/);
    assert.match(message, /"additionalProperties":false/);
    return true;
  });

  const after = await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: mediaId });
  assert.equal(after?.version, before?.version, "a rejected write must leave the row's version unchanged");
});

test("media_update_metadata sets and clears cssClass", async () => {
  const { deps, mediaRepo } = fakeDeps();
  const mediaId = await seedAsset(deps);
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const update = registrations.find((r) => r.descriptor.id === "media_update_metadata");
  assert.ok(update);

  const set = (await update.handler(executionContext({ mediaId, cssClass: "hero wide" }))) as { media: { cssClass: string | null } };
  assert.equal(set.media.cssClass, "hero wide");

  const cleared = (await update.handler(executionContext({ mediaId, cssClass: "" }))) as { media: { cssClass: string | null } };
  assert.equal(cleared.media.cssClass, null);

  const row = await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: mediaId });
  assert.equal(row?.cssClass, null);
});

test("media_update_metadata publishes cssClass and htmlAttributes in its schema, naming every allowlisted attribute", async () => {
  const { deps } = fakeDeps();
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const update = registrations.find((r) => r.descriptor.id === "media_update_metadata");
  assert.ok(update);

  const schema = update.descriptor.inputSchema as { properties: Record<string, { description?: string }> };
  assert.ok(schema.properties.cssClass, "cssClass must be published in the schema");
  assert.ok(schema.properties.htmlAttributes, "htmlAttributes must be published in the schema");
  for (const name of MEDIA_HTML_ATTRIBUTE_ALLOWED_NAMES) {
    assert.ok(schema.properties.htmlAttributes!.description?.includes(name), `htmlAttributes description must name '${name}'`);
  }
});

/**
 * Covers `media_update_metadata`'s 2026-09-16 `slug` field and every media tool view's new `slug`
 * field (owner report: the assistant said "media assets have no slug field at all", which was false
 * — `MediaRecord.slug` shipped 2026-09-07 but no tool view ever returned it).
 */
test("media tool views include the asset slug", async () => {
  const { deps } = fakeDeps();
  const mediaId = await seedAsset(deps);
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const list = registrations.find((r) => r.descriptor.id === "media_list_assets");
  assert.ok(list);

  const result = (await list.handler(executionContext({}))) as { media: Array<{ id: string; slug: string }> };
  const row = result.media.find((m) => m.id === mediaId);
  assert.ok(row, "the seeded asset must appear in the list");
  assert.ok(row!.slug, "every media tool view must carry a non-empty slug");
});

test("media_update_metadata changes the slug", async () => {
  const { deps, mediaRepo } = fakeDeps();
  const mediaId = await seedAsset(deps);
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const update = registrations.find((r) => r.descriptor.id === "media_update_metadata");
  assert.ok(update);

  const result = (await update.handler(executionContext({ mediaId, slug: "sample-commercial-edit" }))) as { media: { slug: string } };
  assert.equal(result.media.slug, "sample-commercial-edit");

  const row = await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: mediaId });
  assert.equal(row?.slug, "sample-commercial-edit");
});

test("media_update_metadata refuses a slug another asset already uses and writes nothing", async () => {
  const { deps, mediaRepo } = fakeDeps();
  const firstId = await seedAsset(deps);
  const secondId = await seedAsset(deps);
  const registrations = buildMediaRegistrations(deps, { resolvePublicUrls: deps.resolvePublicUrls, recordUploadContentType: deps.recordUploadContentType, maxUploadBytes: deps.maxUploadBytes });
  const update = registrations.find((r) => r.descriptor.id === "media_update_metadata");
  assert.ok(update);

  await update.handler(executionContext({ mediaId: firstId, slug: "taken-slug" }));
  const before = await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: secondId });

  await assert.rejects(
    () => update.handler(executionContext({ mediaId: secondId, slug: "taken-slug" })),
    /taken-slug.*already used/
  );

  const after = await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: secondId });
  assert.equal(after?.version, before?.version, "a refused slug conflict must leave the row's version unchanged");
});

function tool(deps: MediaToolDeps, id: string, optional: Parameters<typeof buildMediaRegistrations>[1] = {}) {
  const found = buildMediaRegistrations(deps, optional).find((r) => r.descriptor.id === id);
  assert.ok(found, `${id} must be wired`);
  return found;
}

async function seedDocument(deps: MediaToolDeps, filename: string, body: string): Promise<MediaRecord> {
  const { media } = await uploadMedia({
    deps: { clock: deps.clock, idGen: deps.idGen, mediaRepo: deps.mediaRepo, blobRepo: deps.assetBlobRepo, renditionRepo: deps.assetRenditionRepo, blobStore: deps.blobStore },
    input: { workspaceId: WORKSPACE_ID, kind: "document", filename, contentType: "application/octet-stream", bytes: Buffer.from(body), createdByPrincipal: "uploader" },
  });
  return media;
}

test("library_list lists only active documents, with display filename, content type and stored byte size", async () => {
  const { deps } = fakeDeps();
  const guide = await seedDocument(deps, "guide.md", "# Guide\n");
  const trashed = await seedDocument(deps, "old.txt", "old");
  await tool(deps, "media_trash_asset").handler(executionContext({ mediaId: trashed.id }));
  await seedAsset(deps);
  const result = await tool(deps, "library_list").handler(executionContext({}));
  assert.deepEqual(result, { documents: [{
    id: guide.id, title: "guide", filename: "guide.md", originalFilename: "guide.md", contentType: "text/markdown",
    byteSize: 8, createdAt: NOW, createdBy: "uploader", publicUrl: null,
  }] });
});

test("library_list reports an unknown byte size when the blob row is gone or the store cannot size blobs", async () => {
  const { deps, assetBlobRepo } = fakeDeps();
  const kept = await seedDocument(deps, "kept.md", "kept");
  const orphan = await seedDocument(deps, "orphan.md", "orphan");
  await assetBlobRepo.remove({ workspaceId: WORKSPACE_ID, sha256: orphan.source.sha256 });
  const sizes = (result: unknown) => (result as { documents: Array<{ id: string; byteSize: number | null }> }).documents.map((d) => [d.id, d.byteSize]);
  assert.deepEqual(sizes(await tool(deps, "library_list").handler(executionContext({}))), [[kept.id, 4], [orphan.id, null]]);
  const store = new InMemoryBlobStore();
  const unsized = { put: store.put.bind(store), putIfAbsent: store.putIfAbsent.bind(store), get: store.get.bind(store), exists: store.exists.bind(store), remove: store.remove.bind(store) };
  assert.deepEqual(sizes(await tool({ ...deps, blobStore: unsized }, "library_list").handler(executionContext({}))), [[kept.id, null], [orphan.id, null]]);
});

test("library_read returns a document's untrusted text, and a bad offset or unknown id is rejected with the tool schema attached", async () => {
  const { deps } = fakeDeps();
  const guide = await seedDocument(deps, "guide.md", "# Guide\n");
  const read = tool(deps, "library_read");
  const result = await read.handler(executionContext({ documentId: guide.id })) as { text: string; untrusted: boolean };
  assert.equal(result.text, "# Guide\n");
  assert.equal(result.untrusted, true);
  await assert.rejects(read.handler(executionContext({ documentId: guide.id, offset: "2" })), /offset must be a non-negative byte offset[\s\S]*Schema for 'library_read'/);
  await assert.rejects(read.handler(executionContext({ documentId: "missing" })), /document was not found[\s\S]*Schema for 'library_read'/);
});

test("media_trash_asset soft-deletes the asset and returns its trashed view", async () => {
  const { deps, mediaRepo } = fakeDeps();
  const mediaId = await seedAsset(deps);
  const result = await tool(deps, "media_trash_asset").handler(executionContext({ mediaId })) as { media: { id: string; status: string } };
  assert.equal(result.media.id, mediaId);
  assert.equal(result.media.status, "trashed");
  assert.equal((await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: mediaId }))?.status, "trashed");
});

test("media_upload_asset and media_update_metadata carry string text fields through; an update ignores non-string ones", async () => {
  const { deps, mediaRepo } = fakeDeps();
  const uploaded = await tool(deps, "media_upload_asset").handler(executionContext({
    dataBase64: PNG_BYTES.toString("base64"), filename: "logo.png", contentType: "image/png", alt: " Logo ", caption: "Cap", credit: "Me",
  })) as { media: { id: string; alt: string; caption: string; credit: string } };
  assert.deepEqual([uploaded.media.alt, uploaded.media.caption, uploaded.media.credit], ["Logo", "Cap", "Me"]);
  const updated = await tool(deps, "media_update_metadata").handler(executionContext({
    mediaId: uploaded.media.id, title: "Brand", alt: "Alt", caption: "New caption", credit: "Studio",
  })) as { media: { title: string; alt: string; caption: string; credit: string } };
  assert.deepEqual([updated.media.title, updated.media.alt, updated.media.caption, updated.media.credit], ["Brand", "Alt", "New caption", "Studio"]);
  const ignored = await tool(deps, "media_update_metadata").handler(executionContext({ mediaId: uploaded.media.id, title: 1, alt: null })) as { media: { title: string; alt: string } };
  assert.deepEqual([ignored.media.title, ignored.media.alt], ["Brand", "Alt"]);
  assert.equal((await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: uploaded.media.id }))?.credit, "Studio");
});

test("media views resolve publicUrl through the host's batch resolver and show unknown attribution as null", async () => {
  const { deps, mediaRepo } = fakeDeps();
  const mediaId = await seedAsset(deps);
  const seeded = await mediaRepo.findById({ workspaceId: WORKSPACE_ID, id: mediaId });
  const { createdBy: _createdBy, ...legacy } = seeded!;
  await mediaRepo.remove({ workspaceId: WORKSPACE_ID, id: mediaId });
  await mediaRepo.save(legacy);
  const batches: string[][] = [];
  const resolvePublicUrls = async ({ assets }: { assets: readonly MediaRecord[] }) => {
    batches.push(assets.map((asset) => asset.id));
    return new Map([[mediaId, `https://cdn.example/${mediaId}.png`]]);
  };
  const result = await tool(deps, "media_list_assets", { resolvePublicUrls }).handler(executionContext({})) as { media: Array<{ id: string; createdBy: string | null; publicUrl: string | null }> };
  assert.deepEqual(batches, [[mediaId]]);
  assert.deepEqual(result.media.map(({ id, createdBy, publicUrl }) => ({ id, createdBy, publicUrl })), [{ id: mediaId, createdBy: null, publicUrl: `https://cdn.example/${mediaId}.png` }]);
});

test("library_list shows unknown attribution as null and refuses to guess a type for a document row with no original filename", async () => {
  const { deps, mediaRepo } = fakeDeps();
  const guide = await seedDocument(deps, "guide.md", "# Guide\n");
  const { createdBy: _createdBy, ...unattributed } = guide;
  // Kind, filename and creator are preserved on save, so these legacy rows are seeded directly.
  const legacy = new InMemoryMediaRepo({}, { initialRows: [unattributed] });
  const listed = await tool({ ...deps, mediaRepo: legacy }, "library_list").handler(executionContext({})) as { documents: Array<{ createdBy: string | null }> };
  assert.deepEqual(listed.documents.map((d) => d.createdBy), [null]);
  const { originalFilename: _name, ...nameless } = guide;
  const broken = new InMemoryMediaRepo({}, { initialRows: [nameless] });
  await assert.rejects(tool({ ...deps, mediaRepo: broken }, "library_list").handler(executionContext({})), /document filename must be a plain filename/);
  assert.equal((await mediaRepo.list({ workspaceId: WORKSPACE_ID })).length, 1);
});

src/redirects/__tests__/redirects.reserv.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { InMemoryOutbox } from "./support/events.fixture.js";
import { createVerifiedOrigin, InMemoryOriginSettingRepo, OriginRegistry } from "@jini-ai/http-kit/verified-origin";
import { redirectMatcher } from "../matcher.js";
import type { RedirectDbHandle } from "../ports.internal.js";
import { InMemoryRedirectRepo } from "../repo.memory.js";
import { createRedirect, tombstoneRedirect, updateRedirect, type RedirectsWriteDeps } from "../redirects.js";
import { RedirectTargetNotAllowedError, RedirectValidationError } from "../types.js";
import type { RedirectRecord } from "../types.js";
import { isNeverInTrash, removeVia, restoreVia } from "./remove-redirect-double.js";

/**
 * @file The site-relative half of the write-path target gate (REQ-08's own
 * threat, applied to targets that never reach the origin allowlist because
 * they carry no authority).
 *
 * `assertTargetAllowed` consults `OriginRegistryPort.isAllowedRedirectTarget`
 * only for absolute/protocol-relative targets — a site-relative target has no
 * host to check, so the oracle has nothing to say about it. That leaves the
 * admin application's own URL space (`/admin`, `/api/...` — the SAME Express
 * app serves them, see `admin-static.ts`'s `app.use("/admin", ...)` and
 * `core.ts`'s `app.use("/api/admin", ...)`) reachable as a redirect
 * destination from a public-site rule, including through an agent-callable
 * `redirects_create`. These tests pin the refusal, its decode-then-compare
 * order, and — just as load-bearing — that a path which merely STARTS with
 * the same letters stays allowed.
 */

const WORKSPACE_ID = "workspace-1";
const ACTOR_ID = "user-1";

function makeDeps(opts: { redirectAllowlist?: string[] } = {}): RedirectsWriteDeps {
  const repo = new InMemoryRedirectRepo();
  const originRepo = new InMemoryOriginSettingRepo({ seeds: [
    {
      workspaceId: WORKSPACE_ID,
      origin: createVerifiedOrigin({
        scheme: "https",
        host: "trusted.example",
        verifiedAt: "2026-07-13T00:00:00.000Z",
        source: "workspace-setting",
      }),
      redirectAllowlist: opts.redirectAllowlist ?? [],
    },
  ] });
  let clockTick = 0;
  let idTick = 0;
  return { reservedSegments: new Set(["admin", "api"]),
    repo,
    remove: removeVia(repo as unknown as Parameters<typeof removeVia>[0]),
    isInTrash: isNeverInTrash,
    restore: restoreVia(repo as unknown as Parameters<typeof removeVia>[0]),
    db: repo as unknown as RedirectDbHandle,
    transaction: async (fn) => fn(),
    matcher: redirectMatcher,
    originRegistry: new OriginRegistry({ repo: originRepo }),
    clock: { nowMs: () => Date.parse(`2026-07-13T00:00:${String(clockTick++).padStart(2, "0")}.000Z`) },
    idGen: { newId: () => `redirect-${++idTick}` },
    outbox: new InMemoryOutbox(),
  };
}

function create(deps: RedirectsWriteDeps, fromPattern: string, toTarget: string) {
  return createRedirect({
    deps,
    input: { workspaceId: WORKSPACE_ID, matchType: "exact", fromPattern, toTarget, statusCode: 301, actorId: ACTOR_ID },
  });
}

/**
 * Every spelling that reaches the admin application's own URL space. Each row is a distinct
 * evasion, not a restatement: raw, percent-encoded, case-shifted, dot-segmented, and separator-
 * disguised forms all normalize to `/admin` or `/api/...` in a browser following the `Location`.
 */
const RESERVED_TARGETS: readonly { readonly target: string; readonly why: string }[] = [
  { target: "/admin", why: "the bare admin SPA root" },
  { target: "/admin/settings", why: "a screen inside the admin SPA" },
  { target: "/%61dmin", why: "percent-encoded 'a' — a raw-prefix denylist never sees it" },
  { target: "/%61dmin/settings", why: "percent-encoded 'a' with a deeper path" },
  { target: "/ADMIN", why: "upper case — URL paths are compared case-sensitively by servers" },
  { target: "/AdMiN/settings", why: "mixed case" },
  { target: "/api/admin/v1/workspaces/workspace-1/settings", why: "the session-gated admin API" },
  { target: "/API/admin/v1/auth/me", why: "upper-cased API surface" },
  { target: "/%61pi/admin/v1/auth/me", why: "percent-encoded API surface" },
  { target: "/blog/../admin", why: "a dot segment the browser resolves away before requesting" },
  { target: "/blog/%2e%2e/admin", why: "an encoded dot segment" },
];

for (const { target, why } of RESERVED_TARGETS) {
  test(`createRedirect refuses the reserved target '${target}' (${why})`, async () => {
    const deps = makeDeps();
    await assert.rejects(() => create(deps, "/old", target), (err: unknown) => {
      assert.ok(err instanceof RedirectTargetNotAllowedError, `expected RedirectTargetNotAllowedError, got ${String(err)}`);
      assert.match(err.message, /is not an allowed redirect destination/);
      return true;
    });
  });
}

/**
 * The negative case that makes the rule worth having rather than a blunt prefix ban: a public
 * page whose slug merely begins with the same letters is ordinary site content.
 */
const ALLOWED_TARGETS: readonly string[] = [
  "/administer-survey",
  "/administration",
  "/apiary",
  "/api-docs",
  "/blog/admin-interview",
  "/admins-are-people-too",
];

for (const target of ALLOWED_TARGETS) {
  test(`createRedirect still allows the ordinary site path '${target}'`, async () => {
    const deps = makeDeps();
    const { record } = await create(deps, "/old", target);
    assert.equal(record.toTarget, target);
  });
}

test("updateRedirect refuses a reserved target on an already-live rule", async () => {
  const deps = makeDeps();
  const { record } = await create(deps, "/old", "/new");
  await assert.rejects(
    () =>
      updateRedirect({
        deps,
        input: { workspaceId: WORKSPACE_ID, id: record.id, toTarget: "/admin/settings", actorId: ACTOR_ID },
      }),
    RedirectTargetNotAllowedError
  );
});

test("createRedirect refuses a one-hop chain that COLLAPSES onto a reserved target", async () => {
  const deps = makeDeps();
  // Planted straight into the repo, deliberately bypassing the chokepoint: this is the row a
  // workspace that predates this guard already carries. The collapse re-check (redirects.ts) is
  // what must catch it, not the first-pass check on the caller's own literal target.
  const planted: RedirectRecord = {
    id: "planted-1",
    workspaceId: WORKSPACE_ID,
    matchType: "exact",
    fromPattern: "/hop",
    toTarget: "/admin/settings",
    statusCode: 301,
    status: "active",
    override: false,
    priority: 0,
    source: "manual",
    createdByPrincipal: ACTOR_ID,
    createdAt: "2026-07-12T00:00:00.000Z",
    updatedAt: "2026-07-12T00:00:00.000Z",
    version: 1,
  };
  (deps.repo as InMemoryRedirectRepo).insertRedirect(planted);

  await assert.rejects(() => create(deps, "/old", "/hop"), RedirectTargetNotAllowedError);
});

test("createRedirect refuses a backslash-disguised protocol-relative target", async () => {
  // `/\evil.example` starts with a single '/', so the absolute/protocol-relative branch never
  // fires — but a URL parser treats '\' as '/', making this `//evil.example`. The origin
  // allowlist is the gate this was walking around. Asserting the exact message (not just the
  // error class) proves the OFF-ORIGIN reason wins here — the more specific `checkSiteRelativeTarget`
  // verdict, checked before B2's raw-character rule, keeps its own wording (t91 B2, 2026-09-16).
  const deps = makeDeps();
  await assert.rejects(() => create(deps, "/old", "/\\evil.example"), (err: unknown) => {
    assert.ok(err instanceof RedirectTargetNotAllowedError, `expected RedirectTargetNotAllowedError, got ${String(err)}`);
    assert.equal(
      err.message,
      "toTarget '/\\evil.example' is not an allowed redirect destination: it looks site-relative but resolves to a different host (a URL parser reads '\\' as '/')"
    );
    return true;
  });
});

test("tombstoneRedirect can still turn OFF a legacy rule whose target is now refused", async () => {
  // The escape hatch this guard must leave open: a workspace that predates it can be carrying a
  // rule pointing at /admin, and `updateRedirect` re-validates the EXISTING target on every field
  // change — so if tombstoning went through the same gate, the one operation that neutralizes the
  // bad rule would be the one operation the gate blocked.
  const deps = makeDeps();
  const planted: RedirectRecord = {
    id: "planted-2",
    workspaceId: WORKSPACE_ID,
    matchType: "exact",
    fromPattern: "/legacy",
    toTarget: "/admin/settings",
    statusCode: 301,
    status: "active",
    override: false,
    priority: 0,
    source: "manual",
    createdByPrincipal: ACTOR_ID,
    createdAt: "2026-07-12T00:00:00.000Z",
    updatedAt: "2026-07-12T00:00:00.000Z",
    version: 1,
  };
  (deps.repo as InMemoryRedirectRepo).insertRedirect(planted);

  const { record } = await tombstoneRedirect({
    deps,
    input: { workspaceId: WORKSPACE_ID, id: "planted-2", actorId: ACTOR_ID },
  });
  assert.equal(record.status, "disabled");
});

test("updateRedirect can still REPOINT a legacy rule away from a refused target", async () => {
  const deps = makeDeps();
  const planted: RedirectRecord = {
    id: "planted-3",
    workspaceId: WORKSPACE_ID,
    matchType: "exact",
    fromPattern: "/legacy-2",
    toTarget: "/admin/settings",
    statusCode: 301,
    status: "active",
    override: false,
    priority: 0,
    source: "manual",
    createdByPrincipal: ACTOR_ID,
    createdAt: "2026-07-12T00:00:00.000Z",
    updatedAt: "2026-07-12T00:00:00.000Z",
    version: 1,
  };
  (deps.repo as InMemoryRedirectRepo).insertRedirect(planted);

  const { record } = await updateRedirect({
    deps,
    input: { workspaceId: WORKSPACE_ID, id: "planted-3", toTarget: "/somewhere-safe", actorId: ACTOR_ID },
  });
  assert.equal(record.toTarget, "/somewhere-safe");
});

/**
 * t91 review F2 (coordinator ruling, 2026-09-16): the admin Redirects screen's on/off toggle is a
 * PATCH of `status` alone, and `updateRedirect` used to re-validate the stored target on every
 * update — so a legacy rule whose target the gate now refuses could not even be switched OFF from
 * that screen. Turning off a rule that cannot fire only reduces risk, so an update that changes
 * nothing but `status -> disabled` skips the checks. Anything else (turning a rule ON, or changing
 * any other field in the same update) still runs every check.
 */
const LEGACY_REFUSED_TARGETS: readonly { readonly target: string; readonly why: string }[] = [
  { target: "/admin/settings", why: "a reserved site-relative target" },
  { target: "/a b", why: "raw whitespace the redirect origin check refuses" },
  { target: "/\\evil.example", why: "a backslash-disguised protocol-relative target" },
  { target: "https://trusted.example/admin", why: "an absolute same-origin reserved target" },
  { target: "back", why: "Express's Referer alias" },
];

function plantLegacyRule(deps: RedirectsWriteDeps, id: string, overrides: Partial<RedirectRecord>): RedirectRecord {
  const planted: RedirectRecord = {
    id,
    workspaceId: WORKSPACE_ID,
    matchType: "exact",
    fromPattern: `/${id}`,
    toTarget: "/admin/settings",
    statusCode: 301,
    status: "active",
    override: false,
    priority: 0,
    source: "manual",
    createdByPrincipal: ACTOR_ID,
    createdAt: "2026-07-12T00:00:00.000Z",
    updatedAt: "2026-07-12T00:00:00.000Z",
    version: 1,
    ...overrides,
  };
  (deps.repo as InMemoryRedirectRepo).insertRedirect(planted);
  return planted;
}

for (const { target, why } of LEGACY_REFUSED_TARGETS) {
  test(`updateRedirect can switch OFF a legacy rule whose target is now refused: ${JSON.stringify(target)} (${why})`, async () => {
    const deps = makeDeps();
    const planted = plantLegacyRule(deps, "legacy-off", { toTarget: target });

    const { record } = await updateRedirect({
      deps,
      input: { workspaceId: WORKSPACE_ID, id: planted.id, status: "disabled", actorId: ACTOR_ID },
    });

    assert.deepEqual(record, { ...planted, status: "disabled", updatedAt: record.updatedAt, version: 2 });
    assert.equal((await deps.repo.findById({ workspaceId: WORKSPACE_ID, id: planted.id }))?.status, "disabled");
  });
}

test("updateRedirect switch-OFF also passes when the PATCH repeats every other field unchanged", async () => {
  const deps = makeDeps();
  const planted = plantLegacyRule(deps, "legacy-full-patch", { toTarget: "/admin/settings" });
  const { matchType, fromPattern, toTarget, statusCode, override, priority } = planted;

  const { record } = await updateRedirect({
    deps,
    input: {
      workspaceId: WORKSPACE_ID,
      id: planted.id,
      matchType,
      fromPattern,
      toTarget,
      statusCode,
      override,
      priority,
      status: "disabled",
      actorId: ACTOR_ID,
    },
  });

  assert.equal(record.status, "disabled");
  assert.equal(record.toTarget, "/admin/settings");
});

/** Each update below either turns the legacy rule ON or changes a field besides `status`, so the
 *  refused target must still be refused. */
const STILL_CHECKED_UPDATES: readonly { readonly name: string; readonly plantedStatus: "active" | "disabled"; readonly patch: object }[] = [
  { name: "turning a disabled rule back ON", plantedStatus: "disabled", patch: { status: "active" } },
  { name: "setting status active on an active rule", plantedStatus: "active", patch: { status: "active" } },
  { name: "a priority-only change", plantedStatus: "active", patch: { priority: 5 } },
  { name: "disabling while changing priority", plantedStatus: "active", patch: { status: "disabled", priority: 5 } },
  { name: "disabling while changing statusCode", plantedStatus: "active", patch: { status: "disabled", statusCode: 302 } },
  { name: "disabling while changing override", plantedStatus: "active", patch: { status: "disabled", override: true } },
  { name: "disabling while changing fromPattern", plantedStatus: "active", patch: { status: "disabled", fromPattern: "/moved" } },
  { name: "disabling while changing matchType", plantedStatus: "active", patch: { status: "disabled", matchType: "prefix" } },
  {
    name: "disabling while changing the target to another refused one",
    plantedStatus: "active",
    patch: { status: "disabled", toTarget: "/api/admin/v1/auth/me" },
  },
];

for (const { name, plantedStatus, patch } of STILL_CHECKED_UPDATES) {
  test(`updateRedirect still refuses a legacy rule's refused target on ${name}`, async () => {
    const deps = makeDeps();
    const planted = plantLegacyRule(deps, "legacy-checked", { status: plantedStatus });

    await assert.rejects(
      updateRedirect({
        deps,
        input: { workspaceId: WORKSPACE_ID, id: planted.id, actorId: ACTOR_ID, ...patch },
      }),
      RedirectTargetNotAllowedError
    );
    assert.deepEqual(await deps.repo.findById({ workspaceId: WORKSPACE_ID, id: planted.id }), planted);
  });
}

/**
 * t91 B1 (2026-09-16): an ABSOLUTE same-origin target used to skip the reserved-path rule
 * entirely on write — `assertTargetAllowed` sent it only to the origin allowlist, which answers
 * "is that HOST allowed" and the workspace's own host trivially is. These four all resolve to the
 * workspace's own `/admin` or `/api` surface (a plain same-origin target, and three spellings the
 * read-path gate already refused via `checkSameOriginDestination` — see
 * `phase-handler.read-path-target.test.ts`), so a legacy rule using any of them was previously
 * stored and simply never fired. The write gate now applies the same rule so it is refused before
 * it is ever stored.
 */
const ABSOLUTE_SAME_ORIGIN_RESERVED: readonly { readonly target: string; readonly surface: string }[] = [
  { target: "https://trusted.example./admin", surface: "/admin" },
  { target: "https://trusted.example%2E/admin", surface: "/admin" },
  { target: "https://trusted.example./api/admin/v1/workspaces", surface: "/api" },
  { target: "https://trusted.example/admin", surface: "/admin" },
];

for (const { target, surface } of ABSOLUTE_SAME_ORIGIN_RESERVED) {
  test(`createRedirect refuses the absolute same-origin target '${target}'`, async () => {
    const deps = makeDeps();
    const expectedMessage = `toTarget '${target}' is not an allowed redirect destination: it resolves to '${surface}', which serves the authenticated admin application rather than this site's public pages`;
    await assert.rejects(() => create(deps, "/old", target), (err: unknown) => {
      assert.ok(err instanceof RedirectTargetNotAllowedError, `expected RedirectTargetNotAllowedError, got ${String(err)}`);
      assert.equal(err.message, expectedMessage);
      return true;
    });
  });
}

test("updateRedirect refuses an absolute same-origin reserved target on a live rule", async () => {
  const deps = makeDeps();
  const { record } = await create(deps, "/old", "/new");
  await assert.rejects(
    () =>
      updateRedirect({
        deps,
        input: { workspaceId: WORKSPACE_ID, id: record.id, toTarget: "https://trusted.example./admin", actorId: ACTOR_ID },
      }),
    RedirectTargetNotAllowedError
  );
});

test("createRedirect still allows a same-origin absolute target to ordinary content", async () => {
  const deps = makeDeps();
  for (const target of ["https://trusted.example/blog/post", "https://trusted.example./blog/post"]) {
    const { record } = await create(deps, `/old-${target}`, target);
    assert.equal(record.toTarget, target);
  }
});

test("createRedirect still allows an allowlisted cross-origin host's own /admin", async () => {
  const deps = makeDeps({ redirectAllowlist: ["partner.example"] });
  const { record } = await create(deps, "/old", "https://partner.example/admin");
  assert.equal(record.toTarget, "https://partner.example/admin");
});

/**
 * t91 B2 (2026-09-16): the write gate never checked a site-relative target for a raw backslash or
 * whitespace. `checkSiteRelativeTarget` resolves `\` as `/` (a URL parser reads it that way, and on
 * THIS site `\` really does resolve to `/`, so its own `ok` verdict is truthful), so these all
 * passed the write gate and were stored. On read, `phase-handler.ts`'s `toOracleCandidate` builds
 * the oracle candidate by CONCATENATING a relative location onto the canonical origin string, and
 * the oracle's own `FORBIDDEN_RAW_CHARS` (`features/origin/origin.ts`) refuses any raw backslash or
 * whitespace — so the read gate always refused these, and a stored rule using any of them could
 * never fire. The write gate now applies the oracle's own raw-character predicate
 * (`hasForbiddenRawUrlCharacter`) after `checkSiteRelativeTarget`, so write and read agree.
 */
const RAW_CHARACTER_TARGETS: readonly { readonly target: string; readonly why: string }[] = [
  { target: "\\", why: "the prefix-rule case: '\\' plus a request tail becomes '\\/evil.example'" },
  { target: "\\new", why: "a single leading backslash" },
  { target: "/a\\b", why: "a mid-path backslash" },
  { target: "/a b", why: "a raw space" },
  { target: "/a b", why: "a non-breaking space (JS \\s, not a C0/C1 control)" },
];

for (const { target, why } of RAW_CHARACTER_TARGETS) {
  test(`createRedirect refuses the raw-character target ${JSON.stringify(target)} (${why})`, async () => {
    const deps = makeDeps();
    const expectedMessage = `toTarget '${target}' is not an allowed redirect destination: it contains a backslash or whitespace, which the redirect origin check refuses (write a space as '%20')`;
    await assert.rejects(() => create(deps, "/old", target), (err: unknown) => {
      assert.ok(err instanceof RedirectTargetNotAllowedError, `expected RedirectTargetNotAllowedError, got ${String(err)}`);
      assert.equal(err.message, expectedMessage);
      return true;
    });
  });
}

test("createRedirect refuses a PREFIX rule whose target is a bare backslash (the reviewer's exact case)", async () => {
  const deps = makeDeps();
  await assert.rejects(
    () =>
      createRedirect({
        deps,
        input: {
          workspaceId: WORKSPACE_ID,
          matchType: "prefix",
          fromPattern: "/go",
          toTarget: "\\",
          statusCode: 301,
          actorId: ACTOR_ID,
        },
      }),
    RedirectTargetNotAllowedError
  );
});

test("createRedirect still allows a percent-encoded space", async () => {
  const deps = makeDeps();
  const { record } = await create(deps, "/old", "/a%20b");
  assert.equal(record.toTarget, "/a%20b");
});

/**
 * Express 4's `res.location()` (called by the `res.redirect()` that serves every matched rule)
 * replaces the exact string `back` with the request's `Referer` header. So a stored `back` is not a
 * site-relative path at all: it is "wherever the page that linked here was", an open redirect the
 * origin oracle never sees (t91 review F1, 2026-09-16).
 */
const REFERRER_ALIAS_MESSAGE =
  "toTarget 'back' is not an allowed redirect destination: it is 'back', which the server replaces with the visitor's Referer header (a redirect to whatever page linked here)";

test("createRedirect refuses the target 'back' (Express's Referer alias)", async () => {
  const deps = makeDeps();
  await assert.rejects(() => create(deps, "/old", "back"), (err: unknown) => {
    assert.ok(err instanceof RedirectTargetNotAllowedError, `expected RedirectTargetNotAllowedError, got ${String(err)}`);
    assert.equal(err.message, REFERRER_ALIAS_MESSAGE);
    return true;
  });
});

test("createRedirect refuses a PREFIX rule whose target is 'back' (a request for the bare prefix serves it as-is)", async () => {
  const deps = makeDeps();
  await assert.rejects(
    () =>
      createRedirect({
        deps,
        input: { workspaceId: WORKSPACE_ID, matchType: "prefix", fromPattern: "/go", toTarget: "back", statusCode: 301, actorId: ACTOR_ID },
      }),
    (err: unknown) => err instanceof RedirectTargetNotAllowedError && err.message === REFERRER_ALIAS_MESSAGE
  );
});

test("createRedirect still allows targets that only resemble the Referer alias", async () => {
  // Express compares with `===`: `/back`, `backup` and `BACK` are sent exactly as written.
  for (const target of ["/back", "backup", "BACK"]) {
    const deps = makeDeps();
    const { record } = await create(deps, "/old", target);
    assert.equal(record.toTarget, target);
  }
});

for (const [fromPattern, surface] of [["/admin", "admin"], ["/%61dmin", "admin"], ["/API/x", "api"], ["/admin/*", "admin"]] as const) {
  for (const matchType of ["exact", "prefix", "wildcard"] as const) {
    test(`${matchType}: reserved redirect source ${fromPattern} is refused on create and update`, async () => {
      const deps = makeDeps();
      const expected = (error: unknown) => {
        assert.ok(error instanceof RedirectValidationError);
        assert.equal(error.message, `fromPattern '${fromPattern}' is reserved for the '${surface}' surface`);
        return true;
      };
      await assert.rejects(createRedirect({ deps, input: { workspaceId: WORKSPACE_ID, actorId: ACTOR_ID, matchType, fromPattern, toTarget: "/new", statusCode: 301 } }), expected);
      assert.equal(await deps.repo.findByFromPattern({ workspaceId: WORKSPACE_ID, fromPattern }), null);
      const { record } = await create(deps, "/safe-source", "/new");
      await assert.rejects(updateRedirect({ deps, input: { workspaceId: WORKSPACE_ID, actorId: ACTOR_ID, id: record.id, matchType, fromPattern } }), expected);
      assert.deepEqual(await deps.repo.findById({ workspaceId: WORKSPACE_ID, id: record.id }), record);
    });
  }
}

test("redirect sources sharing only the reserved prefix or a deeper segment remain available", async () => {
  const deps = makeDeps();
  for (const fromPattern of ["/apiary", "/administration", "/public/admin", "/"]) {
    const { record } = await create(deps, fromPattern, "/new");
    assert.equal(record.fromPattern, fromPattern);
  }
});

