type LegacyCreate = Omit<CreateFormDefinitionRequired, "input"> & { input: CreateFormDefinitionRequired["input"] & { notify?: NotifyConfig; idempotencyKey?: string } };
type LegacyUpdate = Omit<UpdateFormDefinitionRequired, "input"> & { input: UpdateFormDefinitionRequired["input"] & { idempotencyKey?: string } };
type LegacyStatus = Omit<SetFormDefinitionStatusRequired, "input"> & { input: SetFormDefinitionStatusRequired["input"] & { idempotencyKey?: string } };
function createFormDefinition({ deps, input: { notify, idempotencyKey, ...input } }: LegacyCreate) {
  return createFormDefinitionCore({ deps, input }, { ...(notify === undefined ? {} : { notify }), ...(idempotencyKey === undefined ? {} : { idempotencyKey }) });
}
function updateFormDefinition({ deps, input: { idempotencyKey, ...input } }: LegacyUpdate) {
  return updateFormDefinitionCore({ deps, input }, idempotencyKey === undefined ? {} : { idempotencyKey });
}
function setFormDefinitionStatus({ deps, input: { idempotencyKey, ...input } }: LegacyStatus) {
  return setFormDefinitionStatusCore({ deps, input }, idempotencyKey === undefined ? {} : { idempotencyKey });
}

src/media/__tests__/rendition-service.te.source:
/**
 * @file Rendition resolution tests — `rendition-service.ts`.
 * Covers: serve-if-exists, the frozen URL contract's lookup-by-triple
 * (assetId, transformName, version) behavior, the "latest version only"
 * anonymous-generation bound, single-flight dedup under concurrency, the
 * trashed->410/not-found->404 outcome mapping, and an unknown transform
 * returning `not-found`.
 */
import assert from "node:assert/strict";
import { test } from "vitest";

import { resolveMediaRendition } from "../rendition-service.js";
import { registerTransform } from "../transform-registry.js";
import { uploadMedia, trashMedia } from "../media-service.js";
import {
  InMemoryAssetBlobRepo,
  InMemoryAssetRenditionRepo,
  InMemoryMediaRepo,
  InMemoryTransformDefinitionRepo,
} from "../repo.memory.js";
import { InMemoryBlobStore } from "../blob-store.memory.js";
import { InMemoryImageTransformer } from "../image-transformer.js";

const WORKSPACE_ID = "workspace-1";

function makeDeps() {
  let counter = 0;
  const transformCalls: unknown[] = [];
  const realTransformer = new InMemoryImageTransformer();
  const countingTransformer = {
    transform: async (input: Parameters<typeof realTransformer.transform>[0]) => {
      transformCalls.push(input.params);
      return realTransformer.transform(input);
    },
  };

  const deps = {
    clock: { nowMs: () => Date.parse("2026-07-10T00:00:00.000Z")},
    idGen: { newId: () => `id-${(counter += 1)}` },
    mediaRepo: new InMemoryMediaRepo({}),
    blobRepo: new InMemoryAssetBlobRepo({}),
    renditionRepo: new InMemoryAssetRenditionRepo({}),
    transformRepo: new InMemoryTransformDefinitionRepo({}),
    blobStore: new InMemoryBlobStore(),
    imageTransformer: countingTransformer,
  };
  return { deps, transformCalls };
}

function bytesFrom(content: string): Uint8Array {
  return new TextEncoder().encode(content);
}

test("SVG transform URLs serve the vector original without invoking the raster transformer or saving renditions", async () => {
  const { deps, transformCalls } = makeDeps();
  const { media } = await uploadMedia({ deps, input: { workspaceId: WORKSPACE_ID, filename: "logo.svg", contentType: "image/svg+xml",
    bytes: bytesFrom('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 10 10"><path d="M0 0h10v10z"/></svg>'), createdByPrincipal: "owner" } });
  await registerTransform({ deps, input: { workspaceId: WORKSPACE_ID, name: "public", params: { format: "webp" }, owner: "core" } });
  const result = await resolveMediaRendition({ deps, input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "public", version: 1 } });
  assert.equal(result.outcome, "ok");
  if (result.outcome !== "ok") assert.fail("SVG rendition must resolve");
  assert.equal(result.contentType, "image/svg+xml");
  assert.match(new TextDecoder().decode(result.bytes), /viewBox="0 0 10 10"/);
  assert.deepEqual(transformCalls, []);
  assert.deepEqual((await deps.renditionRepo.listByAsset({ workspaceId: WORKSPACE_ID, assetId: media.id })).map(row => row.transformName), ["original"]);
});

async function uploadOne(deps: ReturnType<typeof makeDeps>["deps"], content = "source-bytes") {
  return uploadMedia({
    deps,
    input: {
      workspaceId: WORKSPACE_ID,
      bytes: bytesFrom(content),
      filename: "a.png",
      contentType: "image/png",
      createdByPrincipal: "user-1",
    },
  });
}

test("resolveMediaRendition: unknown assetId -> not-found", async () => {
  const { deps } = makeDeps();
  const result = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: "does-not-exist", transformName: "thumb", version: 1 },
  });
  assert.deepEqual(result, { outcome: "not-found" });
});

test("resolveMediaRendition: resolves by slug (2026-09-07), and stores the rendition row under the CANONICAL id, not the slug text", async () => {
  const { deps } = makeDeps();
  const { media } = await uploadOne(deps); // filename "a.png" -> slug "a"
  assert.equal(media.slug, "a");
  const { definition } = await registerTransform({ deps, input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { format: "jpeg" }, owner: "core" } });

  const bySlug = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.slug, transformName: "thumb", version: definition.version },
  });
  assert.equal(bySlug.outcome, "ok");

  // The written rendition row must be keyed by the real id — never the slug — so a later lookup BY
  // ID (the pre-existing, most common path) finds the SAME row instead of generating a duplicate.
  const rowsByCanonicalId = await deps.renditionRepo.listByAsset({ workspaceId: WORKSPACE_ID, assetId: media.id });
  assert.equal(rowsByCanonicalId.filter((r) => r.transformName === "thumb").length, 1);
  const rowsBySlugText = await deps.renditionRepo.listByAsset({ workspaceId: WORKSPACE_ID, assetId: media.slug });
  assert.equal(rowsBySlugText.length, 0, "no rendition row may ever be keyed by the slug text itself");

  const byId = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: definition.version },
  });
  assert.equal(byId.outcome, "ok");
  if (bySlug.outcome === "ok" && byId.outcome === "ok") {
    assert.deepEqual(bySlug.bytes, byId.bytes, "slug and id resolve to the identical already-generated rendition, not two");
  }
});

test("resolveMediaRendition: trashed asset -> gone (410), even though its row still physically exists", async () => {
  const { deps } = makeDeps();
  const { media } = await uploadOne(deps);
  await registerTransform({ deps, input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { format: "jpeg" }, owner: "core" } });
  await trashMedia({ deps, input: { workspaceId: WORKSPACE_ID, id: media.id } });

  const result = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: 1 },
  });
  assert.deepEqual(result, { outcome: "gone" });
});

test("resolveMediaRendition: unregistered transform name -> not-found (never lazily invents a definition)", async () => {
  const { deps } = makeDeps();
  const { media } = await uploadOne(deps);

  const result = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "never-registered", version: 1 },
  });
  assert.deepEqual(result, { outcome: "not-found" });
});

test("resolveMediaRendition: serve-if-exists — an already-generated rendition serves without calling the transformer again", async () => {
  const { deps, transformCalls } = makeDeps();
  const { media } = await uploadOne(deps);
  const { definition } = await registerTransform({
    deps,
    input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { width: 100, height: 100, format: "webp" }, owner: "core" },
  });

  const first = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: definition.version },
  });
  assert.equal(first.outcome, "ok");
  assert.equal(transformCalls.length, 1, "first request actually generated the rendition");

  const second = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: definition.version },
  });
  assert.equal(second.outcome, "ok");
  assert.equal(transformCalls.length, 1, "second request served the existing row — no second transform call");
  if (first.outcome === "ok" && second.outcome === "ok") {
    assert.deepEqual(first.bytes, second.bytes, "same bytes served both times (immutable-by-construction)");
  }
});

test("resolveMediaRendition: lookup ignores cosmetic slug/ext — the (assetId, transformName, version) triple is the only key", async () => {
  // A route layer strips slug/ext before calling this service at all (they are
  // cosmetic and never part of any lookup) — this test proves the service's own input shape has
  // no slug/ext field to smuggle differing behavior through, by resolving the identical triple
  // twice and getting identical bytes regardless of what a caller might have put in the URL.
  const { deps } = makeDeps();
  const { media } = await uploadOne(deps);
  const { definition } = await registerTransform({
    deps,
    input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { format: "jpeg" }, owner: "core" },
  });

  const asPhoto = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: definition.version },
  });
  const asAnythingElse = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: definition.version },
  });

  assert.equal(asPhoto.outcome, "ok");
  assert.equal(asAnythingElse.outcome, "ok");
  if (asPhoto.outcome === "ok" && asAnythingElse.outcome === "ok") {
    assert.deepEqual(asPhoto.bytes, asAnythingElse.bytes);
  }
});

test("resolveMediaRendition: anonymous generation is bounded to the LATEST registered version — an older, ungenerated version is not-found, never lazily materialized", async () => {
  const { deps, transformCalls } = makeDeps();
  const { media } = await uploadOne(deps);
  const { definition: v1 } = await registerTransform({
    deps,
    input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { format: "jpeg" }, owner: "core" },
  });
  const { definition: v2 } = await registerTransform({
    deps,
    input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { format: "webp" }, owner: "core" },
  });
  assert.equal(v1.version, 1);
  assert.equal(v2.version, 2);

  // v1 is a valid, real registry row — but it is no longer the latest, and nothing has ever
  // generated it, so an anonymous request for it must be blocked (the amplification-vector guard).
  const oldVersionResult = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: v1.version },
  });
  assert.deepEqual(oldVersionResult, { outcome: "not-found" });
  assert.equal(transformCalls.length, 0, "the old version was never lazily generated");

  // v2 (the latest) is generatable on first anonymous request.
  const latestVersionResult = await resolveMediaRendition({
    deps,
    input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: v2.version },
  });
  assert.equal(latestVersionResult.outcome, "ok");
  assert.equal(transformCalls.length, 1);
});

test("resolveMediaRendition: single-flight — two concurrent requests for the same ungenerated (sha256, name, version) trigger exactly one transform call and both resolve to the same bytes", async () => {
  const { deps, transformCalls } = makeDeps();
  const { media } = await uploadOne(deps, "shared-source-bytes");
  const { definition } = await registerTransform({
    deps,
    input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { width: 50, height: 50, format: "png" }, owner: "core" },
  });

  const [first, second] = await Promise.all([
    resolveMediaRendition({
      deps,
      input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: definition.version },
    }),
    resolveMediaRendition({
      deps,
      input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: definition.version },
    }),
  ]);

  assert.equal(transformCalls.length, 1, "only one real transform call happened for the concurrent pair");
  assert.equal(first.outcome, "ok");
  assert.equal(second.outcome, "ok");
  if (first.outcome === "ok" && second.outcome === "ok") {
    assert.deepEqual(first.bytes, second.bytes);
  }

  const rows = await deps.renditionRepo.listByAsset({ workspaceId: WORKSPACE_ID, assetId: media.id });
  const thumbRows = rows.filter((row) => row.transformName === "thumb" && row.version === definition.version);
  assert.equal(thumbRows.length, 1, "only one rendition row was written, not two");
});

test("resolveMediaRendition: five concurrent requests for the same ungenerated rendition still produce exactly one transform call (adversarial fan-in)", async () => {
  const { deps, transformCalls } = makeDeps();
  const { media } = await uploadOne(deps, "fan-in-source");
  const { definition } = await registerTransform({
    deps,
    input: { workspaceId: WORKSPACE_ID, name: "square", params: { width: 64, height: 64, format: "webp" }, owner: "core" },
  });

  const results = await Promise.all(
    Array.from({ length: 5 }, () =>
      resolveMediaRendition({
        deps,
        input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "square", version: definition.version },
      })
    )
  );

  assert.equal(transformCalls.length, 1);
  assert.ok(results.every((r) => r.outcome === "ok"));
  const rows = await deps.renditionRepo.listByAsset({ workspaceId: WORKSPACE_ID, assetId: media.id });
  assert.equal(rows.filter((r) => r.transformName === "square").length, 1);
});

test("resolveMediaRendition: a document asset has no image renditions — not-found, never generated", async () => {
  const { deps: uploadDeps, transformCalls } = makeDeps();
  const { media } = await uploadOne(uploadDeps);
  // Kind is fixed at creation (a save cannot change it), so the document row is seeded directly.
  const deps = { ...uploadDeps, mediaRepo: new InMemoryMediaRepo({}, { initialRows: [{ ...media, kind: "document" }] }) };
  await registerTransform({ deps, input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { width: 10, format: "webp" }, owner: "core" } });
  assert.deepEqual(await resolveMediaRendition({ deps, input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: 1 } }), { outcome: "not-found" });
  assert.deepEqual(transformCalls, []);
});

test("resolveMediaRendition: a media row whose source blob row is missing is surfaced as an integrity error, not a 404", async () => {
  const { deps } = makeDeps();
  const { media } = await uploadOne(deps);
  await registerTransform({ deps, input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { width: 10, format: "webp" }, owner: "core" } });
  await deps.blobRepo.remove({ workspaceId: WORKSPACE_ID, sha256: media.source.sha256 });
  await assert.rejects(
    resolveMediaRendition({ deps, input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: 1 } }),
    new RegExp(`media '${media.id}': source blob for sha256 '${media.source.sha256}' was not found`),
  );
});

test("resolveMediaRendition: a stored rendition whose bytes are SVG is re-sanitized on every read", async () => {
  const { deps } = makeDeps();
  const { media } = await uploadOne(deps);
  await registerTransform({ deps, input: { workspaceId: WORKSPACE_ID, name: "thumb", params: { width: 10, format: "webp" }, owner: "core" } });
  // A legacy rendition blob written before SVG sanitizing existed.
  const { storageKey } = await deps.blobStore.put({ workspaceId: WORKSPACE_ID, sha256: "e".repeat(64),
    bytes: bytesFrom('<svg xmlns="http://www.w3.org/2000/svg" onload="alert(1)"><script>alert(1)</script><path d="M0 0h1v1z"/></svg>') });
  await deps.renditionRepo.save({ id: "legacy-rendition", workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: 1, storageKey, createdAt: "2026-07-10T00:00:00.000Z" });
  const result = await resolveMediaRendition({ deps, input: { workspaceId: WORKSPACE_ID, assetId: media.id, transformName: "thumb", version: 1 } });
  if (result.outcome !== "ok") assert.fail(`expected ok, got ${result.outcome}`);
  assert.equal(result.contentType, "image/svg+xml");
  const served = new TextDecoder().decode(result.bytes);
  assert.doesNotMatch(served, /onload|<script/);
  assert.match(served, /<path d="M0 0h1v1z"/);
});

src/content-types/__tests__/write-servic.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import {
  ContentTypeAlreadyExistsError,
  InvalidFieldKindError,
  InvalidFieldNameGrammarError,
  InvalidKeyGrammarError,
  QueryableFieldCapExceededError,
  ReservedContentTypeKeyError,
} from "../errors.js";
import { deprecateContentType, tombstoneContentType } from "../lifecycle.js";
import type { ContentTypeRecord } from "../types.js";
import { registerContentType } from "../write-service.js";

/**
 * @file fixed definition-time guard order, plus
 * 's registration-path behavior.
 *
 * Binding constraint : the five guards (key grammar -> reserved-key -> field-name grammar
 * -> field-kind -> queryable-cap) evaluate in that exact order, and evaluation stops at the first
 * failure — never collected, never reordered.
 * See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
 */

const NOW = "2026-07-15T00:00:00.000Z";
const clock = { nowMs: () => Date.parse(NOW)};
let idCounter = 0;
const ids = { newId: () => `ct-${++idCounter}` };
const alwaysAllow = async () => ({ allowed: true, reason: "matched" });

function fakeRepo() {
  const rows: unknown[] = [];
  const revisions: unknown[] = [];
  return {
    rows,
    revisions,
    save: async (row: unknown) => {
      rows.push(row);
    },
    appendRevision: async (rev: unknown) => {
      revisions.push(rev);
    },
    findByKey: async () => null,
    transaction: async <T>({ fn }: { fn: () => Promise<T> }) => fn(),
  };
}

function fakeIndexProvisioner() {
  const calls: unknown[] = [];
  // `applyFieldIndexTransitions` deliberately does NOT record into `calls`: this suite asserts on
  // `calls` as the provisioning log for the register path, and the update-fields path is a
  // different suite. It exists only because the package typechecks its tests against the full
  // `IndexProvisionerPort` (the host this was ported from excluded tests from typecheck).
  return {
    calls,
    provisionIndexesForNewContentType: async (input: unknown) => { calls.push(input); },
    applyFieldIndexTransitions: async () => undefined,
  };
}

const outbox = { enqueue: async () => undefined };

function validFields() {
  return [{ name: "price", kind: "integer" as const, required: false, queryable: true }];
}

test("AC-01: a well-formed submission creates a content_types row with status='active' and version=1", async () => {
  const repo = fakeRepo();
  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "recipe", label: "Recipe", fields: validFields() },
  });

  assert.equal(result.ok, true);
  if (result.ok) {
    const value = result.value as { contentType: { key: string; status: string; version: number } };
    assert.equal(value.contentType.key, "recipe");
    assert.equal(value.contentType.status, "active");
    assert.equal(value.contentType.version, 1);
  }
});

test("AC-02/AC-03: key='post' and key='page' are both rejected with RESERVED_CONTENT_TYPE_KEY and create no row", async () => {
  for (const key of ["post", "page"]) {
    const repo = fakeRepo();
    const result = await registerContentType({
      deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
      input: { workspaceId: "ws-1", actorId: "user-1", key, label: "X", fields: validFields() },
    });

    assert.equal(result.ok, false);
    if (!result.ok) assert.ok(result.error instanceof ReservedContentTypeKeyError);
    assert.equal(repo.rows.length, 0);
  }
});

test("AC-04: key='My-Recipe' (uppercase + hyphen) is rejected with INVALID_KEY_GRAMMAR", async () => {
  const repo = fakeRepo();
  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "My-Recipe", label: "X", fields: validFields() },
  });

  assert.equal(result.ok, false);
  if (!result.ok) assert.ok(result.error instanceof InvalidKeyGrammarError);
});

test("AC-08: a 21st queryable field is rejected with QUERYABLE_FIELD_CAP_EXCEEDED", async () => {
  const repo = fakeRepo();
  const fields = Array.from({ length: 21 }, (_, i) => ({ name: `field_${i}`, kind: "text" as const, required: false, queryable: true }));

  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "big_type", label: "X", fields },
  });

  assert.equal(result.ok, false);
  if (!result.ok) assert.ok(result.error instanceof QueryableFieldCapExceededError);
});

test("AC-09: exactly 20 queryable fields is accepted", async () => {
  const repo = fakeRepo();
  const fields = Array.from({ length: 20 }, (_, i) => ({ name: `field_${i}`, kind: "text" as const, required: false, queryable: true }));

  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "big_type_ok", label: "X", fields },
  });

  assert.equal(result.ok, true);
});

test("U-002-B1/AC-38: a submission violating BOTH the reserved-key check AND the field-name-grammar check reports RESERVED_CONTENT_TYPE_KEY (the earlier guard), never INVALID_FIELD_NAME_GRAMMAR", async () => {
  const repo = fakeRepo();
  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: {
      workspaceId: "ws-1",
      actorId: "user-1",
      key: "post", // grammar-valid but reserved
      label: "X",
      fields: [{ name: "Bad Field Name!", kind: "text" as const, required: false, queryable: false }],
    },
  });

  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.ok(result.error instanceof ReservedContentTypeKeyError, "REQ-24's fixed guard order requires the reserved-key check (2nd guard) to fire before the field-name-grammar check (3rd guard)");
    assert.equal(result.error instanceof InvalidFieldNameGrammarError, false);
  }
});

test("U-002-B1: a submission violating field-kind AND queryable-cap simultaneously reports INVALID_FIELD_KIND (the earlier guard), never QUERYABLE_FIELD_CAP_EXCEEDED", async () => {
  const repo = fakeRepo();
  const fields = [
    ...Array.from({ length: 20 }, (_, i) => ({ name: `field_${i}`, kind: "text" as const, required: false, queryable: true })),
    { name: "bad_kind_field", kind: "sql_injection_kind" as never, required: false, queryable: true },
  ];

  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "guard_order_type", label: "X", fields },
  });

  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.ok(result.error instanceof InvalidFieldKindError, "field-kind check (4th guard) must fire before the queryable-cap check (5th guard)");
  }
});

test("AC-11/REQ-07: a successful registration commits the watermark stamp and content_type_revisions row in the same call (asserted here at the write-service seam; full same-transaction proof lives in watermark-stamping.integration.test.ts)", async () => {
  const repo = fakeRepo();
  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "revisioned_type", label: "X", fields: validFields() },
  });

  assert.equal(result.ok, true);
  assert.equal(repo.revisions.length, 1);
  const revision = repo.revisions[0] as { op: string };
  assert.equal(revision.op, "register");
});

test("registerContentType is rejected FORBIDDEN and writes nothing when the caller is unauthorized", async () => {
  const repo = fakeRepo();
  const alwaysDeny = async () => ({ allowed: false, reason: "no_grant" });

  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysDeny, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "denied_type", label: "X", fields: validFields() },
  });

  assert.equal(result.ok, false);
  assert.equal(repo.rows.length, 0);
});

test("two fields with the same name are rejected with VALIDATION_ERROR(fields_duplicate_name) and nothing is saved — entry values are keyed by field name, so a duplicate makes one of the two unaddressable", async () => {
  const repo = fakeRepo();
  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: {
      workspaceId: "ws-1",
      actorId: "user-1",
      key: "recipe",
      label: "Recipe",
      fields: [
        { name: "price", kind: "integer", required: false, queryable: true },
        { name: "price", kind: "text", required: false, queryable: false },
      ],
    },
  });

  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.equal(result.error.message, "field name 'price' appears more than once");
    assert.deepEqual((result.error as { details?: unknown }).details, { reason: "fields_duplicate_name" });
  }
  assert.equal(repo.rows.length, 0);
});

// ---------------------------------------------------------------------------
// S9 (web-high fix plan, 2026-09-24) — row 7 (define overwrites/resurrects) + row 15's sibling.
// `fakeRepo()` above always returns `null` from `findByKey`, so these tests need a stateful repo
// where a real `save` is visible to a later `findByKey` — same pattern as
// `write-service.update-fields.test.ts`'s `fakeRepo(seed)` and `lifecycle.test.ts`'s.
// ---------------------------------------------------------------------------

function statefulFakeRepo() {
  let stored: ContentTypeRecord | null = null;
  const revisions: unknown[] = [];
  return {
    getStored: () => stored as ContentTypeRecord,
    revisions,
    save: async (row: ContentTypeRecord) => {
      stored = row;
    },
    appendRevision: async (rev: unknown) => {
      revisions.push(rev);
    },
    findByKey: async () => stored,
    transaction: async <T>({ fn }: { fn: () => Promise<T> }) => fn(),
  };
}

test("S9/row 7: registering the same key twice is rejected with ContentTypeAlreadyExistsError, and the stored fields/version are still the FIRST call's", async () => {
  const repo = statefulFakeRepo();
  const deps = { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox };

  const first = await registerContentType({
    deps,
    input: { workspaceId: "ws-1", actorId: "user-1", key: "recipe", label: "Recipe", fields: validFields() },
  });
  assert.equal(first.ok, true);

  const second = await registerContentType({
    deps,
    input: {
      workspaceId: "ws-1",
      actorId: "user-1",
      key: "recipe",
      label: "Recipe v2",
      fields: [{ name: "other", kind: "text", required: false, queryable: false }],
    },
  });

  assert.equal(second.ok, false);
  if (!second.ok) {
    assert.ok(second.error instanceof ContentTypeAlreadyExistsError);
    assert.equal(
      second.error.message,
      "content type 'recipe' already exists; use collections_content_type_update_fields to change its fields"
    );
  }
  assert.equal(repo.getStored().version, 1);
  assert.deepEqual(repo.getStored().fields, validFields());
});

test("S9/row 15's sibling: registering a key that was tombstoned is rejected naming INV-06, and the row's status stays 'tombstone'", async () => {
  const repo = statefulFakeRepo();
  const deps = { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox };

  const registered = await registerContentType({
    deps,
    input: { workspaceId: "ws-1", actorId: "user-1", key: "recipe", label: "Recipe", fields: validFields() },
  });
  assert.equal(registered.ok, true);

  const deprecated = await deprecateContentType({
    deps: { repo, clock, authorize: alwaysAllow, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "recipe", expectedVersion: 1 },
  });
  assert.equal(deprecated.ok, true);

  const tearDownAllIndexesForContentType = async () => undefined;
  const tombstoned = await tombstoneContentType({
    deps: { repo, clock, authorize: alwaysAllow, outbox, indexProvisioner: { tearDownAllIndexesForContentType } },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "recipe", expectedVersion: 2 },
  });
  assert.equal(tombstoned.ok, true);

  const reRegistered = await registerContentType({
    deps,
    input: { workspaceId: "ws-1", actorId: "user-1", key: "recipe", label: "Recipe again", fields: validFields() },
  });

  assert.equal(reRegistered.ok, false);
  if (!reRegistered.ok) {
    assert.ok(reRegistered.error instanceof ContentTypeAlreadyExistsError);
    assert.equal(
      reRegistered.error.message,
      "content type 'recipe' was permanently deleted; its key can't be reused"
    );
  }
  assert.equal(repo.getStored().status, "tombstone");
});

test("S9/row 7: the in-transaction re-check closes the race — a row saved between the pre-check and the transaction is refused, with no save and no index provisioning", async () => {
  // Simulates two concurrent first creates: the pre-check sees nothing, then the winner commits
  // before this call's transaction opens, so only the in-transaction `findByKey` can see it.
  const winner = { status: "active" } as ContentTypeRecord;
  let findByKeyCalls = 0;
  const saves: ContentTypeRecord[] = [];
  const repo = {
    save: async (row: ContentTypeRecord) => { saves.push(row); },
    appendRevision: async () => undefined,
    findByKey: async () => (++findByKeyCalls === 1 ? null : winner),
    transaction: async <T>({ fn }: { fn: () => Promise<T> }) => fn(),
  };
  const indexProvisioner = fakeIndexProvisioner();

  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "recipe", label: "Recipe", fields: validFields() },
  });

  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.ok(result.error instanceof ContentTypeAlreadyExistsError);
    assert.equal(
      result.error.message,
      "content type 'recipe' already exists; use collections_content_type_update_fields to change its fields"
    );
  }
  assert.equal(findByKeyCalls, 2);
  assert.equal(saves.length, 0, "the loser must not overwrite the winner's row");
  assert.equal(indexProvisioner.calls.length, 0, "provisioning must not run on refusal");
});

test("host-reserved keys are refused after authorization and before any row, revision or index write", async () => {
  for (const key of ["admin", "api"]) {
    const repo = fakeRepo();
    const provisioner = fakeIndexProvisioner();
    const result = await registerContentType({
      deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: provisioner, outbox, reservedKeys: new Set(["admin", "api"]) },
      input: { workspaceId: "ws-1", actorId: "user-1", key, label: "Reserved", fields: validFields() },
    });
    assert.equal(result.ok, false);
    if (result.ok) assert.fail("reserved key accepted");
    assert.ok(result.error instanceof ReservedContentTypeKeyError);
    assert.equal(result.error.message, `key '${key}' is reserved for a host route`);
    assert.deepEqual(repo.rows, []);
    assert.deepEqual(repo.revisions, []);
    assert.deepEqual(provisioner.calls, []);
  }
});

