import assert from "node:assert/strict";
import { test } from "vitest";
import { harness, removal, WS, AT, ACTOR, ALLOW_ALL } from "./fixture.js";
import { createTrashService, computePurgeAfter, bindRemoveEntity, bindForgetRemovedEntity, TrashAdapterMissingError, type TrashChangeEvent } from "../write-service.js";

// Generalized from trash.contract, prior-marker.contract and on-changed.contract suites.
test("hide and restore never parse or rewrite the entity payload; listing uses the snapshot", async () => {
  const h = harness();
  assert.deepEqual(await h.trash.trash(removal), { ok: true, version: 2 });
  assert.equal(h.records.records.get("record-1")!.bodyJson, "{corrupt");
  assert.equal((await h.trash.list({ workspaceId: WS, now: AT, limit: 10 })).items[0]!.displayTitle, "Snapshot title");
  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT }), "restored");
  assert.equal(h.records.records.get("record-1")!.bodyJson, "{corrupt");
  assert.equal(h.records.records.get("record-1")!.version, 3);
  assert.equal(h.repo.all({}).length, 0);
});
test("index insert failure rolls back the marker flip", async () => {
  const h = harness();
  h.repo.insert = async () => { throw new Error("disk full"); };
  await assert.rejects(() => h.trash.trash(removal), /disk full/);
  assert.equal(h.records.records.get("record-1")!.version, 1);
  assert.equal(h.records.records.get("record-1")!.deletedAt, undefined);
  assert.equal(h.repo.all({}).length, 0);
});
test("domain removal may enter an existing transaction", async () => {
  const h = harness();
  const remove = bindRemoveEntity({ trash: h.trash, entityType: "record" });
  await h.deps.transaction({ work: () => remove({ workspaceId: WS, id: "record-1", actor: ACTOR, display: removal.display, at: AT, expectedVersion: 1 }) });
  assert.equal(h.records.records.get("record-1")!.version, 2);
  assert.equal(h.repo.all({}).length, 1);
});
test("missing adapters list snapshots but degrade on restore and purge; adapters resolve per call", async () => {
  const h = harness();
  await h.trash.trash(removal);
  h.adapters.clear();
  assert.equal((await h.trash.list({ workspaceId: WS, now: AT, limit: 10 })).items.length, 1);
  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT }), "adapter-unavailable");
  assert.deepEqual((await h.trash.purgeSelected({ workspaceId: WS, ids: ["trash-1"], actor: ACTOR, authorizeItem: ALLOW_ALL })).results, [{ id: "trash-1", outcome: "adapter-unavailable" }]);
  await assert.rejects(() => h.trash.trash(removal), TrashAdapterMissingError);
  h.adapters.set("record", h.adapter);
  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT }), "restored");
});
test("authorization receives stored rows and gates destruction before adapter resolution", async () => {
  const h = harness();
  await h.trash.trash(removal);
  h.adapters.clear();
  const seen: string[] = [];
  const report = await h.trash.purgeSelected({ workspaceId: WS, ids: ["trash-1", "unknown"], actor: ACTOR,
    authorizeItem: async ({ item }) => { seen.push(item.entityType); return false; } });
  assert.deepEqual(seen, ["record"]);
  assert.deepEqual(report.results, [{ id: "trash-1", outcome: "forbidden" }, { id: "unknown", outcome: "not-found" }]);
  assert.equal(h.repo.all({}).length, 1);
  assert.ok(h.records.records.get("record-1"));
});
test("a stale version stands down and preserves the index; vanished rows remove only the index", async () => {
  const h = harness();
  await h.trash.trash(removal);
  h.records.records.get("record-1")!.version++;
  const input = { workspaceId: WS, ids: ["trash-1"], actor: ACTOR, authorizeItem: ALLOW_ALL };
  assert.equal((await h.trash.purgeSelected(input)).results[0]!.outcome, "version-changed");
  assert.equal(h.repo.all({}).length, 1);
  h.records.records.delete("record-1");
  assert.equal((await h.trash.purgeSelected(input)).results[0]!.outcome, "already-gone");
  assert.equal(h.repo.all({}).length, 0);
});
test("a still-referenced row keeps its index and marker while later rows are purged", async () => {
  const seen: TrashChangeEvent[] = [];
  const h = harness({ onChanged: event => { seen.push(event); } });
  h.records.records.set("record-2", { id: "record-2", workspaceId: WS, version: 1, updatedAt: AT });
  await h.trash.trash(removal);
  await h.trash.trash({ ...removal, entityId: "record-2" });
  const retainedRecord = structuredClone(h.records.records.get("record-1"));
  const retainedIndex = structuredClone(h.repo.all({}).find(row => row.id === "trash-1"));
  const purge = h.adapter.purge;
  h.adapters.set("record", { ...h.adapter, purge: async (required, optional) =>
    required.entityId === "record-1" ? "still-referenced" : purge(required, optional) });
  seen.length = 0;

  assert.deepEqual(await h.trash.purgeSelected({ workspaceId: WS, ids: ["trash-1", "trash-2"], actor: ACTOR, authorizeItem: ALLOW_ALL }), {
    purged: 1,
    results: [{ id: "trash-1", outcome: "still-referenced" }, { id: "trash-2", outcome: "purged" }],
  });
  assert.deepEqual(h.repo.all({}), [retainedIndex]);
  assert.deepEqual(h.records.records.get("record-1"), retainedRecord);
  assert.equal(h.records.records.has("record-2"), false);
  assert.deepEqual(seen, [{ workspaceId: WS, entityType: "record", entityId: "record-2", change: "purge" }]);
});
test("notifications are in arg 2 and cannot undo a mutation when reporting fails", async () => {
  const seen: string[] = [];
  const h = harness({ onChanged: async event => { seen.push(event.change); throw new Error("notifier failed"); }, onError: () => { throw new Error("reporter failed"); } });
  await h.trash.trash(removal);
  await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT });
  await h.trash.trash({ ...removal, expectedVersion: 3 });
  assert.equal((await h.trash.purgeSelected({ workspaceId: WS, ids: ["trash-2"], actor: ACTOR, authorizeItem: ALLOW_ALL })).purged, 1);
  assert.deepEqual(seen, ["trash", "restore", "trash", "purge"]);
  assert.equal(h.records.records.size, 0);
});
test("repeated trash preserves the marker and index without notifying again", async () => {
  const seen: TrashChangeEvent[] = [];
  const h = harness({ onChanged: event => { seen.push(event); } });
  assert.deepEqual(await h.trash.trash(removal), { ok: true, version: 2 });
  const record = structuredClone(h.records.records.get("record-1"));
  const index = structuredClone(h.repo.all({}));
  assert.equal(index.length, 1);
  const event = { workspaceId: WS, entityType: "record", entityId: "record-1", change: "trash" };
  assert.deepEqual(seen, [event]);

  // A retry is successful but explicitly noop; it must not emit a second outbox event (F1487).
  for (const expectedVersion of [2, null]) {
    assert.deepEqual(await h.trash.trash({ ...removal, expectedVersion, at: "2026-09-21T12:00:00.000Z" }),
      { ok: true, version: 2, noop: true });
    assert.deepEqual(h.records.records.get("record-1"), record);
    assert.deepEqual(h.repo.all({}), index);
    assert.deepEqual(seen, [event]);
  }
  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT }), "restored");
  assert.deepEqual(seen, [event, { ...event, change: "restore" }]);
  assert.equal(h.records.records.get("record-1")!.version, 3);
  assert.deepEqual(h.repo.all({}), []);
});
test("restore cleans a stale index without notifying when the marker is already clear", async () => {
  const seen: TrashChangeEvent[] = [];
  const h = harness({ onChanged: event => { seen.push(event); } });
  await h.trash.trash(removal);
  assert.equal(h.repo.all({}).length, 1);
  // Model a marker cleared outside Trash while its index snapshot is still present. The real
  // record adapter returns noop, so cleanup must not claim a second domain transition (F1487).
  const cleared = { ...h.records.records.get("record-1")!, deletedAt: null };
  h.records.records.set("record-1", structuredClone(cleared));
  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: "2026-09-21T12:00:00.000Z" }), "restored");
  assert.deepEqual(h.records.records.get("record-1"), cleared);
  assert.deepEqual(h.repo.all({}), []);
  assert.deepEqual(seen, [{ workspaceId: WS, entityType: "record", entityId: "record-1", change: "trash" }]);
});
test("retention and entity policy are host-owned and evaluated at the operation", async () => {
  const h = harness();
  const short = createTrashService(h.deps, { retentionDays: 2 });
  await short.trash(removal);
  assert.equal(h.repo.all({})[0]!.purgeAfter, "2026-09-22T12:00:00.000Z");
  assert.equal((await short.list({ workspaceId: WS, now: "2026-09-22T12:00:00.000Z", limit: 10 })).items.length, 0);
  assert.equal(computePurgeAfter({ at: AT }, { retentionDays: 60 }), "2026-11-19T12:00:00.000Z");
  const denied = createTrashService({ ...h.deps, entityPolicy: () => false });
  await assert.rejects(() => denied.trash(removal), TrashAdapterMissingError);
  assert.throws(() => computePurgeAfter({ at: "invalid" }, { retentionDays: 60 }), RangeError);
});
test("prior marker from the adapter wins; fallback and index-only cleanup remain available", async () => {
  const h = harness();
  h.adapters.set("record", { ...h.adapter, hide: async () => ({ ok: true, version: 2, priorMarker: "draft" }) });
  await h.trash.trash(removal, { priorMarker: "published" });
  assert.equal(h.repo.all({})[0]!.priorMarker, "draft");
  await bindForgetRemovedEntity({ repo: h.repo, entityType: "record" })({ workspaceId: WS, id: "record-1" });
  assert.equal(h.repo.all({}).length, 0);
});

// REGRESSION: fails if the entityPolicy denial is moved ahead of the missing-adapter branch.
test("authorized missing-domain purge remains adapter-unavailable with a deny policy", async () => {
  const h = harness();
  await h.trash.trash(removal);
  h.adapters.clear();
  const trash = createTrashService({ ...h.deps, entityPolicy: () => false });
  const denied = await trash.purgeSelected({ workspaceId: WS, ids: ["trash-1"], actor: ACTOR, authorizeItem: async () => false });
  assert.deepEqual(denied.results, [{ id: "trash-1", outcome: "forbidden" }]);
  const allowed = await trash.purgeSelected({ workspaceId: WS, ids: ["trash-1"], actor: ACTOR, authorizeItem: async () => true });
  assert.deepEqual(allowed.results, [{ id: "trash-1", outcome: "adapter-unavailable" }]);
  assert.equal(h.repo.all({}).length, 1);
  assert.ok(h.records.records.has("record-1"));
});

test("a refused hide returns the adapter's refusal and writes no index row and no notification", async () => {
  const events: TrashChangeEvent[] = [];
  const h = harness({ onChanged: (event) => { events.push(event); } });

  assert.deepEqual(await h.trash.trash({ ...removal, expectedVersion: 7 }), { ok: false, reason: "version-changed" });
  assert.equal(h.repo.all({}).length, 0);
  assert.equal(h.records.records.get("record-1")!.version, 1);
  assert.deepEqual(events, []);
});

test("restoring an entity that was never trashed is not-found and never consults the adapter", async () => {
  const h = harness();
  let unhides = 0;
  h.adapters.set("record", { ...h.adapter, unhide: async (...args) => { unhides += 1; return h.adapter.unhide(...args); } });

  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT }), "not-found");
  assert.equal(unhides, 0);
});

test("restore maps an adapter not-found to not-found and any other refusal to version-changed, keeping the index row", async () => {
  const h = harness();
  await h.trash.trash(removal);

  h.adapters.set("record", { ...h.adapter, unhide: async () => ({ ok: false, reason: "not-found" }) });
  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT }), "not-found");

  h.adapters.set("record", { ...h.adapter, unhide: async () => ({ ok: false, reason: "version-changed" }) });
  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT }), "version-changed");

  assert.equal(h.repo.all({}).length, 1);
});

test("purgeSelected reports forbidden when the entity policy no longer allows the row's installed type", async () => {
  const h = harness();
  await h.trash.trash(removal);
  const trash = createTrashService({ ...h.deps, entityPolicy: () => false });

  assert.deepEqual(
    await trash.purgeSelected({ workspaceId: WS, ids: ["trash-1"], actor: ACTOR, authorizeItem: ALLOW_ALL }),
    { purged: 0, results: [{ id: "trash-1", outcome: "forbidden" }] }
  );
  assert.ok(h.records.records.get("record-1"));
  assert.equal(h.repo.all({}).length, 1);
});

test("restore forwards the restoring actor to the adapter only when one is supplied", async () => {
  const h = harness();
  await h.trash.trash(removal, { priorMarker: "draft" });
  const seen: unknown[] = [];
  h.adapters.set("record", { ...h.adapter, unhide: async (required, optional) => { seen.push(optional); return h.adapter.unhide(required, optional); } });

  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT }, { actor: ACTOR }), "restored");
  await h.trash.trash({ ...removal, expectedVersion: 3 });
  assert.equal(await h.trash.restore({ workspaceId: WS, entityType: "record", entityId: "record-1", at: AT }), "restored");

  assert.deepEqual(seen, [{ priorMarker: "draft", actor: ACTOR }, { priorMarker: null }]);
});

src/forms/__tests__/submit-service.bound.source:
/** Boundary behaviour of `submitForm` pinned around its persistence, upload-compensation and attempt paths. */
import assert from "node:assert/strict";
import { test } from "vitest";

import { FormDefinitionNotFoundError, FormRateLimitExceededError, FormSubmissionValidationError } from "../errors.js";
import { InMemoryFormDefinitionRepo, InMemoryFormSubmissionRepo } from "../repo.memory.js";
import { createSubmissionAttempts } from "../submission-attempts.js";
import { submitForm, type SubmitFormDeps, type SubmitFormInput } from "../submit-service.js";
import { FORM_SUBMISSION_RECEIVED_EVENT, type FieldDescriptor, type FormDefinitionRecord, type FormFileInput, type FormFileReference, type FormFileStoragePort } from "../types.js";

const png = new Uint8Array([137, 80, 78, 71, 13, 10, 26, 10, 1]);
const photo: FormFileInput = { filename: "photo.png", contentType: "image/png", bytes: png };
const fileField = (id: string): FieldDescriptor => ({ id, label: id, type: "file", required: true, accept: ["image/*"], maxFileSize: 20 });
const textField: FieldDescriptor = { id: "name", label: "Name", type: "text", required: true };

function definition(fields: FieldDescriptor[], status: FormDefinitionRecord["status"] = "active"): FormDefinitionRecord {
  return { id: "form", workspaceId: "ws", name: "Form", slug: "form", fields, notify: { enabled: false, recipients: [] }, status, version: 1, createdAt: "2026-10-11T00:00:00Z", updatedAt: "2026-10-11T00:00:00Z" };
}

function fixture(fields: FieldDescriptor[], status: FormDefinitionRecord["status"] = "active") {
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const warnings: Array<{ message: string; error: unknown }> = [];
  const discarded: FormFileReference[] = [];
  const stored: string[] = [];
  let events = 0;
  let dispatches = 0;
  let id = 0;
  const files: FormFileStoragePort = {
    detectContentType: ({ bytes }) => (bytes[0] === 137 ? "image/png" : "application/octet-stream"),
    store: async ({ fieldId, file }) => { stored.push(fieldId); return { mediaId: `media-${fieldId}`, filename: file.filename, contentType: file.contentType, byteSize: file.bytes.byteLength }; },
    discard: async ({ reference }) => { discarded.push(reference); },
  };
  const deps: SubmitFormDeps = {
    definitionRepo,
    submissionRepo,
    clock: { nowMs: () => 0 },
    idGen: { newId: () => `id-${++id}` },
    rateLimiter: { check: async () => ({ allowed: true }) },
    outbox: { enqueue: async () => { events += 1; } },
    dispatcher: { dispatch: async () => { dispatches += 1; } },
    logger: { warn: ({ message }, optional) => { warnings.push({ message, error: optional?.error }); } },
    files,
    transaction: (work) => submissionRepo.transaction(work),
  };
  const ready = definitionRepo.create(definition(fields, status));
  const rows = async () => (await submissionRepo.listByDefinition({ workspaceId: "ws", formDefinitionId: "form", limit: 10 })).items;
  const input = (body: Record<string, unknown>): SubmitFormInput => ({ workspaceId: "ws", slug: "form", sourceIp: "10.0.0.1", body });
  return { deps, files, ready, rows, input, warnings, discarded, stored, events: () => events, dispatches: () => dispatches };
}

const settle = () => new Promise<void>((resolve) => { setTimeout(resolve, 0); });

test("submitForm: a file submission without a transaction port is refused per file field before any upload", async () => {
  const f = fixture([fileField("front"), fileField("back")]);
  await f.ready;
  const { transaction: _omitted, ...deps } = f.deps;
  await assert.rejects(submitForm({ deps, input: f.input({ front: photo, back: photo }) }), (error: unknown) => {
    assert.ok(error instanceof FormSubmissionValidationError);
    assert.equal(error.message, "file submissions require transactional storage");
    assert.deepEqual(error.fieldErrors, [{ field: "front", reason: "file_storage_unavailable" }, { field: "back", reason: "file_storage_unavailable" }]);
    return true;
  });
  assert.deepEqual(f.stored, []);
});

test("submitForm: a scalar submission without a transaction port still writes the row and event", async () => {
  const f = fixture([textField]);
  await f.ready;
  const { transaction: _omitted, ...deps } = f.deps;
  const events: Parameters<SubmitFormDeps["outbox"]["enqueue"]>[0][] = [];
  deps.outbox = { enqueue: async (event) => { events.push(event); await f.deps.outbox.enqueue(event); } };
  assert.deepEqual(await submitForm({ deps, input: f.input({ name: "Ada" }) }), { status: "accepted" });
  assert.deepEqual([(await f.rows()).length, f.events()], [1, 1]);
  // The delivery subscriber consumes this exact topic and payload to plan every destination.
  assert.deepEqual(events, [{
    id: "id-2", name: FORM_SUBMISSION_RECEIVED_EVENT, occurredAt: "1970-01-01T00:00:00.000Z",
    workspaceId: "ws", aggregateId: "id-1",
    payload: { workspaceId: "ws", formDefinitionId: "form", submissionId: "id-1" },
  }]);
});

test("submitForm: a failed second upload discards only the uploads already stored and rethrows the upload error", async () => {
  const f = fixture([fileField("front"), fileField("back")]);
  await f.ready;
  const store: FormFileStoragePort["store"] = async (args) => {
    if (args.fieldId === "back") throw new Error("media backend offline");
    return f.files.store(args);
  };
  await assert.rejects(submitForm({ deps: { ...f.deps, files: { ...f.files, store } }, input: f.input({ front: photo, back: photo }) }), { message: "media backend offline" });
  assert.deepEqual(f.discarded.map((reference) => reference.mediaId), ["media-front"]);
  assert.deepEqual([(await f.rows()).length, f.events()], [0, 0]);
});

test("submitForm: a failed upload cleanup is logged and the original submission error still propagates", async () => {
  const f = fixture([fileField("front")]);
  await f.ready;
  const cleanupError = new Error("discard refused");
  const discard: FormFileStoragePort["discard"] = async () => { throw cleanupError; };
  const outbox: SubmitFormDeps["outbox"] = { enqueue: async () => { throw new Error("outbox failed"); } };
  await assert.rejects(submitForm({ deps: { ...f.deps, outbox, files: { ...f.files, discard } }, input: f.input({ front: photo }) }), { message: "outbox failed" });
  assert.deepEqual(f.warnings, [{ message: "form upload cleanup failed", error: cleanupError }]);
});

test("submitForm: a throwing logger during upload cleanup cannot replace the original submission error", async () => {
  const f = fixture([fileField("front")]);
  await f.ready;
  const discard: FormFileStoragePort["discard"] = async () => { throw new Error("discard refused"); };
  const outbox: SubmitFormDeps["outbox"] = { enqueue: async () => { throw new Error("outbox failed"); } };
  const logger: SubmitFormDeps["logger"] = { warn: () => { throw new Error("logger down"); } };
  await assert.rejects(submitForm({ deps: { ...f.deps, outbox, logger, files: { ...f.files, discard } }, input: f.input({ front: photo }) }), { message: "outbox failed" });
});

test("submitForm: with attempts, the _attempt token is stripped before validation and never stored", async () => {
  const f = fixture([textField]);
  await f.ready;
  const attempts = createSubmissionAttempts({ hash: (value) => value });
  await submitForm({ deps: f.deps, input: f.input({ name: "Ada", _attempt: "tok" }) }, { attempts });
  assert.deepEqual((await f.rows()).map((row) => row.data), [{ name: "Ada" }]);
});

test("submitForm: without attempts, an _attempt key is an unregistered field", async () => {
  const f = fixture([textField]);
  await f.ready;
  await assert.rejects(submitForm({ deps: f.deps, input: f.input({ name: "Ada", _attempt: "tok" }) }), (error: unknown) => {
    assert.ok(error instanceof FormSubmissionValidationError);
    assert.deepEqual(error.fieldErrors, [{ field: "_attempt", reason: "unregistered_key" }]);
    return true;
  });
});

test("submitForm: a duplicate attempt is accepted without a second row, event or dispatch", async () => {
  const f = fixture([textField]);
  await f.ready;
  const attempts = createSubmissionAttempts({ hash: (value) => value });
  await submitForm({ deps: f.deps, input: f.input({ name: "Ada", _attempt: "tok" }) }, { attempts });
  assert.deepEqual(await submitForm({ deps: f.deps, input: f.input({ name: "Ada", _attempt: "tok" }) }, { attempts }), { status: "accepted" });
  await settle();
  assert.deepEqual([(await f.rows()).length, f.events(), f.dispatches()], [1, 1, 1]);
});

test("submitForm: different attempt tokens for the same body each store a row", async () => {
  const f = fixture([textField]);
  await f.ready;
  const attempts = createSubmissionAttempts({ hash: (value) => value });
  await submitForm({ deps: f.deps, input: f.input({ name: "Ada", _attempt: "one" }) }, { attempts });
  await submitForm({ deps: f.deps, input: f.input({ name: "Ada", _attempt: "two" }) }, { attempts });
  assert.equal((await f.rows()).length, 2);
});

test("submitForm: the definition view replaces the stored definition for validation", async () => {
  const f = fixture([textField]);
  await f.ready;
  const definitionView = () => definition([{ ...textField, id: "nickname" }]);
  await submitForm({ deps: f.deps, input: f.input({ nickname: "Ada" }) }, { definitionView });
  assert.deepEqual((await f.rows()).map((row) => row.data), [{ nickname: "Ada" }]);
});

test("submitForm: a definition view that disables the form answers not found", async () => {
  const f = fixture([textField]);
  await f.ready;
  const definitionView = () => definition([textField], "disabled");
  await assert.rejects(submitForm({ deps: f.deps, input: f.input({ name: "Ada" }) }, { definitionView }), (error: unknown) => {
    assert.ok(error instanceof FormDefinitionNotFoundError);
    assert.equal(error.message, "form 'form' was not found");
    return true;
  });
});

test("submitForm: a missing slug answers not found even with the definition view and email checks enabled", async () => {
  const f = fixture([textField]);
  await f.ready;
  let viewed = 0;
  const definitionView = ({ definition: stored }: { definition: FormDefinitionRecord }) => { viewed += 1; return stored; };
  await assert.rejects(submitForm({ deps: f.deps, input: { ...f.input({ name: "Ada" }), slug: "nope" } }, { definitionView, validateEmails: true }), { message: "form 'nope' was not found" });
  assert.equal(viewed, 0);
});

test("submitForm: validateEmails refuses an invalid email on an active form", async () => {
  const f = fixture([{ id: "email", label: "Email", type: "email", required: true }]);
  await f.ready;
  await assert.rejects(submitForm({ deps: f.deps, input: f.input({ email: "bad" }) }, { validateEmails: true }), (error: unknown) => {
    assert.ok(error instanceof FormSubmissionValidationError);
    assert.deepEqual(error.fieldErrors, [{ field: "email", reason: "invalid_email" }]);
    return true;
  });
});

test("submitForm: disabled and missing forms remain indistinguishable with email checks enabled", async () => {
  const f = fixture([{ id: "email", label: "Email", type: "email", required: true }], "disabled");
  await f.ready;
  for (const slug of ["form", "missing"]) {
    await assert.rejects(submitForm({ deps: f.deps, input: { ...f.input({ email: "bad" }), slug } }, { validateEmails: true }), (error: unknown) => {
      assert.ok(error instanceof FormDefinitionNotFoundError);
      assert.equal(error.message, `form '${slug}' was not found`);
      return true;
    });
  }
  assert.deepEqual(await f.rows(), []);
  assert.equal(f.events(), 0);
});

test("submitForm: a rate-limit refusal names the form and carries retryAfterSeconds", async () => {
  const f = fixture([textField]);
  await f.ready;
  const rateLimiter: SubmitFormDeps["rateLimiter"] = { check: async () => ({ allowed: false, retryAfterSeconds: 7 }) };
  await assert.rejects(submitForm({ deps: { ...f.deps, rateLimiter }, input: f.input({ name: "Ada" }) }), (error: unknown) => {
    assert.ok(error instanceof FormRateLimitExceededError);
    assert.equal(error.message, "rate limit exceeded for form 'form'");
    assert.equal(error.retryAfterSeconds, 7);
    return true;
  });
});

test("submitForm: the dispatch option replaces the bound dispatcher", async () => {
  const f = fixture([textField]);
  await f.ready;
  let custom = 0;
  await submitForm({ deps: f.deps, input: f.input({ name: "Ada" }) }, { dispatch: async () => { custom += 1; } });
  await settle();
  assert.deepEqual([custom, f.dispatches()], [1, 0]);
});

test("submitForm: a failing dispatch is logged and never rejects the accepted submission", async () => {
  const f = fixture([textField]);
  await f.ready;
  const dispatchError = new Error("smtp down");
  assert.deepEqual(await submitForm({ deps: f.deps, input: f.input({ name: "Ada" }) }, { dispatch: async () => { throw dispatchError; } }), { status: "accepted" });
  await settle();
  assert.deepEqual(f.warnings, [{ message: "form outbox dispatch failed", error: dispatchError }]);
});

test("submitForm: a throwing logger on dispatch failure is swallowed", async () => {
  const f = fixture([textField]);
  await f.ready;
  const logger: SubmitFormDeps["logger"] = { warn: () => { throw new Error("logger down"); } };
  const result = await submitForm({ deps: { ...f.deps, logger }, input: f.input({ name: "Ada" }) }, { dispatch: async () => { throw new Error("smtp down"); } });
  await settle();
  assert.deepEqual(result, { status: "accepted" });
});

src/widgets/__tests__/integration/resolv.source:
import assert from "node:assert/strict";
import test from "../support/test-runner.js";

import { InMemoryEntryRepo } from "../../../entries/index.js";
import { buildWidgetAreaFieldsJson, buildWidgetInstanceFieldsJson } from "../support/compat/entry-payload.js";
import { CORE_RESOLVERS, resolveWidgetType } from "../../resolvers/index.js";
import { resolvePageWidgets } from "../../resolver-service.js";
import { InMemoryWidgetRegionBindingRepo } from "../../repo.memory.js";
import { WIDGET_AREA_CONTENT_TYPE, WIDGET_CONTENT_TYPE } from "../../types.js";
import type { WidgetInstanceView, WidgetResolveContext, WidgetResolveResult, WidgetResolver } from "../../types.js";

/**
 * @file C-003/C-004 the resolution pipeline — SPEC-043 REQ-23..28, AC-16..20, INV-05.
 * TDD-certified against the stubs in `resolvers/index.ts`/`resolver-service.ts`; currently RED —
 * these assertions describe the real contract, not current behavior. These are the tests the
 * ADR-047 debate's convergence on batch-first resolution (answering agy's Round 1 N+1 blind-spot
 * question) and failure isolation (the Primary's pre-dispatch structural-gap flag, corroborated
 * by Codex) exist specifically to prove.
 */

const WORKSPACE_ID = "ws-1";
const CTX: WidgetResolveContext = { workspaceId: WORKSPACE_ID, preview: false };

function instance(overrides: Partial<WidgetInstanceView> & Pick<WidgetInstanceView, "id" | "widgetType">): WidgetInstanceView {
  return { config: {}, ...overrides };
}

/** A resolver test double that counts how many times resolveMany is called, for the batching assertion. */
function countingResolver(result: WidgetResolveResult): { resolver: WidgetResolver; callCount: () => number } {
  let calls = 0;
  return {
    resolver: {
      async resolveMany(instances) {
        calls += 1;
        return new Map(instances.map((i) => [i.id, result]));
      },
    },
    callCount: () => calls,
  };
}

function replaceRecentEntriesResolver(t: import("../support/test-runner.js").TestContext, resolver: WidgetResolver): void {
  const hadResolver = Object.hasOwn(CORE_RESOLVERS, "recent-entries");
  const original = CORE_RESOLVERS["recent-entries"];
  t.after(() => {
    if (hadResolver) {
      // @ts-expect-error — restore the readonly map's existing test-double seam.
      CORE_RESOLVERS["recent-entries"] = original;
    } else {
      // @ts-expect-error — restore absence as well as values.
      delete CORE_RESOLVERS["recent-entries"];
    }
  });
  // @ts-expect-error — readonly at the type level; deliberately mutable at runtime.
  CORE_RESOLVERS["recent-entries"] = resolver;
}

test("AC-16/REQ-24: resolving 5 instances of the same type via resolveWidgetType invokes the registered resolver's resolveMany exactly once, not 5 times", async (t) => {
  const { resolver, callCount } = countingResolver({
    ok: true,
    ir: { componentId: "recent-entries", props: {} },
    dependencyKeys: [],
  });
  replaceRecentEntriesResolver(t, resolver);

  const instances = Array.from({ length: 5 }, (_, i) => instance({ id: `w-${i}`, widgetType: "recent-entries" }));
  const results = await resolveWidgetType({ typeKey: "recent-entries", instances, context: CTX });

  assert.equal(callCount(), 1, "resolveMany must be called exactly once for a batch of same-type instances");
  assert.equal(results.size, 5);
});

test("AC-17/REQ-25: an instance configured above the type's registered clamp is capped at the registered value in the resolved result — defense-in-depth at the orchestration layer, independent of the resolver's own discipline (Round-2 external-audit fix, 2026-07-21, Opus 4.8 finding WIDGETS-R2-L1: this assertion was previously a no-op stub)", async (t) => {
  // A rogue resolver that deliberately ignores REQ-25's clamp itself — proves clampResolveResult
  // (resolvers/index.ts) enforces the registered maxItems (20) regardless, not just the resolver's
  // own well-behaved implementation (recent-entries.ts already clamps correctly; this test would not
  // catch a regression there being masked by the orchestration layer, which is exactly the gap).
  const rogueResolver: WidgetResolver = {
    async resolveMany(instances) {
      return new Map(
        instances.map((i) => [
          i.id,
          {
            ok: true as const,
            ir: { componentId: "recent-entries", props: {}, children: Array.from({ length: 30 }, (_, n) => ({ componentId: "entry-summary", props: { title: `E${n}` } })) },
            dependencyKeys: [],
          },
        ])
      );
    },
  };
  replaceRecentEntriesResolver(t, rogueResolver);

  const results = await resolveWidgetType({
    typeKey: "recent-entries",
    instances: [instance({ id: "w-1", widgetType: "recent-entries", config: { maxItems: 500 } })],
    context: CTX,
  });

  const result = results.get("w-1");
  assert.ok(result?.ok);
  if (result.ok) {
    assert.equal(result.ir.children?.length, 20, "clampResolveResult must cap at the registered clamp (20) even when the resolver itself returns 30 and the instance config asks for 500");
  }
});

test("AC-19/INV-05: an uncaught resolver exception is isolated — resolveWidgetType never throws, it returns a typed failure", async (t) => {
  const throwingResolver: WidgetResolver = {
    async resolveMany() {
      throw new Error("simulated resolver crash");
    },
  };
  replaceRecentEntriesResolver(t, throwingResolver);

  const results = await resolveWidgetType({
    typeKey: "recent-entries",
    instances: [instance({ id: "w-crash", widgetType: "recent-entries" })],
    context: CTX,
  });

  const result = results.get("w-crash");
  assert.ok(result);
  assert.equal(result?.ok, false, "a throwing resolver must yield a typed failure, never propagate");
  if (!result?.ok) {
    assert.equal(result.reason, "resolver-error");
  }
});

test("REQ-27: an unknown widget type resolves to a typed unknown-type failure, never an unhandled exception", async () => {
  const results = await resolveWidgetType({
    // @ts-expect-error — deliberately an unregistered type key.
    typeKey: "carousel",
    // @ts-expect-error — the same deliberately unregistered type key, on the instance.
    instances: [instance({ id: "w-1", widgetType: "carousel" })],
    context: CTX,
  });

  const result = results.get("w-1");
  assert.equal(result?.ok, false);
  if (!result?.ok) {
    assert.equal(result.reason, "unknown-type");
  }
});

test("a hung batch times out at 500ms and returns a typed timeout for every instance", { timeout: 2000 }, async (t) => {
  t.mock.timers.enable({ apis: ["setTimeout"] });
  replaceRecentEntriesResolver(t, { resolveMany: () => new Promise(() => undefined) });
  let settled = false;
  const pending = resolveWidgetType({
    typeKey: "recent-entries",
    instances: [instance({ id: "hung-a", widgetType: "recent-entries" }), instance({ id: "hung-b", widgetType: "recent-entries" })],
    context: CTX,
  }).then((result) => { settled = true; return result; });
  t.mock.timers.tick(499);
  await Promise.resolve();
  assert.equal(settled, false);
  t.mock.timers.tick(1);
  assert.deepEqual(Array.from(await pending), [
    ["hung-a", { ok: false, reason: "timeout" }],
    ["hung-b", { ok: false, reason: "timeout" }],
  ]);
});

test("AC-16/REQ-23: resolvePageWidgets assembles resolved IR for every declared region on a page", async () => {
  const bindingRepo = new InMemoryWidgetRegionBindingRepo();
  const entryRepo = new InMemoryEntryRepo();
  const at = "2026-07-21T00:00:00.000Z";
  // Save in a different order from the placements to prove the area controls ordering.
  for (const id of ["second", "disabled", "first"]) {
    await entryRepo.save({
      id, workspaceId: WORKSPACE_ID, type: WIDGET_CONTENT_TYPE, slug: id,
      status: "published", title: id, bodyJson: null,
      fieldsJson: buildWidgetInstanceFieldsJson({ widgetType: "text", config: { text: id }, status: "active" }),
      publishedAt: at, createdAt: at, updatedAt: at, version: 1,
    });
  }
  await entryRepo.save({
    id: "footer-area", workspaceId: WORKSPACE_ID, type: WIDGET_AREA_CONTENT_TYPE,
    slug: "widget-area-footer", status: "published", title: "Footer", bodyJson: null,
    fieldsJson: buildWidgetAreaFieldsJson({
      regionKey: "footer",
      doc: { schemaVersion: 1, placements: [
        { placementId: "p1", widgetEntryId: "first", enabled: true },
        { placementId: "p2", widgetEntryId: "disabled", enabled: false },
        { placementId: "p3", widgetEntryId: "second", enabled: true },
      ] },
    }),
    publishedAt: at, createdAt: at, updatedAt: at, version: 1,
  });
  await bindingRepo.upsert({ workspaceId: WORKSPACE_ID, regionKey: "footer", areaEntryId: "footer-area", updatedAt: at });
  const { regions } = await resolvePageWidgets({
    deps: { bindingRepo, entryRepo },
    input: { workspaceId: WORKSPACE_ID, resolvedRegions: ["footer", "sidebar"] },
  });

  assert.ok("footer" in regions);
  assert.ok("sidebar" in regions);
  assert.deepEqual(regions.footer, [
    { componentId: "text", props: { text: "first" } },
    { componentId: "text", props: { text: "second" } },
  ]);
  assert.deepEqual(regions.sidebar, []);
});

test("2026-08-05 fix: a widgetEmbed node in a real page's pageBodyJson resolves to the widget's real IR, not the REQ-28 placeholder forever (the pageEntryId->EntryRepoPort.findById path this replaces could never reach a PostRecord's bodyJson)", async () => {
  const bindingRepo = new InMemoryWidgetRegionBindingRepo();
  const entryRepo = new InMemoryEntryRepo();

  await entryRepo.save({
    id: "text-widget-1",
    workspaceId: WORKSPACE_ID,
    type: WIDGET_CONTENT_TYPE,
    slug: "text-widget-1",
    status: "published",
    title: "Inline text widget",
    bodyJson: null,
    fieldsJson: buildWidgetInstanceFieldsJson({ widgetType: "text", config: { text: "Hello from inline widget" }, status: "active" }),
    publishedAt: "2026-08-05T00:00:00.000Z",
    createdAt: "2026-08-05T00:00:00.000Z",
    updatedAt: "2026-08-05T00:00:00.000Z",
    version: 1,
  });

  const pageBodyJson = {
