src/entries/__tests__/write-service.comp.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { VersionConflictError } from "../errors.js";
import { InMemoryEntryRepo } from "../repo.memory.js";
import { importEntry, publishEntry, unpublishEntry, updateEntry, type EntryRepoPort, type EntryRevisionInput } from "../write-service.js";
import type { EntryRecord } from "../types.js";

/**
 * @file Entry writes are compare-and-set (wm S3): the version check lives in the repo's `save`,
 * inside the write's own transaction, so two writers that read the same version cannot both land.
 * Covers `InMemoryEntryRepo.save`'s `expectedVersion` contract and every service save that passes it
 * (`updateEntry`, `publishEntry`/`unpublishEntry`, an import-as-update); a loss is the Result's
 * `VersionConflictError`, never a throw. An import-as-create passes `expectedVersion: null` (insert
 * only if the id is absent), so two creates of one id cannot both land either.
 */

const WS = "ws-1";
const NOW = "2026-10-04T00:00:00.000Z";
const clock = { nowMs: () => Date.parse(NOW) };
const alwaysAllow = async () => ({ allowed: true, reason: "matched" });
const activeType = { findByKey: async () => ({ workspaceId: WS, key: "recipe", status: "active" as const, fields: [] }) };

function entry(overrides: Partial<EntryRecord> = {}): EntryRecord {
  return { id: "entry-1", workspaceId: WS, type: "recipe", slug: "chili", status: "draft", title: "Chili", fieldsJson: { ext: { site: {} } }, bodyJson: null, publishedAt: null, createdAt: NOW, updatedAt: NOW, version: 1, ...overrides };
}

function fakeOutbox() {
  const events: Array<{ name: string }> = [];
  return { events, enqueue: async (event: { name: string }) => { events.push(event); } };
}

/** `InMemoryEntryRepo` that records revisions, and where another writer bumps `raceId` right after the service reads it. */
function racingRepo(seed: EntryRecord[], raceId: string | null) {
  const inner = new InMemoryEntryRepo();
  const revisions: EntryRevisionInput[] = [];
  const repo: EntryRepoPort = {
    findBySlug: (params) => inner.findBySlug(params),
    findById: async (params) => {
      const row = await inner.findById(params);
      if (row && row.id === raceId) await inner.save({ ...row, title: "Other writer", version: row.version + 1 });
      return row;
    },
    save: (row, options) => inner.save(row, options),
    appendRevision: async (revision) => {
      revisions.push(revision);
    },
    transaction: (required) => inner.transaction(required),
  };
  return { inner, repo, revisions, seeded: Promise.all(seed.map((row) => inner.save(row))) };
}

function assertLost(result: { ok: boolean; error?: unknown }, message: string): void {
  assert.equal(result.ok, false);
  assert.ok(result.error instanceof VersionConflictError);
  assert.equal(result.error.message, message);
}

test("InMemoryEntryRepo.save with a matching expectedVersion writes the row", async () => {
  const repo = new InMemoryEntryRepo();
  await repo.save(entry());
  await repo.save(entry({ title: "New", version: 2 }), { expectedVersion: 1 });
  assert.deepEqual(await repo.findById({ workspaceId: WS, id: "entry-1" }), entry({ title: "New", version: 2 }));
});

test("InMemoryEntryRepo.save with a stale expectedVersion throws and leaves the row as it was", async () => {
  const repo = new InMemoryEntryRepo();
  await repo.save(entry({ version: 2 }));
  await assert.rejects(
    () => repo.save(entry({ title: "Stale", version: 2 }), { expectedVersion: 1 }),
    (error: unknown) => error instanceof VersionConflictError && error.message === "expected version 1 for entry 'entry-1', found 2"
  );
  assert.equal((await repo.findById({ workspaceId: WS, id: "entry-1" }))?.title, "Chili");
});

test("InMemoryEntryRepo.save with an expectedVersion finds none for a missing or other-workspace row", async () => {
  const repo = new InMemoryEntryRepo();
  await repo.save(entry({ id: "foreign", workspaceId: "ws-2" }));
  for (const id of ["missing", "foreign"]) {
    await assert.rejects(
      () => repo.save(entry({ id, version: 2 }), { expectedVersion: 1 }),
      (error: unknown) => error instanceof VersionConflictError && error.message === `expected version 1 for entry '${id}', found none`
    );
  }
  assert.equal(await repo.findById({ workspaceId: WS, id: "missing" }), null);
  assert.equal((await repo.findById({ workspaceId: "ws-2", id: "foreign" }))?.version, 1);
});

test("InMemoryEntryRepo.save with expectedVersion null inserts an absent id and refuses a taken one in any workspace", async () => {
  const repo = new InMemoryEntryRepo();
  await repo.save(entry(), { expectedVersion: null });
  await repo.save(entry({ id: "foreign", workspaceId: "ws-2", version: 4 }));
  for (const [id, found] of [["entry-1", 1], ["foreign", 4]] as const) {
    await assert.rejects(
      () => repo.save(entry({ id, title: "Second" }), { expectedVersion: null }),
      (error: unknown) => error instanceof VersionConflictError && error.message === `expected no entry '${id}', found ${found}`
    );
  }
  assert.equal((await repo.findById({ workspaceId: WS, id: "entry-1" }))?.title, "Chili");
  assert.deepEqual([(await repo.findById({ workspaceId: "ws-2", id: "foreign" }))?.title, await repo.findById({ workspaceId: WS, id: "foreign" })], ["Chili", null]);
});

test("two concurrent import-as-creates of one id: exactly one lands — one row, one revision, one event", async () => {
  const { inner, repo, revisions, seeded } = racingRepo([], null);
  await seeded;
  const outbox = fakeOutbox();
  const create = (title: string) =>
    importEntry({
      deps: { entryRepo: repo, contentTypeRepo: activeType, clock, authorize: alwaysAllow, outbox },
      input: { workspaceId: WS, actorId: "user-1", id: "entry-1", type: "recipe", slug: "chili", title, status: "published", fieldsJson: { ext: { site: {} } }, publishedAt: NOW, expectedVersion: undefined },
    });
  const results = await Promise.all([create("First"), create("Second")]);

  assert.deepEqual(results.map((result) => result.ok), [true, false]);
  assertLost(results[1]!, "expected no entry 'entry-1', found 1");
  const stored = await inner.findById({ workspaceId: WS, id: "entry-1" });
  assert.deepEqual([stored?.title, stored?.version], ["First", 1]);
  assert.deepEqual(revisions.map((revision) => revision.op), ["create"], "the losing create appends no revision");
  assert.deepEqual(outbox.events.map((event) => event.name), ["entry.imported"]);
});

test("two concurrent updateEntry calls on the same base version: exactly one wins, the other gets a version conflict", async () => {
  const { inner, repo, revisions, seeded } = racingRepo([entry()], null);
  await seeded;
  const outbox = fakeOutbox();
  const edit = (title: string) =>
    updateEntry({ deps: { entryRepo: repo, contentTypeRepo: activeType, clock, authorize: alwaysAllow, outbox }, input: { workspaceId: WS, actorId: "user-1", id: "entry-1", title, expectedVersion: 1 } });
  const results = await Promise.all([edit("First"), edit("Second")]);

  assert.deepEqual(results.map((result) => result.ok), [true, false]);
  assertLost(results[1]!, "expected version 1 for entry 'entry-1', found 2");
  const stored = await inner.findById({ workspaceId: WS, id: "entry-1" });
  assert.deepEqual([stored?.title, stored?.version], ["First", 2]);
  assert.equal(revisions.length, 1, "the losing write appends no revision");
  assert.deepEqual(outbox.events.map((event) => event.name), ["entry.updated"]);
});

test("updateEntry loses to a writer that lands between its read and its save — no revision, no event", async () => {
  const { inner, repo, revisions, seeded } = racingRepo([entry()], "entry-1");
  await seeded;
  const outbox = fakeOutbox();
  const result = await updateEntry({
    deps: { entryRepo: repo, contentTypeRepo: activeType, clock, authorize: alwaysAllow, outbox },
    input: { workspaceId: WS, actorId: "user-1", id: "entry-1", title: "Mine", expectedVersion: 1 },
  });
  assertLost(result, "expected version 1 for entry 'entry-1', found 2");
  assert.equal((await inner.findById({ workspaceId: WS, id: "entry-1" }))?.title, "Other writer");
  assert.deepEqual([revisions, outbox.events], [[], []]);
});

test("updateEntry with a stale expectedVersion is the save's version conflict", async () => {
  const { inner, repo, seeded } = racingRepo([entry({ version: 3 })], null);
  await seeded;
  const result = await updateEntry({
    deps: { entryRepo: repo, contentTypeRepo: activeType, clock, authorize: alwaysAllow, outbox: fakeOutbox() },
    input: { workspaceId: WS, actorId: "user-1", id: "entry-1", title: "Clobbered", expectedVersion: 1 },
  });
  assertLost(result, "expected version 1 for entry 'entry-1', found 3");
  assert.equal((await inner.findById({ workspaceId: WS, id: "entry-1" }))?.title, "Chili");
});

test("publishEntry and unpublishEntry lose to a writer that lands between their read and their save", async () => {
  for (const transition of [publishEntry, unpublishEntry]) {
    const { inner, repo, revisions, seeded } = racingRepo([entry()], "entry-1");
    await seeded;
    const outbox = fakeOutbox();
    const result = await transition({
      deps: { entryRepo: repo, contentTypeRepo: activeType, clock, authorize: alwaysAllow, outbox },
      input: { workspaceId: WS, actorId: "user-1", id: "entry-1", expectedVersion: 1 },
    });
    assertLost(result, "expected version 1 for entry 'entry-1', found 2");
    assert.equal((await inner.findById({ workspaceId: WS, id: "entry-1" }))?.status, "draft");
    assert.deepEqual([revisions, outbox.events], [[], []]);
  }
});

test("an import-as-update loses to a writer that lands between its read and its save", async () => {
  const { inner, repo, revisions, seeded } = racingRepo([entry({ version: 2 })], "entry-1");
  await seeded;
  const result = await importEntry({
    deps: { entryRepo: repo, contentTypeRepo: activeType, clock, authorize: alwaysAllow, outbox: fakeOutbox() },
    input: { workspaceId: WS, actorId: "user-1", id: "entry-1", type: "recipe", slug: "chili", title: "Imported", status: "published", fieldsJson: { ext: { site: {} } }, publishedAt: NOW, expectedVersion: 2 },
  });
  assertLost(result, "expected version 2 for entry 'entry-1', found 3");
  assert.equal((await inner.findById({ workspaceId: WS, id: "entry-1" }))?.title, "Other writer");
  assert.deepEqual(revisions, []);
});

test("updateEntry, publishEntry and unpublishEntry refuse a basis other than the version they read, even when a racing writer makes the save's compare-and-set match", async () => {
  const edits = [
    (deps: Parameters<typeof updateEntry>[0]["deps"]) => updateEntry({ deps, input: { workspaceId: WS, actorId: "user-1", id: "entry-1", title: "Mine", expectedVersion: 2 } }),
    (deps: Parameters<typeof updateEntry>[0]["deps"]) => publishEntry({ deps, input: { workspaceId: WS, actorId: "user-1", id: "entry-1", expectedVersion: 2 } }),
    (deps: Parameters<typeof updateEntry>[0]["deps"]) => unpublishEntry({ deps, input: { workspaceId: WS, actorId: "user-1", id: "entry-1", expectedVersion: 2 } }),
  ];
  for (const edit of edits) {
    // The service reads version 1; the other writer then lands version 2, the version this caller claims.
    const { inner, repo, revisions, seeded } = racingRepo([entry()], "entry-1");
    await seeded;
    const outbox = fakeOutbox();
    const result = await edit({ entryRepo: repo, contentTypeRepo: activeType, clock, authorize: alwaysAllow, outbox });
    assertLost(result, "expected version 2 for entry 'entry-1', found 1");
    const stored = await inner.findById({ workspaceId: WS, id: "entry-1" });
    assert.deepEqual([stored?.title, stored?.status, stored?.version], ["Other writer", "draft", 2], "the other writer's version 2 is not overwritten by a record built from version 1");
    assert.deepEqual([revisions, outbox.events], [[], []]);
  }
});

test("an import-as-update refuses a basis other than the version it read, even when a racing writer makes the save's compare-and-set match", async () => {
  const { inner, repo, revisions, seeded } = racingRepo([entry()], "entry-1");
  await seeded;
  const result = await importEntry({
    deps: { entryRepo: repo, contentTypeRepo: activeType, clock, authorize: alwaysAllow, outbox: fakeOutbox() },
    input: { workspaceId: WS, actorId: "user-1", id: "entry-1", type: "recipe", slug: "chili", title: "Imported", status: "published", fieldsJson: { ext: { site: {} } }, publishedAt: NOW, expectedVersion: 2 },
  });
  assertLost(result, "expected version 2 for entry 'entry-1', found 1");
  const stored = await inner.findById({ workspaceId: WS, id: "entry-1" });
  assert.deepEqual([stored?.title, stored?.version], ["Other writer", 2]);
  assert.deepEqual(revisions, []);
});

test("an error other than a version conflict thrown inside the write still propagates", async () => {
  const { repo, seeded } = racingRepo([entry()], null);
  await seeded;
  await assert.rejects(
    () =>
      updateEntry({
        deps: { entryRepo: repo, contentTypeRepo: activeType, clock, authorize: alwaysAllow, outbox: fakeOutbox(), onWritten: async () => { throw new Error("extractor failed"); } },
        input: { workspaceId: WS, actorId: "user-1", id: "entry-1", title: "Mine", expectedVersion: 1 },
      }),
    /^Error: extractor failed$/
  );
});

src/navigation/__tests__/menu-service.co.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import type { DomainEvent, OutboxPort } from "../../core/ports.js";
import { assignLocation, createMenu, deleteMenu, MenuConflictError, MenuVersionConflictError, updateMenuTree } from "../menu-service.js";
import { InMemoryMenuRepo, InMemoryNavLocationBindingRepo, type MenuRepoPort } from "../repo.memory.js";
import type { NavMenuEntry } from "../types.js";

/**
 * @file Menu writes are compare-and-set (wm S4): the version check lives in the repo's `save`, so
 * two writers that read the same version cannot both land. Covers `InMemoryMenuRepo.save`'s
 * `expectedVersion` contract and the three service saves that pass it (`updateMenuTree` and both
 * `assignLocation` saves).
 */

const WS = "ws-1";

function fakeClock() {
  return { nowMs: () => Date.parse("2026-10-04T00:00:00.000Z") };
}

function fakeIdGen() {
  let counter = 0;
  return { newId: () => `id-${++counter}` };
}

function fakeOutbox(): { outbox: OutboxPort; enqueued: DomainEvent[] } {
  const enqueued: DomainEvent[] = [];
  return {
    enqueued,
    outbox: {
      enqueue: async (event) => {
        enqueued.push(event);
      },
      claimPending: async () => [],
      markDelivered: async () => {},
      markFailed: async () => {},
    },
  };
}

function menuRow(overrides: Partial<NavMenuEntry> = {}): NavMenuEntry {
  return {
    id: "menu-1",
    workspaceId: WS,
    slug: "primary-nav",
    title: "Primary Nav",
    status: "published",
    doc: { type: "menu", version: 1, items: [] },
    locations: [],
    updatedAt: "2026-10-04T00:00:00.000Z",
    version: 1,
    ...overrides,
  };
}

/** A repo where another writer bumps `raceId`'s stored version right after the service reads it. */
function racingRepo(inner: InMemoryMenuRepo, raceId: string): MenuRepoPort {
  return {
    findById: async (required) => {
      const row = await inner.findById(required);
      if (row && row.id === raceId) await inner.save({ ...row, title: "Other writer", version: row.version + 1 });
      return row;
    },
    findBySlug: (required) => inner.findBySlug(required),
    list: (required) => inner.list(required),
    save: (record, options) => inner.save(record, options),
    remove: (required) => inner.remove(required),
    transaction: (required) => inner.transaction(required),
  };
}

/** `repo` whose `transaction` rolls `inner`'s workspace rows back when `fn` throws, as a SQL adapter's
 *  does — so a test can tell a unit that ran inside one transaction from one that did not. */
function rollingBack(inner: InMemoryMenuRepo, repo: MenuRepoPort): MenuRepoPort {
  return {
    ...repo,
    transaction: async ({ fn }) => {
      const before = await inner.list({ workspaceId: WS });
      try {
        return await fn();
      } catch (error) {
        for (const row of await inner.list({ workspaceId: WS })) await inner.remove({ workspaceId: WS, id: row.id });
        for (const row of before) await inner.save(row);
        throw error;
      }
    },
  };
}

test("InMemoryMenuRepo.save with a matching expectedVersion writes the row", async () => {
  const repo = new InMemoryMenuRepo({}, { initialRows: [menuRow()] });
  await repo.save(menuRow({ title: "New", version: 2 }), { expectedVersion: 1 });
  assert.deepEqual(await repo.findById({ workspaceId: WS, id: "menu-1" }), menuRow({ title: "New", version: 2 }));
});

test("InMemoryMenuRepo.save with a stale expectedVersion throws and leaves the row as it was", async () => {
  const repo = new InMemoryMenuRepo({}, { initialRows: [menuRow({ version: 2 })] });
  await assert.rejects(
    () => repo.save(menuRow({ title: "Stale", version: 2 }), { expectedVersion: 1 }),
    (error: unknown) =>
      error instanceof MenuConflictError &&
      error.message === "menu 'menu-1' was modified concurrently (expected version 1, found 2)"
  );
  assert.deepEqual(await repo.findById({ workspaceId: WS, id: "menu-1" }), menuRow({ version: 2 }));
});

test("InMemoryMenuRepo.save with an expectedVersion finds none for a missing or trashed row", async () => {
  const repo = new InMemoryMenuRepo({}, { initialRows: [menuRow({ id: "trashed", status: "trash" }), menuRow({ id: "other-ws", workspaceId: "ws-2" })] });
  for (const id of ["missing", "trashed", "other-ws"]) {
    await assert.rejects(
      () => repo.save(menuRow({ id, version: 2 }), { expectedVersion: 1 }),
      (error: unknown) =>
        error instanceof MenuConflictError &&
        error.message === `menu '${id}' was modified concurrently (expected version 1, found none)`
    );
  }
  assert.equal(await repo.findById({ workspaceId: WS, id: "missing" }), null);
  assert.equal((await repo.findById({ workspaceId: WS, id: "trashed" }))?.status, "trash");
});

test("two concurrent updateMenuTree calls on the same base version: exactly one wins, the other gets a version conflict", async () => {
  const repo = new InMemoryMenuRepo({});
  const { outbox, enqueued } = fakeOutbox();
  const deps = { repo, clock: fakeClock(), idGen: fakeIdGen(), outbox };
  const { menu } = await createMenu({ deps, input: { workspaceId: WS, title: "Primary Nav", slug: "primary-nav" } });
  enqueued.length = 0;

  const edit = (label: string) =>
    updateMenuTree({
      deps,
      input: { workspaceId: WS, id: menu.id, expectedVersion: 1, items: [{ id: label, label, target: { kind: "url", href: "/" } }] },
    });
  const results = await Promise.allSettled([edit("first"), edit("second")]);

  const won = results.filter((result) => result.status === "fulfilled");
  const lost = results.filter((result): result is PromiseRejectedResult => result.status === "rejected");
  assert.equal(won.length, 1);
  assert.equal(lost.length, 1);
  assert.ok(lost[0]?.reason instanceof MenuConflictError);
  assert.equal(lost[0]?.reason.message, `menu '${menu.id}' was modified concurrently (expected version 1, found 2)`);
  const stored = await repo.findById({ workspaceId: WS, id: menu.id });
  assert.equal(stored?.version, 2);
  assert.deepEqual(stored?.doc.items.map((node) => node.id), ["first"]);
  assert.deepEqual(enqueued.map((event) => event.name), ["navigation.menu.updated"], "the losing write enqueues nothing");
});

test("updateMenuTree loses to a writer that lands between its read and its save", async () => {
  const inner = new InMemoryMenuRepo({}, { initialRows: [menuRow()] });
  const { outbox, enqueued } = fakeOutbox();
  await assert.rejects(
    () =>
      updateMenuTree({
        deps: { repo: racingRepo(inner, "menu-1"), clock: fakeClock(), idGen: fakeIdGen(), outbox },
        input: { workspaceId: WS, id: "menu-1", expectedVersion: 1, items: [] },
      }),
    (error: unknown) =>
      error instanceof MenuConflictError &&
      error.message === "menu 'menu-1' was modified concurrently (expected version 1, found 2)"
  );
  assert.equal((await inner.findById({ workspaceId: WS, id: "menu-1" }))?.title, "Other writer");
  assert.deepEqual(enqueued, []);
});

test("updateMenuTree refuses a basis other than the version it read, even when a racing writer makes the save's compare-and-set match", async () => {
  // The service reads version 1; the other writer then lands version 2, the version this caller claims.
  const inner = new InMemoryMenuRepo({}, { initialRows: [menuRow()] });
  const { outbox, enqueued } = fakeOutbox();
  await assert.rejects(
    () =>
      updateMenuTree({
        deps: { repo: racingRepo(inner, "menu-1"), clock: fakeClock(), idGen: fakeIdGen(), outbox },
        input: { workspaceId: WS, id: "menu-1", expectedVersion: 2, items: [] },
      }),
    (error: unknown) =>
      error instanceof MenuVersionConflictError &&
      error.message === "menu 'menu-1' was modified concurrently (expected version 2, found 1)"
  );
  const stored = await inner.findById({ workspaceId: WS, id: "menu-1" });
  assert.deepEqual([stored?.title, stored?.version], ["Other writer", 2]);
  assert.deepEqual(enqueued, []);
});

test("assignLocation's menu save loses to a writer that lands between its read and its save", async () => {
  const inner = new InMemoryMenuRepo({}, { initialRows: [menuRow()] });
  const bindingRepo = new InMemoryNavLocationBindingRepo({});
  const { outbox, enqueued } = fakeOutbox();
  await assert.rejects(
    () =>
      assignLocation({
        deps: { repo: racingRepo(inner, "menu-1"), bindingRepo, clock: fakeClock(), idGen: fakeIdGen(), outbox },
        input: { workspaceId: WS, menuId: "menu-1", locationKey: "primary" },
      }),
    (error: unknown) =>
      error instanceof MenuConflictError &&
      error.message === "menu 'menu-1' was modified concurrently (expected version 1, found 2)"
  );
  assert.deepEqual((await inner.findById({ workspaceId: WS, id: "menu-1" }))?.locations, []);
  assert.equal(await bindingRepo.findByLocation({ workspaceId: WS, locationKey: "primary" }), null);
  assert.deepEqual(enqueued, []);
});

test("assignLocation's displaced-menu save loses to a writer that lands between its read and its save", async () => {
  const inner = new InMemoryMenuRepo({}, {
    initialRows: [menuRow({ id: "displaced", slug: "displaced", locations: ["primary"] }), menuRow({ id: "incoming", slug: "incoming" })],
  });
  const bindingRepo = new InMemoryNavLocationBindingRepo({}, { initialRows: [{ workspaceId: WS, locationKey: "primary", menuId: "displaced", boundAt: "2026-10-04T00:00:00.000Z" }] });
  const { outbox } = fakeOutbox();
  await assert.rejects(
    () =>
      assignLocation({
        deps: { repo: racingRepo(inner, "displaced"), bindingRepo, clock: fakeClock(), idGen: fakeIdGen(), outbox },
        input: { workspaceId: WS, menuId: "incoming", locationKey: "primary" },
      }),
    (error: unknown) =>
      error instanceof MenuConflictError &&
      error.message === "menu 'displaced' was modified concurrently (expected version 1, found 2)"
  );
  const displaced = await inner.findById({ workspaceId: WS, id: "displaced" });
  assert.deepEqual([displaced?.title, displaced?.locations], ["Other writer", ["primary"]]);
  assert.deepEqual((await inner.findById({ workspaceId: WS, id: "incoming" }))?.locations, []);
});

test("assignLocation's menu save losing AFTER the displaced menu's save landed rolls both back: one transaction, no binding change, no events", async () => {
  const inner = new InMemoryMenuRepo({}, {
    initialRows: [menuRow({ id: "displaced", slug: "displaced", locations: ["primary"] }), menuRow({ id: "incoming", slug: "incoming" })],
  });
  const bindingRepo = new InMemoryNavLocationBindingRepo({}, { initialRows: [{ workspaceId: WS, locationKey: "primary", menuId: "displaced", boundAt: "2026-10-04T00:00:00.000Z" }] });
  const { outbox, enqueued } = fakeOutbox();
  await assert.rejects(
    () =>
      assignLocation({
        deps: { repo: rollingBack(inner, racingRepo(inner, "incoming")), bindingRepo, clock: fakeClock(), idGen: fakeIdGen(), outbox },
        input: { workspaceId: WS, menuId: "incoming", locationKey: "primary" },
      }),
    (error: unknown) =>
      error instanceof MenuVersionConflictError &&
      error.message === "menu 'incoming' was modified concurrently (expected version 1, found 2)"
  );
  const displaced = await inner.findById({ workspaceId: WS, id: "displaced" });
  assert.deepEqual([displaced?.locations, displaced?.version], [["primary"], 1], "the displaced menu keeps the key the binding still points at");
  assert.equal((await bindingRepo.findByLocation({ workspaceId: WS, locationKey: "primary" }))?.menuId, "displaced");
  assert.deepEqual(enqueued, []);
});

test("InMemoryMenuRepo.save with expectedVersion null inserts an absent id and refuses one held live, trashed or in another workspace", async () => {
  const repo = new InMemoryMenuRepo({}, {
    initialRows: [menuRow({ id: "trashed", slug: "trashed", status: "trash", version: 3 }), menuRow({ id: "foreign", workspaceId: "ws-2", version: 4 })],
  });
  await repo.save(menuRow(), { expectedVersion: null });
  for (const [id, found] of [["menu-1", 1], ["trashed", 3], ["foreign", 4]] as const) {
    await assert.rejects(
      () => repo.save(menuRow({ id, title: "Second" }), { expectedVersion: null }),
      (error: unknown) => error instanceof MenuVersionConflictError && error.message === `menu '${id}' already exists (expected no menu, found version ${found})`
    );
  }
  assert.equal((await repo.findById({ workspaceId: WS, id: "menu-1" }))?.title, "Primary Nav");
  assert.equal((await repo.findById({ workspaceId: "ws-2", id: "foreign" }))?.title, "Primary Nav");
  assert.equal(await repo.findById({ workspaceId: WS, id: "foreign" }), null);
});

test("deleteMenu's trash save stays unconditional", async () => {
  const inner = new InMemoryMenuRepo({}, { initialRows: [menuRow()] });
  const { menu } = await deleteMenu({
    deps: { repo: racingRepo(inner, "menu-1"), bindingRepo: new InMemoryNavLocationBindingRepo({}), clock: fakeClock(), idGen: fakeIdGen(), outbox: fakeOutbox().outbox },
    input: { workspaceId: WS, id: "menu-1" },
  });
  assert.equal(menu?.status, "trash");
  assert.equal((await inner.findById({ workspaceId: WS, id: "menu-1" }))?.status, "trash");
});

src/taxonomy/__tests__/write-service.bou.source:
import { describe, expect, it } from "vitest";

import {
  assignTerms,
  createTerm,
  deleteTerm,
  importTaxonomy,
  importTerm,
  renameTerm,
  ContentRecordNotFoundError,
  TaxonomyRecordNotFoundError,
  TaxonomyVersionConflictError,
  TermRecordNotFoundError,
} from "../write-service.js";
import type {
  ContentTypeTaxonomyPolicyPort,
  DeleteTermRequired,
  ImportTaxonomyRequired,
  ImportTermRequired,
  RenameTermRequired,
  Taxonomy,
  TaxonomyRevisionRow,
  Term,
  WriteServiceDeps,
} from "../write-service.js";
import { ParentCrossTaxonomyError, TaxonomyNotApplicableError, TermNotFoundError } from "../validation-chain.js";

/**
 * @file Boundary pins for the write-service branches the scenario suites don't reach: missing
 * taxonomy/parent/term lookups, the no-policy and Set-policy allow-list paths, the CAS refusals'
 * exact text, and each import's revision `previousState`. Every fake is typed against the real
 * port it stands in for.
 */

const NOW = "2026-07-15T00:00:00.000Z";

interface Harness {
  deps: WriteServiceDeps & ImportTaxonomyRequired["deps"] & ImportTermRequired["deps"] & DeleteTermRequired["deps"] & RenameTermRequired["deps"];
  taxonomies: Map<string, Taxonomy>;
  terms: Map<string, Term>;
  revisions: TaxonomyRevisionRow[];
  events: unknown[];
  lookups: string[];
}

function makeTaxonomy(id: string, hierarchical: boolean, version = 1): Taxonomy {
  return { id, name: `${id}-name`, hierarchical, status: "active", updatedAt: NOW, version };
}

function makeTerm(id: string, taxonomyId: string, parentId: string | null = null, version = 1): Term {
  return { id, taxonomyId, parentId, name: `${id}-name`, status: "active", updatedAt: NOW, version };
}

function harness(seed: { taxonomies?: Taxonomy[]; terms?: Term[]; policy?: ContentTypeTaxonomyPolicyPort } = {}): Harness {
  const taxonomies = new Map((seed.taxonomies ?? []).map((t) => [t.id, { ...t }]));
  const terms = new Map((seed.terms ?? []).map((t) => [t.id, { ...t }]));
  const revisions: TaxonomyRevisionRow[] = [];
  const events: unknown[] = [];
  const lookups: string[] = [];
  const deps: Harness["deps"] = {
    authorize: async () => ({ allowed: true, reason: "matched" }),
    clock: { nowMs: () => Date.parse(NOW) },
    idGen: { newId: () => "minted-id" },
    transaction: async <T>({ fn }: { fn: () => Promise<T> }): Promise<T> => fn(),
    taxonomies: {
      async findById({ id }) {
        const row = taxonomies.get(id);
        return row ? { id: row.id, hierarchical: row.hierarchical } : null;
      },
      async findByIdFull({ id }) {
        const row = taxonomies.get(id);
        return row ? { ...row } : null;
      },
      async insert(row) { taxonomies.set(row.id, { ...row }); },
      async update(row) { taxonomies.set(row.id, { ...row }); },
    },
    terms: {
      async findById({ id }) {
        const row = terms.get(id);
        return row ? { id: row.id, taxonomyId: row.taxonomyId, name: row.name } : null;
      },
      async findByIdFull({ id }) {
        const row = terms.get(id);
        return row ? { ...row } : null;
      },
      async insert(row) { terms.set(row.id, { ...row }); },
      async update(row) { terms.set(row.id, { ...row }); },
      async delete({ id }) { terms.delete(id); },
      async countChildren({ parentId }) { return [...terms.values()].filter((t) => t.parentId === parentId).length; },
    },
    entryTerms: {
      async upsert() { return undefined; },
      async countByTerm() { return 0; },
    },
    revisions: { async insert(row) { revisions.push(row); } },
    stampWatermark: () => undefined,
    outbox: { async enqueue({ event }) { events.push(event); } },
    workspaceId: "ws-1",
    contentLookup: {
      async resolve({ contentType, contentId }) {
        lookups.push(`${contentType}:${contentId}`);
        return contentId === "missing" ? null : { workspaceId: "ws-1", kind: contentType };
      },
    },
    ...(seed.policy ? { contentTypeTaxonomyPolicy: seed.policy } : {}),
  };
  return { deps, taxonomies, terms, revisions, events, lookups };
}

describe("createTerm boundaries", () => {
  it("refuses a missing taxonomy with TaxonomyRecordNotFoundError naming it", async () => {
    const h = harness();
    await expect(createTerm({ deps: h.deps, principalId: "u-1", taxonomyId: "tax-x", name: "n" }))
      .rejects.toStrictEqual(new TaxonomyRecordNotFoundError({ message: "taxonomy 'tax-x' was not found" }));
    expect(h.terms.size).toBe(0);
  });

  it("refuses a parentId that resolves to no term with TermNotFoundError", async () => {
    const h = harness({ taxonomies: [makeTaxonomy("tax-1", true)] });
    await expect(createTerm({ deps: h.deps, principalId: "u-1", taxonomyId: "tax-1", name: "n" }, { parentId: "ghost" }))
      .rejects.toStrictEqual(new TermNotFoundError({ message: "parent term 'ghost' was not found" }));
    expect(h.terms.size).toBe(0);
  });
});

describe("importTaxonomy boundaries", () => {
  it("records the pre-import name/hierarchical as the revision's previousState on an update", async () => {
    const h = harness({ taxonomies: [makeTaxonomy("tax-1", false, 4)] });
    await importTaxonomy({ deps: h.deps, principalId: "u-1", id: "tax-1", name: "renamed", hierarchical: true, expectedVersion: 4 });
    expect(h.revisions).toEqual([{ taxonomyId: "tax-1", op: "import", previousState: { name: "tax-1-name", hierarchical: false }, actorId: "u-1", recordedAt: NOW }]);
  });

  it("records a null previousState on an import-as-create", async () => {
    const h = harness();
    await importTaxonomy({ deps: h.deps, principalId: "u-1", id: "tax-new", name: "n", hierarchical: false, expectedVersion: undefined });
    expect(h.revisions[0]?.previousState).toBeNull();
  });

  it("names the found version in a mismatch refusal", async () => {
    const h = harness({ taxonomies: [makeTaxonomy("tax-1", false, 4)] });
    await expect(importTaxonomy({ deps: h.deps, principalId: "u-1", id: "tax-1", name: "n", hierarchical: false, expectedVersion: 3 }))
      .rejects.toStrictEqual(new TaxonomyVersionConflictError({ message: "expected version 3 for taxonomy 'tax-1', found 4" }));
  });
});

describe("importTerm boundaries", () => {
  it("refuses a missing owning taxonomy with the exact message before any term lookup", async () => {
    const h = harness();
    await expect(importTerm({ deps: h.deps, principalId: "u-1", id: "t-1", taxonomyId: "tax-x", name: "n", expectedVersion: undefined }))
      .rejects.toStrictEqual(new TaxonomyRecordNotFoundError({ message: "taxonomy 'tax-x' was not found" }));
  });

  it("imports a new term under an existing same-taxonomy parent at version 1", async () => {
    const h = harness({ taxonomies: [makeTaxonomy("tax-1", true)], terms: [makeTerm("p", "tax-1")] });
    const term = await importTerm({ deps: h.deps, principalId: "u-1", id: "t-1", taxonomyId: "tax-1", name: "n", expectedVersion: undefined }, { parentId: "p" });
    expect(term).toEqual({ id: "t-1", taxonomyId: "tax-1", parentId: "p", name: "n", status: "active", updatedAt: NOW, version: 1 });
  });

  it("refuses a parentId that resolves to no term with TermNotFoundError", async () => {
    const h = harness({ taxonomies: [makeTaxonomy("tax-1", true)] });
    await expect(importTerm({ deps: h.deps, principalId: "u-1", id: "t-1", taxonomyId: "tax-1", name: "n", expectedVersion: undefined }, { parentId: "ghost" }))
      .rejects.toStrictEqual(new TermNotFoundError({ message: "parent term 'ghost' was not found" }));
    expect(h.terms.size).toBe(0);
  });

  it("refuses a parent from another taxonomy with ParentCrossTaxonomyError", async () => {
    const h = harness({ taxonomies: [makeTaxonomy("tax-1", true)], terms: [makeTerm("p", "tax-2")] });
    await expect(importTerm({ deps: h.deps, principalId: "u-1", id: "t-1", taxonomyId: "tax-1", name: "n", expectedVersion: undefined }, { parentId: "p" }))
      .rejects.toStrictEqual(new ParentCrossTaxonomyError({ message: "parent term 'p' belongs to taxonomy 'tax-2', not 'tax-1'" }));
  });

  it("records the pre-import name/parentId as the revision's previousState on an update", async () => {
    const h = harness({ taxonomies: [makeTaxonomy("tax-1", true)], terms: [makeTerm("p", "tax-1"), makeTerm("t-1", "tax-1", null, 2)] });
    await importTerm({ deps: h.deps, principalId: "u-1", id: "t-1", taxonomyId: "tax-1", name: "n", expectedVersion: 2 }, { parentId: "p" });
    expect(h.revisions).toEqual([{ taxonomyId: "tax-1", op: "import", previousState: { name: "t-1-name", parentId: null }, actorId: "u-1", recordedAt: NOW }]);
    expect(h.terms.get("t-1")?.parentId).toBe("p");
  });

  it("records a null previousState and emits taxonomy.term_imported on an import-as-create", async () => {
    const h = harness({ taxonomies: [makeTaxonomy("tax-1", false)] });
    await importTerm({ deps: h.deps, principalId: "u-1", id: "t-1", taxonomyId: "tax-1", name: "n", expectedVersion: undefined });
    expect(h.revisions[0]?.previousState).toBeNull();
    expect(h.events).toEqual([{ name: "taxonomy.term_imported", termId: "t-1", actorId: "u-1", occurredAt: NOW }]);
  });

  it("names the existing term in an already-exists refusal", async () => {
    const h = harness({ taxonomies: [makeTaxonomy("tax-1", false)], terms: [makeTerm("t-1", "tax-1")] });
    await expect(importTerm({ deps: h.deps, principalId: "u-1", id: "t-1", taxonomyId: "tax-1", name: "n", expectedVersion: undefined }))
      .rejects.toStrictEqual(new TaxonomyVersionConflictError({ message: "term 't-1' already exists, but no expectedVersion was supplied for import" }));
  });
});

describe("renameTerm boundaries", () => {
  it("fails closed with a plain Error when the transaction port is absent at runtime", async () => {
    const h = harness({ terms: [makeTerm("t-1", "tax-1")] });
    Reflect.deleteProperty(h.deps, "transaction");
    await expect(renameTerm({ deps: h.deps, principalId: "u-1", termId: "t-1", newName: "x" }))
      .rejects.toStrictEqual(new Error("term rename requires a transaction port"));
    expect(h.terms.get("t-1")?.name).toBe("t-1-name");
  });

  it("refuses a missing term with TermRecordNotFoundError naming it", async () => {
    const h = harness();
    await expect(renameTerm({ deps: h.deps, principalId: "u-1", termId: "ghost", newName: "x" }))
      .rejects.toStrictEqual(new TermRecordNotFoundError({ message: "term 'ghost' was not found" }));
  });
});

describe("deleteTerm boundaries", () => {
  it("refuses a missing term with TermRecordNotFoundError naming it", async () => {
    const h = harness();
    await expect(deleteTerm({ deps: h.deps, principalId: "u-1", termId: "ghost" }))
      .rejects.toStrictEqual(new TermRecordNotFoundError({ message: "term 'ghost' was not found" }));
  });
});

describe("assignTerms allow-list boundaries", () => {
  it("treats a non-post/page contentType as unresolvable when no policy is wired: no lookup, TaxonomyNotApplicableError", async () => {
    const h = harness({ terms: [makeTerm("t-1", "tax-1")] });
    await expect(assignTerms({ deps: h.deps, principalId: "u-1", contentType: "recipes", contentId: "e-1", termIds: ["t-1"] }))
      .rejects.toStrictEqual(new TaxonomyNotApplicableError({ message: "taxonomy 'tax-1' is not on the allow-list for content type 'recipes'" }));
    expect(h.lookups).toEqual([]);
  });

  it("admits a term whose taxonomy is in the policy's Set", async () => {
    const h = harness({ terms: [makeTerm("t-1", "tax-1")], policy: { taxonomiesFor: async () => new Set(["tax-1"]) } });
    await assignTerms({ deps: h.deps, principalId: "u-1", contentType: "recipes", contentId: "e-1", termIds: ["t-1"] });
    expect(h.lookups).toEqual(["recipes:e-1"]);
    expect(h.events).toHaveLength(1);
  });

  it("refuses a term whose taxonomy is not in the policy's Set", async () => {
    const h = harness({ terms: [makeTerm("t-1", "tax-2")], policy: { taxonomiesFor: async () => new Set(["tax-1"]) } });
    await expect(assignTerms({ deps: h.deps, principalId: "u-1", contentType: "recipes", contentId: "e-1", termIds: ["t-1"] }))
      .rejects.toStrictEqual(new TaxonomyNotApplicableError({ message: "taxonomy 'tax-2' is not on the allow-list for content type 'recipes'" }));
  });

  it("refuses missing post content with ContentRecordNotFoundError before any term lookup", async () => {
    const h = harness();
    await expect(assignTerms({ deps: h.deps, principalId: "u-1", contentType: "post", contentId: "missing", termIds: ["ghost"] }))
      .rejects.toStrictEqual(new ContentRecordNotFoundError({ message: "content 'post:missing' was not found" }));
  });

  it("refuses an unknown term with TermRecordNotFoundError naming it", async () => {
    const h = harness();
    await expect(assignTerms({ deps: h.deps, principalId: "u-1", contentType: "post", contentId: "p-1", termIds: ["ghost"] }))
      .rejects.toStrictEqual(new TermRecordNotFoundError({ message: "term 'ghost' was not found" }));
  });
});

src/widgets/__tests__/unit/resolvers-rec.source:
import assert from "node:assert/strict";
import test from "../support/test-runner.js";

import type { ContentTypeRecord } from "../../../content-types/index.js";
import type { EntryRecord } from "../../../entries/index.js";
import { createRecentEntriesResolver, type ContentTypeLookup } from "../../resolvers/recent-entries.js";
import type { CollectionListLayout, CollectionListPort, CollectionListQuery, EntryDisplayListPort, EntryListExcludingTypesPort } from "../../resolvers/ports.js";
import type { EntryListPort } from "../../../entries/index.js";
import type { JsonObject } from "@jini-ai/core/primitives";
import type { WidgetInstanceView, WidgetResolveContext, WidgetResolveResult } from "../../types.js";

/**
 * @file `recent-entries` widget resolver ("Collection list") — both per-instance paths through its
 * public `createRecentEntriesResolver` factory, against hand-written fakes of its three injected
 * ports: the legacy batch (one shared, system-type-excluding query, per-instance slicing, layout and
 * column defaults/clamps, date fallbacks) and the `collection` path (missing type, rejected config,
 * the registry clamp re-applied on top of the parser's limit, displayed field values).
 */

const WS = "ws-1";
const CTX: WidgetResolveContext = { workspaceId: WS, preview: false };
const LAYOUTS: ReadonlySet<string> = new Set(["cards", "list", "accordion", "carousel"]);

function entry(overrides: Partial<EntryRecord> & Pick<EntryRecord, "id">): EntryRecord {
  return {
    workspaceId: WS, type: "post", slug: `${overrides.id}-slug`, status: "published", title: `Title ${overrides.id}`,
    bodyJson: null, fieldsJson: null, publishedAt: "2026-09-03T12:00:00.000Z", createdAt: "2026-09-01T12:00:00.000Z",
    updatedAt: "2026-09-04T12:00:00.000Z", version: 1, ...overrides,
  };
}

function instance(id: string, config: JsonObject = {}): WidgetInstanceView {
  return { id, widgetType: "recent-entries", config };
}

const RECIPES: ContentTypeRecord = {
  workspaceId: WS, key: "recipes", label: "Recipes", status: "active", version: 1,
  fields: [{ name: "prepTime", kind: "integer", required: false, queryable: true }],
};

interface Harness {
  resolve(instances: readonly WidgetInstanceView[]): Promise<ReadonlyMap<string, WidgetResolveResult>>;
  legacyQueries: unknown[];
  displayQueries: CollectionListQuery[];
}

function harness(optional: {
  legacyRows?: EntryRecord[];
  displayRows?: EntryRecord[];
  contentTypes?: Record<string, ContentTypeRecord>;
  parse?: CollectionListPort["parseCollectionListConfig"];
  siteTimeZone?: string;
} = {}): Harness {
  const legacyQueries: unknown[] = [];
  const displayQueries: CollectionListQuery[] = [];
  const unexpected = async (): Promise<never> => { throw new Error("unexpected call"); };
  const entryList: EntryListPort & EntryDisplayListPort & EntryListExcludingTypesPort = {
    listByWorkspace: unexpected,
    async listByWorkspaceExcludingTypes(required) { legacyQueries.push(required); return optional.legacyRows ?? []; },
    async listPublishedForDisplay({ query }) { displayQueries.push(query); return optional.displayRows ?? []; },
  };
  const collectionList: CollectionListPort = {
    parseCollectionListConfig: optional.parse ?? (() => ({ ok: false, reason: "unconfigured" })),
    entryPublicHref: (type, slug) => (type === "post" ? null : `/${type}/${slug}`),
    humanizeFieldName: (name) => `Label:${name}`,
    isCollectionListLayout: (value: unknown): value is CollectionListLayout => typeof value === "string" && LAYOUTS.has(value),
    systemContentTypes: ["widget", "widget_area"],
  };
  const contentTypes: ContentTypeLookup = { async findByKey({ key }) { return optional.contentTypes?.[key] ?? null; } };
  const siteTimeZone = optional.siteTimeZone;
  const resolver = createRecentEntriesResolver({
    collectionList, entryList, contentTypes,
    ...(siteTimeZone === undefined ? {} : { siteTimeZone: { resolveTimeZone: async () => siteTimeZone } }),
  });
  return { resolve: (instances) => resolver.resolveMany(instances, CTX), legacyQueries, displayQueries };
}

function okIr(result: WidgetResolveResult | undefined) {
  assert.ok(result?.ok, `expected an ok result, got ${JSON.stringify(result)}`);
  return result;
}

test("legacy path: ONE shared query excludes system types, is published-only, newest-updated first, bounded by the registry clamp", async () => {
  const h = harness({ legacyRows: [entry({ id: "a" }), entry({ id: "b" })] });
  const results = await h.resolve([instance("w1"), instance("w2", { maxItems: 1 })]);

  assert.deepEqual(h.legacyQueries, [{ workspaceId: WS, excludeTypes: ["widget", "widget_area"], status: "published", orderBy: "updatedAt", orderDirection: "desc", limit: 20 }]);
  assert.deepEqual(okIr(results.get("w1")).dependencyKeys, ["a", "b"]);
  assert.deepEqual(okIr(results.get("w2")).dependencyKeys, ["a"]);
});

test("legacy path: each item is an entry-list-item with title, href, publishedAt-first date and no display fields", async () => {
  const h = harness({ legacyRows: [
    entry({ id: "a" }),
    entry({ id: "b", type: "recipes", publishedAt: null }),
    entry({ id: "c", publishedAt: "not-a-date" }),
  ] });
  const result = okIr((await h.resolve([instance("w1")])).get("w1"));

  assert.equal(result.ir.componentId, "recent-entries");
  assert.deepEqual(result.ir.children, [
    { componentId: "entry-list-item", props: { title: "Title a", href: null, dateIso: "2026-09-03T12:00:00.000Z", dateLabel: "Sep 3, 2026", fields: [] } },
    { componentId: "entry-list-item", props: { title: "Title b", href: "/recipes/b-slug", dateIso: "2026-09-04T12:00:00.000Z", dateLabel: "Sep 4, 2026", fields: [] } },
    // A malformed timestamp degrades to the raw string, never "Invalid Date".
    { componentId: "entry-list-item", props: { title: "Title c", href: null, dateIso: "not-a-date", dateLabel: "not-a-date", fields: [] } },
  ]);
});

test("legacy path: per-instance maxItems is clamped to [0, registry max]", async () => {
  const rows = Array.from({ length: 25 }, (_, n) => entry({ id: `e${n}` }));
  const h = harness({ legacyRows: rows });
  const results = await h.resolve([instance("neg", { maxItems: -3 }), instance("big", { maxItems: 50 }), instance("str", { maxItems: "5" })]);

  assert.equal(okIr(results.get("neg")).ir.children!.length, 0);
  assert.equal(okIr(results.get("big")).ir.children!.length, 20);
  // A non-number maxItems is ignored, not coerced: the registry max applies.
  assert.equal(okIr(results.get("str")).ir.children!.length, 20);
});

test("legacy path: layout falls back to list for an absent/unknown value; columns default to 3 and clamp to an integer in [1, 6]", async () => {
  const h = harness();
  const results = await h.resolve([
    instance("default"),
    instance("cards", { layout: "cards", columns: 2.9 }),
    instance("bogus", { layout: "grid", columns: 0 }),
    instance("wide", { columns: 99 }),
    instance("text", { columns: "4" }),
    instance("inf", { columns: Number.POSITIVE_INFINITY }),
  ]);
  const props = (id: string) => okIr(results.get(id)).ir.props;

  assert.deepEqual(props("default"), { layout: "list", columns: 3, typeKey: "recent-entries" });
  assert.deepEqual(props("cards"), { layout: "cards", columns: 2, typeKey: "recent-entries" });
  assert.deepEqual(props("bogus"), { layout: "list", columns: 1, typeKey: "recent-entries" });
  assert.equal(props("wide").columns, 6);
  assert.equal(props("text").columns, 3);
  assert.equal(props("inf").columns, 3);
});

test("a batch with only collection instances never runs the legacy query; an empty collection key stays on the legacy path", async () => {
  const h = harness();
  await h.resolve([instance("c1", { collection: "recipes" })]);
  assert.deepEqual(h.legacyQueries, []);

  await h.resolve([instance("blank", { collection: "" })]);
  assert.equal(h.legacyQueries.length, 1);
});

test("collection path: an unknown content type is target-disabled and never queried", async () => {
  const h = harness();
  const results = await h.resolve([instance("c1", { collection: "missing" })]);

  assert.deepEqual(results.get("c1"), { ok: false, reason: "target-disabled" });
  assert.deepEqual(h.displayQueries, []);
});

test("collection path: a config the parser rejects is invalid-config and never queried", async () => {
  const seen: unknown[] = [];
  const h = harness({
    contentTypes: { recipes: RECIPES },
    parse: (config, contentType, options) => { seen.push([config, contentType.key, options]); return { ok: false, reason: "bad where" }; },
  });
  const results = await h.resolve([instance("c1", { collection: "recipes", where: "nope" })]);

  assert.deepEqual(results.get("c1"), { ok: false, reason: "invalid-config" });
  assert.deepEqual(seen, [[{ collection: "recipes", where: "nope" }, "recipes", { limitKey: "maxItems", defaultSort: "updated" }]]);
  assert.deepEqual(h.displayQueries, []);
});

test("collection path: the registry clamp is re-applied on top of the parser's limit, and declared fields become item values", async () => {
  const query: CollectionListQuery = { type: "recipes", where: [], sort: { by: "updated", dir: "desc" }, limit: 24 };
  const h = harness({
    contentTypes: { recipes: RECIPES },
    displayRows: [
      entry({ id: "r1", type: "recipes", fieldsJson: { ext: { site: { prepTime: 15 } } } }),
      entry({ id: "r2", type: "recipes", fieldsJson: null }),
    ],
    parse: () => ({ ok: true, query, display: { columns: 4, layout: "cards", fields: RECIPES.fields } }),
  });
  const result = okIr((await h.resolve([instance("c1", { collection: "recipes" })])).get("c1"));

  assert.deepEqual(h.displayQueries, [{ ...query, limit: 20 }]);
  // The widget's own layout default ("list") wins over the parser's marker default ("cards").
  assert.deepEqual(result.ir.props, { layout: "list", columns: 4, typeKey: "recipes" });
  assert.deepEqual(result.dependencyKeys, ["r1", "r2"]);
  assert.deepEqual(result.ir.children!.map((child) => child.props.fields), [
    [{ name: "prepTime", label: "Label:prepTime", kind: "integer", value: 15 }],
    [{ name: "prepTime", label: "Label:prepTime", kind: "integer", value: undefined }],
  ]);
  assert.equal(result.ir.children![0]!.props.href, "/recipes/r1-slug");
});

test("collection path: structuredData is carried only when the parser declares it, and a smaller parser limit is kept", async () => {
  const query: CollectionListQuery = { type: "recipes", where: [], sort: { by: "title", dir: "asc" }, limit: 5 };
  const h = harness({
    contentTypes: { recipes: RECIPES },
    parse: () => ({ ok: true, query, display: { columns: 2, layout: "accordion", fields: [], structuredData: "faq-page" } }),
  });
  const result = okIr((await h.resolve([instance("c1", { collection: "recipes", layout: "accordion" })])).get("c1"));

  assert.deepEqual(h.displayQueries, [query]);
  assert.deepEqual(result.ir.props, { layout: "accordion", columns: 2, typeKey: "recipes", structuredData: "faq-page" });
  assert.deepEqual(result.ir.children, []);
});

// Bug D (2026-10-22): 07:30 UTC on Mar 4 is still Mar 3 in Los Angeles; 16:30 UTC on Mar 3 is already Mar 4 in Tokyo.
test("both paths: dateLabel is the calendar day in the site's time zone; dateIso stays the stored instant", async () => {
  const rows = [entry({ id: "a", publishedAt: "2026-03-04T07:30:00.000Z" }), entry({ id: "b", publishedAt: "2026-03-03T16:30:00.000Z" })];
  const query: CollectionListQuery = { type: "recipes", where: [], sort: { by: "updated", dir: "desc" }, limit: 5 };
  const labels = async (siteTimeZone?: string) => {
    const h = harness({
      legacyRows: rows, displayRows: rows, contentTypes: { recipes: RECIPES }, ...(siteTimeZone === undefined ? {} : { siteTimeZone }),
      parse: () => ({ ok: true, query, display: { columns: 2, layout: "list", fields: [] } }),
    });
    const results = await h.resolve([instance("w1"), instance("c1", { collection: "recipes" })]);
    return ["w1", "c1"].map((id) => okIr(results.get(id)).ir.children!.map((child) => [child.props.dateIso, child.props.dateLabel]));
  };
  const both = (a: string, b: string) => [[["2026-03-04T07:30:00.000Z", a], ["2026-03-03T16:30:00.000Z", b]], [["2026-03-04T07:30:00.000Z", a], ["2026-03-03T16:30:00.000Z", b]]];
  assert.deepEqual(await labels("America/Los_Angeles"), both("Mar 3, 2026", "Mar 3, 2026"));
  assert.deepEqual(await labels("Asia/Tokyo"), both("Mar 4, 2026", "Mar 4, 2026"));
  // No port, or an invalid zone: UTC, the pre-fix output.
  assert.deepEqual(await labels(), both("Mar 4, 2026", "Mar 3, 2026"));
  assert.deepEqual(await labels("Nowhere/Invalid"), both("Mar 4, 2026", "Mar 3, 2026"));
});

src/redirects/__tests__/repo.dialects.te.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { describeEachDialect } from "../../core/__tests__/support/dialect-matrix.js";
import { createTables } from "./support/redirects-tables.fixture.js";
import { RedirectSlugChangeCapture } from "../capture.js";
import { type SqlRedirectRepo, redirectRepoFor } from "../sql/repo.js";
import { RedirectNotFoundError, type RedirectRecord, type RedirectRevision } from "../types.js";

/**
 * @file The redirect repo on every dialect through the kernel's matrix (`describeEachDialect` + ONE
 * factory: one query body serves every dialect).
 */

const WS = "ws-dialects";
const OTHER = "other-ws";

function rule(id: string, overrides: Partial<RedirectRecord> = {}): RedirectRecord {
  return {
    id,
    workspaceId: WS,
    matchType: "exact",
    fromPattern: `/${id}`,
    toTarget: "/target",
    statusCode: 301,
    status: "active",
    override: false,
    priority: 0,
    source: "manual",
    createdByPrincipal: "user-1",
    createdAt: "2026-09-28T00:00:00.000Z",
    updatedAt: "2026-09-28T00:00:00.000Z",
    version: 1,
    ...overrides,
  };
}

function revision(record: RedirectRecord, seq = 1, tombstoned = false): RedirectRevision {
  return {
    redirectId: record.id,
    workspaceId: record.workspaceId,
    seq,
    state: record,
    tombstoned,
    actorId: "user-1",
    recordedAt: record.updatedAt,
  };
}

async function saveRule(repo: SqlRedirectRepo, record: RedirectRecord): Promise<void> {
  await repo.save({ record, revision: revision(record) });
}

describeEachDialect<SqlRedirectRepo>(
  { title: "redirect repo", options: {
    tables: ["redirects", "redirect_revisions"], createTables,
    make: (kernel) => redirectRepoFor({ kernel, tables: { redirects: "redirects", revisions: "redirect_revisions" } }, {}),
  }, body: (makeRepo) => {
    test("save round-trips every field incl. optionals and booleans; re-save replaces the row", async () => {
      const repo = makeRepo();
      const full = rule("full", {
        override: true,
        priority: 5,
        source: "auto_slug_change",
        sourceEntryId: "e1",
        fromPathAtCapture: "/a",
        toPathAtCapture: "/b",
        createdByPluginId: "plug",
      });
      await saveRule(repo, full);
      assert.deepEqual(await repo.findById({ workspaceId: WS, id: "full" }), full);
      const replaced = { ...full, toTarget: "/changed", override: false, version: 2, sourceEntryId: undefined };
      await repo.save({ record: replaced, revision: revision(replaced, 2) });
      assert.deepEqual(await repo.findById({ workspaceId: WS, id: "full" }), replaced);
      assert.equal((await repo.list({ workspaceId: WS })).length, 1);
      assert.deepEqual(
        (await repo.listRevisionsForTests({ redirectId: "full" }, {})).map((r) => r.seq),
        [1, 2]
      );
    });

    test("findById misses an unknown id and another workspace's row", async () => {
      const repo = makeRepo();
      await saveRule(repo, rule("a"));
      assert.equal(await repo.findById({ workspaceId: WS, id: "nope" }), null);
      assert.equal(await repo.findById({ workspaceId: OTHER, id: "a" }), null);
    });

    test("lookupExact hits by path, honours override-only, prefers priority, isolates workspaces", async () => {
      const repo = makeRepo();
      await saveRule(repo, rule("lo", { fromPattern: "/p", priority: 1 }));
      await saveRule(repo, rule("hi", { fromPattern: "/p", priority: 9, override: true }));
      await saveRule(repo, rule("gone", { fromPattern: "/q", status: "disabled" }));
      assert.equal((await repo.lookupExact({ workspaceId: WS, path: "/p", includeOverrideOnly: false }))?.id, "hi");
      await saveRule(repo, rule("plain", { fromPattern: "/z" }));
      assert.equal(await repo.lookupExact({ workspaceId: WS, path: "/z", includeOverrideOnly: true }), null);
      assert.equal(await repo.lookupExact({ workspaceId: WS, path: "/q", includeOverrideOnly: false }), null);
      assert.equal(await repo.lookupExact({ workspaceId: OTHER, path: "/p", includeOverrideOnly: false }), null);
    });

    for (const matchType of ["exact", "prefix", "wildcard"] as const) {
      test(`${matchType}: equal priority prefers newest timestamp, then smallest id`, async () => {
        const repo = makeRepo();
        const fromPattern = matchType === "wildcard" ? "/tie/*" : "/tie";
        const older = rule("a-old", { matchType, fromPattern, priority: 7, updatedAt: "2026-01-01T00:00:00.000Z", toTarget: "/old" });
        const newer = rule("z-new", { matchType, fromPattern, priority: 7, updatedAt: "2026-02-01T00:00:00.000Z", toTarget: "/new" });
        const sameTimeSmallerId = rule("b-new", { ...newer, id: "b-new", toTarget: "/id-winner" });
        // Insertion order and id order both favor the older row if recency is ignored.
        await saveRule(repo, older);
        await saveRule(repo, newer);
        const selected = async () => matchType === "exact"
          ? repo.lookupExact({ workspaceId: WS, path: "/tie", includeOverrideOnly: false })
          : matchType === "prefix"
            ? repo.lookupLongestPrefix({ workspaceId: WS, path: "/tie/nested", includeOverrideOnly: false })
            : (await repo.listDynamic({ workspaceId: WS, includeOverrideOnly: false, limit: 1 }))[0];
        const newest = await selected();
        assert.equal(newest?.id, newer.id);
        assert.equal(newest?.toTarget, newer.toTarget);
        await saveRule(repo, sameTimeSmallerId);
        const idWinner = await selected();
        assert.equal(idWinner?.id, sameTimeSmallerId.id);
        assert.equal(idWinner?.toTarget, sameTimeSmallerId.toTarget);
      });
    }

    test("lookupLongestPrefix picks the longest matching prefix; misses non-matches and other workspaces", async () => {
      const repo = makeRepo();
      await saveRule(repo, rule("short", { matchType: "prefix", fromPattern: "/docs" }));
      await saveRule(repo, rule("long", { matchType: "prefix", fromPattern: "/docs/api/" }));
      await saveRule(repo, rule("ov", { matchType: "prefix", fromPattern: "/x", override: true }));
      const hit = (path: string, includeOverrideOnly = false) =>
        repo.lookupLongestPrefix({ workspaceId: WS, path, includeOverrideOnly });
      assert.equal((await hit("/docs/api/v1"))?.id, "long");
      assert.equal((await hit("/docs/other"))?.id, "short");
      assert.equal((await hit("/docs"))?.id, "short");
      assert.equal(await hit("/docsx"), null);
      assert.equal((await hit("/x/y", true))?.id, "ov");
      assert.equal(await hit("/docs/a", true), null);
      assert.equal(await repo.lookupLongestPrefix({ workspaceId: OTHER, path: "/docs/a", includeOverrideOnly: false }), null);
    });

    test("listDynamic returns active wildcard rules, longest first, capped by limit, per workspace", async () => {
      const repo = makeRepo();
      await saveRule(repo, rule("w1", { matchType: "wildcard", fromPattern: "/a/*" }));
      await saveRule(repo, rule("w2", { matchType: "wildcard", fromPattern: "/a/b/*", override: true }));
      await saveRule(repo, rule("w3", { matchType: "wildcard", fromPattern: "/c/*", status: "disabled" }));
      await saveRule(repo, rule("e1"));
      const ids = async (limit: number, includeOverrideOnly = false) =>
        (await repo.listDynamic({ workspaceId: WS, includeOverrideOnly, limit })).map((r) => r.id);
      assert.deepEqual(await ids(10), ["w2", "w1"]);
      assert.deepEqual(await ids(1), ["w2"]);
      assert.deepEqual(await ids(10, true), ["w2"]);
      assert.deepEqual(await repo.listDynamic({ workspaceId: OTHER, includeOverrideOnly: false, limit: 10 }), []);
    });

    test("list filters by status, source and matchType and stays inside the workspace", async () => {
      const repo = makeRepo();
      await saveRule(repo, rule("m", { source: "manual" }));
      await saveRule(repo, rule("c", { source: "auto_slug_change", matchType: "prefix" }));
      await saveRule(repo, rule("t", { status: "disabled" }));
      await saveRule(repo, rule("o", { workspaceId: OTHER }));
      const ids = async (filter: object) =>
        (await repo.list({ workspaceId: WS, ...filter })).map((r) => r.id).sort();
      assert.deepEqual(await ids({}), ["c", "m", "t"]);
      assert.deepEqual(await ids({ status: "disabled" }), ["t"]);
      assert.deepEqual(await ids({ source: "auto_slug_change" }), ["c"]);
      assert.deepEqual(await ids({ matchType: "prefix" }), ["c"]);
      assert.deepEqual(await repo.list({ workspaceId: "empty" }), []);
    });

    test("findByFromPattern prefers an exact active rule; misses tombstoned and other workspaces", async () => {
      const repo = makeRepo();
      await saveRule(repo, rule("pre", { matchType: "prefix", fromPattern: "/same" }));
      await saveRule(repo, rule("ex", { fromPattern: "/same" }));
      await saveRule(repo, rule("dead", { fromPattern: "/dead", status: "disabled" }));
      assert.equal((await repo.findByFromPattern({ workspaceId: WS, fromPattern: "/same" }))?.id, "ex");
      assert.equal(await repo.findByFromPattern({ workspaceId: WS, fromPattern: "/dead" }), null);
      assert.equal(await repo.findByFromPattern({ workspaceId: OTHER, fromPattern: "/same" }), null);
    });

    test("tombstone writes the tombstoned state + revision; unknown or other-workspace id throws and writes nothing", async () => {
      const repo = makeRepo();
      const live = rule("t1");
      await saveRule(repo, live);
      const dead = { ...live, status: "disabled" as const, version: 2 };
      await repo.tombstone({ workspaceId: WS, id: "t1", revision: revision(dead, 2, true) });
      assert.equal((await repo.findById({ workspaceId: WS, id: "t1" }))?.status, "disabled");
      const ledger = await repo.listRevisionsForTests({ redirectId: "t1" }, {});
      assert.deepEqual(ledger.map((r) => r.tombstoned), [false, true]);
      await assert.rejects(
        repo.tombstone({ workspaceId: WS, id: "nope", revision: revision(rule("nope"), 1, true) }),
        RedirectNotFoundError
      );
      await assert.rejects(
        repo.tombstone({ workspaceId: OTHER, id: "t1", revision: revision({ ...dead, workspaceId: OTHER }, 3, true) }),
        RedirectNotFoundError
      );
      assert.equal((await repo.listRevisionsForTests({ redirectId: "nope" }, {})).length, 0);
      assert.equal((await repo.listRevisionsForTests({ redirectId: "t1" }, {})).length, 2);
    });

    test("a save whose revision fails rolls the redirect row back too", async () => {
      const repo = makeRepo();
      const record = rule("r1");
      const bad = { ...revision(record), state: { toJSON: () => { throw new Error("boom"); } } } as unknown as RedirectRevision;
      await assert.rejects(repo.save({ record, revision: bad }), /boom/);
      assert.equal(await repo.findById({ workspaceId: WS, id: "r1" }), null);
    });

    test("a transaction's writes roll back together; a nested one joins", async () => {
      const repo = makeRepo();
      const record = rule("tx");
      await assert.rejects(
        repo.transaction(async () => {
          await repo.insertRedirect(record);
          await repo.transaction(async () => repo.insertRevision(revision(record)));
          throw new Error("boom");
        }),
        /boom/
      );
      assert.equal(await repo.findById({ workspaceId: WS, id: "tx" }), null);
      assert.deepEqual(await repo.listRevisionsForTests({ redirectId: "tx" }, {}), []);
      await repo.transaction(async () => {
        await repo.insertRedirect(record);
        await repo.insertRevision(revision(record));
      });
      assert.equal((await repo.listRevisionsForTests({ redirectId: "tx" }, {})).length, 1);
    });

    test("slug capture after renames a→b→a→c→a→b resolves /a to the live /b, not into a /a→/c→/a loop", async () => {
      const repo = makeRepo();
      let ms = Date.parse("2026-09-28T00:00:00.000Z");
      let n = 0;
      const capture = new RedirectSlugChangeCapture({ repo, db: repo,
        clock: { nowMs: () => (ms += 1000) }, idGen: { newId: () => `cap-${++n}` } });
      const path = ["/a", "/b", "/a", "/c", "/a", "/b"];
      for (let i = 1; i < path.length; i++) {
        const oldPath = path[i - 1], newPath = path[i];
        assert.ok(oldPath);
        assert.ok(newPath);
        await capture.onSlugChange({ workspaceId: WS, entryId: "post-1", oldPath, newPath,
          actor: "user-1", changeSetId: `cs-${i}` });
      }
      const winner = await repo.lookupExact({ workspaceId: WS, path: "/a", includeOverrideOnly: false });
      assert.equal(winner?.toTarget, "/b");
    });
  }
}, {}
);

src/entries/__tests__/write-service.crea.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import {
  ContentTypeNotActiveError,
  EntryFieldValidationError,
  EntrySlugConflictError,
  ForbiddenError,
} from "../errors.js";
import type { EntryRevisionInput } from "../write-service.js";
import { createEntry } from "../write-service.js";
import type { EntryRecord } from "../types.js";

/**
 * @file `createEntry` slug-uniqueness and type-existence/workspace-ownership validation.
 *
 * Covers: (duplicate (workspaceId,type,slug) rejected), (nonexistent type rejected),
 * (cross-workspace type reference rejected — ), (entry.created outbox event).
 * See docs/decisions/DR-002-content-lifecycle-and-cleanup.md.
 */

const NOW = "2026-07-15T00:00:00.000Z";
const clock = { nowMs: () => Date.parse(NOW)};
let idCounter = 0;
const ids = { newId: () => `entry-${++idCounter}` };
const alwaysAllow = async () => ({ allowed: true, reason: "matched" });
const alwaysDeny = async () => ({ allowed: false, reason: "no grant confers admin.collections.manage" });

type ContentTypeStatus = "active" | "deprecated" | "tombstone";
type FieldDef = { name: string; kind: "text"; required: boolean; queryable: boolean };

function contentTypeWith(status: ContentTypeStatus, fields: FieldDef[] = [], workspaceId = "ws-1") {
  return { workspaceId, key: "recipe", status, fields };
}

function activeContentType(workspaceId = "ws-1") {
  return { workspaceId, key: "recipe", status: "active" as const, fields: [] as FieldDef[] };
}

function fakeEntryRepo(existing: Array<{ workspaceId: string; type: string; slug: string }> = []) {
  // The seeds are slug-conflict probes, not whole records: `createEntry` only tests `findBySlug`'s
  // result for truthiness, so `workspaceId`/`type`/`slug` are the only columns ever read off one.
  // The store is typed as `EntryRecord[]` because `save` puts real records into the same array and
  // the package (unlike the host this was ported from) typechecks tests against `EntryRepoPort`.
  const rows = [...existing] as EntryRecord[];
  const events: unknown[] = [];
  // Revisions are captured, not discarded: the columns they carry are `NOT NULL`-typed, and the
  // difference between `null` and `undefined` in them is invisible unless something asserts on it.
  const revisions: Array<Record<string, unknown>> = [];
  return {
    rows,
    events,
    revisions,
    findBySlug: async (params: { workspaceId: string; type: string; slug: string }) =>
      rows.find((r) => r.workspaceId === params.workspaceId && r.type === params.type && r.slug === params.slug) ?? null,
    // `createEntry` resolves by slug, never by id, so this suite's seeds are slug-conflict probes
    // with no id to index on. It throws rather than returning `null`: a silent `null` would let a
    // future call site take the not-found branch and still pass, whereas this names the gap. It
    // exists at all because the package typechecks its tests against the full `EntryRepoPort` —
    // the host this was ported from excluded tests from typecheck.
    findById: async (): Promise<never> => {
      throw new Error("fakeEntryRepo.findById is not implemented — this suite exercises only the create/slug path");
    },
    save: async (row: EntryRecord) => {
      rows.push(row);
    },
    appendRevision: async (rev: EntryRevisionInput) => {
      revisions.push(rev as unknown as Record<string, unknown>);
    },
    transaction: async <T>({ fn }: { fn: () => Promise<T> }) => fn(),
  };
}

function fakeContentTypeRepo(ct: ReturnType<typeof contentTypeWith> | null) {
  return { findByKey: async () => ct };
}

const outbox = { enqueue: async () => undefined };

test("AC-21: a second entry submitted with the identical (workspaceId, type, slug) is rejected with ENTRY_SLUG_CONFLICT, no second row created", async () => {
  const entryRepo = fakeEntryRepo([{ workspaceId: "ws-1", type: "recipe", slug: "chili" }]);
  const contentTypeRepo = fakeContentTypeRepo(activeContentType());

  const result = await createEntry({
    deps: { entryRepo, contentTypeRepo, clock, ids, authorize: alwaysAllow, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", type: "recipe", slug: "chili", title: "Chili Again", fieldsJson: { ext: { site: {} } } },
  });

  assert.equal(result.ok, false);
  if (!result.ok) assert.ok(result.error instanceof EntrySlugConflictError);
  assert.equal(entryRepo.rows.length, 1);
});

test("AC-29: an entry write specifying a nonexistent content type is rejected with CONTENT_TYPE_NOT_FOUND", async () => {
  const entryRepo = fakeEntryRepo();
  const contentTypeRepo = fakeContentTypeRepo(null);

  const result = await createEntry({
    deps: { entryRepo, contentTypeRepo, clock, ids, authorize: alwaysAllow, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", type: "does-not-exist", slug: "x", title: "X", fieldsJson: { ext: { site: {} } } },
  });

  assert.equal(result.ok, false);
  if (!result.ok) assert.equal((result.error as { code?: string }).code ?? (result.error as Error).name, "CONTENT_TYPE_NOT_FOUND");
});

test("AC-30/INV-01: a content type that exists only in a DIFFERENT workspace is not silently accepted — rejected as a workspace-ownership violation", async () => {
  const entryRepo = fakeEntryRepo();
  const contentTypeRepo = fakeContentTypeRepo(activeContentType("ws-OTHER"));

  const result = await createEntry({
    deps: { entryRepo, contentTypeRepo, clock, ids, authorize: alwaysAllow, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", type: "recipe", slug: "x", title: "X", fieldsJson: { ext: { site: {} } } },
  });

  assert.equal(result.ok, false, "a content type owned by a different workspace must never be silently accepted (the general soft-reference rule)");
  assert.equal(entryRepo.rows.length, 0);
});

test("AC-27: a successful entry creation enqueues an entry.created outbox event in the same call", async () => {
  const events: unknown[] = [];
  const trackedOutbox = { enqueue: async (e: unknown) => { events.push(e); } };
  const entryRepo = fakeEntryRepo();
  const contentTypeRepo = fakeContentTypeRepo(activeContentType());

  const result = await createEntry({
    deps: { entryRepo, contentTypeRepo, clock, ids, authorize: alwaysAllow, outbox: trackedOutbox },
    input: { workspaceId: "ws-1", actorId: "user-1", type: "recipe", slug: "chili-new", title: "Chili", fieldsJson: { ext: { site: {} } } },
  });

  assert.equal(result.ok, true);
  assert.equal(events.length, 1);
  const event = events[0] as { name: string };
  assert.equal(event.name, "entry.created");
});

// ---------------------------------------------------------------------------
// Guards added because a mutation sweep proved nothing failed without them. Every test above
// this line passes `alwaysAllow` and a valid, active content type, so `createEntry`'s
// authorization, status, and field-validation guards could each be deleted outright. See docs/decisions/DR-002-content-lifecycle-and-cleanup.md.
// with a green suite. A guard is justified by a test that fails without it, or it comes out.
// ---------------------------------------------------------------------------

test("an unauthorized principal cannot create an entry — FORBIDDEN, and no row is written", async () => {
  const entryRepo = fakeEntryRepo();
  const contentTypeRepo = fakeContentTypeRepo(activeContentType());

  const result = await createEntry({
    deps: { entryRepo, contentTypeRepo, clock, ids, authorize: alwaysDeny, outbox },
    input: { workspaceId: "ws-1", actorId: "intruder", type: "recipe", slug: "chili", title: "Chili", fieldsJson: { ext: { site: {} } } },
  });

  assert.equal(result.ok, false, "authorization is the FIRST gate in createEntry — denying it must stop the write");
  if (!result.ok) assert.ok(result.error instanceof ForbiddenError);
  assert.equal(entryRepo.rows.length, 0, "a denied create must not reach the repo at all");
});

test("REQ-10: a 'deprecated' owning content type blocks NEW entry creation (the inverse of REQ-28, where deprecated blocks nothing)", async () => {
  const entryRepo = fakeEntryRepo();
  const contentTypeRepo = fakeContentTypeRepo(contentTypeWith("deprecated"));

  const result = await createEntry({
    deps: { entryRepo, contentTypeRepo, clock, ids, authorize: alwaysAllow, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", type: "recipe", slug: "chili", title: "Chili", fieldsJson: { ext: { site: {} } } },
  });

  assert.equal(result.ok, false);
  if (!result.ok) assert.ok(result.error instanceof ContentTypeNotActiveError);
  assert.equal(entryRepo.rows.length, 0);
});

test("fieldsJson that does not validate against the type's schema is rejected, not persisted", async () => {
  const entryRepo = fakeEntryRepo();
  // Empty schema, so any populated `site` bag carries an unrecognized field.
  const contentTypeRepo = fakeContentTypeRepo(contentTypeWith("active"));

  const result = await createEntry({
    deps: { entryRepo, contentTypeRepo, clock, ids, authorize: alwaysAllow, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", type: "recipe", slug: "chili", title: "Chili", fieldsJson: { ext: { site: { notInSchema: "x" } } } },
  });

  assert.equal(result.ok, false);
  if (!result.ok) assert.ok(result.error instanceof EntryFieldValidationError);
  assert.equal(entryRepo.rows.length, 0);
});

// The next two assert `null` STRICTLY, because that is the whole content of the guard.
//
// NOT because better-sqlite3 rejects `undefined` binds — it does not. Verified against 11.10.0:
// both positional and named binds store `undefined` as NULL, and only a *missing named key*
// throws. Drizzle's insert path agrees: `buildInsertQuery` emits `sql`null`` for an undefined
// column, and `appendRevision` is insert-only (`repo.sqlite.ts`), so the delegation COLUMNS would
// land as NULL either way.
//
// What the two guards actually protect is narrower, and differs between them:
//   - `bodyJson`: the revision persists the whole record through `JSON.stringify(stateJson)`, and
//     stringify DROPS an undefined-valued key outright. The audit trail silently loses the field.
//   - delegation fields: `delegationFields()` declares `string | null`; returning `undefined`
//     violates its own contract, which is a type-level defect rather than a persistence one.
// Both assertions must be `strictEqual` regardless — `assert.equal` treats `undefined` and `null`
// as equal and would make these tests vacuous.
//
// Caveat that does NOT apply here but does elsewhere in this repo: Drizzle's `mapUpdateSet()`
// DROPS undefined properties, and `onConflictDoUpdate` uses it — so on an upsert, `undefined`
// means "keep the old value", not "write NULL". A `?? null` feeding an upsert IS load-bearing.

test("an omitted bodyJson is stored as null, not undefined — an undefined value vanishes from the revision's serialized state", async () => {
  const entryRepo = fakeEntryRepo();
  const contentTypeRepo = fakeContentTypeRepo(activeContentType());

  const result = await createEntry({
    deps: { entryRepo, contentTypeRepo, clock, ids, authorize: alwaysAllow, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", type: "recipe", slug: "no-body", title: "No Body", fieldsJson: { ext: { site: {} } } },
  });

  assert.equal(result.ok, true);
  const stored = entryRepo.rows[0] as { bodyJson?: unknown };
  assert.strictEqual(stored.bodyJson, null, "omitted bodyJson must normalize to null before it reaches the repo");
});

test("a non-delegated create writes null delegation columns on its revision, not undefined", async () => {
  const entryRepo = fakeEntryRepo();
  const contentTypeRepo = fakeContentTypeRepo(activeContentType());

  const result = await createEntry({
    deps: { entryRepo, contentTypeRepo, clock, ids, authorize: alwaysAllow, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", type: "recipe", slug: "direct", title: "Direct", fieldsJson: { ext: { site: {} } } },
  });

  assert.equal(result.ok, true);
  assert.equal(entryRepo.revisions.length, 1);
  const revision = entryRepo.revisions[0];
  // `noUncheckedIndexedAccess` (on here, off in the host this came from) makes `[0]` possibly
  // undefined. Asserted rather than cast away: if the revision is missing, this names that as the
  // failure instead of a confusing property-access error on the next line.
  assert.ok(revision, "a revision row must have been appended");
  assert.strictEqual(revision.delegatedByWorkspaceId, null, "the common non-delegated case must still bind null");
  assert.strictEqual(revision.delegatedById, null);
});

