import assert from "node:assert/strict";
import { test } from "vitest";

import { assignLocation, createMenu } from "../menu-service.js";
import { InMemoryMenuRepo, InMemoryNavLocationBindingRepo } from "../repo.memory.js";
import { resolveForLocation, type ResolveTargetHrefFn } from "../resolver.js";
import { NAV_DOC_TYPE, type NavItemNode, type NavMenuEntry, type NavTarget } from "../types.js";

function fakeClock(iso = "2026-07-10T00:00:00.000Z") {
  return { nowMs: () => Date.parse(iso)};
}

function fakeIdGen(prefix = "id") {
  let counter = 0;
  return { newId: () => `${prefix}-${++counter}` };
}

/**
 * A fake `resolveTargetHref` for tests: `entryRef` resolves to a deterministic
 * path; `route` resolves `home` only; every `termRef` resolves to `null`
 * (no `entry_refs`-compatible term-target
 * schema exists yet, so a real resolver has nothing to consult for term
 * targets today). Any `entryRef` whose id starts with `deleted-` simulates a
 * trashed target: resolves to a real path but `available: false`.
 */
const fakeResolveTargetHref: ResolveTargetHrefFn = async ({ target }: { target: NavTarget }) => {
  if (target.kind === "url") return null; // resolver.ts never calls us for url
  if (target.kind === "termRef") return null; // see comment above
  if (target.kind === "entryRef") {
    if (target.entryId.startsWith("deleted-")) {
      return { path: `/entries/${target.entryId}`, available: false };
    }
    return { path: `/entries/${target.entryId}`, available: true };
  }
  if (target.kind === "route") {
    if (target.route === "home") return { path: "/", available: true };
    return null;
  }
  return null;
};

/** No-op outbox — this suite exercises `resolver.ts`'s reads, not `menu-service.ts`'s event publication. */
function fakeOutbox() {
  return { enqueue: async () => {}, claimPending: async () => [], markDelivered: async () => {}, markFailed: async () => {} };
}

async function seedMenuBoundToLocation(items: readonly NavItemNode[]) {
  const repo = new InMemoryMenuRepo({});
  const bindingRepo = new InMemoryNavLocationBindingRepo({});
  const clock = fakeClock();
  const idGen = fakeIdGen();
  const outbox = fakeOutbox();

  const { menu } = await createMenu({
    deps: { repo, clock, idGen, outbox },
    input: { workspaceId: "ws-1", title: "Primary Nav", slug: "primary-nav", items },
  });
  await assignLocation({
    deps: { repo, bindingRepo, clock, idGen, outbox },
    input: { workspaceId: "ws-1", menuId: menu.id, locationKey: "primary" },
  });

  return { repo, bindingRepo, menu };
}

test("resolveForLocation returns null when no menu is bound to the location", async () => {
  const repo = new InMemoryMenuRepo({});
  const bindingRepo = new InMemoryNavLocationBindingRepo({});

  const result = await resolveForLocation({
    deps: { menuRepo: repo, bindingRepo, resolveTargetHref: fakeResolveTargetHref },
    input: { workspaceId: "ws-1", locationKey: "footer" },
  });

  assert.equal(result, null);
});

test("resolveForLocation resolves url targets directly and entryRef targets via the injected resolver", async () => {
  const { repo, bindingRepo } = await seedMenuBoundToLocation([
    { id: "item-1", label: "Home", target: { kind: "url", href: "/" } },
    { id: "item-2", label: "About", target: { kind: "entryRef", entryId: "about-page" } },
  ]);

  const resolved = await resolveForLocation({
    deps: { menuRepo: repo, bindingRepo, resolveTargetHref: fakeResolveTargetHref },
    input: { workspaceId: "ws-1", locationKey: "primary" },
  });

  assert.ok(resolved);
  assert.equal(resolved.items.length, 2);
  assert.equal(resolved.items[0]!.href, "/");
  assert.equal(resolved.items[0]!.available, true);
  assert.equal(resolved.items[1]!.href, "/entries/about-page");
  assert.equal(resolved.items[1]!.available, true);
});

test("resolveForLocation marks an unavailable target as available:false without breaking the rest of the tree", async () => {
  const { repo, bindingRepo } = await seedMenuBoundToLocation([
    { id: "item-1", label: "Home", target: { kind: "url", href: "/" } },
    {
      id: "item-2",
      label: "Deleted Page",
      target: { kind: "entryRef", entryId: "deleted-page-1" },
    },
    { id: "item-3", label: "About", target: { kind: "entryRef", entryId: "about-page" } },
  ]);

  const resolved = await resolveForLocation({
    deps: { menuRepo: repo, bindingRepo, resolveTargetHref: fakeResolveTargetHref },
    input: { workspaceId: "ws-1", locationKey: "primary" },
  });

  assert.ok(resolved);
  assert.equal(resolved.items.length, 3);

  // The unavailable item is flagged, not dropped from the model (theme's job
  // to omit it) and its href is nulled out.
  assert.equal(resolved.items[1]!.available, false);
  assert.equal(resolved.items[1]!.href, null);

  // Sibling items on either side still resolved normally.
  assert.equal(resolved.items[0]!.available, true);
  assert.equal(resolved.items[0]!.href, "/");
  assert.equal(resolved.items[2]!.available, true);
  assert.equal(resolved.items[2]!.href, "/entries/about-page");
});

test("resolveForLocation propagates unavailable through nested children without breaking siblings", async () => {
  const { repo, bindingRepo } = await seedMenuBoundToLocation([
    {
      id: "parent",
      label: "Company",
      target: { kind: "url", href: "/company" },
      children: [
        { id: "child-1", label: "Team", target: { kind: "entryRef", entryId: "team-page" } },
        {
          id: "child-2",
          label: "Deleted Child",
          target: { kind: "entryRef", entryId: "deleted-child" },
        },
      ],
    },
  ]);

  const resolved = await resolveForLocation({
    deps: { menuRepo: repo, bindingRepo, resolveTargetHref: fakeResolveTargetHref },
    input: { workspaceId: "ws-1", locationKey: "primary" },
  });

  assert.ok(resolved);
  const parent = resolved.items[0]!;
  assert.equal(parent.children.length, 2);
  assert.equal(parent.children[0]!.available, true);
  assert.equal(parent.children[1]!.available, false);
  assert.equal(parent.children[1]!.href, null);
});

test("resolveForLocation resolves termRef targets to unavailable (Round-3 fold item 1: no term schema yet)", async () => {
  const { repo, bindingRepo } = await seedMenuBoundToLocation([
    {
      id: "item-1",
      label: "Category",
      target: { kind: "termRef", termId: "cat-1", taxonomy: "category" },
    },
  ]);

  const resolved = await resolveForLocation({
    deps: { menuRepo: repo, bindingRepo, resolveTargetHref: fakeResolveTargetHref },
    input: { workspaceId: "ws-1", locationKey: "primary" },
  });

  assert.ok(resolved);
  assert.equal(resolved.items[0]!.available, false);
  assert.equal(resolved.items[0]!.href, null);
});

test("resolveForLocation computes isCurrent/isActive against the current path", async () => {
  const { repo, bindingRepo } = await seedMenuBoundToLocation([
    { id: "item-1", label: "Home", target: { kind: "route", route: "home" } },
    { id: "item-2", label: "About", target: { kind: "entryRef", entryId: "about-page" } },
  ]);

  const resolved = await resolveForLocation({
    deps: { menuRepo: repo, bindingRepo, resolveTargetHref: fakeResolveTargetHref },
    input: { workspaceId: "ws-1", locationKey: "primary", currentPath: "/" },
  });

  assert.ok(resolved);
  assert.equal(resolved.items[0]!.isCurrent, true);
  assert.equal(resolved.items[0]!.isActive, true);
  assert.equal(resolved.items[1]!.isCurrent, false);
  assert.equal(resolved.items[1]!.isActive, false);
});

// ---------------------------------------------------------------------------
// Default-selection coverage: what resolveForLocation does when there is no
// *currently valid* binding to resolve. Before this suite, only the
// "no binding row at all" case (above) was exercised. Two other early-return
// defaults reachable from the same function were completely untested:
//
// 1. Status independence — a documented (menu-service.ts `createMenu` doc
//    comment, 2026-08-09) but previously unverified product decision that a
//    menu's `status` never gates resolution, only the trash/purge lifecycle
//    does. `deleteMenu`'s first call flips status to `trash` and returns
//    WITHOUT touching bindings, so a trashed-but-not-yet-purged menu stays
//    bound and must keep resolving. A test that only ever seeds `published`
//    menus (as every test above this point does, via `createMenu`) can never
//    catch a regression that starts filtering on status.
// 2. Stale binding — the resolver's own defensive `if (!menu) return null`
//    guard (see its "Defensive note" doc comment) for when the derived
//    `nav_location_bindings` index points at a menu id the menu repo no
//    longer has. This produces the same `null` result as "no binding at all",
//    so any test asserting only the end result — "nothing rendered" — cannot
//    tell the two branches apart; a regression in the `!menu` guard
//    specifically (e.g. it starts throwing, or dereferences `menu` before the
//    null check) would pass unnoticed if the only observed signal is the
//    final `null`/non-null outcome. Each test below seeds ONLY the state
//    needed to force its own branch, isolating the mechanism rather than the
//    rendered output.
// ---------------------------------------------------------------------------

test("resolveForLocation resolves a trashed (soft-deleted) menu exactly like a published one — status never gates resolution, only the purge lifecycle does", async () => {
  const repo = new InMemoryMenuRepo({});
  const bindingRepo = new InMemoryNavLocationBindingRepo({});

  // Constructed directly (not via createMenu + deleteMenu) so this test
  // isolates resolver.ts's own status-agnostic behavior from menu-service.ts's
  // deleteMenu logic — going through the full ladder would conflate two units
  // and could pass or fail for reasons unrelated to resolution itself.
  const trashedMenu: NavMenuEntry = {
    id: "menu-1",
    workspaceId: "ws-1",
    slug: "primary-nav",
    title: "Primary Nav",
    status: "trash",
    doc: {
      type: NAV_DOC_TYPE,
      version: 1,
      items: [{ id: "item-1", label: "Home", target: { kind: "url", href: "/" } }],
    },
    locations: ["primary"],
    updatedAt: "2026-07-10T00:00:00.000Z",
    version: 2,
  };
  await repo.save(trashedMenu);
  await bindingRepo.upsert({
    workspaceId: "ws-1",
    locationKey: "primary",
    menuId: "menu-1",
    boundAt: "2026-07-10T00:00:00.000Z",
  });

  const resolved = await resolveForLocation({
    deps: { menuRepo: repo, bindingRepo, resolveTargetHref: fakeResolveTargetHref },
    input: { workspaceId: "ws-1", locationKey: "primary" },
  });

  assert.ok(resolved, "a trashed-but-still-bound menu must still resolve, not silently disappear");
  assert.equal(resolved.items.length, 1);
  assert.equal(resolved.items[0]!.href, "/");
  assert.equal(resolved.items[0]!.available, true);
});

test("resolveForLocation returns null, not a throw, when the binding index points at a menu id with no backing menu row (a stale/dangling derived-index entry)", async () => {
  const repo = new InMemoryMenuRepo({});
  const bindingRepo = new InMemoryNavLocationBindingRepo({});

  // Seeded directly on the binding repo — bypassing assignLocation, which
  // requires a real menu to exist — specifically to reach resolveForLocation's
  // `!menu` guard without ever exercising its `!binding` guard.
  await bindingRepo.upsert({
    workspaceId: "ws-1",
    locationKey: "footer",
    menuId: "menu-does-not-exist",
    boundAt: "2026-07-10T00:00:00.000Z",
  });

  const result = await resolveForLocation({
    deps: { menuRepo: repo, bindingRepo, resolveTargetHref: fakeResolveTargetHref },
    input: { workspaceId: "ws-1", locationKey: "footer" },
  });

  assert.equal(result, null);
});

test("resolveForLocation renders an item with no label as an empty label rather than undefined", async () => {
  const { repo, bindingRepo } = await seedMenuBoundToLocation([{ id: "item-1", target: { kind: "url", href: "/" } }]);
  const resolved = await resolveForLocation({
    deps: { menuRepo: repo, bindingRepo, resolveTargetHref: fakeResolveTargetHref },
    input: { workspaceId: "ws-1", locationKey: "primary" },
  });
  assert.equal(resolved?.items[0]?.label, "");
  assert.equal(resolved?.items[0]?.href, "/");
});

src/redirects/__tests__/phase-handler.or.source:
import assert from "node:assert/strict";
import { test } from "vitest";
import { nodeTestContext } from "./support/node-test-context.fixture.js";

import { createVerifiedOrigin, InMemoryOriginSettingRepo, OriginRegistry } from "@jini-ai/http-kit/verified-origin";
import { redirectMatcher } from "../matcher.js";
import { RedirectPhaseHandlerResolver } from "../resolver.js";
import { InMemoryRedirectRepo } from "../repo.memory.js";
import type { RedirectRecord } from "../types.js";

/**
 * @file T006 (INV-03, AC-12/13/14, REQ-09/10) — DEDICATED, highest-aggregate-
 * risk test: the open-redirect write+read dual-path check's READ half.
 *
 * `RedirectResolver.resolve` must call `OriginRegistryPort.isAllowedRedirectTarget`
 * against the FULLY-INTERPOLATED `location` in every code path before EVER
 * returning `matched: true`. A wildcard capture crafted to interpolate a
 * disallowed cross-origin location must resolve to `{ matched: false }` —
 * NEVER a match, regardless of match-type precedence. A same-origin relative
 * target must still pass.
 *
 * This gets the same dedicated, non-folded treatment SPEC-007 gave its write
 * chokepoint (T008 there) — certified against the real `RedirectMatcher` +
 * `InMemoryRedirectRepo` + the real `OriginRegistry` (not a stub), so the
 * actual open-redirect oracle logic (`normalizeOriginCandidate` +
 * same-origin/allowlist checks) is exercised, not a mock that could hide a
 * bypass.
 */

const WORKSPACE_ID = "workspace-1";

function makeOriginRegistry(opts: { redirectAllowlist?: string[] } = {}) {
  const repo = new InMemoryOriginSettingRepo({ seeds: [
    {
      workspaceId: WORKSPACE_ID,
      origin: createVerifiedOrigin({
        scheme: "https",
        host: "trusted.example",
        verifiedAt: "2026-07-13T00:00:00.000Z",
        source: "workspace-setting",
      }),
      redirectAllowlist: opts.redirectAllowlist ?? [],
    },
  ] });
  return new OriginRegistry({ repo });
}

function rule(overrides: Partial<RedirectRecord>): RedirectRecord {
  return {
    id: overrides.id ?? "rule-1",
    workspaceId: WORKSPACE_ID,
    matchType: "exact",
    fromPattern: "/a",
    toTarget: "/b",
    statusCode: 301,
    status: "active",
    override: false,
    priority: 0,
    source: "manual",
    createdByPrincipal: "user-1",
    createdAt: "2026-07-13T00:00:00.000Z",
    updatedAt: "2026-07-13T00:00:00.000Z",
    version: 1,
    ...overrides,
  };
}

test("INV-03: a wildcard capture crafted to interpolate a disallowed cross-origin location NEVER resolves to matched:true", async () => {
  // Realistic scenario: an operator authors a "URL-shortener-style" wildcard
  // rule (`/go/*` -> `https://$1`, e.g. for social-share short links). An
  // attacker requests a path whose single-segment capture turns the
  // interpolated location into an absolute URL pointing at their own domain.
  const repo = new InMemoryRedirectRepo({ seed: [
    rule({
      id: "wildcard-evil",
      matchType: "wildcard",
      fromPattern: "/go/*",
      toTarget: "https://$1",
    }),
  ] }, {});
  const originRegistry = makeOriginRegistry(); // empty allowlist — evil.example is never allowed
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]), repo, matcher: redirectMatcher, originRegistry });

  const result = await resolver.resolve({
    workspaceId: WORKSPACE_ID,
    path: "/go/evil.example",
    phase: "post_content",
  });

  assert.deepEqual(result, { matched: false });
});

test("INV-03: a protocol-relative-looking interpolated location also never resolves to matched:true", async () => {
  const repo = new InMemoryRedirectRepo({ seed: [
    rule({ id: "wildcard-protocol-relative", matchType: "wildcard", fromPattern: "/go2/*", toTarget: "//$1" }),
  ] }, {});
  const originRegistry = makeOriginRegistry();
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]), repo, matcher: redirectMatcher, originRegistry });

  const result = await resolver.resolve({
    workspaceId: WORKSPACE_ID,
    path: "/go2/evil.example",
    phase: "post_content",
  });

  assert.deepEqual(result, { matched: false });
});

test("a same-origin relative target passes (matched:true, oracle allows it)", async () => {
  const repo = new InMemoryRedirectRepo({ seed: [
    rule({ id: "same-origin", matchType: "exact", fromPattern: "/old", toTarget: "/new" }),
  ] }, {});
  const originRegistry = makeOriginRegistry();
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]), repo, matcher: redirectMatcher, originRegistry });

  const result = await resolver.resolve({ workspaceId: WORKSPACE_ID, path: "/old", phase: "post_content" });

  assert.deepEqual(result, {
    matched: true,
    redirectId: "same-origin",
    location: "/new",
    statusCode: 301,
    matchType: "exact",
  });
});

test("an ALLOWLISTED cross-origin wildcard target passes", async () => {
  const repo = new InMemoryRedirectRepo({ seed: [
    rule({ id: "wildcard-allowlisted", matchType: "wildcard", fromPattern: "/go3/*", toTarget: "https://$1" }),
  ] }, {});
  const originRegistry = makeOriginRegistry({ redirectAllowlist: ["partner.example"] });
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]), repo, matcher: redirectMatcher, originRegistry });

  const result = await resolver.resolve({
    workspaceId: WORKSPACE_ID,
    path: "/go3/partner.example",
    phase: "post_content",
  });

  assert.equal(result.matched, true);
  if (result.matched) assert.equal(result.location, "https://partner.example");
});

test("a same-origin ABSOLUTE target (matching the workspace's own verified origin) passes", async () => {
  const repo = new InMemoryRedirectRepo({ seed: [
    rule({
      id: "absolute-same-origin",
      matchType: "exact",
      fromPattern: "/old-abs",
      toTarget: "https://trusted.example/new-abs",
    }),
  ] }, {});
  const originRegistry = makeOriginRegistry();
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]), repo, matcher: redirectMatcher, originRegistry });

  const result = await resolver.resolve({ workspaceId: WORKSPACE_ID, path: "/old-abs", phase: "post_content" });

  assert.equal(result.matched, true);
});

test("no matching rule resolves to matched:false without ever consulting the oracle for a nonexistent path", async () => {
  const t = nodeTestContext();
  const repo = new InMemoryRedirectRepo({ seed: [] }, {});
  const originRegistry = makeOriginRegistry();
  const oracle = t.mock.method(originRegistry, "isAllowedRedirectTarget", async () => { throw new Error("no candidate to check"); });
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]), repo, matcher: redirectMatcher, originRegistry });

  const result = await resolver.resolve({ workspaceId: WORKSPACE_ID, path: "/nowhere", phase: "post_content" });
  assert.deepEqual(result, { matched: false });
  assert.equal(oracle.mock.callCount(), 0);
});

test("pre_content phase only considers override:true rules", async () => {
  const repo = new InMemoryRedirectRepo({ seed: [
    rule({ id: "non-override", matchType: "exact", fromPattern: "/x", toTarget: "/y", override: false }),
  ] }, {});
  const originRegistry = makeOriginRegistry();
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]), repo, matcher: redirectMatcher, originRegistry });

  const result = await resolver.resolve({ workspaceId: WORKSPACE_ID, path: "/x", phase: "pre_content" });
  assert.deepEqual(result, { matched: false });
});

test("pre_content phase matches an override:true rule", async () => {
  const repo = new InMemoryRedirectRepo({ seed: [
    rule({ id: "override-rule", matchType: "exact", fromPattern: "/x", toTarget: "/y", override: true }),
  ] }, {});
  const originRegistry = makeOriginRegistry();
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]), repo, matcher: redirectMatcher, originRegistry });

  const result = await resolver.resolve({ workspaceId: WORKSPACE_ID, path: "/x", phase: "pre_content" });
  assert.equal(result.matched, true);
});

for (const pending of [false, true]) {
  test(`redirect resolution records the exact hit and completes with an ${pending ? "unsettled" : "rejecting"} outbox`, async () => {
    let release!: () => void;
    const held = new Promise<void>(resolve => { release = resolve; });
    const events: unknown[] = [];
    const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]),
      repo: new InMemoryRedirectRepo({ seed: [rule({ id: "hit-rule", fromPattern: "/old", toTarget: "/new" })] }, {}),
      matcher: redirectMatcher, originRegistry: makeOriginRegistry(),
      hits: { clock: { nowMs: () => Date.parse("2026-07-13T00:00:00.000Z") }, idGen: { newId: () => "hit-1" },
        outbox: { enqueue: async (event: unknown) => { events.push(event); if (pending) await held; else throw new Error("hit sink unavailable"); } } as never },
    });
    const resolution = resolver.resolve({ workspaceId: WORKSPACE_ID, path: "/old", phase: "post_content" });
    try {
      const result = await Promise.race([resolution, new Promise(resolve => setImmediate(() => resolve("still waiting on outbox")))]);
      assert.deepEqual(result, { matched: true, redirectId: "hit-rule", location: "/new", statusCode: 301, matchType: "exact" });
      assert.deepEqual(events, [{ id: "hit-1", name: "redirect.hit", occurredAt: "2026-07-13T00:00:00.000Z",
        aggregateId: "hit-rule", workspaceId: WORKSPACE_ID,
        payload: { workspaceId: WORKSPACE_ID, redirectId: "hit-rule", at: "2026-07-13T00:00:00.000Z" } }]);
    } finally { release(); await resolution; }
  });
}

test("a relative redirect without a verified origin fails closed", async () => {
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]),
    repo: new InMemoryRedirectRepo({ seed: [rule({})] }, {}), matcher: redirectMatcher,
    originRegistry: new OriginRegistry({ repo: new InMemoryOriginSettingRepo({ seeds: [] }) }),
  });
  assert.deepEqual(await resolver.resolve({ workspaceId: WORKSPACE_ID, path: "/a", phase: "post_content" }), { matched: false });
});

test("an allowed absolute redirect fails closed when the canonical origin cannot be read", async () => {
  const t = nodeTestContext();
  const originRegistry = makeOriginRegistry({ redirectAllowlist: ["partner.example"] });
  t.mock.method(originRegistry, "canonicalOrigin", async () => { throw new Error("origin unavailable"); });
  const oracle = t.mock.method(originRegistry, "isAllowedRedirectTarget");
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]),
    repo: new InMemoryRedirectRepo({ seed: [rule({ toTarget: "https://partner.example/new" })] }, {}), matcher: redirectMatcher, originRegistry,
  });
  assert.deepEqual(await resolver.resolve({ workspaceId: WORKSPACE_ID, path: "/a", phase: "post_content" }), { matched: false });
  assert.deepEqual(oracle.mock.calls.map(c => c.arguments), [[{ context: { workspaceId: WORKSPACE_ID }, url: "https://partner.example/new" }]]);
});

test("a dynamic rule the repo returns but whose pattern does not match the path resolves to matched:false with nothing refused", async () => {
  const repo = new InMemoryRedirectRepo({ seed: [rule({ id: "wild", matchType: "wildcard", fromPattern: "/go/*", toTarget: "/to/$1" })] }, {});
  const checked: string[] = [];
  const originRegistry = makeOriginRegistry();
  const oracle = {
    canonicalOrigin: originRegistry.canonicalOrigin.bind(originRegistry),
    isAllowedRedirectTarget: async (input: { url: string }) => { checked.push(input.url); return true; },
  };
  const resolver = new RedirectPhaseHandlerResolver({ reservedSegments: new Set(["admin", "api"]), repo, matcher: redirectMatcher, originRegistry: oracle });
  assert.deepEqual(await resolver.resolveWithRefusals({ workspaceId: WORKSPACE_ID, path: "/elsewhere/x", phase: "post_content" }), { resolution: { matched: false }, refused: [] });
  assert.deepEqual(checked, []);
});

src/forms/__tests__/repo.dialects.test.t.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { describeEachDialect } from "./support/dialect-matrix.fixture.js";
import type { ContentKernel } from "./support/dialect-matrix.fixture.js";
import { FormSlugConflictError } from "../index.js";
import { formDefinitionRepoFor, formSubmissionRepoFor } from "./support/repo-ports.fixture.js";
import { formSubmissionRepoFor as packageSubmissionRepoFor } from "../sql/index.js";
import { tables } from "./support/forms-tables.fixture.js";
import type { FormDefinitionRecord, FormSubmissionRecord } from "../index.js";

/**
 * @file Both forms repos on every dialect through the kernel's matrix (`describeEachDialect` + ONE
 * factory: one query body serves every dialect). Covers every public method: hit, miss,
 * other-workspace isolation, trashed-row handling and rollback.
 */

const WS = "ws-dialects";
const OTHER = "ws-other";
const T0 = "2026-09-28T00:00:00.000Z";

function definition(id: string, slug: string, overrides: Partial<FormDefinitionRecord> = {}): FormDefinitionRecord {
  return {
    id,
    workspaceId: WS,
    name: `Form ${slug}`,
    slug,
    fields: [{ id: "name", label: "Name", type: "text", required: true }],
    notify: { enabled: true, recipients: ["a@example.com"] },
    status: "active",
    createdAt: T0,
    updatedAt: T0,
    version: 1,
    ...overrides,
  };
}

function submission(id: string, submittedAt: string, overrides: Partial<FormSubmissionRecord> = {}): FormSubmissionRecord {
  return {
    id,
    workspaceId: WS,
    formDefinitionId: "def-1",
    data: { name: `n-${id}`, agree: true },
    sourceIp: "203.0.113.9",
    submittedAt,
    ...overrides,
  };
}

function repos(kernel: ContentKernel) {
  return { kernel, defs: formDefinitionRepoFor(kernel), subs: formSubmissionRepoFor(kernel) };
}

describeEachDialect(
  "forms repos",
  { tables: ["form_definitions", "form_submissions"], make: repos },
  (makeRepos) => {
    const trash = (kernel: ContentKernel, table: "form_definitions" | "form_submissions", id: string) =>
      kernel.run((db) => db.updateTable(table).set({ deleted_at: T0 }).where("id", "=", id).execute());

    test("definition create then findById / findBySlug / list round-trip", async () => {
      const { defs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      await defs.create(definition("def-2", "survey"));
      await defs.create(definition("def-x", "contact", { workspaceId: OTHER }));
      assert.deepEqual(await defs.findById({ workspaceId: WS, id: "def-1" }), definition("def-1", "contact"));
      assert.deepEqual(await defs.findBySlug({ workspaceId: WS, slug: "survey" }), definition("def-2", "survey"));
      assert.deepEqual((await defs.list({ workspaceId: WS })).map((d) => d.id).sort(), ["def-1", "def-2"]);
    });

    test("definition reads miss unknown ids/slugs and never cross workspaces", async () => {
      const { defs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      assert.equal(await defs.findById({ workspaceId: WS, id: "nope" }), null);
      assert.equal(await defs.findById({ workspaceId: OTHER, id: "def-1" }), null);
      assert.equal(await defs.findBySlug({ workspaceId: WS, slug: "nope" }), null);
      assert.equal(await defs.findBySlug({ workspaceId: OTHER, slug: "contact" }), null);
      assert.deepEqual(await defs.list({ workspaceId: OTHER }), []);
    });

    test("a duplicate slug throws FormSlugConflictError; another workspace may reuse it", async () => {
      const { defs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      await assert.rejects(
        defs.create(definition("def-2", "contact")),
        (err: unknown) => err instanceof FormSlugConflictError && /already exists/.test(err.message) && err.slug === "contact"
      );
      await defs.create(definition("def-3", "contact", { workspaceId: OTHER }));
      assert.equal((await defs.list({ workspaceId: WS })).length, 1);
    });

    test("a trashed row hides from reads but still holds its slug, with the Trash message", async () => {
      const { kernel, defs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      await trash(kernel, "form_definitions", "def-1");
      assert.equal(await defs.findById({ workspaceId: WS, id: "def-1" }), null);
      assert.equal(await defs.findBySlug({ workspaceId: WS, slug: "contact" }), null);
      assert.deepEqual(await defs.list({ workspaceId: WS }), []);
      assert.equal(await defs.isSlugTaken({ workspaceId: WS, slug: "contact" }), true);
      await assert.rejects(defs.create(definition("def-2", "contact")), /in the Trash/);
    });

    test("isSlugTaken: hit, miss and other workspace", async () => {
      const { defs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      assert.equal(await defs.isSlugTaken({ workspaceId: WS, slug: "contact" }), true);
      assert.equal(await defs.isSlugTaken({ workspaceId: WS, slug: "nope" }), false);
      assert.equal(await defs.isSlugTaken({ workspaceId: OTHER, slug: "contact" }), false);
    });

    test("update rewrites the live row but never moves version; other workspaces and trashed rows are untouched", async () => {
      const { kernel, defs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      await defs.create(definition("def-t", "old"));
      await defs.create(definition("def-o", "contact", { workspaceId: OTHER }));
      await trash(kernel, "form_definitions", "def-t");
      await defs.update(definition("def-1", "contact", { name: "Renamed", fields: [], status: "disabled", updatedAt: "2026-09-29T00:00:00.000Z", version: 99 }));
      await defs.update(definition("def-t", "old", { name: "Ghost" }));
      await defs.update(definition("def-o", "contact", { workspaceId: WS, name: "Wrong ws" }));
      assert.deepEqual(
        await defs.findById({ workspaceId: WS, id: "def-1" }),
        definition("def-1", "contact", { name: "Renamed", fields: [], status: "disabled", updatedAt: "2026-09-29T00:00:00.000Z", version: 1 })
      );
      assert.equal((await defs.findById({ workspaceId: OTHER, id: "def-o" }))?.name, "Form contact");
      const trashed = await kernel.run((db) => db.selectFrom("form_definitions").select("name").where("id", "=", "def-t").executeTakeFirst());
      assert.equal(trashed?.name, "Form old");
    });

    test("submission create then findById round-trips; misses, other workspace and trashed rows return null", async () => {
      const { kernel, defs, subs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      await subs.create(submission("s1", T0));
      await subs.create(submission("s2", T0));
      assert.deepEqual(await subs.findById({ workspaceId: WS, id: "s1" }), submission("s1", T0));
      assert.equal(await subs.findById({ workspaceId: WS, id: "nope" }), null);
      assert.equal(await subs.findById({ workspaceId: OTHER, id: "s1" }), null);
      await trash(kernel, "form_submissions", "s2");
      assert.equal(await subs.findById({ workspaceId: WS, id: "s2" }), null);
    });

    test("listByDefinition pages newest-first with an id tie-break and a cursor", async () => {
      const { defs, subs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      await subs.create(submission("a", "2026-09-28T01:00:00.000Z"));
      await subs.create(submission("b", "2026-09-28T02:00:00.000Z"));
      await subs.create(submission("c", "2026-09-28T02:00:00.000Z"));
      await subs.create(submission("d", "2026-09-28T03:00:00.000Z"));
      const first = await subs.listByDefinition({ workspaceId: WS, formDefinitionId: "def-1", limit: 2 });
      assert.deepEqual(first.items.map((s) => s.id), ["d", "c"]);
      assert.equal(first.nextCursor, "c");
      const second = await subs.listByDefinition({ workspaceId: WS, formDefinitionId: "def-1", limit: 2, cursor: first.nextCursor });
      assert.deepEqual(second.items.map((s) => s.id), ["b", "a"]);
      assert.equal(second.nextCursor, null);
    });

    test("listByDefinition ignores an unknown cursor and excludes other definitions, workspaces and trashed rows", async () => {
      const { kernel, defs, subs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      await defs.create(definition("def-2", "survey"));
      await defs.create(definition("def-w", "contact", { workspaceId: OTHER }));
      await subs.create(submission("a", "2026-09-28T01:00:00.000Z"));
      await subs.create(submission("t", "2026-09-28T02:00:00.000Z"));
      await subs.create(submission("o", "2026-09-28T03:00:00.000Z", { formDefinitionId: "def-2" }));
      await subs.create(submission("w", "2026-09-28T04:00:00.000Z", { workspaceId: OTHER, formDefinitionId: "def-w" }));
      await trash(kernel, "form_submissions", "t");
      const page = await subs.listByDefinition({ workspaceId: WS, formDefinitionId: "def-1", limit: 10, cursor: "unknown" });
      assert.deepEqual(page.items.map((s) => s.id), ["a"]);
      assert.equal(page.nextCursor, null);
      // A cursor id from another workspace resolves to nothing (first page), never leaks its position.
      const crossWs = await subs.listByDefinition({ workspaceId: WS, formDefinitionId: "def-1", limit: 10, cursor: "w" });
      assert.deepEqual(crossWs.items.map((s) => s.id), ["a"]);
      assert.deepEqual(await subs.listByDefinition({ workspaceId: WS, formDefinitionId: "empty", limit: 5 }), { items: [], nextCursor: null });
    });

    test("the package's submission repo factory binds the host table names and pages by its options cursor", async () => {
      const { kernel, defs } = makeRepos();
      const subs = packageSubmissionRepoFor({ kernel, tables }, {});
      await defs.create(definition("def-1", "contact"));
      await subs.create(submission("a", "2026-09-28T00:00:01.000Z"));
      await subs.create(submission("b", "2026-09-28T00:00:02.000Z"));
      const first = await subs.listByDefinition({ workspaceId: WS, formDefinitionId: "def-1", limit: 1 });
      assert.deepEqual(first.items.map((s) => s.id), ["b"]);
      assert.equal(first.nextCursor, "b");
      const second = await subs.listByDefinition({ workspaceId: WS, formDefinitionId: "def-1", limit: 1 }, { cursor: first.nextCursor });
      assert.deepEqual(second, { items: [{ ...submission("a", "2026-09-28T00:00:01.000Z") }], nextCursor: null });
    });

    test("a submission whose IP the retention sweep cleared reads back with an empty source IP", async () => {
      const { kernel, defs, subs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      await subs.create(submission("a", T0));
      await kernel.run((db) => db.updateTable("form_submissions").set({ source_ip: null }).where("id", "=", "a").execute());
      const read = await subs.findById({ workspaceId: WS, id: "a" });
      assert.equal(read?.sourceIp, "");
      assert.deepEqual(read?.data, { name: "n-a", agree: true });
    });

    test("a transaction's definition + submission writes roll back together", async () => {
      const { kernel, defs, subs } = makeRepos();
      await assert.rejects(
        kernel.transaction(async () => {
          await defs.create(definition("def-1", "contact"));
          await subs.create(submission("s1", T0));
          throw new Error("boom");
        }),
        /boom/
      );
      assert.equal(await defs.findById({ workspaceId: WS, id: "def-1" }), null);
      assert.equal(await subs.findById({ workspaceId: WS, id: "s1" }), null);
    });

    test("a slug conflict inside a caller's transaction aborts the earlier writes too", async () => {
      const { kernel, defs } = makeRepos();
      await defs.create(definition("def-1", "contact"));
      await assert.rejects(
        kernel.transaction(async () => {
          await defs.create(definition("def-2", "fresh"));
          await defs.create(definition("def-3", "contact"));
        }),
        FormSlugConflictError
      );
      assert.equal(await defs.findBySlug({ workspaceId: WS, slug: "fresh" }), null);
    });
  }
);

