/**
 * @file `SharpImageTransformer` test (`image-transformer.sharp.ts`).
 *
 * `sharp` is an OPTIONAL runtime dependency of this package (see that file's
 * header — mirrors `identity/hasher.ts`'s treatment of `argon2`), but this
 * test statically imports it to exercise the real resize + format-conversion
 * success path, not just the honest-failure path — the same choice
 * `identity/__tests__/*.test.ts` makes for `argon2`. That means `sharp` must
 * be a real, installed devDependency of this package for this test to run;
 * see the package's `argon2` peerDependency/devDependency entries for the
 * precedent this mirrors.
 */
import assert from "node:assert/strict";
import { test } from "vitest";
import sharp from "sharp";

import { ImageSourceCorruptError, ImageTransformUnavailableError, SharpImageTransformer, type SharpInstance } from "../image-transformer.sharp.js";

test("SharpImageTransformer.transform actually resizes and re-encodes real image bytes", async () => {
  const transformer = new SharpImageTransformer();
  const sourcePng = await sharp({
    create: { width: 20, height: 10, channels: 3, background: { r: 10, g: 20, b: 30 } },
  })
    .png()
    .toBuffer();

  const result = await transformer.transform({
    bytes: new Uint8Array(sourcePng),
    params: { width: 5, height: 5, format: "jpeg" },
  });

  assert.strictEqual(result.contentType, "image/jpeg");
  const outMeta = await sharp(Buffer.from(result.bytes)).metadata();
  assert.strictEqual(outMeta.format, "jpeg");
  assert.strictEqual(outMeta.width, 5);
  assert.strictEqual(outMeta.height, 5);
  // Re-encoded output must differ from the untouched source bytes (never a passthrough).
  assert.notDeepStrictEqual(Buffer.from(result.bytes), sourcePng);
});

test("SharpImageTransformer.transform rejects genuinely invalid image bytes with a named ImageSourceCorruptError (not a silent fallback, and not an undifferentiated throw)", async () => {
  const transformer = new SharpImageTransformer();
  await assert.rejects(
    () =>
      transformer.transform({
        bytes: new TextEncoder().encode("not-real-image-bytes"),
        params: { width: 100, height: 100, format: "jpeg" },
      }),
    (error: unknown) => {
      assert.ok(error instanceof ImageSourceCorruptError, `expected ImageSourceCorruptError, got ${String(error)}`);
      return true;
    }
  );
});

// A minimal, deliberately-malformed GIF: a valid GIF89a signature/logical-screen-descriptor
// followed by a frame libvips (sharp's decoder) rejects — this is the SAME failure class the live
// defect this test guards against actually hit (a real, small user-uploaded GIF whose bytes pass
// this package's own magic-byte sniff, `sniffContentType`, yet cannot be decoded by `sharp`). Proves
// the fix does not only cover "not an image at all" but also "sniffs as an image, isn't really
// decodable" — the exact gap that produced an opaque 500 on the live route.
const MALFORMED_GIF = Buffer.from([
  0x47, 0x49, 0x46, 0x38, 0x39, 0x61, // "GIF89a"
  0x08, 0x00, 0x08, 0x00, // 8x8 logical screen descriptor
  0x80, 0x00, 0x3f, // packed fields / bg color / aspect ratio
  0xff, 0xff, 0xc0, // truncated/invalid global color table + no valid image-descriptor/frame data
]);

test("SharpImageTransformer.transform rejects a malformed GIF that passes this package's own magic-byte sniff but is not really decodable", async () => {
  const transformer = new SharpImageTransformer();
  await assert.rejects(
    () => transformer.transform({ bytes: MALFORMED_GIF, params: { format: "webp" } }),
    (error: unknown) => {
      assert.ok(error instanceof ImageSourceCorruptError, `expected ImageSourceCorruptError, got ${String(error)}`);
      return true;
    }
  );
});

test("ImageTransformUnavailableError stays exported and instantiable for environments without 'sharp'", () => {
  const err = new ImageTransformUnavailableError({ message: "the 'sharp' npm package is not installed" });
  assert.ok(err instanceof Error);
  assert.match(err.message, /sharp/i);
});

/**
 * Builds a real multi-frame animated GIF (three distinct solid-color frames) via `sharp`'s own
 * `join({ animated: true })` API — the same fixture-construction technique this test file already
 * uses for its "actually resizes" test, applied to a genuinely multi-page source instead of a
 * synthetic single frame. Used below to prove animation survives `SharpImageTransformer.transform`
 * end to end, not just that the call succeeds or that bytes changed.
 */
async function buildAnimatedGif(): Promise<Buffer> {
  const colors = [
    { r: 255, g: 0, b: 0 },
    { r: 0, g: 255, b: 0 },
    { r: 0, g: 0, b: 255 },
  ];
  const frames = await Promise.all(
    colors.map((background) =>
      sharp({ create: { width: 20, height: 10, channels: 3, background } })
        .png()
        .toBuffer()
    )
  );
  return sharp(frames, { join: { animated: true } }).gif().toBuffer();
}

test("SharpImageTransformer.transform preserves every frame of an animated GIF when the target format can carry animation (webp)", async () => {
  const transformer = new SharpImageTransformer();
  const animatedGif = await buildAnimatedGif();
  const sourceMeta = await sharp(animatedGif, { animated: true }).metadata();
  assert.strictEqual(sourceMeta.pages, 3, "fixture must actually be 3 frames, or this test proves nothing");

  const result = await transformer.transform({
    bytes: new Uint8Array(animatedGif),
    params: { format: "webp" },
  });

  const outMeta = await sharp(Buffer.from(result.bytes), { animated: true }).metadata();
  assert.strictEqual(outMeta.format, "webp");
  // The bug this guards against: sharp decodes only frame 0 without `{ animated: true }` on load,
  // silently flattening every animated GIF/WebP served through the "public" transform to a still.
  // `pages` would read back as `undefined` (single-frame) under that bug — asserting the exact
  // frame count (not merely "> 1" or "no error") is what catches a regression to that behavior.
  assert.strictEqual(outMeta.pages, 3, "output must retain all 3 source frames, not flatten to a still");
});

test("SharpImageTransformer.transform keeps animation frame-accurate (not squashed) across a real resize", async () => {
  const transformer = new SharpImageTransformer();
  const animatedGif = await buildAnimatedGif();

  const result = await transformer.transform({
    bytes: new Uint8Array(animatedGif),
    params: { width: 10, height: 5, fit: "cover", format: "webp" },
  });

  const outMeta = await sharp(Buffer.from(result.bytes), { animated: true }).metadata();
  assert.strictEqual(outMeta.pages, 3, "resize must not drop frames");
  assert.strictEqual(outMeta.width, 10);
  // The trap a naive `{ animated: true }`-only fix falls into: sharp represents multi-frame images
  // as one tall vertical strip, with `pageHeight` carrying the PER-FRAME height. `pageHeight` must
  // equal the requested `height` (5) — if the resize instead treated 5 as the TOTAL strip height,
  // `pageHeight` would read back as `5 / 3` (not an integer) and the real per-frame image would be
  // squashed to a sliver.
  assert.strictEqual(outMeta.pageHeight, 5, "each frame must be resized to the requested height, not the whole strip");
  assert.strictEqual(outMeta.height, 15, "total strip height must be pageHeight * frame count (5 * 3)");
});

test("SharpImageTransformer.transform deliberately flattens an animated source to one representative frame when the target format cannot carry animation (jpeg)", async () => {
  const transformer = new SharpImageTransformer();
  const animatedGif = await buildAnimatedGif();

  const result = await transformer.transform({
    bytes: new Uint8Array(animatedGif),
    params: { format: "jpeg" },
  });

  const outMeta = await sharp(Buffer.from(result.bytes)).metadata();
  assert.strictEqual(outMeta.format, "jpeg");
  // JPEG cannot carry animation. The regression this guards against is worse than a plain flatten:
  // loading with `{ animated: true }` unconditionally and then encoding to a non-animated format
  // makes sharp write out the whole multi-frame "toilet roll" as ONE tall static image (all frames
  // stacked, visibly corrupted) instead of either a clean single frame or a real animated output.
  // A correctly-flattened single frame must report the SOURCE frame's own height (10), not
  // `pageHeight * frameCount` (30).
  assert.strictEqual(outMeta.height, 10, "must be a single clean frame, not all frames stacked into one image");
  assert.strictEqual(outMeta.pages, undefined);
});

test('transparent PNG pixels become white in JPEG while PNG retains alpha', async () => {
  const source = await sharp({ create: { width: 8, height: 8, channels: 4, background: { r: 255, g: 0, b: 0, alpha: 0 } } }).png().toBuffer();
  const transformer = new SharpImageTransformer();
  const jpeg = await transformer.transform({ bytes: source, params: { format: 'jpeg', quality: 82 } });
  const pixels = await sharp(jpeg.bytes).raw().toBuffer();
  assert.deepEqual(pixels, Buffer.alloc(8 * 8 * 3, 255), 'transparent pixels must flatten onto white, not black');
  const png = await transformer.transform({ bytes: source, params: { format: 'png' } });
  assert.deepEqual(await sharp(png.bytes).raw().toBuffer(), await sharp(source).raw().toBuffer(), 'alpha-capable formats retain transparent pixels');
});

test('og JPEG applies named dimensions and quality to real pixels', async () => {
  const source = await sharp({ create: { width: 1200, height: 630, channels: 3, background: { r: 173, g: 91, b: 37 } } }).png().toBuffer();
  const params = { width: 1200, height: 630, fit: 'cover' as const, format: 'jpeg' as const, quality: 82 };
  const transformed = await new SharpImageTransformer().transform({ bytes: source, params });
  const expected = await sharp(source).resize(1200, 630, { fit: 'cover' }).jpeg({ quality: 82 }).toBuffer();
  assert.equal(transformed.contentType, 'image/jpeg');
  assert.deepEqual(Buffer.from(transformed.bytes), expected);
  const decoded = await sharp(transformed.bytes).metadata();
  assert.equal(decoded.width, 1200);
  assert.equal(decoded.height, 630);
  assert.equal(decoded.format, 'jpeg');
});

test('a sharp loader that fails is reported as ImageTransformUnavailableError, never as a corrupt source', async () => {
  const transformer = new SharpImageTransformer({}, { loadSharp: () => { throw Object.assign(new Error("Cannot find module 'sharp'"), { code: 'MODULE_NOT_FOUND' }); } });
  await assert.rejects(transformer.transform({ bytes: new Uint8Array([1]), params: { format: 'png' } }), (error: unknown) => {
    assert.ok(error instanceof ImageTransformUnavailableError);
    assert.match(error.message, /'sharp' npm package is not installed/);
    return true;
  });
});

test('a non-Error rejection from the codec still surfaces as ImageSourceCorruptError carrying its text', async () => {
  const calls: unknown[][] = [];
  const failing: SharpInstance = {
    resize: (...args) => { calls.push(['resize', ...args]); return failing; },
    flatten: (options) => { calls.push(['flatten', options]); return failing; },
    toFormat: (...args) => { calls.push(['toFormat', ...args]); return failing; },
    toBuffer: () => Promise.reject('VipsJpeg: premature end of input'),
  };
  const transformer = new SharpImageTransformer({}, { loadSharp: () => (_input, options) => { calls.push(['load', options]); return failing; } });
  await assert.rejects(transformer.transform({ bytes: new Uint8Array([1]), params: { format: 'jpeg' } }), (error: unknown) => {
    assert.ok(error instanceof ImageSourceCorruptError);
    assert.equal(error.message, "the source image could not be decoded/re-encoded (target format 'jpeg'): VipsJpeg: premature end of input");
    return true;
  });
  // No resize without dimensions; JPEG is flattened onto white and encoded without a quality override.
  assert.deepEqual(calls, [['load', undefined], ['flatten', { background: '#ffffff' }], ['toFormat', 'jpeg', undefined]]);
});

scripts/__tests__/check-packaging.test.t.source:
import { describe, expect, it } from 'vitest';
import { mkdtempSync, mkdirSync, realpathSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

import {
  bareImportSpecifiers,
  checkPackaging,
  envProblems,
  isCheckedSource,
  main,
  packageNameOf,
  runCheckPackaging,
  sideEffectProblems,
  undeclaredImportProblems,
  walkFiles,
} from '../check-packaging.mjs';

/**
 * @file The packaging guard's three checks are pure over `{ rel, src }`; the CLI's filesystem,
 * console and exit are ports. Fakes below are a hand-written in-memory tree, never a module mock.
 */

/** In-memory filesystem: keys ending in "/" are directories, everything else a file. */
function fakeFs(tree: Record<string, string>) {
  const isDir = (p: string) => Object.keys(tree).some((k) => k.startsWith(`${p}/`));
  return {
    readFileSync(path: string) {
      const content = tree[path];
      if (content === undefined) throw new Error(`ENOENT: ${path}`);
      return content;
    },
    readdirSync(dir: string) {
      const names = Object.keys(tree)
        .filter((k) => k.startsWith(`${dir}/`))
        .map((k) => k.slice(dir.length + 1).split('/')[0]!);
      return [...new Set(names)];
    },
    statSync(path: string) {
      return { isDirectory: () => isDir(path) };
    },
    realpathSync(path: string) {
      return path;
    },
  };
}

function captureOutput() {
  const out: string[] = [];
  const err: string[] = [];
  return { out, err, log: (line: string) => out.push(line), error: (line: string) => err.push(line) };
}

const ROOT = '/virtual/pkg';
const SCRIPT_URL = pathToFileURL(`${ROOT}/scripts/check-packaging.mjs`).href;

describe('bareImportSpecifiers', () => {
  it('collects static, re-export, side-effect, dynamic and require specifiers, skipping relatives', () => {
    const src = [
      "import { a } from 'pkg-a';",
      'import type { B } from "@scope/b/sub";',
      "export { c } from 'pkg-c/deep/path';",
      "import 'side-effect-pkg';",
      "const d = await import('pkg-d');",
      "const e = require('pkg-e');",
      "import { local } from './local.js';",
      "import { a as again } from 'pkg-a';",
    ].join('\n');
    expect(bareImportSpecifiers({ src })).toEqual(['pkg-a', '@scope/b/sub', 'pkg-c/deep/path', 'side-effect-pkg', 'pkg-d', 'pkg-e']);
  });

  it('ignores imports that only appear inside block or line comments', () => {
    const src = [
      '/* import { x } from "commented-block"; */',
      '// import { y } from "commented-line";',
      "import { z } from 'real-dep'; // trailing note: import 'not-this'",
    ].join('\n');
    expect(bareImportSpecifiers({ src })).toEqual(['real-dep']);
  });

  it('does not mistake the "//" of a URL for a comment that would hide the rest of the line', () => {
    expect(bareImportSpecifiers({ src: "const u = 'https://cdn.test'; const m = require('real-dep');" })).toEqual(['real-dep']);
  });
});

describe('packageNameOf', () => {
  it('maps scoped and unscoped deep specifiers to their installable package', () => {
    expect(packageNameOf({ spec: '@scope/name/deep/file.js' })).toBe('@scope/name');
    expect(packageNameOf({ spec: 'lodash/fp' })).toBe('lodash');
    expect(packageNameOf({ spec: 'plain' })).toBe('plain');
  });
});

describe('isCheckedSource', () => {
  it('checks shipped .ts sources only', () => {
    expect(isCheckedSource({ path: '/r/src/a.ts' })).toBe(true);
    expect(isCheckedSource({ path: '/r/src/a.test.ts' })).toBe(false);
    expect(isCheckedSource({ path: '/r/src/__tests__/fixture.ts' })).toBe(false);
    expect(isCheckedSource({ path: '/r/src/a.js' })).toBe(false);
  });
});

describe('undeclaredImportProblems', () => {
  const src = "import 'node:fs';\nimport { a } from 'dep-a';\nimport { p } from 'peer-p';\nimport { m } from '@scope/missing/x';";

  it('accepts dependencies, peerDependencies and node: builtins, and names each undeclared package', () => {
    expect(undeclaredImportProblems({ rel: 'src/x.ts', src, pkg: { dependencies: { 'dep-a': '1' }, peerDependencies: { 'peer-p': '1' } } })).toEqual([
      'src/x.ts: imports "@scope/missing" but it is in neither dependencies nor peerDependencies',
    ]);
  });

  it('treats a manifest with no dependency sections as declaring nothing', () => {
    expect(undeclaredImportProblems({ rel: 'src/x.ts', src, pkg: {} })).toEqual([
      'src/x.ts: imports "dep-a" but it is in neither dependencies nor peerDependencies',
      'src/x.ts: imports "peer-p" but it is in neither dependencies nor peerDependencies',
      'src/x.ts: imports "@scope/missing" but it is in neither dependencies nor peerDependencies',
    ]);
  });
});

describe('sideEffectProblems', () => {
  const withCalls = 'register(thing);\nsetup();\nconst ok = 1;\n  indented();';

  it('reports nothing for a module without top-level calls, whatever sideEffects says', () => {
    expect(sideEffectProblems({ rel: 'src/a.ts', src: 'const x = f();', pkg: { sideEffects: false } })).toEqual([]);
  });

  it('flags top-level calls when the package declares sideEffects: false', () => {
    expect(sideEffectProblems({ rel: 'src/core/a.ts', src: withCalls, pkg: { sideEffects: false } })).toEqual([
      'src/core/a.ts: 2 top-level call(s) = import-time side effects, but "./dist/core/a.js" is not listed in package.json "sideEffects". A bundler may drop this module.',
    ]);
  });

  it('flags a module missing from a sideEffects allow-list and accepts one that is listed', () => {
    expect(sideEffectProblems({ rel: 'src/a.ts', src: withCalls, pkg: { sideEffects: ['./dist/other.js'] } })).toHaveLength(1);
    expect(sideEffectProblems({ rel: 'src/a.ts', src: withCalls, pkg: { sideEffects: ['./dist/a.js'] } })).toEqual([]);
  });

  it('accepts top-level calls when sideEffects is absent or true (no tree-shaking licence given)', () => {
    expect(sideEffectProblems({ rel: 'src/a.ts', src: withCalls, pkg: {} })).toEqual([]);
    expect(sideEffectProblems({ rel: 'src/a.ts', src: withCalls, pkg: { sideEffects: true } })).toEqual([]);
  });
});

describe('envProblems', () => {
  it('flags any process.env read and passes sources that take configuration as parameters', () => {
    expect(envProblems({ rel: 'src/a.ts', src: 'const k = process.env.KEY;' })).toEqual([
      'src/a.ts: reads process.env — a library must not resolve host configuration; take it as a parameter',
    ]);
    expect(envProblems({ rel: 'src/a.ts', src: 'export function f(env: string) { return env; }' })).toEqual([]);
  });
});

describe('checkPackaging', () => {
  it('reports every check per file, in file order then check order', () => {
    const files = [
      { rel: 'src/clean.ts', src: "import { a } from 'dep-a';" },
      { rel: 'src/bad.ts', src: "import { z } from 'undeclared';\ninit();\nconst v = process.env.V;" },
    ];
    expect(checkPackaging({ pkg: { dependencies: { 'dep-a': '1' }, sideEffects: false }, files })).toEqual([
      'src/bad.ts: imports "undeclared" but it is in neither dependencies nor peerDependencies',
      'src/bad.ts: 1 top-level call(s) = import-time side effects, but "./dist/bad.js" is not listed in package.json "sideEffects". A bundler may drop this module.',
      'src/bad.ts: reads process.env — a library must not resolve host configuration; take it as a parameter',
    ]);
  });
});

describe('walkFiles', () => {
  it('lists nested files depth-first through the injected fs port', () => {
    const fs = fakeFs({ '/t/a.ts': '', '/t/sub/b.ts': '', '/t/sub/deeper/c.ts': '' });
    expect(walkFiles({ dir: '/t' }, { fs })).toEqual(['/t/a.ts', '/t/sub/b.ts', '/t/sub/deeper/c.ts']);
  });

  it('defaults to the real filesystem', () => {
    const dir = mkdtempSync(join(tmpdir(), 'check-packaging-'));
    try {
      mkdirSync(join(dir, 'nested'));
      writeFileSync(join(dir, 'nested', 'x.ts'), 'export {};');
      expect(walkFiles({ dir })).toEqual([join(dir, 'nested', 'x.ts')]);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

describe('runCheckPackaging', () => {
  const pkgJson = JSON.stringify({ dependencies: { 'dep-a': '1' }, sideEffects: false });

  it('prints OK with the number of shipped sources checked, skipping tests, and returns 0', () => {
    const fs = fakeFs({
      [`${ROOT}/package.json`]: pkgJson,
      [`${ROOT}/src/a.ts`]: "import { a } from 'dep-a';",
      [`${ROOT}/src/nested/b.ts`]: 'export const b = 1;',
      [`${ROOT}/src/__tests__/t.ts`]: 'const x = process.env.X;',
      [`${ROOT}/src/a.test.ts`]: "import 'undeclared';",
      [`${ROOT}/src/readme.md`]: 'process.env',
    });
    const io = captureOutput();
    expect(runCheckPackaging({ root: ROOT }, { fs, ...io })).toBe(0);
    expect(io.out).toEqual(['check:packaging — OK (2 files checked)']);
    expect(io.err).toEqual([]);
  });

  it('prints a problem count header then each problem with root-relative paths, and returns 1', () => {
    const fs = fakeFs({
      [`${ROOT}/package.json`]: pkgJson,
      [`${ROOT}/src/media/env.ts`]: 'export const v = process.env.V;',
    });
    const io = captureOutput();
    expect(runCheckPackaging({ root: ROOT }, { fs, ...io })).toBe(1);
    expect(io.out).toEqual([]);
    expect(io.err).toEqual([
      'check:packaging — 1 problem(s):\n',
      '  src/media/env.ts: reads process.env — a library must not resolve host configuration; take it as a parameter',
    ]);
  });
});

describe('main', () => {
  const failingTree = {
    [`${ROOT}/package.json`]: '{}',
    [`${ROOT}/src/a.ts`]: 'export const v = process.env.V;',
  };

  it('does nothing when this module is not the process entry point', () => {
    const exits: number[] = [];
    const io = captureOutput();
    const fs = fakeFs(failingTree);
    expect(main({ moduleUrl: SCRIPT_URL, argv: ['node', '/elsewhere/other.mjs'] }, { fs, ...io, exit: (c: number) => exits.push(c) })).toBeUndefined();
    expect(main({ moduleUrl: SCRIPT_URL, argv: ['node'] }, { fs, ...io, exit: (c: number) => exits.push(c) })).toBeUndefined();
    expect([exits, io.out, io.err]).toEqual([[], [], []]);
  });

  it('as the entry point, checks the package one directory above the script and exits 1 on problems', () => {
    const exits: number[] = [];
    const io = captureOutput();
    const code = main({ moduleUrl: SCRIPT_URL, argv: ['node', `${ROOT}/scripts/check-packaging.mjs`] }, { fs: fakeFs(failingTree), ...io, exit: (c: number) => exits.push(c) });
    expect(code).toBe(1);
    expect(exits).toEqual([1]);
    expect(io.err[0]).toBe('check:packaging — 1 problem(s):\n');
  });

  it('as the entry point of a clean package, logs OK and never calls exit', () => {
    const exits: number[] = [];
    const io = captureOutput();
    const fs = fakeFs({ [`${ROOT}/package.json`]: '{}', [`${ROOT}/src/a.ts`]: 'export const a = 1;' });
    expect(main({ moduleUrl: SCRIPT_URL, argv: ['node', `${ROOT}/scripts/check-packaging.mjs`] }, { fs, ...io, exit: (c: number) => exits.push(c) })).toBe(0);
    expect(exits).toEqual([]);
    expect(io.out).toEqual(['check:packaging — OK (1 files checked)']);
  });

  it('resolves the entry path through realpath, so a symlinked invocation still counts as the entry', () => {
    const io = captureOutput();
    const fs = { ...fakeFs({ [`${ROOT}/package.json`]: '{}' }), realpathSync: (p: string) => (p === '/link/cp.mjs' ? `${ROOT}/scripts/check-packaging.mjs` : p) };
    expect(main({ moduleUrl: SCRIPT_URL, argv: ['node', '/link/cp.mjs'] }, { fs, ...io, exit: () => undefined })).toBe(0);
  });

  it('defaults its ports to Node: imported under a test runner it is not the entry and stays inert', () => {
    const entry = process.argv[1]!;
    expect(pathToFileURL(realpathSync(entry)).href).not.toBe(SCRIPT_URL);
    expect(main({ moduleUrl: SCRIPT_URL, argv: process.argv })).toBeUndefined();
  });
});

src/forms/__tests__/descriptor-rules.tes.source:
import assert from "node:assert/strict";
import { test } from "vitest";
import { commonDescriptorErrors } from "../descriptor-rules.js";
import { MAX_FORM_FILE_BYTES } from "../field-registry.js";
import type { FieldDescriptor } from "../types.js";

const field = (overrides: Partial<FieldDescriptor> = {}): FieldDescriptor => ({ id: "answer", label: "Answer", type: "text", required: false, ...overrides });
/** Stored descriptors are untrusted JSON; parsing keeps ill-typed values without a type assertion. */
const untrusted = (raw: Record<string, unknown>): FieldDescriptor => JSON.parse(JSON.stringify({ id: "answer", label: "Answer", type: "text", required: false, ...raw }));
const reasons = (descriptor: FieldDescriptor): string[] => commonDescriptorErrors({ field: descriptor }).map((error) => error.reason);
const choices = [{ value: "a", label: "A" }, { value: "b", label: "B" }];

const MIN_LENGTH = "minLength must be an integer within the text length bounds";
const MAX_LENGTH = "maxLength is only supported on text fields and must be an integer";
const UNSAFE_PATTERN = "pattern must be a safe text pattern (no groups, alternation, backreferences or multiple repetitions)";
const BROWSER_PATTERN = "pattern is ignored by browsers: escape '-' and other symbols inside [...] with a backslash, e.g. [0-9 +.\\-]";
const OPTION_SHAPE = "options must contain only a non-empty value and label (up to 200 characters)";
const STEP = "step must be a positive finite number on a numeric field";
const ACCEPT = "accept must contain recognized safe MIME types or image/*, video/*, */*";

test("commonDescriptorErrors: a minimal valid text field has no errors", () => {
  assert.deepEqual(commonDescriptorErrors({ field: field() }), []);
});

test("commonDescriptorErrors: errors carry the field id, or (unknown) when the id is empty", () => {
  assert.deepEqual(commonDescriptorErrors({ field: untrusted({ id: "", required: "yes" }) }), [{ field: "(unknown)", reason: "required must be a boolean" }]);
  assert.deepEqual(commonDescriptorErrors({ field: untrusted({ required: "yes" }) }), [{ field: "answer", reason: "required must be a boolean" }]);
});

test("commonDescriptorErrors: every unknown property is named", () => {
  assert.deepEqual(reasons(untrusted({ onclick: "x", style: "y" })), ["property 'onclick' is not allowed", "property 'style' is not allowed"]);
});

test("commonDescriptorErrors: name must equal the id when present", () => {
  assert.deepEqual(reasons(field({ name: "answer" })), []);
  assert.deepEqual(reasons(field({ name: "other" })), ["name must equal the stable field id"]);
});

test("commonDescriptorErrors: placeholder and helpText are strings of at most 500 characters", () => {
  assert.deepEqual(reasons(field({ placeholder: "x".repeat(500), helpText: "y".repeat(500) })), []);
  assert.deepEqual(reasons(field({ placeholder: "x".repeat(501) })), ["placeholder must be a string of at most 500 characters"]);
  assert.deepEqual(reasons(untrusted({ helpText: 5 })), ["helpText must be a string of at most 500 characters"]);
});

test("commonDescriptorErrors: an unregistered type skips type rules but still resolves its default", () => {
  assert.deepEqual(reasons(untrusted({ type: "password", options: [], min: "x" })), []);
  assert.deepEqual(reasons(untrusted({ type: "password", default: "x" })), ["default: invalid_type"]);
});

test("commonDescriptorErrors: minLength accepts integers within 0..maxLength (explicit or attribute)", () => {
  assert.deepEqual(reasons(field({ minLength: 0 })), []);
  assert.deepEqual(reasons(field({ minLength: 5000 })), []);
  assert.deepEqual(reasons(field({ minLength: 3, maxLength: 3 })), []);
  assert.deepEqual(reasons(field({ attributes: { minlength: "2" } })), []);
});

test("commonDescriptorErrors: minLength refusals cover non-text, fractional, negative, oversize and attribute spellings", () => {
  for (const descriptor of [
    field({ type: "number", minLength: 1 }), field({ minLength: 1.5 }), field({ minLength: -1 }), field({ minLength: 5001 }),
    field({ minLength: 4, maxLength: 3 }), field({ attributes: { minlength: "abc" } }),
  ]) assert.deepEqual(reasons(descriptor), [MIN_LENGTH], JSON.stringify(descriptor));
});

test("commonDescriptorErrors: maxLength is refused on non-text fields and non-integers, but ignored on checkboxes", () => {
  assert.deepEqual(reasons(field({ maxLength: 10 })), []);
  assert.deepEqual(reasons(field({ maxLength: null })), []);
  assert.deepEqual(reasons(field({ type: "checkbox", maxLength: 10 })), []);
  assert.deepEqual(reasons(field({ type: "number", maxLength: 10 })), [MAX_LENGTH]);
  assert.deepEqual(reasons(field({ maxLength: 1.5 })), [MAX_LENGTH]);
});

test("commonDescriptorErrors: patterns must be safe text patterns that browsers also honour", () => {
  assert.deepEqual(reasons(field({ pattern: "[a-z]+" })), []);
  assert.deepEqual(reasons(field({ attributes: { pattern: "[a-z]+" } })), []);
  assert.deepEqual(reasons(field({ type: "number", pattern: "[0-9]+" })), [UNSAFE_PATTERN]);
  assert.deepEqual(reasons(untrusted({ pattern: 5 })), [UNSAFE_PATTERN]);
  assert.deepEqual(reasons(field({ pattern: "(a|b)" })), [UNSAFE_PATTERN]);
  assert.deepEqual(reasons(field({ pattern: "[a-z-]" })), [BROWSER_PATTERN]);
});

test("commonDescriptorErrors: options on a non-choice field are refused", () => {
  assert.deepEqual(reasons(field({ options: choices })), ["options are only supported on choice fields"]);
});

test("commonDescriptorErrors: choice fields need 1-100 options", () => {
  assert.deepEqual(reasons(field({ type: "select", options: choices })), []);
  assert.deepEqual(reasons(field({ type: "select", options: Array.from({ length: 100 }, (_, index) => ({ value: `v${index}`, label: "L" })) })), []);
  assert.deepEqual(reasons(field({ type: "radio" })), ["choice fields require 1-100 options"]);
  for (const options of [[], Array.from({ length: 101 }, (_, index) => ({ value: `v${index}`, label: "L" }))]) {
    assert.deepEqual(reasons(field({ type: "radio", options })), ["choice fields require 1-100 options"]);
  }
  assert.deepEqual(reasons(untrusted({ type: "radio", options: "a" })), ["choice fields require 1-100 options"]);
});

test("commonDescriptorErrors: each malformed option is refused once and well-formed duplicates are refused", () => {
  const malformed = [null, 5, { value: "", label: "L" }, { value: "x".repeat(201), label: "L" }, { value: 1, label: "L" }, { value: "v", label: "" }, { value: "v", label: "x".repeat(201) }, { value: "v", label: 2 }, { value: "v", label: "L", extra: 1 }];
  for (const option of malformed) assert.deepEqual(reasons(untrusted({ type: "select", options: [option] })), [OPTION_SHAPE], JSON.stringify(option));
  assert.deepEqual(reasons(field({ type: "select", options: [{ value: "x".repeat(200), label: "y".repeat(200) }] })), []);
  assert.deepEqual(reasons(field({ type: "checkbox-group", options: [...choices, { value: "a", label: "Again" }, { value: "a", label: "Thrice" }] })), ["option values must be unique", "option values must be unique"]);
});

test("commonDescriptorErrors: numeric bounds accept finite numbers and numeric strings", () => {
  assert.deepEqual(reasons(field({ type: "number", min: 0, max: "10", step: 0.5 })), []);
  assert.deepEqual(reasons(field({ type: "range", attributes: { min: "1", max: "1", step: "2" } })), []);
});

test("commonDescriptorErrors: numeric bounds refuse blanks, non-numbers and infinities", () => {
  assert.deepEqual(reasons(field({ type: "number", min: " " })), ["min must be a finite number"]);
  assert.deepEqual(reasons(untrusted({ type: "number", max: true })), ["max must be a finite number"]);
  assert.deepEqual(reasons(field({ type: "number", max: "Infinity" })), ["max must be a finite number"]);
  assert.deepEqual(reasons(field({ type: "number", min: "abc" })), ["min must be a finite number"]);
});

test("commonDescriptorErrors: reversed numeric bounds are refused", () => {
  assert.deepEqual(reasons(field({ type: "number", min: 5, max: 4 })), ["min must not exceed max"]);
  assert.deepEqual(reasons(field({ type: "number", attributes: { min: "5", max: "4" } })), ["min must not exceed max"]);
});

test("commonDescriptorErrors: temporal bounds must use the native format of their field type", () => {
  assert.deepEqual(reasons(field({ type: "date", min: "2026-01-01", max: "2026-12-31" })), []);
  assert.deepEqual(reasons(field({ type: "time", min: "09:00" })), []);
  assert.deepEqual(reasons(field({ type: "datetime", max: "2026-01-01T09:00" })), []);
  assert.deepEqual(reasons(field({ type: "date", min: "2026-02-30" })), ["min must match the field's native date/time format"]);
  assert.deepEqual(reasons(field({ type: "time", max: 9 })), ["max must match the field's native date/time format"]);
});

test("commonDescriptorErrors: reversed temporal bounds are refused while equivalent spellings are equal", () => {
  assert.deepEqual(reasons(field({ type: "date", min: "2026-12-31", max: "2026-01-01" })), ["min must not exceed max"]);
  assert.deepEqual(reasons(field({ type: "time", min: "12:30", max: "12:30:00" })), []);
});

test("commonDescriptorErrors: bounds on non-numeric, non-temporal fields are refused per key", () => {
  assert.deepEqual(reasons(field({ min: 1, max: 0 })), ["min is only supported on numeric and date/time fields", "max is only supported on numeric and date/time fields"]);
});

test("commonDescriptorErrors: step must be a positive finite number on numeric fields", () => {
  assert.deepEqual(reasons(field({ step: 1 })), [STEP]);
  assert.deepEqual(reasons(field({ type: "number", step: 0 })), [STEP]);
  assert.deepEqual(reasons(field({ type: "number", attributes: { step: "abc" } })), [STEP]);
  assert.deepEqual(reasons(field({ type: "date", attributes: { step: "60" } })), [STEP]);
});

test("commonDescriptorErrors: accept/maxFileSize on a non-file field are refused", () => {
  assert.deepEqual(reasons(field({ accept: ["image/png"] })), ["accept/maxFileSize are only supported on file fields"]);
  assert.deepEqual(reasons(field({ maxFileSize: 10 })), ["accept/maxFileSize are only supported on file fields"]);
});

test("commonDescriptorErrors: file fields accept safe narrowing", () => {
  assert.deepEqual(reasons(field({ type: "file", accept: ["image/png", "image/*", "video/*", "*/*"], maxFileSize: MAX_FORM_FILE_BYTES })), []);
  assert.deepEqual(reasons(field({ type: "file", maxFileSize: 1 })), []);
});

test("commonDescriptorErrors: file maxFileSize must be an integer within 1..MAX_FORM_FILE_BYTES", () => {
  for (const maxFileSize of [0, 1.5, MAX_FORM_FILE_BYTES + 1]) assert.deepEqual(reasons(field({ type: "file", maxFileSize })), [`maxFileSize must be 1-${MAX_FORM_FILE_BYTES} bytes`]);
});

test("commonDescriptorErrors: file accept must be 1-20 recognized safe types", () => {
  for (const accept of [[], Array.from({ length: 21 }, () => "image/png"), ["text/html"]]) assert.deepEqual(reasons(field({ type: "file", accept })), [ACCEPT]);
  assert.deepEqual(reasons(untrusted({ type: "file", accept: "image/png" })), [ACCEPT]);
});

test("commonDescriptorErrors: file fields cannot have defaults", () => {
  assert.deepEqual(reasons(field({ type: "file", default: "x" })), ["file fields cannot have defaults"]);
});

test("commonDescriptorErrors: defaults are resolved as optional answers", () => {
  assert.deepEqual(reasons(field({ required: true, default: "" })), []);
  assert.deepEqual(reasons(field({ type: "number", default: "abc" })), ["default: invalid_number"]);
  assert.deepEqual(reasons(field({ type: "select", options: choices, default: ["a", "b"] })), ["default: must be a string"]);
});

test("commonDescriptorErrors: defaults are not resolved once another rule already failed", () => {
  assert.deepEqual(reasons(field({ type: "number", min: 5, max: 4, default: "abc" })), ["min must not exceed max"]);
});

