import assert from "node:assert/strict";
import { test } from "vitest";

import type { ToolExecutionContext } from "@jini-ai/core";

import type { OutboxPort } from "../../core/ports.js";
import { menusAgentToolCatalog } from "../agent-tools.js";
import { MAX_MENU_HTML_LENGTH } from "../menu-html.js";
import { mergeMenuHtml } from "../menu-html.js";
import { createMenu as createUniversalMenu } from "../menu-service.js";
import { createMenu, MenuValidationError, updateMenuTree, buildMenusRegistrations, mergeMenuHtml as nodeMergeMenuHtml } from "../node/index.js";
import { InMemoryMenuRepo, InMemoryNavLocationBindingRepo } from "../repo.memory.js";
import type { MenusToolDeps } from "../tool-registrations.js";

/**
 * @file Menu HTML mode (owner 2026-10-08): a menu stores author-written HTML beside its item tree,
 * mirroring HTML-mode forms — trusted markup behind the host's raw-HTML permission, normalized on save,
 * and switching mode never destroys the other mode's data.
 */

const outbox: OutboxPort = { enqueue: async () => {}, claimPending: async () => [], markDelivered: async () => {}, markFailed: async () => {} };
const WS = "ws-1";
const item = { id: "home", label: "Home", target: { kind: "url" as const, href: "/" } };

function deps(repo: InMemoryMenuRepo) {
  let n = 0;
  return { repo, clock: { nowMs: () => Date.parse("2026-10-08T00:00:00.000Z") }, idGen: { newId: () => `id-${++n}` }, outbox };
}

test("universal HTML writes require a normalizer before saving or publishing an event", async () => {
  const repo = new InMemoryMenuRepo({});
  let events = 0;
  await assert.rejects(() => createUniversalMenu({
    deps: { ...deps(repo), outbox: { ...outbox, enqueue: async () => { events++; } } },
    input: { workspaceId: WS, title: "Header", slug: "header", html: "</nav><div>" },
  }), { message: "Menu HTML normalization is not configured" });
  assert.equal(await repo.findBySlug({ workspaceId: WS, slug: "header" }), null);
  assert.equal(events, 0);
});

test("a universal create forwards its injected normalizer and stores the balanced output", async () => {
  const repo = new InMemoryMenuRepo({});
  const submitted: string[] = [];
  const { menu } = await createUniversalMenu({
    deps: { ...deps(repo), normalizeMenuHtml: ({ html }) => { submitted.push(html); return "<p>host fragment</p>"; } },
    input: { workspaceId: WS, title: "Header", slug: "header", mode: "html", html: "<p>host fragment" },
  });
  assert.deepEqual(submitted, ["<p>host fragment"]);
  assert.equal(menu.doc.html, "<p>host fragment</p>");
  assert.equal((await repo.findById({ workspaceId: WS, id: menu.id }))?.doc.html, "<p>host fragment</p>");
});

test("the universal merge uses an injected normalizer only for submitted markup", () => {
  const submitted: string[] = [];
  const normalizeHtml = ({ html }: { html: string }) => { submitted.push(html); return "<div>balanced</div>"; };
  assert.deepEqual(mergeMenuHtml({ input: { mode: "html", html: "<div>" } }, { normalizeHtml }), { mode: "html", html: "<div>balanced</div>" });
  assert.deepEqual(mergeMenuHtml({ input: { mode: "items" }, existing: { mode: "html", html: "<p>stored</p>" } }, { normalizeHtml }), { mode: "items", html: "<p>stored</p>" });
  assert.deepEqual(submitted, ["<div>"]);
  assert.throws(() => mergeMenuHtml({ input: { html: "<div>" } }), { message: "Menu HTML normalization is not configured" });
});

async function seed(repo: InMemoryMenuRepo, extra: { mode?: "items" | "html"; html?: string } = {}) {
  return (await createMenu({ deps: deps(repo), input: { workspaceId: WS, title: "Header", slug: "header", items: [item], ...extra } })).menu;
}

test("a menu that never used HTML mode stores no mode/html keys", async () => {
  const menu = await seed(new InMemoryMenuRepo({}));
  assert.deepEqual(Object.keys(menu.doc).sort(), ["items", "type", "version"]);
});

test("createMenu stores mode and normalized html", async () => {
  const menu = await seed(new InMemoryMenuRepo({}), { mode: "html", html: "<ul><li><a href='/'>Home</a></ul>" });
  assert.equal(menu.doc.mode, "html");
  assert.equal(menu.doc.html, '<ul><li><a href="/">Home</a></li></ul>');
  assert.equal(menu.doc.items.length, 1);
});

test("updateMenuTree with only html keeps the stored items", async () => {
  const repo = new InMemoryMenuRepo({});
  const menu = await seed(repo);
  const { menu: updated } = await updateMenuTree({ deps: deps(repo), input: { workspaceId: WS, id: menu.id, expectedVersion: 1, mode: "html", html: "<p>Hi</p>" } });
  assert.equal(updated.doc.mode, "html");
  assert.equal(updated.doc.html, "<p>Hi</p>");
  assert.deepEqual(updated.doc.items, menu.doc.items);
});

test("an items-only save keeps the stored mode and html (other repo writers never drop them)", async () => {
  const repo = new InMemoryMenuRepo({});
  const menu = await seed(repo, { mode: "html", html: "<p>Hi</p>" });
  const { menu: updated } = await updateMenuTree({ deps: deps(repo), input: { workspaceId: WS, id: menu.id, expectedVersion: 1, items: [] } });
  assert.equal(updated.doc.mode, "html");
  assert.equal(updated.doc.html, "<p>Hi</p>");
  assert.deepEqual(updated.doc.items, []);
});

test("switching back to items keeps the html for a later switch", async () => {
  const repo = new InMemoryMenuRepo({});
  const menu = await seed(repo, { mode: "html", html: "<p>Hi</p>" });
  const { menu: updated } = await updateMenuTree({ deps: deps(repo), input: { workspaceId: WS, id: menu.id, expectedVersion: 1, items: [item], mode: "items" } });
  assert.equal(updated.doc.mode, "items");
  assert.equal(updated.doc.html, "<p>Hi</p>");
});

test("stray closing tags cannot escape the fragment; scripts stay (trusted markup, like forms)", async () => {
  const menu = await seed(new InMemoryMenuRepo({}), { mode: "html", html: "<ul><li>A</nav></body></html><div><script>x()</script>" });
  assert.equal(menu.doc.html, "<ul><li>A<div><script>x()</script></div></li></ul>");
});

test("an unknown mode and oversized html are validation errors", async () => {
  const repo = new InMemoryMenuRepo({});
  const menu = await seed(repo);
  await assert.rejects(
    () => updateMenuTree({ deps: deps(repo), input: { workspaceId: WS, id: menu.id, expectedVersion: 1, mode: "tree" as never } }),
    (err: unknown) => err instanceof MenuValidationError && /mode must be 'items' or 'html'/.test(err.message),
  );
  await assert.rejects(
    () => updateMenuTree({ deps: deps(repo), input: { workspaceId: WS, id: menu.id, expectedVersion: 1, html: "x".repeat(MAX_MENU_HTML_LENGTH + 1) } }),
    (err: unknown) => err instanceof MenuValidationError && /html must be a string of at most 200000 characters/.test(err.message),
  );
});

function ctx(input: Record<string, unknown>): ToolExecutionContext {
  return { executionId: "exec-1", principal: { id: "p1" }, run: { id: "run-1" }, input, signal: new AbortController().signal };
}

function toolDeps(denied: readonly string[] = [], extra: Partial<MenusToolDeps> = {}): MenusToolDeps & { asked: string[] } {
  let n = 0;
  const asked: string[] = [];
  return {
    asked,
    authorize: async ({ permission }) => { asked.push(permission); return denied.includes(permission) ? { allowed: false, reason: "no_grant" } : { allowed: true, reason: "matched" }; },
    workspaceId: WS,
    clock: { nowMs: () => Date.parse("2026-10-08T00:00:00.000Z") },
    idGen: { newId: () => `id-${++n}` },
    outbox,
    menuRepo: new InMemoryMenuRepo({}),
    navLocationBindingRepo: new InMemoryNavLocationBindingRepo({}),
    rawHtmlPermission: "pages.edit_html",
    ...extra,
  };
}

function tool(d: MenusToolDeps, id: string) {
  const found = buildMenusRegistrations(d).find((r) => r.descriptor.id === id);
  assert.ok(found, `${id} must be wired`);
  return found;
}

test("menus_update_menu_tree accepts html without items and returns mode/html in the view", async () => {
  const d = toolDeps();
  const created = (await tool(d, "menus_create_menu").handler(ctx({ title: "Header", slug: "header", items: [item] }))) as { menu: { id: string } };
  const out = (await tool(d, "menus_update_menu_tree").handler(ctx({ menuId: created.menu.id, expectedVersion: 1, mode: "html", html: "<p>Hi</p>" }))) as {
    menu: { mode?: string; html?: string; items: unknown[] };
  };
  assert.equal(out.menu.mode, "html");
  assert.equal(out.menu.html, "<p>Hi</p>");
  assert.equal(out.menu.items.length, 1);
  assert.ok(d.asked.includes("pages.edit_html"), "html authoring must check the host's raw-HTML permission");
});

test("menus_update_menu_tree without the raw-HTML permission rejects and leaves the menu unchanged", async () => {
  const d = toolDeps(["pages.edit_html"]);
  const created = (await tool(d, "menus_create_menu").handler(ctx({ title: "Header", slug: "header" }))) as { menu: { id: string } };
  await assert.rejects(
    () => tool(d, "menus_update_menu_tree").handler(ctx({ menuId: created.menu.id, expectedVersion: 1, html: "<p>Hi</p>" })),
    /not authorized for 'pages.edit_html'/,
  );
  const stored = await d.menuRepo.findById({ workspaceId: WS, id: created.menu.id });
  assert.equal(stored?.doc.html, undefined);
  assert.equal(stored?.version, 1);
});

test("menus_create_menu with html is refused when the host configured no raw-HTML permission", async () => {
  const d = toolDeps([], { rawHtmlPermission: undefined });
  await assert.rejects(() => tool(d, "menus_create_menu").handler(ctx({ title: "Header", slug: "header", mode: "html", html: "<p>x</p>" })), /HTML menus are not enabled/);
});

test("switching a menu back to items needs no raw-HTML permission", async () => {
  const d = toolDeps(["pages.edit_html"]);
  const created = (await tool(d, "menus_create_menu").handler(ctx({ title: "Header", slug: "header", items: [item] }))) as { menu: { id: string } };
  const out = (await tool(d, "menus_update_menu_tree").handler(ctx({ menuId: created.menu.id, expectedVersion: 1, mode: "items" }))) as { menu: { mode?: string } };
  assert.equal(out.menu.mode, "items");
});

test("menus_update_menu_tree requires items, html or mode", async () => {
  const d = toolDeps();
  const created = (await tool(d, "menus_create_menu").handler(ctx({ title: "Header", slug: "header" }))) as { menu: { id: string } };
  await assert.rejects(() => tool(d, "menus_update_menu_tree").handler(ctx({ menuId: created.menu.id, expectedVersion: 1 })), /'items' \(array\), 'html' or 'mode' is required/);
});

test("the published create/update schemas declare mode and html, and update no longer requires items", () => {
  for (const name of ["menus_create_menu", "menus_update_menu_tree"]) {
    const schema = menusAgentToolCatalog.find((t) => t.name === name)?.inputSchema as { properties: Record<string, { enum?: string[]; type?: string }>; required: string[] };
    assert.deepEqual(schema.properties.mode?.enum, ["items", "html"], name);
    assert.equal(schema.properties.html?.type, "string", name);
  }
  const update = menusAgentToolCatalog.find((t) => t.name === "menus_update_menu_tree")?.inputSchema as { required: string[] };
  assert.deepEqual(update.required, ["id", "expectedVersion"]);
});

test("the Node merge balances submitted HTML with parse5 by default, defers to a caller normalizer, and keeps stored HTML when none is submitted", () => {
  assert.deepEqual(nodeMergeMenuHtml({ input: { mode: "html", html: "<ul><li>Home" } }), { mode: "html", html: "<ul><li>Home</li></ul>" });
  assert.deepEqual(nodeMergeMenuHtml({ input: { html: "<b>x" } }, { normalizeHtml: ({ html }) => `[${html}]` }), { html: "[<b>x]" });
  assert.deepEqual(nodeMergeMenuHtml({ input: {}, existing: { mode: "html", html: "<p>kept</p>" } }), { mode: "html", html: "<p>kept</p>" });
});

src/widgets/__tests__/integration/read-s.source:
import { widgetHostFixture } from "../support/host.fixture.js";
import assert from "node:assert/strict";
import test from "../support/test-runner.js";

import { InMemoryEntryRefsRepo } from "../support/host.fixture.js";
import { InMemoryContentTypeRepo } from "../../../content-types/index.js";
import { buildWidgetInstanceFieldsJson } from "../support/compat/entry-payload.js";
import { memoryWidgetTrash } from "../support/memory-widget-trash.js";
import { getWidgetInstance, listWidgetInstances, type WidgetReadServiceDeps } from "../../read-service.js";
import { WidgetForbiddenError, WidgetInstanceNotFoundError } from "../../errors.js";
import { createWidgetInstance, trashWidgetInstance, type WidgetTrashDeps, type WidgetWriteServiceDeps } from "../../write-service.js";
import { InMemoryOutbox } from "../support/host.fixture.js";

/**
 * @file C-005-adjacent widget-instance READ accessors (SPEC-043 REQ-04). External /audit-work
 * finding (2026-07-21, ADR-047): confirmed no read/list accessor existed in this package at all
 * before this file.
 */

const WORKSPACE_ID = "ws-1";
const ACTOR = { principalId: "user-1" };

function makeRepos() {
  const trash = memoryWidgetTrash();
  return { entryRepo: trash.entryRepo, contentTypeRepo: new InMemoryContentTypeRepo(), entryRefsRepo: new InMemoryEntryRefsRepo(), trash };
}

let counter = 0;
function writeDeps(repos: ReturnType<typeof makeRepos>, authorize?: WidgetWriteServiceDeps["authorize"]): WidgetTrashDeps {
  return {
    host: widgetHostFixture,
    entryRepo: repos.entryRepo,
    contentTypeRepo: repos.contentTypeRepo,
    entryRefsRepo: repos.entryRefsRepo,
    remove: repos.trash.remove,
    clock: { nowMs: () => Date.parse("2026-07-21T00:00:00.000Z") },
    ids: { newId: () => `id-${++counter}` },
    authorize: authorize ?? (async () => ({ allowed: true, reason: "test: always allow" })),
    outbox: new InMemoryOutbox(),
  };
}

function readDeps(repos: ReturnType<typeof makeRepos>, authorize?: WidgetReadServiceDeps["authorize"]): WidgetReadServiceDeps {
  return { entryRepo: repos.entryRepo, authorize: authorize ?? (async () => ({ allowed: true, reason: "test: always allow" })) };
}

test("REQ-04: getWidgetInstance returns a widgets.read-holding principal's requested instance, current state, and a stable (currently empty) revisions shape", async () => {
  const repos = makeRepos();
  const { instance: created } = await createWidgetInstance({
    deps: writeDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title: "Footer note", config: { body: "hi" } },
  });

  const { instance, revisions } = await getWidgetInstance({
    deps: readDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: created.id },
  });

  assert.equal(instance.id, created.id);
  assert.equal(instance.title, "Footer note");
  assert.deepEqual(revisions, []);
});

// REQ-04 (changed 2026-09-21, generic Trash): a deleted widget is in the Trash, not a readable
// "trash" status — reads treat it as missing until it is restored from the Trash.
test("REQ-04: a widget in the Trash reads as not found, and reads again once restored", async () => {
  const repos = makeRepos();
  const { instance: created } = await createWidgetInstance({
    deps: writeDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title: "Footer note", config: { body: "hi" } },
  });
  await trashWidgetInstance({ deps: writeDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: created.id } });

  await assert.rejects(
    getWidgetInstance({ deps: readDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: created.id } }),
    { name: "WidgetInstanceNotFoundError", message: `widget instance '${created.id}' was not found` }
  );

  await repos.trash.restore({ workspaceId: WORKSPACE_ID, id: created.id });
  const { instance } = await getWidgetInstance({
    deps: readDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: created.id },
  });
  assert.equal(instance.status, "active");
});

test("getWidgetInstance 404s for an unknown id, not a crash", async () => {
  const repos = makeRepos();
  await assert.rejects(
    () => getWidgetInstance({ deps: readDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: "nope" } }),
    (err: unknown) => err instanceof WidgetInstanceNotFoundError
  );
});

// URL-uses-slug (2026-09-22): the admin widget editor's URL now carries the widget's slug
// (`WidgetsLibrary.tsx`'s row link, `use-widget-instance-editor.hooks.ts`'s create-navigate), so
// this route param may itself BE that slug rather than the widget's real id — same slug-first/
// id-second resolution as posts' `getAdminPostByIdOrSlug` and forms' `resolveFormDefinitionByIdOrSlug`.
test("REQ-04: getWidgetInstance resolves by slug, and still resolves an old bookmark's raw id", async () => {
  const repos = makeRepos();
  const { instance: created } = await createWidgetInstance({
    deps: writeDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title: "Footer note", config: { body: "hi" } },
  });

  const bySlug = await getWidgetInstance({
    deps: readDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: created.slug },
  });
  assert.equal(bySlug.instance.id, created.id);

  const byId = await getWidgetInstance({
    deps: readDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: created.id },
  });
  assert.equal(byId.instance.id, created.id);
});

test("REQ-04: a trashed widget's slug 404s too, not just its id — the slug lookup doesn't leak trashed rows", async () => {
  const repos = makeRepos();
  const { instance: created } = await createWidgetInstance({
    deps: writeDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title: "Footer note", config: { body: "hi" } },
  });
  await trashWidgetInstance({ deps: writeDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: created.id } });

  await assert.rejects(
    getWidgetInstance({ deps: readDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: created.slug } }),
    { name: "WidgetInstanceNotFoundError" }
  );
});

test("REQ-40/41: a principal lacking widgets.read is rejected — INV-07 applies to reads too, not only mutations", async () => {
  const repos = makeRepos();
  const { instance: created } = await createWidgetInstance({
    deps: writeDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title: "Footer note", config: { body: "hi" } },
  });

  const denyAll = async () => ({ allowed: false, reason: "no_grant" });
  await assert.rejects(
    () => getWidgetInstance({ deps: readDeps(repos, denyAll), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: created.id } }),
    (err: unknown) => err instanceof WidgetForbiddenError
  );
  await assert.rejects(
    () => listWidgetInstances({ deps: readDeps(repos, denyAll), input: { workspaceId: WORKSPACE_ID, actor: ACTOR } }),
    (err: unknown) => err instanceof WidgetForbiddenError
  );
});

test("REQ-04: listWidgetInstances defaults to active-only and narrows by widgetType; a widget in the Trash is left out even with includeInactive", async () => {
  const repos = makeRepos();
  const { instance: text1 } = await createWidgetInstance({
    deps: writeDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title: "Text A", config: { body: "a" } },
  });
  const { instance: social } = await createWidgetInstance({
    deps: writeDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "social-links", title: "Socials", config: { links: [] } },
  });
  const { instance: liveText } = await createWidgetInstance({ deps: writeDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title: "Live text", config: { body: "Live body" } } });
  const { instance: legacy } = await createWidgetInstance({ deps: writeDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title: "Legacy inactive", config: { body: "Legacy body" } } });
  const legacyRow = await repos.entryRepo.findById({ workspaceId: WORKSPACE_ID, id: legacy.id });
  assert.ok(legacyRow);
  await repos.entryRepo.save({ ...legacyRow, fieldsJson: buildWidgetInstanceFieldsJson({ widgetType: "text", config: { body: "Legacy body" }, status: "purged" }) });
  await trashWidgetInstance({ deps: writeDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetInstanceId: text1.id } });

  const activeOnly = await listWidgetInstances({ deps: readDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR } });
  assert.deepEqual(activeOnly.instances.map((row) => row.id).sort(), [social.id, liveText.id].sort());

  const narrowed = await listWidgetInstances({
    deps: readDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "social-links" },
  });
  assert.deepEqual(narrowed.instances.map((row) => row.id), [social.id]);

  const includingTrashed = await listWidgetInstances({
    deps: readDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, includeInactive: true },
  });
  assert.deepEqual(includingTrashed.instances.map((row) => row.id).sort(), [social.id, liveText.id, legacy.id].sort(), "includeInactive includes readable legacy rows and excludes the actual Trash");
  for (const includeInactive of [false, true]) {
    const texts = await listWidgetInstances({ deps: readDeps(repos), input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", includeInactive } });
    assert.deepEqual(texts.instances.map((row) => row.id).sort(), (includeInactive ? [liveText.id, legacy.id] : [liveText.id]).sort());
  }
});

test("dossier C5 follow-up: a malformed widget-instance record is skipped, counted before filters, and identified for the caller", async () => {
  const repos = makeRepos();
  await createWidgetInstance({
    deps: writeDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title: "Good widget", config: { body: "hi" } },
  });

  // Reproduces the two real `workspace-local` rows found during the C5 investigation
  // (`__entries-create-probe__`/`__fix-verify-entries__`): created via the generic entries route
  // directly, so `fields_json` is `{ ext: { site: {...} } }` instead of the widgets domain's own
  // `{ ext: { widget: { payload: ... } } }` shape. `parseWidgetInstancePayload` throws on this.
  await repos.entryRepo.save({
    id: "malformed-1",
    workspaceId: WORKSPACE_ID,
    type: "widget",
    slug: "malformed-probe",
    status: "draft",
    title: "malformed-probe",
    bodyJson: null,
    fieldsJson: { ext: { site: { payload: "probe" } } },
    publishedAt: null,
    createdAt: "2026-08-03T00:00:00.000Z",
    updatedAt: "2026-08-03T00:00:00.000Z",
    version: 1,
  });

  const result = await listWidgetInstances({
    deps: readDeps(repos),
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text" },
  });

  assert.equal(result.instances.length, 1, "the one well-formed widget must still be returned");
  assert.ok(result.instances[0]);
  assert.equal(result.instances[0].title, "Good widget");
  assert.equal(result.skippedCount, 1, "the malformed row must be counted, not silently disappear with no trace");
  assert.deepEqual(result.skippedIds, ["malformed-1"], "the caller must receive the malformed record's id even though its unparseable payload makes its type and status unknowable");
});

