import assert from "node:assert/strict";
import { test, vi, afterEach } from "vitest";

import { InMemoryPostRepo, type PostRecord } from "./support/post.fixture.js";
import { InMemorySettingsRepo } from "./support/legacy-api.fixture.js";
import { InMemoryAssetRenditionRepo, InMemoryMediaRepo, InMemoryTransformDefinitionRepo } from "../../media/index.js";
import { OriginNotVerifiedError, OriginRegistry, type OriginRegistryPort } from "@jini-ai/http-kit/verified-origin";
import { ensureSeoSettingDefinitions } from "./support/legacy-api.fixture.js";
import { buildSitemap, invalidateSitemapCache, registerSitemapCollectHook, resetSitemapCollectHooksForTests } from "./support/legacy-api.fixture.js";
import { buildPostRecord } from "./support/post.fixture.js";

/**
 * @file T033 — failing-first unit certification of `buildSitemap`
 * (INV-04/05, AC-16/17, EC-04): excludes effective-`noindex` and non-
 * `published` entries; empty workspace -> valid empty array; entries ordered
 * by keyset `id` ascending (behavior.spec.md §2.2).
 */

const WORKSPACE = "workspace-sitemap-1";
const clock = { nowIso: () => "2026-07-13T00:00:00.000Z" };
let idCounter = 0;
const ids = { newId: () => `sitemap-test-id-${++idCounter}` };
const alwaysAllow = async () => ({ allowed: true, reason: "matched" });

function post(overrides: Partial<PostRecord>): PostRecord {
  return buildPostRecord({
    id: "a",
    workspaceId: WORKSPACE,
    title: "Post",
    slug: "post",
    bodyJson: { type: "doc", content: [] },
    status: "published",
    kind: "post",
    updatedAt: "2026-07-13T00:00:00.000Z",
    version: 1,
    seoExtJson: null,
    ...overrides,
  });
}

/** Mirrors `seo.test.ts`'s own copy of this fake — `origin` undefined (the default, and every
 *  pre-existing test's implicit behavior) means no verified origin registered, which keeps every
 *  `loc` assertion below unchanged (still relative). */
function fakeOriginRegistry(origin?: import("@jini-ai/http-kit/verified-origin").VerifiedOrigin): OriginRegistryPort {
  return {
    async canonicalOrigin() {
      if (!origin) throw new OriginNotVerifiedError({ message: "no verified origin registered for this workspace" });
      return origin;
    },
    async isAllowedRedirectTarget() {
      return false;
    },
    async isAllowedEgressTarget() {
      return false;
    },
  };
}

async function makeDeps(posts: PostRecord[], origin?: import("@jini-ai/http-kit/verified-origin").VerifiedOrigin) {
  invalidateSitemapCache({ workspaceId: WORKSPACE });
  const postRepo = new InMemoryPostRepo(posts);
  const settingsRepo = new InMemorySettingsRepo();
  const settingsDeps = { settingsRepo, clock, ids, authorize: alwaysAllow, principals: { findById: async () => null } as never };
  await ensureSeoSettingDefinitions(settingsDeps, { workspaceId: WORKSPACE, systemPrincipalId: "system-seo" });

  return {
    postRepo,
    settingsRepo,
    media: {
      mediaRepo: new InMemoryMediaRepo({}, { initialRows: [] }),
      assetRenditionRepo: new InMemoryAssetRenditionRepo({}, { initialRows: [] }),
      transformDefinitionRepo: new InMemoryTransformDefinitionRepo({}, { initialRows: [] }),
    },
    originRegistry: fakeOriginRegistry(origin),
  };
}

test("buildSitemap: an empty workspace resolves a valid empty array, never null", async () => {
  const deps = await makeDeps([]);
  const entries = await buildSitemap(deps, { workspaceId: WORKSPACE });
  assert.deepEqual(entries, []);
});

// 2026-09-03 absolute-URL fix side effect: `computeSitemapEntries` builds `loc` from
// `getEntryMeta`'s own `meta.canonical` — once that became absolute, sitemap entries did too, for
// free. The sitemap protocol requires `loc` to be absolute, the same requirement `og:url` has.
test("buildSitemap: with a verified origin, entries' loc is absolute (2026-09-03 fix side effect)", async () => {
  const deps = await makeDeps([post({ id: "a", slug: "published-visible", status: "published" })], {
    scheme: "https",
    host: "example.test",
    verifiedAt: "2026-09-03T00:00:00.000Z",
    source: "workspace-setting",
  });
  const entries = await buildSitemap(deps, { workspaceId: WORKSPACE });
  assert.equal(entries.length, 1);
  assert.equal(entries[0]!.loc, "https://example.test/published-visible");
});

// 2026-09-18 production bug (reproduced live on tovu.fly.dev via WebFetch before this fix):
// `seedDevCapabilityOrigin` (server/runtime/composition/deps.ts) durably persisted
// `http://localhost:3000` as the registered origin on Fly's first boot, and every sitemap entry's
// `loc` inherited it verbatim -- exactly the shape asserted as the (pre-fix) wrong value below.
// `resolveWorkspaceOrigin` (absolute-url.ts) now degrades a dev-capability origin to "unverified"
// under production runtime mode, so `buildSitemap` must fall back to the pre-existing bare-relative-
// path behavior instead, never a localhost URL.
test("buildSitemap: a dev-capability localhost origin never leaks into loc when running in production (regression pin, 2026-09-18)", async () => {
  const originalMode = process.env.TOVU_RUNTIME_MODE;
  process.env.TOVU_RUNTIME_MODE = "production";
  try {
    const deps = await makeDeps([post({ id: "a", slug: "published-visible", status: "published" })], {
      scheme: "http",
      host: "localhost",
      port: 3000,
      verifiedAt: "2026-07-16T00:00:00.000Z",
      source: "dev-capability",
    });
    const entries = await buildSitemap(deps, { workspaceId: WORKSPACE });
    assert.equal(entries.length, 1);
    assert.equal(entries[0]!.loc, "/published-visible", "must degrade to the bare relative path, never http://localhost:3000/published-visible");
    assert.ok(!entries[0]!.loc.includes("localhost"), "sitemap loc must never contain the dev-capability localhost origin in production");
  } finally {
    if (originalMode === undefined) delete process.env.TOVU_RUNTIME_MODE;
    else process.env.TOVU_RUNTIME_MODE = originalMode;
  }
});

test("buildSitemap: excludes drafts and effective-noindex entries, includes only eligible published entries (AC-16/17)", async () => {
  const deps = await makeDeps([
    post({ id: "a", slug: "published-visible", status: "published" }),
    post({ id: "b", slug: "draft-post", status: "draft" }),
    post({ id: "c", slug: "noindex-post", status: "published", seoExtJson: JSON.stringify({ noindex: true }) }),
  ]);

  const entries = await buildSitemap(deps, { workspaceId: WORKSPACE });
  assert.equal(entries.length, 1);
  assert.ok(entries[0]!.loc.includes("published-visible"));
});

test("buildSitemap: a members/paid/tiers-gated published post is excluded — a crawler must not be told a gated post's URL/existence exists (ADR-030 §4, 2026-09-03 sweep)", async () => {
  const deps = await makeDeps([
    post({ id: "a", slug: "public-post", status: "published" }),
    post({ id: "b", slug: "members-only-post", status: "published", memberAccessJson: JSON.stringify({ visibility: "members" }) }),
    post({ id: "c", slug: "paid-only-post", status: "published", memberAccessJson: JSON.stringify({ visibility: "paid" }) }),
    post({ id: "d", slug: "tiers-only-post", status: "published", memberAccessJson: JSON.stringify({ visibility: "tiers", tierIds: ["t-1"] }) }),
  ]);

  const entries = await buildSitemap(deps, { workspaceId: WORKSPACE });
  assert.equal(entries.length, 1, "only the ungated post may appear");
  assert.ok(entries[0]!.loc.includes("public-post"));
  for (const gatedSlug of ["members-only-post", "paid-only-post", "tiers-only-post"]) {
    assert.ok(
      !entries.some((e) => e.loc.includes(gatedSlug)),
      `${gatedSlug} must not appear in the sitemap`
    );
  }
});

test("buildSitemap: a post with malformed memberAccessJson fails CLOSED (excluded), same as resolvePostMemberAccess's own fail-closed contract", async () => {
  const deps = await makeDeps([post({ id: "a", slug: "malformed-access-post", status: "published", memberAccessJson: "{not json" })]);

  const entries = await buildSitemap(deps, { workspaceId: WORKSPACE });
  assert.deepEqual(entries, []);
});

test("buildSitemap: a post with a NULL memberAccessJson (every pre-existing row) is treated as public, unchanged from pre-gating behavior", async () => {
  const deps = await makeDeps([post({ id: "a", slug: "legacy-ungated-post", status: "published", memberAccessJson: null })]);

  const entries = await buildSitemap(deps, { workspaceId: WORKSPACE });
  assert.equal(entries.length, 1);
  assert.ok(entries[0]!.loc.includes("legacy-ungated-post"));
});

test("buildSitemap: a trashed post that still carries status: 'published' is excluded (softDelete never clears status, so the status guard alone can't catch it)", async () => {
  const deps = await makeDeps([
    post({ id: "a", slug: "still-live-post", status: "published" }),
    post({ id: "b", slug: "trashed-but-published-post", status: "published", deletedAt: "2026-09-04T00:00:00.000Z" }),
  ]);

  const entries = await buildSitemap(deps, { workspaceId: WORKSPACE });
  assert.equal(entries.length, 1, "only the non-trashed post may appear");
  assert.ok(entries[0]!.loc.includes("still-live-post"));
  assert.ok(
    !entries.some((e) => e.loc.includes("trashed-but-published-post")),
    "a trashed post must never appear in the sitemap, even though its status column still reads 'published'"
  );
});

test("buildSitemap: entries are ordered by keyset id ascending with lastmod from updatedAt", async () => {
  const deps = await makeDeps([
    post({ id: "c", slug: "a-post", updatedAt: "2026-07-15T00:00:00.000Z", createdAt: "2026-01-01T00:00:00.000Z" }),
    post({ id: "a", slug: "z-post", updatedAt: "2026-07-13T00:00:00.000Z", createdAt: "2026-01-02T00:00:00.000Z" }),
    post({ id: "b", slug: "m-post", updatedAt: "2026-07-14T00:00:00.000Z", createdAt: "2026-01-03T00:00:00.000Z" }),
  ]);
  const entries = await buildSitemap(deps, { workspaceId: WORKSPACE });
  assert.deepEqual(entries.map(e => e.loc), ["/z-post", "/m-post", "/a-post"]);
  assert.deepEqual(entries, [
    { loc: "/z-post", lastmod: "2026-07-13T00:00:00.000Z" },
    { loc: "/m-post", lastmod: "2026-07-14T00:00:00.000Z" },
    { loc: "/a-post", lastmod: "2026-07-15T00:00:00.000Z" },
  ]);
});

test("sitemap contributors append entries in priority order with workspace context and reset removes them", async () => {
  resetSitemapCollectHooksForTests();
  const calls: unknown[] = [];
  try {
    const deps = await makeDeps([post({ slug: "base-post" })]);
    registerSitemapCollectHook({ priority: 20, handle: async ctx => { calls.push(["later", ctx]); return [{ loc: "/later", lastmod: "2026-07-02" }]; } });
    registerSitemapCollectHook({ priority: 5, handle: async ctx => { calls.push(["earlier", ctx]); return [{ loc: "/earlier", lastmod: "2026-07-01" }]; } });
    assert.deepEqual(await buildSitemap(deps, { workspaceId: WORKSPACE }), [
      { loc: "/base-post", lastmod: "2026-07-13T00:00:00.000Z" },
      { loc: "/earlier", lastmod: "2026-07-01" }, { loc: "/later", lastmod: "2026-07-02" },
    ]);
    assert.deepEqual(calls, [["earlier", { workspaceId: WORKSPACE, baseUrl: "" }], ["later", { workspaceId: WORKSPACE, baseUrl: "" }]]);
    resetSitemapCollectHooksForTests();
    invalidateSitemapCache({ workspaceId: WORKSPACE });
    assert.deepEqual(await buildSitemap(deps, { workspaceId: WORKSPACE }), [{ loc: "/base-post", lastmod: "2026-07-13T00:00:00.000Z" }]);
    assert.equal(calls.length, 2);
  } finally {
    resetSitemapCollectHooksForTests();
    invalidateSitemapCache({ workspaceId: WORKSPACE });
  }
});

afterEach(() => { vi.restoreAllMocks(); vi.useRealTimers(); });

src/redirects/__tests__/open-redirect.ma.source:
import assert from "node:assert/strict";
import { test } from "vitest";
import type { NextFunction, Request, Response } from "express";
import { createVerifiedOrigin, InMemoryOriginSettingRepo, OriginRegistry } from "@jini-ai/http-kit/verified-origin";
import { createRedirectResolver } from "../resolver.js";
import { redirectMatcher } from "../matcher.js";
import { InMemoryRedirectRepo } from "../repo.memory.js";
import { createSpaRedirectGuard } from "../spa/index.js";
import { toNetlifyRedirects, toVercelRedirects } from "../host-config/index.js";
import { createRedirectMiddleware, RedirectMiddlewareContextError } from "../express/index.js";
import type { RedirectTargetOracle } from "../target-gate.js";
import type { RedirectRecord } from "../types.js";

const workspaceId = "workspace-1";
const reservedSegments = new Set(["admin", "api"]);
const idnHost = new URL("https://évil.example").hostname;

// One adversarial case table drives EVERY effect boundary. Percent-encoded slashes stay in a
// same-origin pathname; refusing their authority-looking spelling must not invent an off-site URL.
const cases = [
  { name: "//evil", template: "//$1", capture: "evil.example", location: "//evil.example", allowed: false },
  { name: "/\\evil", template: "/$1", capture: "\\evil.example", location: "/\\evil.example", allowed: false },
  { name: "https:evil", template: "https:$1", capture: "evil.example", location: "https:evil.example", allowed: false },
  { name: "%2F%2F", template: "/$1", capture: "%2F%2Fevil.example", location: "/%2F%2Fevil.example", allowed: true },
  { name: "userinfo", template: "https://$1/new", capture: "user@trusted.example", location: "https://user@trusted.example/new", allowed: false },
  { name: "IDN outside allowlist", template: "https://$1/new", capture: "évil.example", location: "https://évil.example/new", allowed: false },
  { name: "IDN explicitly allowed", template: "https://$1/new", capture: "évil.example", location: "https://évil.example/new", allowed: true, allowlist: [idnHost] },
  { name: "same-origin path", template: "/$1", capture: "new", location: "/new", allowed: true },
  { name: "same-origin absolute", template: "https://trusted.example/$1", capture: "new", location: "https://trusted.example/new", allowed: true },
  { name: "reserved after capture", template: "/$1", capture: "admin", location: "/admin", allowed: false },
  { name: "encoded reserved after capture", template: "/$1", capture: "%61dmin", location: "/%61dmin", allowed: false },
  { name: "dot-segment reserved after decode", template: "/$1", capture: "safe%2F..%2Fadmin", location: "/safe%2F..%2Fadmin", allowed: false },
  { name: "Express referrer alias", template: "$1", capture: "back", location: "back", allowed: false },
] as const;

function rule(overrides: Partial<RedirectRecord> = {}): RedirectRecord {
  return {
    id: "rule-1", workspaceId, matchType: "wildcard", fromPattern: "/go/*", toTarget: "/$1",
    statusCode: 308, status: "active", override: true, priority: 0, source: "manual",
    createdByPrincipal: "user-1", createdAt: "2026-10-07T00:00:00.000Z", updatedAt: "2026-10-07T00:00:00.000Z", version: 1,
    ...overrides,
  };
}
function origin(allowlist: readonly string[] = []): { oracle: RedirectTargetOracle; candidates: string[] } {
  const registry = new OriginRegistry({ repo: new InMemoryOriginSettingRepo({ seeds: [{
    workspaceId, origin: createVerifiedOrigin({ scheme: "https", host: "trusted.example", verifiedAt: "2026-10-07T00:00:00.000Z", source: "workspace-setting" }),
    redirectAllowlist: [...allowlist],
  }] }) });
  const candidates: string[] = [];
  return {
    candidates,
    oracle: {
      canonicalOrigin: context => registry.canonicalOrigin(context),
      isAllowedRedirectTarget: required => { candidates.push(required.url); return registry.isAllowedRedirectTarget(required); },
    },
  };
}

for (const entry of cases) {
  test(`shared open-redirect matrix: ${entry.name}`, async () => {
    const dynamicRule = rule({ toTarget: entry.template });
    const request = { workspaceId, path: `/go/${entry.capture}`, phase: "post_content" as const };
    const { oracle, candidates } = origin("allowlist" in entry ? entry.allowlist : []);
    const resolver = createRedirectResolver({ repo: new InMemoryRedirectRepo({ seed: [dynamicRule] }, {}), matcher: redirectMatcher, originRegistry: oracle, reservedSegments }, {});
    const resolution = await resolver.resolve(request, {});
    assert.equal(resolution.matched, entry.allowed, "resolver verdict");
    if (resolution.matched) assert.equal(resolution.location, entry.location);

    const navigations: string[] = [];
    const guard = createSpaRedirectGuard({ rules: [dynamicRule], oracle, reservedSegments, navigate: ({ location }) => { navigations.push(location); } }, {});
    const guarded = await guard({ request }, {});
    assert.equal(guarded.navigated, entry.allowed, "SPA verdict");
    assert.deepEqual(navigations, entry.allowed ? [entry.location] : [], "SPA effect only after approval");
    assert.equal(guarded.refused.length, entry.allowed ? 0 : 1, "SPA reports its refusal");

    const sent: Array<{ status: number; location: string }> = [];
    let nextCalls = 0;
    const errors: unknown[] = [];
    const response = { locals: { redirectContext: { workspaceId } }, redirect: (status: number, location: string) => { sent.push({ status, location }); } };
    const middleware = createRedirectMiddleware({ resolver }, { phase: "post_content" });
    const http = await middleware({ path: request.path } as Request, response as unknown as Response,
      ((error?: unknown) => { nextCalls++; if (error !== undefined) errors.push(error); }) as NextFunction);
    assert.deepEqual(errors, []);
    assert.deepEqual(sent, entry.allowed ? [{ status: 308, location: entry.location }] : [], "HTTP effect only after approval");
    assert.equal(nextCalls, entry.allowed ? 0 : 1);
    assert.ok("refused" in http);
    if ("refused" in http) assert.equal(http.refused.length, entry.allowed ? 0 : 1, "HTTP reports its refusal");

    // Static exporters check the SAME finished Location as a literal rule. They cannot ship the
    // dynamic template itself: its other inputs cannot be rechecked by a static host file.
    const literal = rule({ matchType: "exact", fromPattern: "/old", toTarget: entry.location });
    const netlify = await toNetlifyRedirects({ rules: [literal], oracle, reservedSegments }, {});
    const vercel = await toVercelRedirects({ rules: [literal], oracle, reservedSegments }, {});
    assert.equal(netlify.emitted.length > 0, entry.allowed, "Netlify literal verdict");
    assert.equal(vercel.emitted.redirects.length, entry.allowed ? 1 : 0, "Vercel literal verdict");
    assert.equal(netlify.refused.length, entry.allowed ? 0 : 1);
    assert.equal(vercel.refused.length, entry.allowed ? 0 : 1);
    if (entry.allowed) {
      assert.equal(netlify.emitted, `/old ${entry.location} 308!\n`);
      assert.deepEqual(vercel.emitted.redirects, [{ source: "/old", destination: entry.location, statusCode: 308 }]);
    }
    for (const exporter of [toNetlifyRedirects, toVercelRedirects]) {
      const dynamic = await exporter({ rules: [dynamicRule], oracle, reservedSegments }, {});
      assert.equal(dynamic.refused.length, 1, "unbounded template is explicitly refused");
    }
    if (entry.name !== "Express referrer alias") {
      const expectedCandidate = /^(?:\/\/|[a-z][a-z0-9+.-]*:)/i.test(entry.location)
        ? entry.location : `https://trusted.example${entry.location}`;
      assert.ok(candidates.length >= 3, "every runtime boundary reached the real oracle");
      assert.ok(candidates.every(candidate => candidate === expectedCandidate), "oracle sees interpolated Location, never the template");
    } else assert.deepEqual(candidates, [], "no candidate can describe Express's Referer substitution");
  });
}

test("an omitted verified origin refuses every effect boundary", async () => {
  const registry = new OriginRegistry({ repo: new InMemoryOriginSettingRepo({ seeds: [] }) });
  const literal = rule({ matchType: "exact", fromPattern: "/old", toTarget: "/new" });
  const resolver = createRedirectResolver({ repo: new InMemoryRedirectRepo({ seed: [literal] }, {}), matcher: redirectMatcher, originRegistry: registry, reservedSegments }, {});
  assert.deepEqual(await resolver.resolve({ workspaceId, path: "/old", phase: "post_content" }, {}), { matched: false });
  let navigated = false;
  const guard = createSpaRedirectGuard({ rules: [literal], oracle: registry, reservedSegments, navigate: () => { navigated = true; } }, {});
  assert.equal((await guard({ request: { workspaceId, path: "/old", phase: "post_content" } }, {})).refused.length, 1);
  assert.equal(navigated, false);
  assert.equal((await toNetlifyRedirects({ rules: [literal], oracle: registry, reservedSegments }, {})).emitted, "");
  assert.deepEqual((await toVercelRedirects({ rules: [literal], oracle: registry, reservedSegments }, {})).emitted, { redirects: [] });
});

test("required reserved segments are host policy on resolver, SPA and exporter, with no admin-only default", async () => {
  const { oracle } = origin();
  const literal = rule({ matchType: "exact", fromPattern: "/old", toTarget: "/private" });
  for (const reservePrivate of [false, true]) {
    const hostReserved = new Set(reservePrivate ? ["private"] : []);
    const resolver = createRedirectResolver({ repo: new InMemoryRedirectRepo({ seed: [literal] }, {}), matcher: redirectMatcher, originRegistry: oracle, reservedSegments: hostReserved }, {});
    assert.equal((await resolver.resolve({ workspaceId, path: "/old", phase: "post_content" }, {})).matched, !reservePrivate);
    let navigated = false;
    const guard = createSpaRedirectGuard({ rules: [literal], oracle, reservedSegments: hostReserved, navigate: () => { navigated = true; } }, {});
    await guard({ request: { workspaceId, path: "/old", phase: "post_content" } }, {});
    assert.equal(navigated, !reservePrivate);
    assert.equal((await toNetlifyRedirects({ rules: [literal], oracle, reservedSegments: hostReserved }, {})).emitted.length > 0, !reservePrivate);
    assert.equal((await toVercelRedirects({ rules: [literal], oracle, reservedSegments: hostReserved }, {})).emitted.redirects.length > 0, !reservePrivate);
  }
});

test("Express forwards resolver failure and missing host context without emitting a Location", async () => {
  const failure = new Error("repo unavailable");
  const resolver = { resolve: async () => { throw failure; }, resolveWithRefusals: async () => { throw failure; } };
  const middleware = createRedirectMiddleware({ resolver }, {});
  const forwarded: unknown[] = [];
  const sent: unknown[] = [];
  const response = { locals: { redirectContext: { workspaceId } }, redirect: (...args: unknown[]) => { sent.push(args); } };
  const next = ((error?: unknown) => forwarded.push(error)) as NextFunction;
  assert.deepEqual(await middleware({ path: "/old" } as Request, response as unknown as Response, next), { error: failure });
  assert.equal(forwarded[0], failure);
  const missing = await middleware({ path: "/old" } as Request, { ...response, locals: {} } as unknown as Response, next);
  assert.ok("error" in missing && missing.error instanceof RedirectMiddlewareContextError);
  assert.deepEqual(sent, []);
});

src/widgets/__tests__/plugin-export.unit.source:
import { describe, expect, it } from 'vitest';
import { parseFragment } from 'parse5';
import { embedMarkerSnippetFromConfig, scanEmbedMarkers } from '../markers/marker.js';
import { scanHtmlEmbeds, substituteHtmlEmbeds } from '../html/html-embeds.js';
import {
  fillPluginExportTemplate, resolvePluginExportEmbeds,
  type PluginExportRender, type PluginExportTemplate, type PluginExportsPort,
} from '../html/plugin-export.js';

const config = { type: 'plugin', plugin: 'example/login', component: 'button', version: 1, props: {} };
const snippet = (props: Record<string, unknown> = {}) => embedMarkerSnippetFromConfig({ config: { ...config, props } });
const definition: PluginExportTemplate = {
  plugin: 'example/login', component: 'button', version: 2, minVersion: 1, consent: 'necessary',
  template: '<a class="plugin-login-button" href="{{host.start}}"><span>{{props.label}}</span></a>',
  props: { label: 'Continue' }, host: { start: '/api/member/start' },
};
const rendered: PluginExportRender = {
  plugin: 'example/login', component: 'button', version: 1, consent: 'necessary',
  html: '<a class="plugin-login-button" href="/api/member/start"><span>Continue</span></a>',
};

function resolve(html: string, port?: PluginExportsPort) {
  return resolvePluginExportEmbeds({ refs: scanHtmlEmbeds({ html }), workspaceId: 'site-a', ...(port ? { port } : {}) });
}

describe('plugin marker serialization and substitution', () => {
  it('round trips apostrophes, ampersands, closing tags and future fields', () => {
    const complete = { ...config, props: { label: "Owner's & </div> {{host.secret}}" }, future: { enabled: true } };
    const html = embedMarkerSnippetFromConfig({ config: complete });
    expect(scanEmbedMarkers({ html }).markers[0]?.config).toEqual(complete);
    // Check the browser parser too: closing-tag text in an attribute cannot truncate the marker.
    const root = parseFragment(html);
    const node = root.childNodes[0];
    if (!node || !('attrs' in node)) throw new Error('missing marker element');
    expect(JSON.parse(node.attrs[0]!.value)).toEqual(complete);
  });

  it('keys every occurrence independently even with the same authored id', () => {
    const html = embedMarkerSnippetFromConfig({ config: { ...config, id: 'same' } });
    expect(scanHtmlEmbeds({ html: html + html }).map(ref => ref.id)).toEqual(['plugin:1', 'plugin:2']);
  });

  it.each([undefined, '', '<b>generic placeholder</b>'])('keeps wrapper and fallback for unresolved output %s', output => {
    const html = `<aside class="theme" style="color:red" aria-label="Sign in" data-embed-config='${JSON.stringify(config)}'><b>Try later</b></aside>`;
    expect(substituteHtmlEmbeds({ html, resolve: () => output })).toBe('<aside class="theme" style="color:red" aria-label="Sign in"><b>Try later</b></aside>');
  });

  it('keeps author hooks and overwrites all author-typed stamps with canonical values', () => {
    const html = `<section id="signin" class="theme" style="color:red" aria-label="Login" DATA-PLUGIN="wrong" data-component="wrong" data-embed-v="99" data-consent-category="marketing" data-embed-config='${JSON.stringify(config)}'>fallback</section>`;
    expect(substituteHtmlEmbeds({ html, resolve: () => rendered })).toBe('<section id="signin" class="theme" style="color:red" aria-label="Login" data-plugin="example/login" data-component="button" data-embed-v="1" data-consent-category="necessary">' + rendered.html + '</section>');
  });

  it('always keeps even a bare wrapper on success', () => {
    expect(substituteHtmlEmbeds({ html: snippet(), resolve: () => rendered })).toBe('<div data-plugin="example/login" data-component="button" data-embed-v="1" data-consent-category="necessary">' + rendered.html + '</div>');
  });

  it('keeps existing widget, media, and content output byte-identical', () => {
    const html = `<div data-embed-config='{"type":"widget","id":"w"}'></div><figure class="photo" data-embed-config='{"type":"media","id":"m"}'></figure><main data-embed-config='{"type":"content","id":"c"}'></main>`;
    const outputs: Record<string, string> = { widget: '<b>Widget</b>', media: '<img src="/photo.png">', content: '<p>Body</p>' };
    expect(substituteHtmlEmbeds({ html, resolve: ref => outputs[ref.type] })).toBe('<b>Widget</b><figure class="photo"><img src="/photo.png"></figure><main><p>Body</p></main>');
  });
});

describe('plugin export template policy', () => {
  it.each(['/some/path', 'https://example.com/path', '//example.com/path', 'javascript:alert(1)'])('refuses literal URL %s in every supported URL attribute', value => {
    for (const template of [`<a href="${value}">Link</a>`, `<img src="${value}" alt="">`, `<form action="${value}"></form>`]) {
      expect(() => fillPluginExportTemplate({ definition: { ...definition, template } })).toThrow();
    }
  });

  it.each([
    '<a HREF="&#47;some/path">Link</a>', '<a href=/some/path>Link</a>', '<a href="">Link</a>',
    '<a href="/prefix{{host.start}}">Link</a>', '<a href="{{host.start}}/suffix">Link</a>',
    '<a href="{{host.start}}{{host.start}}">Link</a>', '<a href="{{host.links.start}}">Link</a>',
    '<img src="{{host.assets.mark}}?literal=1" alt="">',
  ])('requires one complete declared host URL slot: %s', template => {
    expect(() => fillPluginExportTemplate({ definition: { ...definition, template } }))
      .toThrow('plugin export URL must be a whole hostLinks or assets slot');
  });

  it.each([
    ['<a href="{{host.signIn}}">Link</a>', '<a href="/member/sign-in">Link</a>'],
    ['<img src="{{host.assets.mark}}" alt="">', '<img src="/plugin-assets/mark.png" alt="">'],
  ])('accepts the host-resolved URL slot in %s', (template, expected) => {
    expect(fillPluginExportTemplate({ definition: { ...definition, template,
      host: { signIn: '/member/sign-in', assets: { mark: '/plugin-assets/mark.png' } },
    } })).toBe(expected);
  });

  it.each([
    '<img srcset="/image.png 1x" alt="">', '<button formaction="/submit">Submit</button>',
    '<div poster="/poster.png"></div>', '<a xlink:href="/link">Link</a>',
    '<span style="background:url(/image.png)">Image</span>',
  ])('retains the fragment policy refusal for unsupported URL sinks: %s', template => {
    expect(() => fillPluginExportTemplate({ definition: { ...definition, template } })).toThrow();
  });

  it('escapes text and attributes without interpreting values as template source', () => {
    const label = `Owner's " & </span><script>x</script> {{host.secret}}`;
    const html = fillPluginExportTemplate({ definition: { ...definition, template: '<span title="{{props.label}}">{{props.label}}</span>', props: { label } } });
    const node = parseFragment(html).childNodes[0];
    if (!node || !('attrs' in node)) throw new Error('missing span');
    expect(node.attrs[0]?.value).toBe(label);
    expect(node.childNodes).toEqual([expect.objectContaining({ nodeName: '#text', value: label })]);
    // Attribute text needs no tag escaping; the text-node copy must serialize as inert entities.
    expect(html).toContain('&lt;/span&gt;&lt;script&gt;');
  });

  it.each(['javascript:alert(1)', '//evil.example/start', 'https://evil.example/start', '/\\evil.example', '/path\nnext'])('refuses host URL %s', start => {
    expect(() => fillPluginExportTemplate({ definition: { ...definition, host: { start } } })).toThrow();
  });

  it.each([
    '<script>x</script>', '<span style="color:red">x</span>', '<span onclick="x">x</span>',
    '<span data-embed-config="x">x</span>', '<span data-page-region="x">x</span>',
    '<a href="{{props.url}}">x</a>', '<span title={{props.label}}>x</span>',
    '<span>{{props.missing}}</span>', '<span>{{props.__proto__.x}}</span>',
    '<span>{{include template}}</span>', '<!-- {{props.label}} -->',
  ])('refuses unsupported template %s', template => {
    expect(() => fillPluginExportTemplate({ definition: { ...definition, template, props: { label: 'hi', url: '/safe' } } })).toThrow();
  });

  it('uses the existing fragment byte cap', () => {
    expect(() => fillPluginExportTemplate({ definition: { ...definition, template: '<span>{{props.label}}</span>', props: { label: 'x'.repeat(65536) } } })).toThrow('size cap');
  });
});

describe('plugin export occurrence resolution', () => {
  it.each(['/some/path', 'https://example.com/path', '//example.com/path', 'javascript:alert(1)'])('keeps authored fallback for literal URL %s and still renders the next occurrence', async value => {
    const html = snippet().replace('></div>', '><b>Author fallback</b></div>') + snippet();
    let calls = 0;
    const result = await resolve(html, { resolve: async () => calls++ === 0
      ? { ...definition, template: `<a href="${value}">Refused link</a>` } : definition });
    expect([...result.keys()]).toEqual(['plugin:2']);
    expect(substituteHtmlEmbeds({ html, resolve: ref => result.get(ref.id!)?.props as unknown as PluginExportRender | undefined }))
      .toBe('<div><b>Author fallback</b></div><div data-plugin="example/login" data-component="button" data-embed-v="1" data-consent-category="necessary">' + rendered.html + '</div>');
  });

  it('does not require a port and never emits a placeholder IR', async () => {
    expect([...await resolve(snippet())]).toEqual([]);
  });

  it('renders different props per occurrence and carries canonical metadata into substitution', async () => {
    const html = snippet({ label: 'One' }) + snippet({ label: 'Two' });
    const result = await resolve(html, { resolve: async ({ config: marker, workspaceId }) => {
      expect(workspaceId).toBe('site-a');
      return { ...definition, props: marker.props as Record<string, unknown> };
    } });
    expect(result.get('plugin:1')?.props.html).toContain('<span>One</span>');
    expect(result.get('plugin:2')?.props.html).toContain('<span>Two</span>');
    const output = substituteHtmlEmbeds({ html, resolve: ref => result.get(ref.id!)?.props as unknown as PluginExportRender | undefined });
    expect(output).toContain('<span>One</span>');
    expect(output).toContain('<span>Two</span>');
    expect(output).not.toContain('data-embed-config');
  });

  it.each([undefined, 1, 2, 0, 3, -1, 1.5, '1', null])('applies the declared version range to %s', async version => {
    const marker = { ...config, version };
    const result = await resolve(embedMarkerSnippetFromConfig({ config: marker }), { resolve: async () => definition });
    const accepted = version === undefined || version === 1 || version === 2;
    expect(result.size).toBe(accepted ? 1 : 0);
    if (accepted) expect(result.get('plugin:1')?.props.version).toBe(version ?? 1);
  });

  it('refuses retired marker contracts', async () => {
    const result = await resolve(snippet(), { resolve: async () => ({ ...definition, minVersion: 2 }) });
    expect(result.size).toBe(0);
  });

  it.each(['unavailable', 'schema failure', 'unsafe fragment'])('falls back on %s while preserving the next occurrence', async reason => {
    let calls = 0;
    const result = await resolve(snippet() + snippet(), { resolve: async () => {
      if (calls++ > 0) return definition;
      if (reason === 'unavailable') return undefined;
      if (reason === 'schema failure') throw new Error('invalid props');
      return { ...definition, template: '<iframe></iframe>' };
    } });
    expect([...result.keys()]).toEqual(['plugin:2']);
  });
});

