import assert from "node:assert/strict";
import { test } from "vitest";

import { InvalidFieldKindError, StorageOnlyFieldNotQueryableError } from "../errors.js";
import { mapFieldKindToCast, resolveFieldIndexTransition } from "../index-provisioning.js";
import { registerContentType, updateContentTypeFields } from "../write-service.js";
import {
  CONTENT_TYPE_FIELD_KINDS,
  CONTENT_TYPE_SCALAR_KINDS,
  INDEXABLE_FIELD_KINDS,
  STORAGE_ONLY_FIELD_KINDS,
  isIndexableFieldKind,
} from "../types.js";

/**
 * @file the indexable-vs-storage-only field-kind split.
 *
 * Companion to `index-provisioning.ddl-safety.test.ts`, which stays the certified owner of the
 * original DDL-injection properties. This file owns the properties the split introduces, and its
 * single most important assertion is the DDL-ALPHABET one: the set of DISTINCT strings that can
 * reach a `CAST(... AS {type})` position must be exactly the four it has always been. The table
 * gaining a key is not a security event; the table gaining a VALUE would be, and only a test that
 * pins the value set can tell those two apart.
 * See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
 */

/** The complete set of CAST literals reachable before `relation` existed. Must never grow. */
const HISTORICAL_DDL_ALPHABET = ["BOOLEAN", "INTEGER", "REAL", "TEXT"] as const;

test("U-001-B1 (THE security property): the set of DISTINCT CAST literals reachable from any indexable kind is exactly the historical four — a new KEY may be added, a new VALUE may not", () => {
  const reachable = new Set(INDEXABLE_FIELD_KINDS.map((kind) => mapFieldKindToCast({ kind: kind })));

  assert.deepEqual(
    [...reachable].sort(),
    [...HISTORICAL_DDL_ALPHABET],
    "the DDL alphabet grew — every new value here is a new string that can reach a CAST position and must be reviewed as a DDL change, not as an enum addition",
  );
});

test("U-001-B1 (property, auto-covering future additions): every indexable kind maps to a plain uppercase SQL type token with no injection-shaped characters", () => {
  for (const kind of INDEXABLE_FIELD_KINDS) {
    const literal = mapFieldKindToCast({ kind: kind });
    assert.match(literal, /^[A-Z]+$/, `CAST literal for '${kind}' must be a plain uppercase token, got: ${literal}`);
    assert.equal(/['";()\s]/.test(literal), false, `CAST literal for '${kind}' must contain no injection-shaped characters`);
  }
});

test("'relation' maps to the literal already used by 'text' — it adds a key, not a value", () => {
  assert.equal(mapFieldKindToCast({ kind: "relation" }), "TEXT");
  assert.equal(mapFieldKindToCast({ kind: "relation" }), mapFieldKindToCast({ kind: "text" }));
  assert.equal(mapFieldKindToCast({ kind: "relation" }), mapFieldKindToCast({ kind: "datetime" }));
});

test("the five original scalars still map to their original literals, unchanged", () => {
  assert.deepEqual(
    CONTENT_TYPE_SCALAR_KINDS.map((kind) => mapFieldKindToCast({ kind: kind })),
    ["TEXT", "INTEGER", "REAL", "BOOLEAN", "TEXT"],
  );
});

test("U-001-B1: every storage-only kind is REJECTED by mapFieldKindToCast — a legal kind to declare is not thereby a legal kind to CAST", () => {
  for (const kind of STORAGE_ONLY_FIELD_KINDS) {
    assert.throws(() => mapFieldKindToCast({ kind: kind }), InvalidFieldKindError, `'${kind}' must never yield a CAST literal`);
  }
});

test("U-001-B1 (exhaustive over the enum): every declared kind either maps to a literal in the historical alphabet or throws — there is no third outcome", () => {
  for (const kind of CONTENT_TYPE_FIELD_KINDS) {
    if (isIndexableFieldKind({ value: kind })) {
      assert.ok((HISTORICAL_DDL_ALPHABET as readonly string[]).includes(mapFieldKindToCast({ kind: kind })));
    } else {
      assert.throws(() => mapFieldKindToCast({ kind: kind }), InvalidFieldKindError);
    }
  }
});

test("the two subsets are disjoint, and their concatenation IS the enum — a kind can never be both indexable and storage-only", () => {
  const overlap = INDEXABLE_FIELD_KINDS.filter((kind) => (STORAGE_ONLY_FIELD_KINDS as readonly string[]).includes(kind));
  assert.deepEqual(overlap, [], "a kind in both sets would be indexable and unindexable at once");
  assert.deepEqual([...CONTENT_TYPE_FIELD_KINDS], [...INDEXABLE_FIELD_KINDS, ...STORAGE_ONLY_FIELD_KINDS]);
});

test("ordering is load-bearing: the five original scalars are still the first five members, in their original order", () => {
  assert.deepEqual(CONTENT_TYPE_FIELD_KINDS.slice(0, 5), ["text", "integer", "real", "boolean", "datetime"]);
  assert.deepEqual([...CONTENT_TYPE_SCALAR_KINDS], ["text", "integer", "real", "boolean", "datetime"]);
});

test("resolveFieldIndexTransition still ACCEPTS a storage-only kind on the non-provisioning arms and answers 'none'/'teardown'", () => {
  const json = { kind: "json" as const, queryable: false };
  assert.deepEqual(resolveFieldIndexTransition({ before: undefined, after: json }), { action: "none" });
  assert.deepEqual(resolveFieldIndexTransition({ before: json, after: json }), { action: "none" });
  assert.deepEqual(resolveFieldIndexTransition({ before: json, after: undefined }), { action: "none" });
  assert.deepEqual(
    resolveFieldIndexTransition({ before: { kind: "json", queryable: true }, after: json }),
    { action: "teardown" },
    "teardown must stay reachable so an index left behind by a bypassed guard can still be removed",
  );
});

test("resolveFieldIndexTransition FAILS LOUDLY if a storage-only kind reaches a provisioning arm, rather than emitting a newKind with no CAST target", () => {
  assert.throws(
    () => resolveFieldIndexTransition({ before: undefined, after: { kind: "json", queryable: true } }),
    InvalidFieldKindError,
    "provision arm",
  );
  assert.throws(
    () => resolveFieldIndexTransition({ before: { kind: "text", queryable: true }, after: { kind: "json", queryable: true } }),
    InvalidFieldKindError,
    "reprovision arm",
  );
});

test("'relation' is a first-class indexable kind through the transition resolver", () => {
  assert.deepEqual(
    resolveFieldIndexTransition({ before: undefined, after: { kind: "relation", queryable: true } }),
    { action: "provision", newKind: "relation" },
  );
  assert.deepEqual(
    resolveFieldIndexTransition({ before: { kind: "text", queryable: true }, after: { kind: "relation", queryable: true } }),
    { action: "reprovision", newKind: "relation" },
  );
});

/* ------------------------------------------------------------------ write-service guard 4b */

const NOW = "2026-09-05T00:00:00.000Z";
const clock = { nowMs: () => Date.parse(NOW)};
const ids = { newId: () => "ct-1" };
const alwaysAllow = async () => ({ allowed: true, reason: "matched" });
const outbox = { enqueue: async () => undefined };

function fakeRepo(current?: unknown) {
  const rows: unknown[] = [];
  return {
    rows,
    save: async (row: unknown) => { rows.push(row); },
    appendRevision: async () => undefined,
    findByKey: async () => (current ?? null) as never,
    transaction: async <T>({ fn }: { fn: () => Promise<T> }) => fn(),
  };
}

function fakeIndexProvisioner() {
  const calls: unknown[] = [];
  return {
    calls,
    provisionIndexesForNewContentType: async (input: unknown) => { calls.push(input); },
    applyFieldIndexTransitions: async (input: unknown) => { calls.push(input); },
  };
}

const register = (fields: unknown[], provisioner = fakeIndexProvisioner(), repo = fakeRepo()) =>
  registerContentType({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: provisioner, outbox },
    input: { workspaceId: "ws-1", actorId: "user-1", key: "recipe", label: "Recipe", fields: fields as never },
  });

test("U-002-B1 guard 4b: register REJECTS a storage-only kind declared queryable, and writes no row", async () => {
  const repo = fakeRepo();
  const provisioner = fakeIndexProvisioner();
  const result = await register([{ name: "ingredients", kind: "json", required: false, queryable: true }], provisioner, repo);

  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.equal(result.error.constructor.name, "StorageOnlyFieldNotQueryableError");
    assert.match(result.error.message, /storage-only kind 'json' and cannot be queryable/);
  }
  assert.equal(repo.rows.length, 0, "a rejected registration must persist nothing");
  assert.equal(provisioner.calls.length, 0, "no index may be provisioned for a rejected registration");
});

test("U-002-B1 guard 4b: update-fields rejects the same pairing", async () => {
  const current = { workspaceId: "ws-1", key: "recipe", label: "Recipe", fields: [], status: "active", version: 1 };
  const repo = fakeRepo(current);
  const result = await updateContentTypeFields({
    deps: { repo, clock, ids, authorize: alwaysAllow, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: {
      workspaceId: "ws-1", actorId: "user-1", key: "recipe", expectedVersion: 1,
      fields: [{ name: "ingredients", kind: "json", required: false, queryable: true }] as never,
    },
  });

  assert.equal(result.ok, false);
  if (!result.ok) assert.equal(result.error.constructor.name, "StorageOnlyFieldNotQueryableError");
});

test("the guard-4b error is an InvalidFieldKindError SUBCLASS, so every existing boundary `instanceof` list maps it to 400 rather than falling through to 500", () => {
  const error = new StorageOnlyFieldNotQueryableError({ message: "x" });
  assert.ok(error instanceof InvalidFieldKindError, "an unmapped sibling class would become a 500 at boundaries this package cannot edit");
  assert.ok(error instanceof Error);
  assert.equal(error.name, "StorageOnlyFieldNotQueryableError", "the finer signal must still be available by name");
});

test("U-002-B1 ordering: guard 4 (unknown kind) still fires BEFORE guard 4b, asserted by exact class so the subclass relationship cannot mask a reordering", async () => {
  const result = await register([
    { name: "ingredients", kind: "json", required: false, queryable: true },
    { name: "bad", kind: "sql_injection_kind", required: false, queryable: true },
  ]);

  assert.equal(result.ok, false);
  if (!result.ok) {
    assert.equal(result.error.constructor.name, "InvalidFieldKindError", "an unknown kind anywhere in the array must beat a storage-only-queryable field earlier in it");
  }
});

test("U-002-B1 ordering: guard 4b fires BEFORE guard 5 (queryable-cap)", async () => {
  const result = await register([
    ...Array.from({ length: 25 }, (_, i) => ({ name: `f_${i}`, kind: "text", required: false, queryable: true })),
    { name: "ingredients", kind: "json", required: false, queryable: true },
  ]);

  assert.equal(result.ok, false);
  if (!result.ok) assert.equal(result.error.constructor.name, "StorageOnlyFieldNotQueryableError");
});

test("a storage-only field declared NON-queryable is accepted, and 'relation' is accepted as queryable", async () => {
  const repo = fakeRepo();
  const result = await register(
    [
      { name: "ingredients", kind: "json", required: false, queryable: false },
      { name: "author_id", kind: "relation", required: true, queryable: true },
    ],
    fakeIndexProvisioner(),
    repo,
  );

  assert.equal(result.ok, true);
  assert.equal(repo.rows.length, 1);
});

src/content-types/__tests__/tool-registr.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { AGENT_TOOL_PRINCIPAL_KIND, ToolInputError, type ToolExecutionContext, type ToolRegistration } from "@jini-ai/core";

import { ContentTypeLifecycleError, ForbiddenError, ReservedContentTypeKeyError, VersionConflictError } from "../errors.js";
import { InMemoryContentTypeRepo } from "../repo.memory.js";
import { buildContentTypesRegistrations, contentTypesDerivedRisk, type ContentTypesToolDeps } from "../tool-registrations.js";
import type { ContentTypeFieldDef } from "../types.js";

/**
 * @file The content-types agent tools driven end to end through their registrations: what each
 * handler hands the model (the workspace-free view), what it writes (row, revision provenance,
 * index calls, outbox events), and how it refuses (input shape, permission, lifecycle, version).
 */

const WORKSPACE_ID = "ws-ct-tools";
const NOW = "2026-10-21T00:00:00.000Z";
const TITLE_FIELD: ContentTypeFieldDef = { name: "title", kind: "text", required: true, queryable: true };

function ctx(input: unknown, principalId = "agent-principal"): ToolExecutionContext {
  return { executionId: "exec-1", principal: { id: principalId }, run: { id: "run-1" }, input, signal: new AbortController().signal } as ToolExecutionContext;
}

function harness(overrides: Partial<ContentTypesToolDeps> = {}) {
  const repo = new InMemoryContentTypeRepo();
  const events: Array<{ id: string; name: string; workspaceId: string; occurredAt: string; payload: Record<string, unknown> }> = [];
  const indexCalls: Array<[string, unknown]> = [];
  const permissionRequests: unknown[] = [];
  let ids = 0;
  const deps: ContentTypesToolDeps = {
    authorize: async (request) => { permissionRequests.push(request); return { allowed: true, reason: "matched" }; },
    workspaceId: WORKSPACE_ID,
    clock: { nowMs: () => Date.parse(NOW) },
    idGen: { newId: () => `id-${++ids}` },
    outbox: { enqueue: async (event) => { events.push(event); }, claimPending: async () => [], markDelivered: async () => {}, markFailed: async () => {} },
    contentTypeRepo: repo,
    contentTypeIndexProvisioner: {
      provisionIndexesForNewContentType: async (call) => { indexCalls.push(["provision", call]); },
      applyFieldIndexTransitions: async (call) => { indexCalls.push(["transition", call]); },
      tearDownAllIndexesForContentType: async (call) => { indexCalls.push(["teardown", call]); },
    },
    ...overrides,
  };
  const registrations = buildContentTypesRegistrations(deps);
  const tool = (id: string): ToolRegistration => {
    const found = registrations.find((registration) => registration.descriptor.id === id);
    assert.ok(found, `${id} must be wired`);
    return found;
  };
  return { deps, repo, events, indexCalls, permissionRequests, registrations, tool };
}

async function defineRecipe(h: ReturnType<typeof harness>) {
  return h.tool("collections_content_type_define").handler(ctx({ key: "recipe", label: "Recipe", fields: [TITLE_FIELD] }));
}

test("exactly the six classified tools are wired; the two cleanup tools are withheld", () => {
  const h = harness();
  assert.deepEqual(h.registrations.map((r) => r.descriptor.id).sort(), [...contentTypesDerivedRisk.keys()].sort());
  assert.equal(h.registrations.some((r) => r.descriptor.id.includes("cleanup")), false);
});

test("collections_content_type_define returns the workspace-free view and records agent provenance", async () => {
  const h = harness();

  const result = await defineRecipe(h);

  assert.deepEqual(result, { contentType: { key: "recipe", label: "Recipe", status: "active", version: 1, fields: [TITLE_FIELD] } });
  const stored = await h.repo.findByKey({ workspaceId: WORKSPACE_ID, key: "recipe" });
  assert.equal(stored?.workspaceId, WORKSPACE_ID);
  const [revision] = h.repo.listRevisions();
  assert.equal(revision?.actorId, "agent-principal");
  assert.equal(revision?.principalKind, AGENT_TOOL_PRINCIPAL_KIND);
});

test("collections_content_type_define rejects malformed fields with the tool's published schema appended, writing nothing", async () => {
  const h = harness();

  await assert.rejects(
    () => h.tool("collections_content_type_define").handler(ctx({ key: "recipe", label: "Recipe", fields: [{ name: "title", kind: "text", required: "yes", queryable: true }] })),
    (error: unknown) => {
      assert.ok(error instanceof ToolInputError);
      assert.match(error.message, /Schema for 'collections_content_type_define'/);
      return true;
    },
  );
  assert.equal(await h.repo.findByKey({ workspaceId: WORKSPACE_ID, key: "recipe" }), null);
});

test("collections_content_type_define honors the host's reserved keys when supplied", async () => {
  const h = harness({ reservedContentTypeKeys: new Set(["blog"]) });

  await assert.rejects(
    () => h.tool("collections_content_type_define").handler(ctx({ key: "blog", label: "Blog", fields: [] })),
    (error: unknown) => error instanceof ReservedContentTypeKeyError && /reserved for a host route/.test(error.message),
  );
  assert.equal(await h.repo.findByKey({ workspaceId: WORKSPACE_ID, key: "blog" }), null);
});

test("collections_content_type_update_fields replaces the field schema at the expected version", async () => {
  const h = harness();
  await defineRecipe(h);
  const summary: ContentTypeFieldDef = { name: "summary", kind: "text", required: false, queryable: false };

  const result = await h.tool("collections_content_type_update_fields").handler(ctx({ key: "recipe", fields: [TITLE_FIELD, summary], expectedVersion: 1 }));

  assert.deepEqual(result, { contentType: { key: "recipe", label: "Recipe", status: "active", version: 2, fields: [TITLE_FIELD, summary] } });
  await assert.rejects(
    () => h.tool("collections_content_type_update_fields").handler(ctx({ key: "recipe", fields: [TITLE_FIELD], expectedVersion: 1 })),
    (error: unknown) => error instanceof VersionConflictError,
  );
  await assert.rejects(
    () => h.tool("collections_content_type_update_fields").handler(ctx({ key: "recipe", fields: "title", expectedVersion: 2 })),
    (error: unknown) => error instanceof ToolInputError && /Schema for 'collections_content_type_update_fields'/.test(error.message),
  );
});

test("deprecate -> reactivate -> deprecate -> tombstone runs through the tools; only the tombstoned view carries tombstonedAt", async () => {
  const h = harness();
  await defineRecipe(h);

  const deprecated = await h.tool("collections_content_type_deprecate").handler(ctx({ key: "recipe", expectedVersion: 1 }));
  assert.deepEqual(deprecated, { contentType: { key: "recipe", label: "Recipe", status: "deprecated", version: 2, fields: [TITLE_FIELD] } });

  const reactivated = await h.tool("collections_content_type_reactivate").handler(ctx({ key: "recipe", expectedVersion: 2 }));
  assert.deepEqual(reactivated, { contentType: { key: "recipe", label: "Recipe", status: "active", version: 3, fields: [TITLE_FIELD] } });

  await h.tool("collections_content_type_deprecate").handler(ctx({ key: "recipe", expectedVersion: 3 }));
  const tombstoned = await h.tool("collections_content_type_tombstone").handler(ctx({ key: "recipe", expectedVersion: 4 }));
  assert.deepEqual(tombstoned, { contentType: { key: "recipe", label: "Recipe", status: "tombstone", version: 5, fields: [TITLE_FIELD], tombstonedAt: NOW } });

  // The real `core/ports` outbox receives full domain events: id, workspace, and occurredAt included.
  assert.deepEqual(h.events.map((event) => [event.name, event.workspaceId, event.occurredAt, event.payload]), [
    ["content_type.deprecated", WORKSPACE_ID, NOW, { workspaceId: WORKSPACE_ID, key: "recipe" }],
    ["content_type.deprecated", WORKSPACE_ID, NOW, { workspaceId: WORKSPACE_ID, key: "recipe" }],
    ["content_type.tombstoned", WORKSPACE_ID, NOW, { workspaceId: WORKSPACE_ID, key: "recipe" }],
  ]);
  assert.equal(new Set(h.events.map((event) => event.id)).size, 3);
  assert.ok(h.events.every((event) => typeof event.id === "string"));
  assert.deepEqual(h.indexCalls.filter(([kind]) => kind === "teardown"), [["teardown", { workspaceId: WORKSPACE_ID, contentTypeKey: "recipe" }]]);
  assert.ok(h.repo.listRevisions().every((revision) => revision.principalKind === AGENT_TOOL_PRINCIPAL_KIND));

  await assert.rejects(
    () => h.tool("collections_content_type_reactivate").handler(ctx({ key: "recipe", expectedVersion: 5 })),
    (error: unknown) => error instanceof ContentTypeLifecycleError,
  );
});

test("lifecycle tools reject a missing key or a non-numeric expectedVersion before any write", async () => {
  const h = harness();
  await defineRecipe(h);

  for (const id of ["collections_content_type_deprecate", "collections_content_type_reactivate", "collections_content_type_tombstone"]) {
    await assert.rejects(() => h.tool(id).handler(ctx({ expectedVersion: 1 })), ToolInputError);
    await assert.rejects(() => h.tool(id).handler(ctx({ key: "recipe", expectedVersion: "1" })), ToolInputError);
    await assert.rejects(() => h.tool(id).handler(ctx("recipe")), ToolInputError);
  }
  assert.equal((await h.repo.findByKey({ workspaceId: WORKSPACE_ID, key: "recipe" }))?.version, 1);
  assert.equal(h.events.length, 0);
});

test("collections_content_type_list returns workspace-scoped views after checking admin.collections.read", async () => {
  const h = harness();
  await defineRecipe(h);
  await h.repo.save({ workspaceId: "other-ws", key: "foreign", label: "Foreign", fields: [], status: "active", version: 1 });
  h.permissionRequests.length = 0;

  const listed = await h.tool("collections_content_type_list").handler(ctx(undefined));
  const listedWithEmptyInput = await h.tool("collections_content_type_list").handler(ctx({}));

  const expected = { contentTypes: [{ key: "recipe", label: "Recipe", status: "active", version: 1, fields: [TITLE_FIELD] }] };
  assert.deepEqual(listed, expected);
  assert.deepEqual(listedWithEmptyInput, expected);
  assert.deepEqual(h.permissionRequests[0], { principalId: "agent-principal", permission: "admin.collections.read", workspaceId: WORKSPACE_ID, entityType: "content-type" });
});

test("collections_content_type_list refuses invented filters and a denied principal", async () => {
  const denied = harness({ authorize: async () => ({ allowed: false, reason: "no-grant" }) });
  await assert.rejects(() => denied.tool("collections_content_type_list").handler(ctx({ status: "active" })), ToolInputError);
  await assert.rejects(
    () => denied.tool("collections_content_type_list").handler(ctx(undefined)),
    (error: unknown) => error instanceof Error && /not authorized for 'admin.collections.read' \(no-grant\)/.test(error.message),
  );
});

test("mutating tools refuse a denied principal through the domain's own authorization, writing nothing", async () => {
  const h = harness({ authorize: async () => ({ allowed: false, reason: "no-grant" }) });

  await assert.rejects(
    () => h.tool("collections_content_type_define").handler(ctx({ key: "recipe", label: "Recipe", fields: [] })),
    (error: unknown) => error instanceof ForbiddenError,
  );
  assert.equal(await h.repo.findByKey({ workspaceId: WORKSPACE_ID, key: "recipe" }), null);
  assert.deepEqual(h.indexCalls, []);
});

