import { describe, expect, it } from "vitest";
import { resolveGalleryEmbeds, type GalleryMediaResolver } from "../../gallery-resolver.js";
import type { PageHtmlEmbedRef } from "../../html/html-embeds.js";
import type { WidgetRenderIR } from "../../types.js";

/**
 * @file Direct branch coverage for `resolveGalleryEmbeds`: per-marker acceptance (config, key,
 * budget), the media batch it builds (legacy id vs slug refs), the media it keeps (canonical id,
 * no video/audio in a legacy gallery) and the issues it reports.
 */

function ref(id: string | null, config: Record<string, unknown>, type = "gallery"): PageHtmlEmbedRef {
  return { type, id, slug: null, name: null, variant: null, header: true, config };
}

function image(assetId: string, extra: Record<string, unknown> = {}): WidgetRenderIR {
  return { componentId: "media-image", props: { assetId, ...extra } };
}

function recordingMedia(found: ReadonlyMap<string, WidgetRenderIR> = new Map()) {
  const batches: PageHtmlEmbedRef[][] = [];
  const resolveMedia: GalleryMediaResolver = async ({ refs }) => { batches.push([...refs]); return found; };
  return { batches, resolveMedia };
}

function issues() {
  const reported: Array<{ key: string | null; messages: readonly string[] }> = [];
  return { reported, reportIssue: (issue: { key: string | null; messages: readonly string[] }) => { reported.push(issue); } };
}

const legacy = (...mediaIds: string[]) => ({ layout: "grid", images: mediaIds.map((mediaId) => ({ mediaId, alt: "" })) });
const slugs = (...slugList: string[]) => ({ mode: "media", layout: "grid", items: slugList.map((slug) => ({ slug })) });

describe("resolveGalleryEmbeds marker acceptance", () => {
  it("reports an invalid config under the marker's key and resolves nothing for it", async () => {
    const { reported, reportIssue } = issues();
    const { batches, resolveMedia } = recordingMedia();
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", { layout: "grid", images: [] })], resolveMedia }, { reportIssue });
    expect(result.size).toBe(0);
    expect(batches).toEqual([]);
    expect(reported).toEqual([{ key: "g1", messages: ["images must contain between 1 and 50 images"] }]);
  });

  it("refuses a valid marker with no occurrence key, reporting no messages", async () => {
    const { reported, reportIssue } = issues();
    const { resolveMedia } = recordingMedia();
    const result = await resolveGalleryEmbeds({ refs: [ref(null, legacy("a"))], resolveMedia }, { reportIssue });
    expect(result.size).toBe(0);
    expect(reported).toEqual([{ key: null, messages: [] }]);
  });

  it("skips an invalid marker silently when no reporter is supplied", async () => {
    const { resolveMedia } = recordingMedia();
    expect((await resolveGalleryEmbeds({ refs: [ref("g1", {})], resolveMedia })).size).toBe(0);
  });

  it("allows an empty image list only for a media-type marker", async () => {
    const { batches, resolveMedia } = recordingMedia();
    const result = await resolveGalleryEmbeds({ refs: [ref("m1", { layout: "grid", images: [] }, "media")], resolveMedia });
    expect(batches).toEqual([]);
    expect(result.get("m1")).toEqual({ componentId: "media", props: { config: { layout: "grid", images: [] }, media: {} } });
  });

  it("unwraps a placement's content config and passes the unwrapped config through", async () => {
    const { resolveMedia } = recordingMedia(new Map([["a", image("a")]]));
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", { content: legacy("a") })], resolveMedia });
    expect(result.get("g1")!.props.config).toEqual(legacy("a"));
  });

  it("skips a gallery past the media budget silently when no reporter is supplied", async () => {
    const { batches, resolveMedia } = recordingMedia();
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a", "b"))], resolveMedia }, { maxMedia: 1 });
    expect(result.size).toBe(0);
    expect(batches).toEqual([]);
  });

  it("reports a gallery past the media budget under its key", async () => {
    const { reported, reportIssue } = issues();
    const { resolveMedia } = recordingMedia();
    await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a", "b"))], resolveMedia }, { maxMedia: 1, reportIssue });
    expect(reported).toEqual([{ key: "g1", messages: ["gallery media exceeds the page budget of 1 distinct assets"] }]);
  });

  it("does not charge already-requested assets against the budget again", async () => {
    const { batches, resolveMedia } = recordingMedia();
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a")), ref("g2", legacy("a"))], resolveMedia }, { maxMedia: 1 });
    expect([...result.keys()]).toEqual(["g1", "g2"]);
    expect(batches.map((batch) => batch.length)).toEqual([1]);
  });
});

describe("resolveGalleryEmbeds media batch", () => {
  it("requests a legacy mediaId by id", async () => {
    const { batches, resolveMedia } = recordingMedia();
    await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a"))], resolveMedia });
    expect(batches).toEqual([[{ type: "media", id: "a", slug: null, name: null, variant: null, header: true }]]);
  });

  it("requests a slug item by slug", async () => {
    const { batches, resolveMedia } = recordingMedia();
    await resolveGalleryEmbeds({ refs: [ref("g1", slugs("photo"))], resolveMedia });
    expect(batches).toEqual([[{ type: "media", id: null, slug: "photo", name: null, variant: null, header: true }]]);
  });

  it("requests html-mode data-media-slug references by slug", async () => {
    const { batches, resolveMedia } = recordingMedia();
    await resolveGalleryEmbeds({ refs: [ref("g1", { mode: "html", html: '<img data-media-slug="hero">' })], resolveMedia });
    expect(batches.map((batch) => batch.map((r) => r.slug))).toEqual([["hero"]]);
  });

  it("requests no media for URL-only images", async () => {
    const { batches, resolveMedia } = recordingMedia();
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", { layout: "grid", images: [{ src: "https://example.com/x.jpg", alt: "" }] })], resolveMedia });
    expect(batches).toEqual([]);
    expect(result.get("g1")!.props.media).toEqual({});
  });

  it("reports a timed-out media batch with no key", async () => {
    const { reported, reportIssue } = issues();
    await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a"))], resolveMedia: () => new Promise(() => {}) }, { timeoutMs: 1, reportIssue });
    expect(reported).toEqual([{ key: null, messages: ["gallery media resolution timed out"] }]);
  });

  it("returns an empty map on timeout, reporting nothing without a reporter", async () => {
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a"))], resolveMedia: () => new Promise(() => {}) }, { timeoutMs: 1 });
    expect(result.size).toBe(0);
  });
});

describe("resolveGalleryEmbeds kept media", () => {
  it("keeps a legacy image resolved under its canonical id", async () => {
    const { resolveMedia } = recordingMedia(new Map([["a", image("a", { alt: "A" })]]));
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a"))], resolveMedia });
    expect(result.get("g1")).toEqual({ componentId: "gallery", props: { config: legacy("a"), media: { a: { assetId: "a", alt: "A" } } } });
  });

  it("drops a legacy id that resolved through a slug alias, silently without a reporter", async () => {
    const { resolveMedia } = recordingMedia(new Map([["alias", image("canonical")]]));
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("alias"))], resolveMedia });
    expect(result.get("g1")!.props.media).toEqual({});
  });

  it("reports a legacy id that resolved through a slug alias under that id", async () => {
    const { reported, reportIssue } = issues();
    const { resolveMedia } = recordingMedia(new Map([["alias", image("canonical")]]));
    await resolveGalleryEmbeds({ refs: [ref("g1", legacy("alias"))], resolveMedia }, { reportIssue });
    expect(reported).toEqual([{ key: "alias", messages: ["gallery mediaId must be the canonical media id, not a slug"] }]);
  });

  it("drops audio from a legacy gallery", async () => {
    const { resolveMedia } = recordingMedia(new Map([["a", image("a", { contentType: "audio/mpeg" })]]));
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a"))], resolveMedia });
    expect(result.get("g1")!.props.media).toEqual({});
  });

  it("keeps a legacy image whose content type is not a string", async () => {
    const { resolveMedia } = recordingMedia(new Map([["a", image("a", { contentType: 5 })]]));
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a"))], resolveMedia });
    expect(result.get("g1")!.props.media).toEqual({ a: { assetId: "a", contentType: 5 } });
  });

  it("keeps an image/* legacy item", async () => {
    const { resolveMedia } = recordingMedia(new Map([["a", image("a", { contentType: "image/png" })]]));
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a"))], resolveMedia });
    expect(Object.keys(result.get("g1")!.props.media as object)).toEqual(["a"]);
  });

  it("keeps slug media whatever its canonical id or content type", async () => {
    const { resolveMedia } = recordingMedia(new Map([["clip", image("clip-id", { contentType: "video/mp4" })]]));
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", slugs("clip"))], resolveMedia });
    expect(result.get("g1")!.props.media).toEqual({ clip: { assetId: "clip-id", contentType: "video/mp4" } });
  });

  it("applies slug rules to a key authored both as a legacy id and as a slug on one page", async () => {
    const { resolveMedia } = recordingMedia(new Map([["k", image("other-id")]]));
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("k")), ref("g2", slugs("k"))], resolveMedia });
    expect(result.get("g1")!.props.media).toEqual({ k: { assetId: "other-id" } });
  });

  it("shares one media record across all accepted markers", async () => {
    const { resolveMedia } = recordingMedia(new Map([["a", image("a")], ["b", image("b")]]));
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", legacy("a")), ref("g2", legacy("b"))], resolveMedia });
    expect(result.get("g1")!.props.media).toBe(result.get("g2")!.props.media);
  });

  it("reports each unresolved slug under its own key", async () => {
    const { reported, reportIssue } = issues();
    const { resolveMedia } = recordingMedia(new Map([["found", image("f")]]));
    await resolveGalleryEmbeds({ refs: [ref("g1", slugs("found", "lost"))], resolveMedia }, { reportIssue });
    expect(reported).toEqual([{ key: "lost", messages: ["unknown media slug: lost"] }]);
  });

  it("skips unresolved slugs silently without a reporter", async () => {
    const { resolveMedia } = recordingMedia();
    const result = await resolveGalleryEmbeds({ refs: [ref("g1", slugs("lost"))], resolveMedia });
    expect(result.get("g1")!.props.media).toEqual({});
  });
});

src/navigation/__tests__/menu-service.bo.source:
/**
 * Boundary and refusal paths of `menu-service.ts` that the behaviour-level suites do not reach:
 * each untrusted-input rejection with its exact message, the version-conflict wording for a create,
 * the slug-change uniqueness check, and the already-assigned location no-op.
 */
import assert from "node:assert/strict";
import { test } from "vitest";

import type { DomainEvent, OutboxPort } from "../../core/ports.js";
import {
  assignLocation,
  createMenu,
  isAllowedHref,
  MenuConflictError,
  MenuNotFoundError,
  MenuValidationError,
  MenuVersionConflictError,
  menuVersionConflictError,
  updateMenuTree,
  validateAndCloneTree,
} from "../menu-service.js";
import { InMemoryMenuRepo, InMemoryNavLocationBindingRepo } from "../repo.memory.js";
import { NAV_DOC_TYPE, type NavItemNode, type NavMenuEntry } from "../types.js";

const clock = { nowMs: () => Date.parse("2026-07-10T00:00:00.000Z") };

function fakeIdGen() {
  let counter = 0;
  return { newId: () => `id-${++counter}` };
}

function fakeOutbox(): { outbox: OutboxPort; enqueued: DomainEvent[] } {
  const enqueued: DomainEvent[] = [];
  const outbox: OutboxPort = {
    enqueue: async (event) => {
      enqueued.push(event);
    },
    claimPending: async () => [],
    markDelivered: async () => {},
    markFailed: async () => {},
  };
  return { outbox, enqueued };
}

function storedMenu(overrides: Partial<NavMenuEntry> & { id: string; slug: string }): NavMenuEntry {
  return {
    workspaceId: "ws-1",
    title: "Menu",
    status: "published",
    doc: { type: NAV_DOC_TYPE, version: 1, items: [] },
    locations: [],
    updatedAt: "2026-07-01T00:00:00.000Z",
    version: 1,
    ...overrides,
  };
}

/** A store whose slug lookup ignores case, the way a SQL adapter with a NOCASE collation would. */
class CaseInsensitiveSlugRepo extends InMemoryMenuRepo {
  override async findBySlug(required: { workspaceId: string; slug: string }): Promise<NavMenuEntry | null> {
    const rows = await this.list({ workspaceId: required.workspaceId });
    return rows.find((row) => row.slug.toLowerCase() === required.slug.toLowerCase()) ?? null;
  }
}

/** Untrusted request bodies arrive as parsed JSON, so malformed shapes are built the same way. */
function parsedItems(json: string): readonly NavItemNode[] {
  return JSON.parse(json);
}

function validationError(message: string) {
  return (error: unknown) => error instanceof MenuValidationError && error.message === message;
}

// --- menuVersionConflictError ------------------------------------------------

test("menuVersionConflictError words a create that found the id taken", () => {
  const error = menuVersionConflictError({ id: "m-1", expectedVersion: null, found: 3 });
  assert.ok(error instanceof MenuVersionConflictError);
  assert.equal(error.message, "menu 'm-1' already exists (expected no menu, found version 3)");
});

test("menuVersionConflictError reports 'none' for a create conflict whose adapter could not read the stored version", () => {
  const error = menuVersionConflictError({ id: "m-1", expectedVersion: null, found: null });
  assert.equal(error.message, "menu 'm-1' already exists (expected no menu, found version none)");
});

test("menuVersionConflictError reports 'none' when no stored version was found", () => {
  const error = menuVersionConflictError({ id: "m-1", expectedVersion: 2, found: null });
  assert.equal(error.message, "menu 'm-1' was modified concurrently (expected version 2, found none)");
});

// --- isAllowedHref -----------------------------------------------------------

test("isAllowedHref rejects a '/…' href the URL parser cannot resolve", () => {
  assert.equal(isAllowedHref({ rawHref: "//[" }), false);
});

test("isAllowedHref rejects a protocol-relative href that resolves off-origin", () => {
  assert.equal(isAllowedHref({ rawHref: "//evil.example/x" }), false);
});

// --- validateAndCloneTree ----------------------------------------------------

test("validateAndCloneTree rejects a non-array items value", () => {
  assert.throws(() => validateAndCloneTree({ items: parsedItems('{"id":"a"}') }), validationError("menu items must be an array"));
});

test("validateAndCloneTree rejects a non-array children value", () => {
  const items = parsedItems('[{"id":"a","label":"A","target":{"kind":"route","route":"home"},"children":{"id":"b"}}]');
  assert.throws(() => validateAndCloneTree({ items }), validationError("menu items must be an array"));
});

test("validateAndCloneTree rejects a tree past maxItemCount", () => {
  const items: NavItemNode[] = [
    { id: "a", label: "A", target: { kind: "url", href: "/" } },
    { id: "b", label: "B", target: { kind: "url", href: "/" } },
  ];
  assert.throws(() => validateAndCloneTree({ items }, { maxItemCount: 1 }), validationError("menu tree exceeds max item count of 1"));
});

test("validateAndCloneTree rejects a whitespace-only id", () => {
  const items: NavItemNode[] = [{ id: "  ", label: "A", target: { kind: "url", href: "/" } }];
  assert.throws(() => validateAndCloneTree({ items }), validationError("every menu item requires a non-empty id"));
});

test("validateAndCloneTree throws a TypeError, not a MenuValidationError, for a non-string id (reported, not fixed)", () => {
  // Untrusted JSON can carry a numeric id; `.trim()` on it throws an uncaught TypeError, which the
  // host surfaces as a 500 rather than the intended 400.
  const items = parsedItems('[{"id":5,"label":"A","target":{"kind":"url","href":"/"}}]');
  assert.throws(() => validateAndCloneTree({ items }), (error: unknown) => error instanceof TypeError && !(error instanceof MenuValidationError));
});

test("validateAndCloneTree rejects an unknown target kind", () => {
  const items = parsedItems('[{"id":"a","label":"A","target":{"kind":"banana"}}]');
  assert.throws(() => validateAndCloneTree({ items }), validationError("unknown target kind 'banana'"));
});

test("validateAndCloneTree rejects a url target whose href is not a string", () => {
  const items = parsedItems('[{"id":"a","label":"A","target":{"kind":"url","href":7}}]');
  assert.throws(() => validateAndCloneTree({ items }), validationError("url target requires a non-empty href"));
});

test("validateAndCloneTree reports a whitespace-only url href as missing, not as a disallowed shape", () => {
  const items: NavItemNode[] = [{ id: "a", label: "A", target: { kind: "url", href: "   " } }];
  assert.throws(() => validateAndCloneTree({ items }), validationError("url target requires a non-empty href"));
});

test("validateAndCloneTree accepts an entryRef target with an allowed lastKnownHref", () => {
  const items: NavItemNode[] = [{ id: "a", label: "A", target: { kind: "entryRef", entryId: "e-1", lastKnownHref: "/about" } }];
  assert.deepEqual(validateAndCloneTree({ items }), [{ ...items[0], children: undefined }]);
});

// --- createMenu --------------------------------------------------------------

test("createMenu rejects a blank title", async () => {
  const repo = new InMemoryMenuRepo({});
  await assert.rejects(
    createMenu({ deps: { repo, clock, idGen: fakeIdGen(), outbox: fakeOutbox().outbox }, input: { workspaceId: "ws-1", title: "   ", slug: "main" } }),
    validationError("title is required")
  );
});

test("createMenu rejects a slug with characters outside lowercase letters, numbers and dashes", async () => {
  const repo = new InMemoryMenuRepo({});
  await assert.rejects(
    createMenu({ deps: { repo, clock, idGen: fakeIdGen(), outbox: fakeOutbox().outbox }, input: { workspaceId: "ws-1", title: "Main", slug: "main_nav" } }),
    validationError("slug must use lowercase letters, numbers, and dashes")
  );
});

// --- updateMenuTree ----------------------------------------------------------

test("updateMenuTree rejects an unknown menu id", async () => {
  const repo = new InMemoryMenuRepo({});
  await assert.rejects(
    updateMenuTree({ deps: { repo, clock, idGen: fakeIdGen(), outbox: fakeOutbox().outbox }, input: { workspaceId: "ws-1", id: "missing", expectedVersion: 1 } }),
    (error: unknown) => error instanceof MenuNotFoundError && error.message === "menu 'missing' was not found"
  );
});

test("updateMenuTree rejects a slug change onto a slug another menu holds", async () => {
  const repo = new InMemoryMenuRepo({}, { initialRows: [storedMenu({ id: "m-1", slug: "main" }), storedMenu({ id: "m-2", slug: "footer" })] });
  await assert.rejects(
    updateMenuTree({ deps: { repo, clock, idGen: fakeIdGen(), outbox: fakeOutbox().outbox }, input: { workspaceId: "ws-1", id: "m-1", expectedVersion: 1, slug: "footer" } }),
    (error: unknown) => error instanceof MenuConflictError && !(error instanceof MenuVersionConflictError) && error.message === "slug 'footer' already exists"
  );
});

test("updateMenuTree accepts a slug change onto a free slug", async () => {
  const repo = new InMemoryMenuRepo({}, { initialRows: [storedMenu({ id: "m-1", slug: "main" })] });
  const { menu } = await updateMenuTree({ deps: { repo, clock, idGen: fakeIdGen(), outbox: fakeOutbox().outbox }, input: { workspaceId: "ws-1", id: "m-1", expectedVersion: 1, slug: "Primary" } });
  assert.equal(menu.slug, "primary");
});

test("updateMenuTree does not treat the menu's own row as a slug conflict when the store matches slugs case-insensitively", async () => {
  // A legacy row stored with an uppercase slug normalizes to a different string, and a NOCASE store
  // then returns the same menu for the lookup.
  const repo = new CaseInsensitiveSlugRepo({}, { initialRows: [storedMenu({ id: "m-1", slug: "Main" })] });
  const { menu } = await updateMenuTree({ deps: { repo, clock, idGen: fakeIdGen(), outbox: fakeOutbox().outbox }, input: { workspaceId: "ws-1", id: "m-1", expectedVersion: 1 } });
  assert.equal(menu.slug, "main");
});

// --- assignLocation ----------------------------------------------------------

test("assignLocation rejects an unknown menu id", async () => {
  const repo = new InMemoryMenuRepo({});
  const bindingRepo = new InMemoryNavLocationBindingRepo({});
  await assert.rejects(
    assignLocation({ deps: { repo, bindingRepo, clock, idGen: fakeIdGen(), outbox: fakeOutbox().outbox }, input: { workspaceId: "ws-1", menuId: "missing", locationKey: "header" } }),
    (error: unknown) => error instanceof MenuNotFoundError && error.message === "menu 'missing' was not found"
  );
});

test("assignLocation keeps a location key the menu already holds without duplicating it", async () => {
  const repo = new InMemoryMenuRepo({}, { initialRows: [storedMenu({ id: "m-1", slug: "main", locations: ["header"] })] });
  const bindingRepo = new InMemoryNavLocationBindingRepo({});
  const { menu } = await assignLocation({ deps: { repo, bindingRepo, clock, idGen: fakeIdGen(), outbox: fakeOutbox().outbox }, input: { workspaceId: "ws-1", menuId: "m-1", locationKey: "header" } });
  assert.deepEqual(menu.locations, ["header"]);
  assert.equal(menu.version, 2);
});

