import assert from "node:assert/strict";
import { test } from "./support/node-test.fixture.js";

import { InMemoryEventBus } from "./support/switch-bindings.fixture.js";
import type { DomainEvent } from "../../core/index.js";
import type { MailerPort, MailerSendOptions, MailerSendResult, OutboundEmail } from "./support/switch-bindings.fixture.js";
import { registerFormNotifySubscriber } from "./support/switch-bindings.fixture.js";
import { InMemoryFormDefinitionRepo, InMemoryFormSubmissionRepo } from "../repo.memory.js";
import type { FormDefinitionRecord, FormSubmissionRecord } from "../index.js";

/**
 * @file Unit tests for `registerFormNotifySubscriber` (C-009, REQ-12, AC-17/18, EC-06).
 * Notify-enabled definition -> MailerPort.send() invoked per recipient with an idempotencyKey
 * built from submissionId; notify-disabled -> never invoked; a SUPPRESSED mailer result is
 * logged, not thrown.
 */

const NOW = "2026-07-13T00:00:00.000Z";
const WORKSPACE_ID = "ws-1";

class RecordingMailer implements MailerPort {
  readonly calls: Array<{ message: OutboundEmail; opts: MailerSendOptions }> = [];
  result: MailerSendResult = { ok: true, providerMessageId: "msg-1", acceptedAt: NOW };

  capabilities() {
    return { driver: "recording", supportsIdempotencyKey: true, supportsWebhookFeedback: false, maxBatchSize: 1, supportsAttachments: false };
  }
  async send(message: OutboundEmail, opts: MailerSendOptions): Promise<MailerSendResult> {
    this.calls.push({ message, opts });
    return this.result;
  }
  async sendBatch(messages: readonly OutboundEmail[], opts: MailerSendOptions) {
    const results: MailerSendResult[] = [];
    for (const m of messages) results.push(await this.send(m, opts));
    return results;
  }
}

function makeDefinition(overrides: Partial<FormDefinitionRecord> = {}): FormDefinitionRecord {
  return {
    id: "def-1",
    workspaceId: WORKSPACE_ID,
    name: "Contact",
    slug: "contact",
    fields: [{ id: "name", label: "Name", type: "text", required: true }],
    notify: { enabled: false, recipients: [] },
    version: 1,
    status: "active",
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

function makeSubmission(overrides: Partial<FormSubmissionRecord> = {}): FormSubmissionRecord {
  return {
    id: "sub-1",
    workspaceId: WORKSPACE_ID,
    formDefinitionId: "def-1",
    data: { name: "Ada" },
    sourceIp: "127.0.0.1",
    submittedAt: NOW,
    ...overrides,
  };
}

function publishSubmissionEvent(bus: InMemoryEventBus, submissionId: string, formDefinitionId = "def-1") {
  const event: DomainEvent<{ workspaceId: string; formDefinitionId: string; submissionId: string }> = {
    id: `evt-${submissionId}`,
    name: "form.submission.received",
    occurredAt: NOW,
    workspaceId: WORKSPACE_ID,
    payload: { workspaceId: WORKSPACE_ID, formDefinitionId, submissionId },
  };
  return bus.publish(event);
}

test("registerFormNotifySubscriber: AC-17 — invokes MailerPort.send() for a notify-enabled definition with an idempotencyKey built from submissionId", async () => {
  const bus = new InMemoryEventBus();
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const mailer = new RecordingMailer();

  await definitionRepo.create(
    makeDefinition({ notify: { enabled: true, recipients: ["ops@example.com"] } })
  );
  await submissionRepo.create(makeSubmission());

  await registerFormNotifySubscriber({ bus, mailer, formDefinitionRepo: definitionRepo, formSubmissionRepo: submissionRepo });
  await publishSubmissionEvent(bus, "sub-1");

  assert.equal(mailer.calls.length, 1);
  assert.ok(mailer.calls[0]);
  assert.equal(mailer.calls[0].message.to.email, "ops@example.com");
  assert.ok(mailer.calls[0].opts.idempotencyKey.includes("sub-1"));
  assert.deepEqual(mailer.calls[0].message, {
    workspaceId: WORKSPACE_ID, to: { email: "ops@example.com" }, from: { email: "no-reply@forms.local", name: "Forms" },
    subject: "New submission: Contact", text: JSON.stringify({ name: "Ada" }),
  });
  assert.deepEqual(mailer.calls[0].opts, { idempotencyKey: "forms:notify:sub-1:ops@example.com", workspaceId: WORKSPACE_ID, sourceContext: { module: "forms", ref: "def-1" }, purpose: "transactional", lane: "notification" });
});

test("registerFormNotifySubscriber: AC-18 — never invokes MailerPort.send() when notify is disabled", async () => {
  const bus = new InMemoryEventBus();
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const mailer = new RecordingMailer();

  await definitionRepo.create(makeDefinition({ notify: { enabled: false, recipients: ["ops@example.com"] } }));
  await submissionRepo.create(makeSubmission());

  await registerFormNotifySubscriber({ bus, mailer, formDefinitionRepo: definitionRepo, formSubmissionRepo: submissionRepo });
  await publishSubmissionEvent(bus, "sub-1");

  assert.equal(mailer.calls.length, 0);
});

test("registerFormNotifySubscriber: invokes send() once per configured recipient", async () => {
  const bus = new InMemoryEventBus();
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const mailer = new RecordingMailer();

  await definitionRepo.create(
    makeDefinition({ notify: { enabled: true, recipients: ["a@example.com", "b@example.com"] } })
  );
  await submissionRepo.create(makeSubmission());

  await registerFormNotifySubscriber({ bus, mailer, formDefinitionRepo: definitionRepo, formSubmissionRepo: submissionRepo });
  await publishSubmissionEvent(bus, "sub-1");

  assert.equal(mailer.calls.length, 2);
  assert.deepEqual(
    mailer.calls.map((c) => c.message.to.email).sort(),
    ["a@example.com", "b@example.com"]
  );
  assert.deepEqual(mailer.calls.map((call) => call.opts.idempotencyKey).sort(), ["forms:notify:sub-1:a@example.com", "forms:notify:sub-1:b@example.com"]);
  await publishSubmissionEvent(bus, "sub-1");
  assert.equal(mailer.calls.length, 4);
  assert.deepEqual(mailer.calls.slice(2).map((call) => call.opts.idempotencyKey), mailer.calls.slice(0, 2).map((call) => call.opts.idempotencyKey));
});

test("registerFormNotifySubscriber: EC-06 — a SUPPRESSED mailer result is logged, not thrown, and does not crash the subscriber", async () => {
  const bus = new InMemoryEventBus();
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const mailer = new RecordingMailer();
  mailer.result = { ok: false, retryable: false, errorCode: "SUPPRESSED", message: "recipient suppressed" };

  await definitionRepo.create(
    makeDefinition({ notify: { enabled: true, recipients: ["ops@example.com"] } })
  );
  await submissionRepo.create(makeSubmission());

  await registerFormNotifySubscriber({ bus, mailer, formDefinitionRepo: definitionRepo, formSubmissionRepo: submissionRepo });
  // Should not throw / reject.
  await assert.doesNotReject(() => publishSubmissionEvent(bus, "sub-1"));
  assert.equal(mailer.calls.length, 1);
});

// REGRESSION: fails if the default logger reads error from argument one instead of argument two.
test("registerFormNotifySubscriber: a throwing MailerPort.send() is caught, logged with its cause, never propagated into the bus", async (t) => {
  const bus = new InMemoryEventBus();
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const mailer = new RecordingMailer();
  const failure = new Error("provider is down");
  const warnings: unknown[][] = [];
  t.mock.method(console, "warn", (...args: unknown[]) => { warnings.push(args); });
  mailer.send = async () => {
    throw failure;
  };

  await definitionRepo.create(
    makeDefinition({ notify: { enabled: true, recipients: ["ops@example.com"] } })
  );
  await submissionRepo.create(makeSubmission());

  await registerFormNotifySubscriber({ bus, mailer, formDefinitionRepo: definitionRepo, formSubmissionRepo: submissionRepo });
  await assert.doesNotReject(() => publishSubmissionEvent(bus, "sub-1"));
  assert.equal(warnings.length, 1);
  assert.ok(warnings[0]);
  assert.match(String(warnings[0][0]), /mail send threw/);
  assert.equal(warnings[0][1], failure);
});

for (const scenario of ["missing definition", "missing submission", "empty recipients", "definition read fails", "submission read fails"] as const) {
  test(`registerFormNotifySubscriber: ${scenario} sends nothing and preserves sibling delivery`, async (t) => {
    const bus = new InMemoryEventBus();
    const definitionRepo = new InMemoryFormDefinitionRepo();
    const submissionRepo = new InMemoryFormSubmissionRepo();
    const mailer = new RecordingMailer();
    if (scenario !== "missing definition") await definitionRepo.create(makeDefinition({ notify: { enabled: true, recipients: scenario === "empty recipients" ? [] : ["ops@example.com"] } }));
    if (scenario !== "missing submission") await submissionRepo.create(makeSubmission());
    if (scenario === "definition read fails") t.mock.method(definitionRepo, "findById", async () => { throw new Error("definition read failed"); });
    if (scenario === "submission read fails") t.mock.method(submissionRepo, "findById", async () => { throw new Error("submission read failed"); });
    await registerFormNotifySubscriber({ bus, mailer, formDefinitionRepo: definitionRepo, formSubmissionRepo: submissionRepo });
    let siblingCalls = 0;
    await bus.subscribe({ eventName: "form.submission.received", handler: async () => { siblingCalls++; } });
    await assert.doesNotReject(() => publishSubmissionEvent(bus, "sub-1"));
    assert.equal(mailer.calls.length, 0);
    assert.equal(siblingCalls, 1);
  });
}

test("registerFormNotifySubscriber: unsubscribe stops later sends while sibling subscribers remain active", async () => {
  const bus = new InMemoryEventBus();
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const mailer = new RecordingMailer();
  await definitionRepo.create(makeDefinition({ notify: { enabled: true, recipients: ["ops@example.com"] } }));
  await submissionRepo.create(makeSubmission());
  const unsubscribe = await registerFormNotifySubscriber({ bus, mailer, formDefinitionRepo: definitionRepo, formSubmissionRepo: submissionRepo });
  let siblingCalls = 0;
  await bus.subscribe({ eventName: "form.submission.received", handler: async () => { siblingCalls++; } });
  await publishSubmissionEvent(bus, "sub-1");
  assert.equal(mailer.calls.length, 1);
  await unsubscribe();
  await publishSubmissionEvent(bus, "sub-1");
  assert.equal(mailer.calls.length, 1);
  assert.equal(siblingCalls, 2);
});

src/media/__tests__/content-type-sniffer.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { sniffContentType } from "../content-type-sniffer.js";

/**
 * @file Unit tests for `content-type-sniffer.ts`'s magic-byte allowlist. Every format named in the
 * task brief is covered directly, plus the security-critical negative cases: a sniffed HTML/SVG
 * result (the stored-XSS vector a serving route must defuse), and the safe fallback for anything
 * else — including inputs crafted to almost-but-not-quite match a signature, and inputs too short
 * to hold one at all (must not throw).
 */

function bytesOf(values: number[]): Uint8Array {
  return new Uint8Array(values);
}

function textBytes(text: string): Uint8Array {
  return new TextEncoder().encode(text);
}

test("sniffContentType: recognizes PNG by its 8-byte signature", () => {
  const bytes = bytesOf([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 1, 2, 3]);
  assert.equal(sniffContentType({ bytes: bytes }), "image/png");
});

test("sniffContentType: recognizes JPEG by its FF D8 FF prefix", () => {
  const bytes = bytesOf([0xff, 0xd8, 0xff, 0xe0, 0, 0, 1, 2]);
  assert.equal(sniffContentType({ bytes: bytes }), "image/jpeg");
});

test("sniffContentType: recognizes GIF87a and GIF89a", () => {
  assert.equal(sniffContentType({ bytes: textBytes("GIF87a" + "rest-of-file") }), "image/gif");
  assert.equal(sniffContentType({ bytes: textBytes("GIF89a" + "rest-of-file") }), "image/gif");
});

test("sniffContentType: recognizes WebP (RIFF____WEBP)", () => {
  const bytes = new Uint8Array(16);
  bytes.set(textBytes("RIFF"), 0);
  bytes.set(bytesOf([0x24, 0, 0, 0]), 4); // chunk size — arbitrary, not checked
  bytes.set(textBytes("WEBP"), 8);
  assert.equal(sniffContentType({ bytes: bytes }), "image/webp");
});

test("sniffContentType: distinguishes WAV from WebP in the shared RIFF container", () => {
  const bytes = new Uint8Array(16);
  bytes.set(textBytes("RIFF"), 0);
  bytes.set(bytesOf([0x24, 0, 0, 0]), 4);
  bytes.set(textBytes("WAVE"), 8); // a .wav file, not .webp
  assert.equal(sniffContentType({ bytes: bytes }), "audio/wav");
});

test("sniffContentType: recognizes MP4/ISO-BMFF by the ftyp box at offset 4", () => {
  const bytes = new Uint8Array(16);
  bytes.set(bytesOf([0, 0, 0, 0x18]), 0); // box size — arbitrary, not checked
  bytes.set(textBytes("ftyp"), 4);
  bytes.set(textBytes("isom"), 8); // major brand
  assert.equal(sniffContentType({ bytes: bytes }), "video/mp4");
});

test("sniffContentType: recognizes WebM by its EBML header", () => {
  const bytes = bytesOf([0x1a, 0x45, 0xdf, 0xa3, 1, 2, 3, 4]);
  assert.equal(sniffContentType({ bytes: bytes }), "video/webm");
});

test("sniffContentType: an HTML document declared as an upload's contentType is still sniffed as text/html from its real bytes", () => {
  const bytes = textBytes("<!DOCTYPE html><html><head><script>alert(document.cookie)</script></head></html>");
  assert.equal(sniffContentType({ bytes: bytes }), "text/html");
});

test("sniffContentType: a bare <html> root without a doctype is still sniffed as text/html", () => {
  assert.equal(sniffContentType({ bytes: textBytes("<html><body>hi</body></html>") }), "text/html");
});

test("sniffContentType: an XHTML document (XML prolog + <html) is sniffed as text/html", () => {
  const bytes = textBytes('<?xml version="1.0" encoding="UTF-8"?><html xmlns="http://www.w3.org/1999/xhtml"></html>');
  assert.equal(sniffContentType({ bytes: bytes }), "text/html");
});

test("sniffContentType: an SVG document is sniffed as image/svg+xml, not image/png, regardless of upload-time claims", () => {
  const bytes = textBytes('<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>');
  assert.equal(sniffContentType({ bytes: bytes }), "image/svg+xml");
});

test("sniffContentType: an SVG with an XML prolog is still sniffed as image/svg+xml", () => {
  const bytes = textBytes('<?xml version="1.0" standalone="no"?>\n<svg xmlns="http://www.w3.org/2000/svg"></svg>');
  assert.equal(sniffContentType({ bytes: bytes }), "image/svg+xml");
});

test("sniffContentType: a leading UTF-8 BOM and whitespace do not defeat HTML/SVG detection", () => {
  const withBom = new Uint8Array([0xef, 0xbb, 0xbf, ...textBytes("  \n<html><body/></html>")]);
  assert.equal(sniffContentType({ bytes: withBom }), "text/html");
});

test("sniffContentType: falls back to application/octet-stream for genuinely unknown bytes", () => {
  assert.equal(sniffContentType({ bytes: bytesOf([1, 2, 3, 4, 5, 6, 7, 8]) }), "application/octet-stream");
  assert.equal(sniffContentType({ bytes: textBytes("just some plain text, not markup") }), "application/octet-stream");
});

test("sniffContentType: near-miss signatures (one byte off) do not falsely match", () => {
  // PNG signature with the last byte flipped.
  assert.equal(sniffContentType({ bytes: bytesOf([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0xff]) }), "application/octet-stream");
  // "GIF88a" is not a real GIF version string.
  assert.equal(sniffContentType({ bytes: textBytes("GIF88a") }), "application/octet-stream");
});

test("sniffContentType: inputs shorter than a signature never throw, and are treated as unrecognized", () => {
  assert.equal(sniffContentType({ bytes: bytesOf([]) }), "application/octet-stream");
  assert.equal(sniffContentType({ bytes: bytesOf([0x89, 0x50]) }), "application/octet-stream");
  assert.equal(sniffContentType({ bytes: bytesOf([0xff, 0xd8]) }), "application/octet-stream");
});

/**
 * Builds an ISO-BMFF `ftyp` box: a 4-byte big-endian box size, the literal `ftyp` tag, a 4-byte
 * major brand, a 4-byte minor version, then one 4-byte entry per compatible brand. The declared
 * size is computed from the actual content so the box is self-consistent — the sniffer bounds its
 * compatible-brand scan by that field, so a fixture that lied about its size would not exercise
 * the real scan.
 */
function ftypBytes(majorBrand: string, compatibleBrands: readonly string[]): Uint8Array {
  const boxLength = 16 + compatibleBrands.length * 4;
  const bytes = new Uint8Array(boxLength + 8); // + trailing non-ftyp payload, as a real file has
  bytes.set([(boxLength >> 24) & 0xff, (boxLength >> 16) & 0xff, (boxLength >> 8) & 0xff, boxLength & 0xff], 0);
  bytes.set(textBytes("ftyp"), 4);
  bytes.set(textBytes(majorBrand), 8);
  compatibleBrands.forEach((brand, index) => bytes.set(textBytes(brand), 16 + index * 4));
  return bytes;
}

/**
 * Regression (2026-09-06): AVIF is an ISO-BMFF container, so its leading `ftyp` box matched the
 * MP4 check — which tests ONLY for the `ftyp` tag and never reads the brand — and every real
 * `.avif` upload was sniffed as `video/mp4`. Because the sniffed type is persisted as the
 * image-vs-video source of truth (the host's `routes/media/upload.ts` writes it to
 * `mediaContentTypeStore`), that mislabel made an AVIF render as an unplayable `<video>` on a
 * public page. These bytes are the real leading box of a genuine AVIF file.
 */
test("sniffContentType: a real AVIF ftyp box is image/avif, NOT video/mp4", () => {
  const bytes = new Uint8Array([
    0x00, 0x00, 0x00, 0x18, 0x66, 0x74, 0x79, 0x70, 0x61, 0x76, 0x69, 0x66, 0x00, 0x00, 0x00, 0x00,
    0x6d, 0x69, 0x66, 0x31, 0x6d, 0x69, 0x61, 0x66, 0x00, 0x00, 0x01, 0x68, 0x6d, 0x65, 0x74, 0x61,
  ]);
  assert.equal(sniffContentType({ bytes: bytes }), "image/avif");
});

test("sniffContentType: an AVIF whose MAJOR brand is mif1 is still image/avif via its compatible brands", () => {
  assert.equal(sniffContentType({ bytes: ftypBytes("mif1", ["mif1", "avif"]) }), "image/avif");
});

test("sniffContentType: an AVIF image sequence (avis brand) is image/avif", () => {
  assert.equal(sniffContentType({ bytes: ftypBytes("avis", ["avis", "avif"]) }), "image/avif");
});

test("sniffContentType: a real MP4 is still video/mp4 — the AVIF check must not swallow ISO-BMFF video", () => {
  assert.equal(sniffContentType({ bytes: ftypBytes("isom", ["isom", "mp41"]) }), "video/mp4");
  assert.equal(sniffContentType({ bytes: ftypBytes("mp42", []) }), "video/mp4");
});

/**
 * HEIC is also ISO-BMFF but declares no AVIF brand, so it must NOT be claimed as `image/avif`:
 * the installed `sharp`/libvips build decodes AVIF but not HEIC, so labelling a HEIC as an image
 * would route it into a transform pipeline that cannot decode it. It therefore keeps falling
 * through to the brand-blind MP4 check and is still reported as `video/mp4` — a KNOWN, pre-existing
 * misclassification this change deliberately does not fix (see the handoff's format audit). Pinned
 * exactly rather than loosely so a future HEIC fix has to update this line consciously.
 */
test("sniffContentType: HEIC is not claimed as AVIF (its own mislabel as video/mp4 is a pinned, pre-existing gap)", () => {
  const heic = ftypBytes("heic", ["mif1", "heic"]);
  assert.notEqual(sniffContentType({ bytes: heic }), "image/avif");
  assert.equal(sniffContentType({ bytes: heic }), "video/mp4");
});

test("sniffContentType: an ftyp box truncated mid-brand never throws and stays video/mp4", () => {
  assert.equal(sniffContentType({ bytes: bytesOf([0, 0, 0, 0x18, 0x66, 0x74, 0x79, 0x70, 0x61, 0x76]) }), "video/mp4");
});


test("mediawidget audio: identifies positive audio signatures and rejects invalid MPEG headers", () => {
  assert.equal(sniffContentType({ bytes: textBytes("ID3audio") }), "audio/mpeg");
  assert.equal(sniffContentType({ bytes: bytesOf([0xff, 0xfb, 0x90, 0]) }), "audio/mpeg");
  assert.equal(sniffContentType({ bytes: bytesOf([0xff, 0xfb, 0xfc, 0]) }), "application/octet-stream");
  assert.equal(sniffContentType({ bytes: textBytes("fLaCaudio") }), "audio/flac");
  const m4a = new Uint8Array(16); m4a.set(textBytes("ftypM4A "), 4);
  assert.equal(sniffContentType({ bytes: m4a }), "audio/mp4");
});

test("sniffContentType: scans at most sixteen compatible brands, so a late avif brand stays video/mp4", () => {
  const brands = [...Array(16).fill("mp42"), "avif"].join("");
  const size = 16 + brands.length;
  const ftyp = Buffer.concat([Buffer.from([0, 0, 0, size]), Buffer.from("ftypisom"), Buffer.alloc(4), Buffer.from(brands)]);
  assert.equal(sniffContentType({ bytes: ftyp }), "video/mp4");
  assert.equal(sniffContentType({ bytes: Buffer.concat([ftyp.subarray(0, 16), Buffer.from("avif"), ftyp.subarray(20)]) }), "image/avif");
});

test("sniffContentType: untagged MPEG audio with a reserved sample-rate index is not audio", () => {
  assert.equal(sniffContentType({ bytes: Buffer.from([0xff, 0xfb, 0x90, 0x00]) }), "audio/mpeg");
  assert.equal(sniffContentType({ bytes: Buffer.from([0xff, 0xfb, 0x9c, 0x00]) }), "application/octet-stream");
});

