import assert from "node:assert/strict";
import { test } from "vitest";

import { ToolInputError, ToolPermissionDeniedError, type ToolExecutionContext, type ToolRegistration } from "@jini-ai/core";

import type { AuthorizeFn } from "../../core/commands/command.js";
import { getWorkspaceAgentToolCatalog } from "../agent-tools.js";
import { WorkspaceConflictError, WorkspaceValidationError, type WorkspaceRecord } from "../create.js";
import * as workspaceBarrel from "../index.js";
import { InMemoryWorkspaceRepo } from "../repo.memory.js";
import { buildWorkspaceRegistrations, workspaceDerivedRisk, type WorkspaceToolDeps } from "../tool-registrations.js";

/**
 * @file Agent-tool surface of the Workspace domain: the catalog (`agent-tools.ts`), the wiring
 * (`tool-registrations.ts`) and the barrel (`index.ts`). The highest-stakes property here is the
 * exclusion of `workspace_create`/`workspace_delete` — an agent must never see or call them.
 */

const WORKSPACE_ID = "ws-boot-wired";
const PRINCIPAL_ID = "principal-under-test";
const SEED: WorkspaceRecord = { id: WORKSPACE_ID, name: "Main Site", slug: "main-site", createdAt: "2026-01-01T00:00:00.000Z" };
const OTHER: WorkspaceRecord = { id: "ws-other", name: "Other", slug: "taken", createdAt: "2026-01-02T00:00:00.000Z" };

type AuthorizeCall = Parameters<AuthorizeFn>[0];

function executionContext(input: unknown): ToolExecutionContext {
  return { executionId: "exec-1", principal: { id: PRINCIPAL_ID }, run: { id: "run-1" }, input, signal: new AbortController().signal } as ToolExecutionContext;
}

/** Hand-written deps: a real in-memory repo plus an authorize fake that records each request. */
function fakeDeps({ allowed = true, rows = [SEED, OTHER] }: { allowed?: boolean; rows?: WorkspaceRecord[] } = {}): {
  deps: WorkspaceToolDeps;
  repo: InMemoryWorkspaceRepo;
  calls: AuthorizeCall[];
} {
  const calls: AuthorizeCall[] = [];
  const repo = new InMemoryWorkspaceRepo({}, { initialRows: rows });
  const authorize: AuthorizeFn = async (request) => {
    calls.push(request);
    return allowed ? { allowed: true, reason: "matched" } : { allowed: false, reason: "no grant" };
  };
  return { deps: { authorize, workspaceId: WORKSPACE_ID, workspaceRepo: repo }, repo, calls };
}

function registrationFor({ deps, toolId }: { deps: WorkspaceToolDeps; toolId: string }): ToolRegistration {
  const registration = buildWorkspaceRegistrations(deps).find((candidate) => candidate.descriptor.id === toolId);
  assert.ok(registration, `${toolId} must be wired`);
  return registration;
}

test("the catalog declares get/update with schemas and create/delete as schema-less, excluded entries", () => {
  const catalog = getWorkspaceAgentToolCatalog();
  assert.deepEqual(catalog.map((entry) => [entry.name, entry.sideEffects, entry.authorization]), [
    ["workspace_get", "none", { permission: "workspace.manage" }],
    ["workspace_update", "mutates-durable-state", { permission: "workspace.manage" }],
    ["workspace_create", "mutates-durable-state", { permission: "workspace.manage" }],
    ["workspace_delete", "mutates-durable-state", { permission: "workspace.manage" }],
  ]);
  const byName = new Map(catalog.map((entry) => [entry.name, entry]));
  assert.deepEqual(byName.get("workspace_get")?.inputSchema, { type: "object", additionalProperties: false, required: [], properties: {} });
  assert.deepEqual(Object.keys(byName.get("workspace_update")?.inputSchema?.["properties"] as object), ["name", "slug"]);
  assert.equal(byName.get("workspace_create")?.inputSchema, undefined);
  assert.equal(byName.get("workspace_delete")?.inputSchema, undefined);
  assert.notEqual(getWorkspaceAgentToolCatalog(), catalog, "each call returns a fresh array a caller may not mutate shared state through");
});

test("only the read and the rename are wired; create and delete never become registrations", () => {
  const { deps } = fakeDeps();
  const registrations = buildWorkspaceRegistrations(deps);
  assert.deepEqual(registrations.map((r) => [r.descriptor.id, r.descriptor.readOnly]), [
    ["workspace_get", true],
    ["workspace_update", false],
  ]);
  assert.deepEqual([...workspaceDerivedRisk.entries()], [
    ["workspace_get", "none"],
    ["workspace_update", "mutates-durable-state"],
  ]);
});

test("workspace_get returns the boot-wired workspace after a workspace.manage check scoped to the workspace entity", async () => {
  const { deps, calls } = fakeDeps();
  const get = registrationFor({ deps, toolId: "workspace_get" });

  assert.deepEqual(await get.handler(executionContext(undefined)), { workspace: SEED });
  assert.deepEqual(await get.handler(executionContext({})), { workspace: SEED });
  assert.deepEqual(calls[0], { principalId: PRINCIPAL_ID, permission: "workspace.manage", workspaceId: WORKSPACE_ID, entityType: "workspace" });
  assert.equal(calls.length, 2);
});

test("workspace_get refuses any input before consulting authorization", async () => {
  const { deps, calls } = fakeDeps();
  const get = registrationFor({ deps, toolId: "workspace_get" });
  await assert.rejects(() => get.handler(executionContext({ id: "ws-other" })), ToolInputError);
  assert.equal(calls.length, 0);
});

test("workspace_get surfaces a denial as ToolPermissionDeniedError without reading the row", async () => {
  const { deps, repo } = fakeDeps({ allowed: false });
  let reads = 0;
  const findById = repo.findById.bind(repo);
  repo.findById = async (required) => { reads += 1; return findById(required); };
  const get = registrationFor({ deps, toolId: "workspace_get" });
  await assert.rejects(() => get.handler(executionContext({})), (error: unknown) => {
    assert.ok(error instanceof ToolPermissionDeniedError);
    assert.match(error.message, /not authorized for 'workspace\.manage' \(no grant\)/);
    return true;
  });
  assert.equal(reads, 0);
});

test("workspace_get fails loudly when the boot-wired workspace row is missing", async () => {
  const { deps } = fakeDeps({ rows: [OTHER] });
  const get = registrationFor({ deps, toolId: "workspace_get" });
  await assert.rejects(() => get.handler(executionContext({})), { message: `workspace '${WORKSPACE_ID}' was not found` });
});

test("workspace_update renames only the boot-wired workspace and persists the normalized values", async () => {
  const { deps, repo, calls } = fakeDeps();
  const update = registrationFor({ deps, toolId: "workspace_update" });

  const result = await update.handler(executionContext({ name: "  Renamed  ", slug: "Renamed-Site" }));
  const expected = { ...SEED, name: "Renamed", slug: "renamed-site" };
  assert.deepEqual(result, { workspace: expected });
  assert.deepEqual(await repo.findById({ id: WORKSPACE_ID }), expected);
  assert.deepEqual(await repo.findById({ id: OTHER.id }), OTHER, "the other row is untouched");
  assert.deepEqual(calls, [{ principalId: PRINCIPAL_ID, permission: "workspace.manage", workspaceId: WORKSPACE_ID, entityType: "workspace" }]);
});

test("workspace_update accepts a slug-only change and keeps the existing name", async () => {
  const { deps } = fakeDeps();
  const update = registrationFor({ deps, toolId: "workspace_update" });
  assert.deepEqual(await update.handler(executionContext({ slug: "fresh" })), { workspace: { ...SEED, slug: "fresh" } });
});

test("workspace_update propagates typed domain errors for empty, invalid and conflicting updates", async () => {
  const { deps, repo } = fakeDeps();
  const update = registrationFor({ deps, toolId: "workspace_update" });
  await assert.rejects(() => update.handler(executionContext({})), WorkspaceValidationError);
  await assert.rejects(() => update.handler(executionContext({ slug: "bad slug" })), WorkspaceValidationError);
  await assert.rejects(() => update.handler(executionContext({ slug: OTHER.slug })), WorkspaceConflictError);
  assert.deepEqual(await repo.findById({ id: WORKSPACE_ID }), SEED);
});

test("workspace_update rejects non-object input and non-string fields before authorizing", async () => {
  const { deps, calls } = fakeDeps();
  const update = registrationFor({ deps, toolId: "workspace_update" });
  await assert.rejects(() => update.handler(executionContext("rename")), ToolInputError);
  assert.equal(calls.length, 0);
  await assert.rejects(() => update.handler(executionContext({ name: 42 })), { message: "'name' must be a string" });
});

test("workspace_update denied by authorization leaves the row unchanged", async () => {
  const { deps, repo } = fakeDeps({ allowed: false });
  const update = registrationFor({ deps, toolId: "workspace_update" });
  await assert.rejects(() => update.handler(executionContext({ name: "Hijacked" })), ToolPermissionDeniedError);
  assert.deepEqual(await repo.findById({ id: WORKSPACE_ID }), SEED);
});

test("the barrel publishes the domain's functions, errors and adapters as the same bindings", async () => {
  const create = await import("../create.js");
  const update = await import("../update.js");
  const remove = await import("../delete.js");
  assert.equal(workspaceBarrel.createWorkspace, create.createWorkspace);
  assert.equal(workspaceBarrel.validateWorkspaceNameAndSlug, create.validateWorkspaceNameAndSlug);
  assert.equal(workspaceBarrel.WorkspaceConflictError, create.WorkspaceConflictError);
  assert.equal(workspaceBarrel.WorkspaceLastRemainingError, create.WorkspaceLastRemainingError);
  assert.equal(workspaceBarrel.WorkspaceNotFoundError, create.WorkspaceNotFoundError);
  assert.equal(workspaceBarrel.WorkspaceValidationError, create.WorkspaceValidationError);
  assert.equal(workspaceBarrel.updateWorkspace, update.updateWorkspace);
  assert.equal(workspaceBarrel.deleteWorkspace, remove.deleteWorkspace);
  assert.equal(workspaceBarrel.InMemoryWorkspaceRepo, InMemoryWorkspaceRepo);
  assert.equal(workspaceBarrel.getWorkspaceAgentToolCatalog, getWorkspaceAgentToolCatalog);
  assert.equal(workspaceBarrel.buildWorkspaceRegistrations, buildWorkspaceRegistrations);
  assert.equal(workspaceBarrel.workspaceDerivedRisk, workspaceDerivedRisk);
  assert.equal("SqliteWorkspaceRepo" in workspaceBarrel, false, "no host-schema adapter on the public contract");
});

src/media/__tests__/html-attributes.test.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import {
  describeMediaHtmlAttributeError,
  isAllowedMediaHtmlAttributeName,
  parseMediaHtmlAttributes,
} from "../html-attributes.js";

/**
 * @file `html-attributes.ts`'s allowlist — the server-side (Node) copy of the identical validator
 * the consuming product's admin carries in `apps/admin/src/features/media/rules.ts`. See that file's header and this
 * one's for why the two copies are deliberately duplicated rather than shared through one import.
 *
 * Ported verbatim from the admin copy's own test suite
 * (`apps/admin/src/features/media/__tests__/media-html-attributes.unit.test.tsx`) so both copies are
 * proven against the identical adversarial cases — mixed valid+invalid tokens, case variation, quote
 * styles, boolean attributes, malformed fragments. A validator whose whole job is refusing input has
 * not been tested at all if only the happy path is covered.
 */

test("isAllowedMediaHtmlAttributeName: allows the data- prefix family regardless of suffix", () => {
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "data-motion" }), true);
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "data-anything-at-all" }), true);
});

test("isAllowedMediaHtmlAttributeName: allows the aria- prefix family regardless of suffix", () => {
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "aria-hidden" }), true);
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "aria-label" }), true);
});

test("isAllowedMediaHtmlAttributeName: allows every exact-match name on the fixed list", () => {
  for (const name of ["loading", "decoding", "playsinline", "muted", "loop", "autoplay", "poster"]) {
    assert.equal(isAllowedMediaHtmlAttributeName({ name: name }), true);
  }
});

test("isAllowedMediaHtmlAttributeName: is case-insensitive in both directions", () => {
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "DATA-FOO" }), true);
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "ARIA-LABEL" }), true);
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "LOADING" }), true);
});

test("isAllowedMediaHtmlAttributeName: rejects a name that is not on the allowlist", () => {
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "style" }), false);
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "href" }), false);
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "srcdoc" }), false);
  // Not a data-/aria- prefix, and not on the exact list — a prefix check that matched a substring
  // anywhere in the name (rather than anchored at the start) would wrongly admit this.
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "x-data-foo" }), false);
});

test("isAllowedMediaHtmlAttributeName: rejects on* handlers even though this check runs independently of the event-handler check", () => {
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "onerror" }), false);
  assert.equal(isAllowedMediaHtmlAttributeName({ name: "onclick" }), false);
});

test("parseMediaHtmlAttributes: returns no attributes and no error for an empty (or whitespace-only) draft", () => {
  assert.deepEqual(parseMediaHtmlAttributes({ text: "" }), { attributes: {}, error: null });
  assert.deepEqual(parseMediaHtmlAttributes({ text: "   " }), { attributes: {}, error: null });
});

test("parseMediaHtmlAttributes: parses one allowed quoted attribute", () => {
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'data-motion="fade-in"' }), {
    attributes: { "data-motion": "fade-in" },
    error: null,
  });
});

test("parseMediaHtmlAttributes: parses multiple allowed attributes, including single-quoted and unquoted values", () => {
  const result = parseMediaHtmlAttributes({ text: `data-motion="fade-in" aria-label='hello' loading=lazy` });
  assert.deepEqual(result, {
    attributes: { "data-motion": "fade-in", "aria-label": "hello", loading: "lazy" },
    error: null,
  });
});

test("parseMediaHtmlAttributes: parses a bare boolean attribute (no value) as present with an empty string value", () => {
  assert.deepEqual(parseMediaHtmlAttributes({ text: "muted" }), { attributes: { muted: "" }, error: null });
});

test("parseMediaHtmlAttributes: lowercases attribute names on the way in", () => {
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'DATA-Motion="Fade"' }), {
    attributes: { "data-motion": "Fade" },
    error: null,
  });
});

test("parseMediaHtmlAttributes: rejects an on* handler with the specific event-handler reason, naming the attribute", () => {
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'onerror="alert(1)"' }), {
    attributes: {},
    error: { reason: "event-handler", attribute: "onerror" },
  });
});

test("parseMediaHtmlAttributes: rejects on* case-insensitively", () => {
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'OnClick="doThing()"' }), {
    attributes: {},
    error: { reason: "event-handler", attribute: "onclick" },
  });
});

test("parseMediaHtmlAttributes: rejects a javascript: value on an otherwise-allowed name", () => {
  // `poster` is a real, allowed <video> attribute — the value, not the name, is what's dangerous
  // here, so this must report `javascript-url`, not let the allowed name mask the bad value.
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'poster="javascript:alert(1)"' }), {
    attributes: {},
    error: { reason: "javascript-url", attribute: "poster" },
  });
});

test("parseMediaHtmlAttributes: catches a javascript: value regardless of case or leading whitespace", () => {
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'poster="  JavaScript:alert(1)"' }), {
    attributes: {},
    error: { reason: "javascript-url", attribute: "poster" },
  });
});

test("parseMediaHtmlAttributes: rejects a name that is not on the allowlist, naming it", () => {
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'style="color:red"' }), {
    attributes: {},
    error: { reason: "disallowed-name", attribute: "style" },
  });
});

test("parseMediaHtmlAttributes: reports the FIRST rejection when several tokens would each fail, not a batch", () => {
  // `style` (disallowed) comes before `onerror` (event handler) in the input — the first offender
  // scanning left to right must win, proving this doesn't silently continue past a rejection.
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'style="color:red" onerror="alert(1)"' }), {
    attributes: {},
    error: { reason: "disallowed-name", attribute: "style" },
  });
});

test("parseMediaHtmlAttributes: stops at the first bad token even when good tokens came before it", () => {
  // Adversarial: an operator (or an attacker relying on a reviewer skimming only the start of the
  // string) could front-load safe-looking attributes before a smuggled one. Every already-parsed
  // attribute must be discarded, not partially accepted.
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'data-motion="fade-in" loading="lazy" onerror="alert(1)"' }), {
    attributes: {},
    error: { reason: "event-handler", attribute: "onerror" },
  });
});

test("parseMediaHtmlAttributes: reports a malformed fragment it cannot tokenize as a name/value pair", () => {
  const result = parseMediaHtmlAttributes({ text: 'data-motion="fade-in" "stray-quote"' });
  assert.deepEqual(result.attributes, {});
  assert.equal(result.error?.reason, "malformed");
});

test("parseMediaHtmlAttributes: a dangling '=' or quote after the last attribute is malformed, not silently dropped", () => {
  assert.deepEqual(parseMediaHtmlAttributes({ text: 'loading="lazy" =' }), { attributes: {}, error: { reason: "malformed", attribute: "=" } });
  assert.deepEqual(parseMediaHtmlAttributes({ text: "data-motion='x' '" }), { attributes: {}, error: { reason: "malformed", attribute: "'" } });
});

test("describeMediaHtmlAttributeError: names the rejected attribute in the event-handler message", () => {
  assert.match(describeMediaHtmlAttributeError({ reason: "event-handler", attribute: "onerror" }), /onerror/);
});

test("describeMediaHtmlAttributeError: names the rejected attribute in the javascript-url message", () => {
  assert.match(describeMediaHtmlAttributeError({ reason: "javascript-url", attribute: "poster" }), /poster/);
});

test("describeMediaHtmlAttributeError: names the rejected attribute in the disallowed-name message", () => {
  assert.match(describeMediaHtmlAttributeError({ reason: "disallowed-name", attribute: "style" }), /style/);
});

test("describeMediaHtmlAttributeError: names the unparsable fragment in the malformed message", () => {
  assert.match(describeMediaHtmlAttributeError({ reason: "malformed", attribute: "stray-quote" }), /stray-quote/);
});

// ---------------------------------------------------------------------------
// Attribute-NAME shape (2026-09-07 stored-XSS fix). The `data-`/`aria-` prefix families accepted
// ANY suffix, and the tokenizer's name class excludes only whitespace/`=`/quotes — so `<`, `>` and
// `/` were legal in a name a renderer then interpolates RAW into ` name="value"`.
// ---------------------------------------------------------------------------

test("isAllowedMediaHtmlAttributeName: rejects a data-/aria- name carrying tag-breaking characters", () => {
  for (const name of ["data-x><svg/onload", "data-a/onerror", "aria-x<img", "data-x`y", "data-x>", "aria-]"]) {
    assert.equal(isAllowedMediaHtmlAttributeName({ name: name }), false, `${name} must not be allowed`);
  }
});

test("isAllowedMediaHtmlAttributeName: still accepts every well-formed name the field exists for", () => {
  for (const name of ["data-motion", "aria-label", "DATA-FOO", "loading", "decoding", "poster", "data-x-1"]) {
    assert.equal(isAllowedMediaHtmlAttributeName({ name: name }), true, `${name} must stay allowed`);
  }
});

test("parseMediaHtmlAttributes: an attribute name that would close the tag is rejected, not parsed into the map", () => {
  const result = parseMediaHtmlAttributes({ text: "data-x><svg/onload=alert(1)" });
  assert.deepEqual(result.attributes, {});
  assert.deepEqual(result.error, { reason: "disallowed-name", attribute: "data-x><svg/onload" });
});

