import assert from "node:assert/strict";
import { test } from "vitest";
import { createVerifiedOrigin, InMemoryOriginSettingRepo, OriginRegistry } from "@jini-ai/http-kit/verified-origin";
import { toNetlifyRedirects, toVercelRedirects } from "../host-config/index.js";
import type { RedirectTargetOracle } from "../target-gate.js";
import type { RedirectRecord } from "../types.js";

const reservedSegments = new Set(["admin", "api"]);
const oracle = new OriginRegistry({ repo: new InMemoryOriginSettingRepo({ seeds: [{
  workspaceId: "site", origin: createVerifiedOrigin({ scheme: "https", host: "trusted.example", verifiedAt: "2026-10-07T00:00:00.000Z", source: "workspace-setting" }), redirectAllowlist: ["partner.example"],
}] }) });
function rule(overrides: Partial<RedirectRecord>): RedirectRecord {
  return { id: "r1", workspaceId: "site", matchType: "exact", fromPattern: "/old", toTarget: "/new", statusCode: 301,
    status: "active", override: true, priority: 0, source: "manual", createdByPrincipal: "user", createdAt: "2026-10-07T00:00:00.000Z", updatedAt: "2026-10-07T00:00:00.000Z", version: 1, ...overrides };
}

test("Netlify golden preserves status codes, force markers, absolute targets and deterministic order", async () => {
  const result = await toNetlifyRedirects({ oracle, reservedSegments, rules: [
    rule({ id: "temporary-method", fromPattern: "/z", toTarget: "/new-z", statusCode: 307 }),
    rule({ id: "fallback", fromPattern: "/fallback", toTarget: "/new-fallback", statusCode: 302, override: false }),
    rule({ id: "external", fromPattern: "/external", toTarget: "https://partner.example/landing?from=site", statusCode: 308 }),
    rule({ id: "permanent", fromPattern: "/a", toTarget: "/new-a", statusCode: 301 }),
  ] }, {});
  assert.deepEqual(result, {
    emitted: "/a /new-a 301!\n/external https://partner.example/landing?from=site 308!\n/fallback /new-fallback 302\n/z /new-z 307!\n",
    refused: [],
  });
});

test("Vercel golden preserves all four status codes and refuses a post-content match", async () => {
  const result = await toVercelRedirects({ oracle, reservedSegments, rules: [
    rule({ id: "r308", fromPattern: "/d", toTarget: "/new-d", statusCode: 308 }),
    rule({ id: "r307", fromPattern: "/c", toTarget: "/new-c", statusCode: 307 }),
    rule({ id: "r302", fromPattern: "/b", toTarget: "/new-b", statusCode: 302 }),
    rule({ id: "r301", fromPattern: "/a", toTarget: "/new-a", statusCode: 301 }),
    rule({ id: "fallback", fromPattern: "/fallback", override: false }),
  ] }, {});
  assert.deepEqual(result, {
    emitted: { redirects: [
      { source: "/a", destination: "/new-a", statusCode: 301 },
      { source: "/b", destination: "/new-b", statusCode: 302 },
      { source: "/c", destination: "/new-c", statusCode: 307 },
      { source: "/d", destination: "/new-d", statusCode: 308 },
    ] },
    refused: [{ redirectId: "fallback", reason: "host-phase-would-widen" }],
  });
});

test("export refuses interpolated absolute targets, widened host patterns and dynamic relative targets", async () => {
  const rules = [
    rule({ id: "absolute-template", matchType: "wildcard", fromPattern: "/go/*", toTarget: "https://$1" }),
    rule({ id: "glob", matchType: "wildcard", fromPattern: "/one/*", toTarget: "/new/$1" }),
    rule({ id: "prefix", matchType: "prefix", fromPattern: "/docs", toTarget: "/new-docs" }),
    rule({ id: "placeholder", fromPattern: "/old/:id" }),
    rule({ id: "dot-normalized", fromPattern: "/a/../old" }),
    rule({ id: "encoded-source", fromPattern: "/%6fld" }),
    rule({ id: "reserved", fromPattern: "/allowed-source", toTarget: "/admin" }),
    rule({ id: "disabled", status: "disabled", fromPattern: "/disabled" }),
  ];
  const expected = [
    { redirectId: "absolute-template", reason: "interpolated-absolute-target" },
    { redirectId: "glob", reason: "host-match-would-widen" },
    { redirectId: "prefix", reason: "dynamic-target-requires-runtime-oracle" },
    { redirectId: "placeholder", reason: "host-match-would-widen" },
    { redirectId: "dot-normalized", reason: "host-match-would-widen" },
    { redirectId: "encoded-source", reason: "host-match-would-widen" },
    { redirectId: "reserved", reason: "reserved-destination" },
    { redirectId: "disabled", reason: "inactive-rule" },
  ];
  assert.deepEqual(await toNetlifyRedirects({ rules, oracle, reservedSegments }, {}), { emitted: "", refused: expected });
  assert.deepEqual(await toVercelRedirects({ rules, oracle, reservedSegments }, {}), { emitted: { redirects: [] }, refused: expected });
});

test("duplicate paths preserve the runtime winner; an unsafe winner cannot expose a lower-priority fallback", async () => {
  const fallback = rule({ id: "fallback", priority: 1 });
  const winner = rule({ id: "winner", priority: 9, toTarget: "https://evil.example/new" });
  for (const rules of [[fallback, winner], [winner, fallback]]) {
    const result = await toNetlifyRedirects({ rules, oracle, reservedSegments }, {});
    assert.equal(result.emitted, "");
    assert.equal(result.refused.length, 2);
    assert.deepEqual(result.refused.find(entry => entry.redirectId === "fallback"), { redirectId: "fallback", reason: "shadowed-rule" });
    assert.deepEqual(result.refused.find(entry => entry.redirectId === "winner"), { redirectId: "winner", reason: "target-not-allowed" });
  }
  const safe = rule({ id: "winner", priority: 9, toTarget: "/winner" });
  assert.equal((await toNetlifyRedirects({ rules: [fallback, safe], oracle, reservedSegments }, {})).emitted, "/old /winner 301!\n");
});

test("mixed workspaces and unavailable oracle yield explicit refusals without partial hidden output", async () => {
  const rules = [rule({ id: "site-a" }), rule({ id: "site-b", workspaceId: "other", fromPattern: "/other" })];
  assert.deepEqual(await toNetlifyRedirects({ rules, oracle, reservedSegments }, {}), {
    emitted: "", refused: [{ redirectId: "site-a", reason: "mixed-workspaces" }, { redirectId: "site-b", reason: "mixed-workspaces" }],
  });
  const unavailable: RedirectTargetOracle = { canonicalOrigin: context => oracle.canonicalOrigin(context), isAllowedRedirectTarget: async () => { throw new Error("/private/driver/path"); } };
  const failed = await toVercelRedirects({ rules: [rule({ id: "failed" })], oracle: unavailable, reservedSegments }, {});
  assert.deepEqual(failed, { emitted: { redirects: [] }, refused: [{ redirectId: "failed", reason: "oracle-error" }] });
});

test("host export preserves pre-content precedence and refuses a literal displaced by a dynamic override", async () => {
  const fallback = rule({ id: "post", priority: 9, override: false, toTarget: "/post" });
  const earlier = rule({ id: "pre", priority: 1, override: true, toTarget: "/pre" });
  assert.deepEqual(await toNetlifyRedirects({ rules: [fallback, earlier], oracle, reservedSegments }, {}), {
    emitted: "/old /pre 301!\n", refused: [{ redirectId: "post", reason: "shadowed-rule" }],
  });
  const dynamic = rule({ id: "dynamic", matchType: "prefix", fromPattern: "/old", override: true, toTarget: "/pre" });
  assert.deepEqual(await toNetlifyRedirects({ rules: [fallback, dynamic], oracle, reservedSegments }, {}), {
    emitted: "", refused: [{ redirectId: "post", reason: "shadowed-rule" }, { redirectId: "dynamic", reason: "dynamic-target-requires-runtime-oracle" }],
  });
  const nestedFallback = rule({ id: "nested-post", fromPattern: "/old/nested", override: false });
  assert.deepEqual(await toNetlifyRedirects({ rules: [nestedFallback, dynamic], oracle, reservedSegments }, {}), {
    emitted: "", refused: [{ redirectId: "nested-post", reason: "shadowed-rule" }, { redirectId: "dynamic", reason: "dynamic-target-requires-runtime-oracle" }],
  });
});

test("export refuses exact targets that would be read as host template syntax", async () => {
  const rules = [
    rule({ id: "named-token", fromPattern: "/a", toTarget: "/new/:id" }),
    rule({ id: "capture-token", fromPattern: "/b", toTarget: "/new/$1" }),
    rule({ id: "bare-relative", fromPattern: "/c", toTarget: "new" }),
    rule({ id: "absolute-token", fromPattern: "/d", toTarget: "https://partner.example/:slug" }),
    rule({ id: "absolute-port", fromPattern: "/e", toTarget: "https://partner.example:8443/x" }),
  ];
  assert.deepEqual(await toNetlifyRedirects({ rules, oracle, reservedSegments }, {}), { emitted: "", refused: [
    { redirectId: "named-token", reason: "host-template-syntax" },
    { redirectId: "capture-token", reason: "host-template-syntax" },
    { redirectId: "bare-relative", reason: "host-template-syntax" },
    { redirectId: "absolute-token", reason: "host-template-syntax" },
    { redirectId: "absolute-port", reason: "host-template-syntax" },
  ] });
});

test("an interpolated relative wildcard target is refused as a widened host match, not as an absolute template", async () => {
  const result = await toVercelRedirects({ rules: [rule({ id: "relative", matchType: "wildcard", fromPattern: "/w/*", toTarget: "/$1" })], oracle, reservedSegments }, {});
  assert.deepEqual(result.refused, [{ redirectId: "relative", reason: "host-match-would-widen" }]);
});

test("Netlify keeps a post-content literal without a force marker even beside a non-override dynamic rule", async () => {
  const literal = rule({ id: "literal", fromPattern: "/old", override: false, toTarget: "/post" });
  const dynamic = rule({ id: "dynamic", matchType: "prefix", fromPattern: "/old", override: false, toTarget: "/elsewhere" });
  assert.deepEqual(await toNetlifyRedirects({ rules: [literal, dynamic], oracle, reservedSegments }, {}), {
    emitted: "/old /post 301\n", refused: [{ redirectId: "dynamic", reason: "shadowed-rule" }],
  });
});

test("export keeps source-path order when the input is already sorted", async () => {
  const result = await toNetlifyRedirects({ oracle, reservedSegments, rules: [
    rule({ id: "first", fromPattern: "/a", toTarget: "/new-a" }),
    rule({ id: "second", fromPattern: "/b", toTarget: "/new-b" }),
  ] }, {});
  assert.equal(result.emitted, "/a /new-a 301!\n/b /new-b 301!\n");
});

src/routing/__tests__/routing.phase-life.source:
import assert from "node:assert/strict";
import { test, beforeEach, afterEach } from "vitest";

import { createTestRouting } from './support.fixture.js';
const { registerResolvePhase, resetRoutingRegistrationsForTests, runPostContentPhase, runPreContentPhase, unregisterResolvePhaseOwner } = createTestRouting();
import type { RouteResolveContext } from "../types.js";

/**
 * @file The phase registry's LIFECYCLE contract (2026-09-16) — the half `routing.test.ts` and
 * `routing.phase-runners.test.ts` never covered, because both only ever ask what a registered
 * handler resolves to, never what happens to a handler whose registrant is gone.
 *
 * `phaseRegistry` is module-level and so process-wide, but its registrants are not: a composition
 * root registers a handler that has closed over THAT composition's resources, and a process can run
 * more than one composition (an integration test composes one per site it boots; loading
 * `composition/app.ts` itself registers nothing — see t91 F4.1). Append-only, every superseded
 * composition's closure stayed on the live request path forever. The concrete production-shaped
 * failure that produced these tests: a site's `SqliteRedirectRepo` handler outliving that site's
 * database, so a later request threw `TypeError: The database connection is not open` out of the
 * phase and 500ed `/` and `/pricing` — while `/products`, which runs no phase at all, kept serving
 * and made it look like a render bug.
 *
 * Two independent guarantees are pinned here, deliberately not one:
 *   1. OWNERSHIP — an owned registration supersedes that owner's previous one, and can be revoked
 *      outright, so the stale handler is not merely harmless but absent.
 *   2. ISOLATION is opt-in (`onError: "skip"`); the default propagates. A `"skip"` handler that
 *      throws is skipped, not propagated, so ONE registrant's fault can never take down an unrelated
 *      route — but only for a registrant that opted in, because it knows its own failure can only
 *      DECLINE an outcome. A handler with no `onError` (or an explicit `"fail"`) rethrows instead, so
 *      the caller's own error handling runs — see t91 F4.3, and
 *      `site-phase-handler-fail-policy.test.ts` for the route-level 500 that default produces.
 */

const ctx: RouteResolveContext = { workspaceId: "ws-lifecycle" };

beforeEach(() => resetRoutingRegistrationsForTests({}));
afterEach(() => resetRoutingRegistrationsForTests({}));

test("an owned registration REPLACES that owner's previous handlers rather than appending", async () => {
  const owner = Symbol("owner");
  let staleRan = false;

  registerResolvePhase({ phase: "pre_content", resolver: async () => {
      staleRan = true;
      return { kind: "redirect", location: "/from-the-stale-handler", statusCode: 301 };
    } }, { owner });
  registerResolvePhase({ phase: "pre_content", resolver: async () => null }, { owner });

  const outcome = await runPreContentPhase({ path: "/anything", ctx: ctx });
  assert.equal(outcome, null, "only the most recent registration for this owner may run");
  assert.equal(staleRan, false, "the superseded handler must not be on the request path at all");
});

test("superseding is per-owner: a different owner's registration is untouched", async () => {
  const replaced = Symbol("replaced");
  const other = Symbol("other");
  let otherRan = false;

  registerResolvePhase({ phase: "pre_content", resolver: async () => null }, { owner: replaced });
  registerResolvePhase({ phase: "pre_content", resolver: async () => {
      otherRan = true;
      return null;
    } }, { owner: other });
  registerResolvePhase({ phase: "pre_content", resolver: async () => null }, { owner: replaced });

  await runPreContentPhase({ path: "/anything", ctx: ctx });
  assert.equal(otherRan, true, "replacing one owner's registration must not evict another's");
});

test("superseding is per-phase-and-owner: re-registering pre_content leaves the same owner's post_content handler alone", async () => {
  const owner = Symbol("owner");
  let postRan = false;

  registerResolvePhase({ phase: "pre_content", resolver: async () => null }, { owner });
  registerResolvePhase({ phase: "post_content", resolver: async () => {
      postRan = true;
      return null;
    } }, { owner });
  registerResolvePhase({ phase: "pre_content", resolver: async () => null }, { owner });

  await runPostContentPhase({ path: "/anything", ctx: ctx });
  assert.equal(postRan, true, "a pre_content re-registration must not evict this owner's post_content handler");
});

test("unregisterResolvePhaseOwner revokes that owner's handlers in EVERY phase", async () => {
  const owner = Symbol("owner");
  const seen: string[] = [];

  registerResolvePhase({ phase: "pre_content", resolver: async () => {
      seen.push("pre");
      return null;
    } }, { owner });
  registerResolvePhase({ phase: "post_content", resolver: async () => {
      seen.push("post");
      return null;
    } }, { owner });

  const other = Symbol("surviving-owner");
  registerResolvePhase({ phase: "pre_content", resolver: async () => ({ kind: "redirect", location: "/other-pre", statusCode: 301 }) }, { owner: other });
  registerResolvePhase({ phase: "post_content", resolver: async () => ({ kind: "redirect", location: "/other-post", statusCode: 302 }) }, { owner: other });

  unregisterResolvePhaseOwner({ owner: owner });

  assert.deepEqual(await runPreContentPhase({ path: "/anything", ctx: ctx }), { kind: "redirect", location: "/other-pre", statusCode: 301 });
  assert.deepEqual(await runPostContentPhase({ path: "/anything", ctx: ctx }), { kind: "redirect", location: "/other-post", statusCode: 302 });
  await runPreContentPhase({ path: "/anything", ctx: ctx });
  await runPostContentPhase({ path: "/anything", ctx: ctx });
  assert.deepEqual(seen, [], "a revoked owner must run in neither phase");
});

test("unregisterResolvePhaseOwner(undefined) is a no-op — `undefined` is the no-owner marker, not an owner", async () => {
  let unownedRan = false;
  registerResolvePhase({ phase: "pre_content", resolver: async () => {
    unownedRan = true;
    return null;
  } });

  unregisterResolvePhaseOwner({ owner: undefined });

  await runPreContentPhase({ path: "/anything", ctx: ctx });
  assert.equal(unownedRan, true, "revoking `undefined` must not sweep away every unowned registration");
});

test("registerResolvePhase returns a disposer that removes exactly its own registration", async () => {
  const seen: string[] = [];
  const disposeFirst = registerResolvePhase({ phase: "pre_content", resolver: async () => {
    seen.push("first");
    return null;
  } });
  registerResolvePhase({ phase: "pre_content", resolver: async () => {
    seen.push("second");
    return null;
  } });

  disposeFirst();
  disposeFirst(); // idempotent — a second call must not remove the sibling too.

  await runPreContentPhase({ path: "/anything", ctx: ctx });
  assert.deepEqual(seen, ["second"], "only the disposed registration may be removed");
});

test("a skip handler that THROWS is skipped, and the phase's remaining handlers still run", async () => {
  let laterRan = false;
  registerResolvePhase({ phase: "pre_content", resolver: async () => {
      throw new TypeError("The database connection is not open");
    } }, { onError: "skip" });
  registerResolvePhase({ phase: "pre_content", resolver: async () => {
      laterRan = true;
      return { kind: "redirect", location: "/still-resolved", statusCode: 301 };
    } }, { onError: "skip" });

  const outcome = await runPreContentPhase({ path: "/anything", ctx: ctx });
  assert.equal(laterRan, true, "a failing handler must not abort the chain");
  assert.deepEqual(outcome, { kind: "redirect", location: "/still-resolved", statusCode: 301 });
});

test("a phase whose ONLY skip handler throws resolves to null — the request falls through to content, it does not 500", async () => {
  registerResolvePhase({ phase: "post_content", resolver: async () => {
      throw new TypeError("The database connection is not open");
    } }, { onError: "skip" });

  // The exact shape `routes/site/pages.ts` depends on: no throw escapes the phase, so its own
  // outer catch never turns one registrant's fault into `<h1>Site error</h1>` for the whole route.
  const outcome = await runPostContentPhase({ path: "/anything", ctx: ctx });
  assert.equal(outcome, null);
});

test("a synchronously-throwing skip handler is isolated too, not just a rejected promise", async () => {
  let laterRan = false;
  registerResolvePhase({ phase: "pre_content", resolver: (() => {
      throw new Error("thrown before any promise exists");
    }) as never }, { onError: "skip" });
  registerResolvePhase({ phase: "pre_content", resolver: async () => {
      laterRan = true;
      return null;
    } }, { onError: "skip" });

  const outcome = await runPreContentPhase({ path: "/anything", ctx: ctx });
  assert.equal(laterRan, true, "a handler that throws before returning a promise must be isolated the same way");
  assert.equal(outcome, null);
});

test("a handler registered with no onError (default fail) that THROWS rejects the phase", async () => {
  let laterRan = false;
  registerResolvePhase({ phase: "pre_content", resolver: async () => {
    throw new Error("guard store down");
  } });
  registerResolvePhase({ phase: "pre_content", resolver: async () => {
    laterRan = true;
    return { kind: "redirect", location: "/from-the-later-handler", statusCode: 301 };
  } });

  await assert.rejects(runPreContentPhase({ path: "/x", ctx: ctx }), /guard store down/);
  assert.equal(laterRan, false, "a fail-policy throw must abort the phase before a later handler runs");
});

test("explicit onError: 'fail' on post_content rejects too (sync throw included)", async () => {
  registerResolvePhase({ phase: "post_content", resolver: (() => {
      throw new Error("guard store down, synchronously");
    }) as never }, { onError: "fail" });

  await assert.rejects(runPostContentPhase({ path: "/x", ctx: ctx }));
});

