import assert from "node:assert/strict";
import { test } from "vitest";
import { ForbiddenError } from "../../../core/index.js";
import { FormFieldValidationError, type FormDefinitionRecord, type FormDefinitionRepoPort } from "../../index.js";
import { prepareFormAuthoring, withFormAuthoring } from "../../__tests__/support/host-ports.fixture.js";
import { htmlSubmissionDefinition } from "../html-submission-adapter.js";
import type { HtmlFormDefinitionRecord } from "../html-authoring.js";
import type { FormWriteServiceDeps } from "../../write-service.js";

// Direct tests for the two form host adapters: the authoring trust boundary (raw-HTML authority is
// checked before any parsing) and the HTML checkbox submission compatibility shim.
type AuthorizeInput = { principalId: string; permission: string; workspaceId: string };
function deps(allowed = true) {
  const calls: AuthorizeInput[] = [];
  const value = { authorize: async (input: AuthorizeInput) => { calls.push(input); return allowed ? { allowed: true } : { allowed: false, reason: "role_lacks_permission" }; } } as unknown as FormWriteServiceDeps;
  return { deps: value, calls };
}
const actor = { id: "editor-1" };
const base = { workspaceId: "ws-1", actor };
const HTML = '<input name="email" type="email" required>';
const existingHtml = { mode: "html", html: '<input name="old">' } as HtmlFormDefinitionRecord;
const fieldIds = (result: Awaited<ReturnType<typeof prepareFormAuthoring>>) => result?.fields?.map(field => field.id);

test("a write without mode/html re-derives fields only for an existing HTML form, without authorizing", async () => {
  const d = deps(false);
  const rederived = await prepareFormAuthoring({ deps: d.deps, input: base, existing: existingHtml });
  assert.equal(rederived?.mode, "html");
  assert.equal(rederived?.html, '<input name="old">');
  assert.deepEqual(fieldIds(rederived), ["old"]);
  const emptyHtml = await prepareFormAuthoring({ deps: d.deps, input: base, existing: { mode: "html" } as HtmlFormDefinitionRecord });
  assert.deepEqual([emptyHtml?.mode, emptyHtml?.html, emptyHtml?.fields], ["html", "", []]);
  assert.equal(await prepareFormAuthoring({ deps: d.deps, input: base, existing: { mode: "builder" } as HtmlFormDefinitionRecord }), undefined);
  assert.equal(await prepareFormAuthoring({ deps: d.deps, input: base }), undefined);
  assert.deepEqual(d.calls, []);
});

test("staying in builder mode needs no HTML authority", async () => {
  const d = deps(false);
  assert.deepEqual(await prepareFormAuthoring({ deps: d.deps, input: { ...base, mode: "builder" } }), { mode: "builder", html: undefined });
  assert.deepEqual(await prepareFormAuthoring({ deps: d.deps, input: { ...base, mode: "builder" }, existing: { mode: "builder" } as HtmlFormDefinitionRecord }), { mode: "builder", html: undefined });
  assert.deepEqual(d.calls, []);
});

test("switching an HTML form back to builder requires pages.edit_html and clears the markup", async () => {
  const d = deps();
  assert.deepEqual(await prepareFormAuthoring({ deps: d.deps, input: { ...base, mode: "builder" }, existing: existingHtml }), { mode: "builder", html: undefined });
  assert.deepEqual(d.calls, [{ principalId: "editor-1", permission: "pages.edit_html", workspaceId: "ws-1" }]);
  // Sending html alongside builder mode also needs authority, and still stores no markup.
  assert.deepEqual(await prepareFormAuthoring({ deps: d.deps, input: { ...base, mode: "builder", html: HTML } }), { mode: "builder", html: undefined });
  assert.equal(d.calls.length, 2);
});

test("denied principals are refused before the HTML is parsed", async () => {
  const d = deps(false);
  // Over the 200000 character parser limit: a parse would throw a validation error instead.
  const huge = "x".repeat(200_001);
  for (const input of [{ ...base, html: huge }, { ...base, mode: "html" as const }, { ...base, mode: "builder" as const, html: HTML }]) {
    await assert.rejects(prepareFormAuthoring({ deps: d.deps, input, existing: existingHtml }), (error: unknown) => {
      assert.ok(error instanceof ForbiddenError);
      assert.equal(error.message, "HTML form authoring is restricted to admins and owners");
      assert.deepEqual({ permission: (error as ForbiddenError & { permission: string }).permission, reason: (error as ForbiddenError & { reason: string }).reason }, { permission: "pages.edit_html", reason: "role_lacks_permission" });
      return true;
    });
  }
});

test("an unknown mode is a field validation error once authorized", async () => {
  await assert.rejects(prepareFormAuthoring({ deps: deps().deps, input: { ...base, mode: "markdown" as never } }), (error: unknown) => {
    assert.ok(error instanceof FormFieldValidationError);
    assert.equal(error.message, "Invalid form mode");
    assert.deepEqual(error.fieldErrors, [{ field: "mode", reason: "must be builder or html" }]);
    return true;
  });
});

test("authorized HTML writes derive fields from the new markup, else from the existing markup", async () => {
  const d = deps();
  const fresh = await prepareFormAuthoring({ deps: d.deps, input: { ...base, mode: "html", html: HTML }, existing: existingHtml });
  assert.deepEqual([fresh?.mode, fresh?.html, fieldIds(fresh)], ["html", HTML, ["email"]]);
  const htmlOnly = await prepareFormAuthoring({ deps: d.deps, input: { ...base, html: HTML } });
  assert.deepEqual(fieldIds(htmlOnly), ["email"]);
  const kept = await prepareFormAuthoring({ deps: d.deps, input: { ...base, mode: "html" }, existing: existingHtml });
  assert.deepEqual([kept?.html, fieldIds(kept)], ['<input name="old">', ["old"]]);
  const blank = await prepareFormAuthoring({ deps: d.deps, input: { ...base, mode: "html" } });
  assert.deepEqual([blank?.html, blank?.fields], ["", []]);
  await assert.rejects(prepareFormAuthoring({ deps: d.deps, input: { ...base, html: "<form></form><form></form>" } }), FormFieldValidationError);
});

function recordingRepo() {
  const calls: Array<[string, unknown]> = [];
  const record = { id: "f1", workspaceId: "ws-1", fields: [{ id: "x" }], name: "Form" } as unknown as FormDefinitionRecord;
  const repo: FormDefinitionRepoPort = {
    findById: async (target) => { calls.push(["findById", target]); return target.id === "f1" ? { ...record } : null; },
    findBySlug: async (target) => { calls.push(["findBySlug", target]); return record; },
    list: async (target) => { calls.push(["list", target]); return [record]; },
    isSlugTaken: async (target) => { calls.push(["isSlugTaken", target]); return true; },
    create: async (value) => { calls.push(["create", { ...value }]); },
    update: async (value) => { calls.push(["update", { ...value }]); },
  } as FormDefinitionRepoPort;
  return { repo, calls, record };
}

test("withFormAuthoring writes the authoring fields in the same create/update call", async () => {
  const { repo, calls } = recordingRepo();
  const authoring = { mode: "html" as const, html: HTML, fields: [] };
  const wrapped = withFormAuthoring({ repo, authoring });
  const created = { id: "f2", fields: [{ id: "a" }], name: "New" } as unknown as FormDefinitionRecord;
  await wrapped.create(created);
  await wrapped.update({ id: "f1", name: "Edited" } as unknown as FormDefinitionRecord);
  assert.deepEqual(calls, [
    ["create", { id: "f2", fields: [], name: "New", mode: "html", html: HTML }],
    ["update", { id: "f1", name: "Edited", mode: "html", html: HTML, fields: [] }],
  ]);
  // The caller's record object carries the authored state afterwards too.
  assert.equal((created as HtmlFormDefinitionRecord).html, HTML);
});

test("withFormAuthoring forwards reads unchanged, clearing fields on findById only when replacing", async () => {
  const { repo, calls, record } = recordingRepo();
  const plain = withFormAuthoring({ repo, authoring: { mode: "builder" } });
  assert.deepEqual(await plain.findById({ workspaceId: "ws-1", id: "f1" } as never), record);
  assert.equal(await plain.findBySlug({ workspaceId: "ws-1", slug: "s" } as never), record);
  assert.deepEqual(await plain.list({ workspaceId: "ws-1" } as never), [record]);
  assert.equal(await plain.isSlugTaken({ workspaceId: "ws-1", slug: "s" } as never), true);
  const replacing = withFormAuthoring({ repo, authoring: { mode: "html", html: HTML } }, { replaceFields: true });
  assert.deepEqual(await replacing.findById({ workspaceId: "ws-1", id: "f1" } as never), { ...record, fields: [] });
  assert.equal(await replacing.findById({ workspaceId: "ws-1", id: "missing" } as never), null);
  assert.deepEqual(calls.map(([name, target]) => [name, target]), [
    ["findById", { workspaceId: "ws-1", id: "f1" }], ["findBySlug", { workspaceId: "ws-1", slug: "s" }], ["list", { workspaceId: "ws-1" }],
    ["isSlugTaken", { workspaceId: "ws-1", slug: "s" }], ["findById", { workspaceId: "ws-1", id: "f1" }], ["findById", { workspaceId: "ws-1", id: "missing" }],
  ]);
});

test("htmlSubmissionDefinition retains authored checkbox rules and requiredness for both form modes", () => {
  const fields = [
    { id: "consent", type: "checkbox", required: true, checkboxValue: "yes" },
    { id: "news", type: "checkbox", required: true, checkboxValue: "" },
    { id: "bool", type: "checkbox", required: true, checkboxValue: "on" },
    { id: "plain", type: "checkbox", required: true },
    { id: "name", type: "text", required: true },
  ];
  const definition = { id: "f", mode: "html", fields } as unknown as FormDefinitionRecord;
  const body = { consent: "yes", news: "", bool: true, plain: "on", name: "Ada" };
  const result = htmlSubmissionDefinition({ definition, body });
  assert.equal(result, definition);
  assert.deepEqual(result.fields, fields);
  assert.equal((result as HtmlFormDefinitionRecord).mode, "html");
  // The stored definition is not mutated.
  assert.equal(fields[0]!.type, "checkbox");
  const builder = { id: "f", mode: "builder", fields } as unknown as FormDefinitionRecord;
  assert.equal(htmlSubmissionDefinition({ definition: builder, body }), builder);
});

src/entries/__tests__/tool-registrations.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { ToolInputError, type ToolExecutionContext, type ToolRegistration } from "@jini-ai/core";

import { entriesAgentToolCatalog } from "../agent-tools.js";
import { ContentTypeNotActiveError, EntryNotFoundError, ForbiddenError, VersionConflictError } from "../errors.js";
import { InMemoryEntryRepo } from "../repo.memory.js";
import { buildEntriesRegistrations, entriesDerivedRisk, type EntriesToolDeps } from "../tool-registrations.js";
import type { OwningContentType } from "../types.js";

/**
 * @file The entries agent tools driven end to end through their registrations: the workspace-free
 * view each returns, the full domain events the host outbox receives, the read permission the list
 * tool checks itself, and the rejections — only `fieldsJson` shape problems get the schema appended.
 */

const WORKSPACE_ID = "ws-entry-tools";
const NOW = "2026-10-21T00:00:00.000Z";

const recipeType: OwningContentType = {
  workspaceId: WORKSPACE_ID, key: "recipe", status: "active",
  fields: [{ name: "summary", kind: "text", required: false, queryable: false }],
};

function ctx(input: unknown): ToolExecutionContext {
  return { executionId: "exec-1", principal: { id: "agent-principal" }, run: { id: "run-1" }, input, signal: new AbortController().signal } as ToolExecutionContext;
}

function harness(overrides: Partial<EntriesToolDeps> = {}, contentTypes: Record<string, OwningContentType> = { recipe: recipeType }) {
  const entryRepo = new InMemoryEntryRepo();
  const events: Array<{ id: string; name: string; workspaceId: string; occurredAt: string; payload: Record<string, unknown> }> = [];
  const permissionRequests: unknown[] = [];
  let ids = 0;
  const deps: EntriesToolDeps = {
    authorize: async (request) => { permissionRequests.push(request); return { allowed: true, reason: "matched" }; },
    workspaceId: WORKSPACE_ID,
    clock: { nowMs: () => Date.parse(NOW) },
    idGen: { newId: () => `id-${++ids}` },
    outbox: { enqueue: async (event) => { events.push(event); }, claimPending: async () => [], markDelivered: async () => {}, markFailed: async () => {} },
    entryRepo,
    contentTypeRepo: { findByKey: async ({ workspaceId, key }) => (workspaceId === WORKSPACE_ID ? contentTypes[key] ?? null : null) },
    ...overrides,
  };
  const registrations = buildEntriesRegistrations(deps);
  const tool = (id: string): ToolRegistration => {
    const found = registrations.find((registration) => registration.descriptor.id === id);
    assert.ok(found, `${id} must be wired`);
    return found;
  };
  return { entryRepo, events, permissionRequests, registrations, tool };
}

type EntryView = { entry: Record<string, unknown> & { id: string; version: number } };

async function createChili(h: ReturnType<typeof harness>, input: Record<string, unknown> = {}): Promise<EntryView> {
  return (await h.tool("collections_entry_create").handler(ctx({ type: "recipe", slug: "chili", title: "Chili", ...input }))) as EntryView;
}

test("the entire catalog is wired, and every wired tool is classified by the wiring layer", () => {
  const h = harness();
  const wired = h.registrations.map((r) => r.descriptor.id).sort();
  assert.deepEqual(wired, entriesAgentToolCatalog.map((t) => t.name).sort());
  assert.deepEqual(wired, [...entriesDerivedRisk.keys()].sort());
});

test("collections_entry_create returns the workspace-free view, defaulting fieldsJson to the empty site envelope", async () => {
  const h = harness();

  const result = await createChili(h);

  assert.deepEqual(result, {
    entry: {
      id: "id-1", type: "recipe", slug: "chili", status: "draft", title: "Chili",
      fieldsJson: { ext: { site: {} } }, bodyJson: null, publishedAt: null, createdAt: NOW, updatedAt: NOW, version: 1,
    },
  });
  assert.equal("workspaceId" in result.entry, false);
  assert.equal((await h.entryRepo.findById({ workspaceId: WORKSPACE_ID, id: "id-1" }))?.workspaceId, WORKSPACE_ID);
});

test("collections_entry_create keeps caller-supplied fieldsJson and bodyJson", async () => {
  const h = harness();
  const fieldsJson = { ext: { site: { summary: "Hot" } } };
  const bodyJson = { type: "doc", content: [] };

  const result = await createChili(h, { fieldsJson, bodyJson });

  assert.deepEqual(result.entry.fieldsJson, fieldsJson);
  assert.deepEqual(result.entry.bodyJson, bodyJson);
});

test("collections_entry_create appends the schema to a fieldsJson shape rejection only", async () => {
  const h = harness({}, { recipe: recipeType, archived: { ...recipeType, key: "archived", status: "deprecated" } });

  await assert.rejects(
    () => createChili(h, { fieldsJson: { ext: { site: { unknownField: 1 } } } }),
    (error: unknown) => error instanceof ToolInputError && /Schema for 'collections_entry_create'/.test(error.message),
  );
  await assert.rejects(
    () => h.tool("collections_entry_create").handler(ctx({ type: "archived", slug: "old", title: "Old" })),
    (error: unknown) => error instanceof ContentTypeNotActiveError && !/Schema for/.test(error.message),
  );
  await assert.rejects(() => h.tool("collections_entry_create").handler(ctx({ type: "recipe", slug: "chili" })), ToolInputError);
  assert.deepEqual(await h.entryRepo.listByWorkspace({ workspaceId: WORKSPACE_ID }), []);
  assert.deepEqual(h.events, []);
});

test("collections_entry_update changes the title (string only) and fields at the expected version", async () => {
  const h = harness();
  const created = await createChili(h);

  const renamed = (await h.tool("collections_entry_update").handler(ctx({ id: created.entry.id, title: "Chili v2", expectedVersion: 1 }))) as EntryView;
  assert.equal(renamed.entry.title, "Chili v2");
  assert.equal(renamed.entry.version, 2);

  const nonStringTitle = (await h.tool("collections_entry_update").handler(ctx({ id: created.entry.id, title: 42, fieldsJson: { ext: { site: { summary: "Mild" } } }, expectedVersion: 2 }))) as EntryView;
  assert.equal(nonStringTitle.entry.title, "Chili v2", "a non-string title is ignored, not coerced");
  assert.deepEqual(nonStringTitle.entry.fieldsJson, { ext: { site: { summary: "Mild" } } });

  await assert.rejects(
    () => h.tool("collections_entry_update").handler(ctx({ id: created.entry.id, title: "late", expectedVersion: 1 })),
    (error: unknown) => error instanceof VersionConflictError && !/Schema for/.test(error.message),
  );
  await assert.rejects(
    () => h.tool("collections_entry_update").handler(ctx({ id: created.entry.id, fieldsJson: { ext: {} }, expectedVersion: 3 })),
    (error: unknown) => error instanceof ToolInputError && /Schema for 'collections_entry_update'/.test(error.message),
  );
  assert.equal((await h.entryRepo.findById({ workspaceId: WORKSPACE_ID, id: created.entry.id }))?.version, 3);
});

test("collections_entry_publish / unpublish flip status and deliver full domain events to the host outbox", async () => {
  const h = harness();
  const created = await createChili(h);

  const published = (await h.tool("collections_entry_publish").handler(ctx({ id: created.entry.id, expectedVersion: 1 }))) as EntryView;
  assert.equal(published.entry.status, "published");
  assert.equal(published.entry.publishedAt, NOW);

  const unpublished = (await h.tool("collections_entry_unpublish").handler(ctx({ id: created.entry.id, expectedVersion: 2 }))) as EntryView;
  assert.equal(unpublished.entry.status, "unpublished");
  assert.equal(unpublished.entry.version, 3);

  const names = h.events.map((event) => event.name);
  assert.deepEqual(names.slice(-2), ["entry.published", "entry.unpublished"]);
  for (const event of h.events) {
    assert.equal(event.workspaceId, WORKSPACE_ID);
    assert.equal(event.occurredAt, NOW);
    assert.equal(typeof event.id, "string");
  }

  await assert.rejects(() => h.tool("collections_entry_publish").handler(ctx({ id: "missing", expectedVersion: 1 })), EntryNotFoundError);
  await assert.rejects(() => h.tool("collections_entry_unpublish").handler(ctx({ id: created.entry.id })), ToolInputError);
});

test("collections_entry_list checks admin.collections.read, accepts omitted input, and filters by type", async () => {
  const h = harness({}, { recipe: recipeType, article: { ...recipeType, key: "article" } });
  await createChili(h);
  await h.tool("collections_entry_create").handler(ctx({ type: "article", slug: "news", title: "News" }));
  h.permissionRequests.length = 0;

  const all = (await h.tool("collections_entry_list").handler(ctx(undefined))) as { items: Array<{ slug: string; workspaceId?: string }> };
  const recipes = (await h.tool("collections_entry_list").handler(ctx({ type: "recipe" }))) as { items: Array<{ slug: string }> };

  assert.deepEqual(all.items.map((item) => item.slug).sort(), ["chili", "news"]);
  assert.ok(all.items.every((item) => !("workspaceId" in item)));
  assert.deepEqual(recipes.items.map((item) => item.slug), ["chili"]);
  assert.deepEqual(h.permissionRequests[0], { principalId: "agent-principal", permission: "admin.collections.read", workspaceId: WORKSPACE_ID, entityType: "entry" });
  await assert.rejects(() => h.tool("collections_entry_list").handler(ctx("recipe")), ToolInputError);
  await assert.rejects(() => h.tool("collections_entry_list").handler(ctx({ type: 7 })), ToolInputError);
});

test("a denied principal is refused by the list check and by every mutation's own authorization, writing nothing", async () => {
  const h = harness({ authorize: async () => ({ allowed: false, reason: "no-grant" }) });

  await assert.rejects(
    () => h.tool("collections_entry_list").handler(ctx(undefined)),
    (error: unknown) => error instanceof Error && /not authorized for 'admin.collections.read' \(no-grant\)/.test(error.message),
  );
  await assert.rejects(() => createChili(h), ForbiddenError);
  assert.deepEqual(await h.entryRepo.listByWorkspace({ workspaceId: WORKSPACE_ID }), []);
});

src/widgets/__tests__/gallery-config.uni.source:
import { describe, expect, it } from 'vitest';
import { galleryMediaReferences, MAX_GALLERY_IMAGES, mediaHtmlSlugs, parseGalleryConfig } from '../markers/gallery.js';

/** Boundary pins for both gallery config shapes: legacy `images` and slug-first `items`/`html`. */

const legacy = { images: [{ mediaId: 'one', alt: '' }], layout: 'grid' };
const many = (count: number, make: (index: number) => unknown) => Array.from({ length: count }, (_, index) => make(index));

describe('parseGalleryConfig legacy images', () => {
  it('accepts a valid gallery and returns the authored object', () => {
    const config = { ...legacy, columns: 6, aspectRatio: '4 / 3', lightbox: false, extra: 1 };
    expect(parseGalleryConfig({ config })).toEqual({ config, errors: [], warnings: [] });
  });
  it('rejects an empty image list unless allowEmpty is set', () => {
    expect(parseGalleryConfig({ config: { images: [], layout: 'grid' } }).errors).toEqual([`images must contain between 1 and ${MAX_GALLERY_IMAGES} images`]);
    expect(parseGalleryConfig({ config: { images: [], layout: 'grid' } }, { allowEmpty: true }).errors).toEqual([]);
  });
  it('accepts exactly the image cap and rejects one more', () => {
    const image = () => ({ mediaId: 'm', alt: '' });
    expect(parseGalleryConfig({ config: { images: many(MAX_GALLERY_IMAGES, image), layout: 'grid' } }).errors).toEqual([]);
    expect(parseGalleryConfig({ config: { images: many(MAX_GALLERY_IMAGES + 1, image), layout: 'grid' } }).errors).toEqual(['images must contain between 1 and 50 images']);
  });
  it('rejects a non-array images value', () => {
    expect(parseGalleryConfig({ config: { images: 'x', layout: 'grid' } })).toEqual({ errors: ['images must contain between 1 and 50 images'], warnings: [] });
  });
  it('reports every image error in order before option errors, keeping warnings', () => {
    const config = { images: [{ mediaId: 'a', src: 'https://e.com/x', alt: 1, caption: 2 }, { mediaId: 'a/b' }, 7], layout: 'single', columns: 1, aspectRatio: '0', lightbox: 'yes' };
    expect(parseGalleryConfig({ config })).toEqual({
      errors: [
        'images[0] requires exactly one of mediaId or src',
        'images[0].alt must be a string',
        'images[0].caption must be a string',
        'images[1].mediaId must be a nonempty media id of at most 200 characters, without slashes or whitespace',
        'images[2] must be an object',
        'layout must be grid, carousel or masonry',
        'columns must be an integer between 2 and 6',
        'aspectRatio must be a positive number or ratio such as 16/9',
        'lightbox must be a boolean',
      ],
      warnings: ['images[1].alt is missing; supply alt text or an explicit empty string for a decorative image'],
    });
  });
  it('rejects an image with neither mediaId nor src', () => {
    expect(parseGalleryConfig({ config: { images: [{ alt: '' }], layout: 'grid' } }).errors).toEqual(['images[0] requires exactly one of mediaId or src']);
  });
  it('rejects a src that is not http(s)', () => {
    expect(parseGalleryConfig({ config: { images: [{ src: 'ftp://e.com/x', alt: '' }], layout: 'grid' } }).errors).toEqual(['images[0].src must be an HTTP(S) image URL without credentials, at most 2048 characters']);
  });
  it('rejects unparseable, oversized and non-string sources', () => {
    for (const src of ['not a URL', `https://e.com/${'a'.repeat(2048)}`, '', 5]) {
      expect(parseGalleryConfig({ config: { images: [{ src, alt: '' }], layout: 'grid' } }).errors).toEqual(['images[0].src must be an HTTP(S) image URL without credentials, at most 2048 characters']);
    }
  });
  it('rejects columns above 6 and fractional columns', () => {
    expect(parseGalleryConfig({ config: { ...legacy, columns: 7 } }).errors).toEqual(['columns must be an integer between 2 and 6']);
    expect(parseGalleryConfig({ config: { ...legacy, columns: 2.5 } }).errors).toEqual(['columns must be an integer between 2 and 6']);
  });
  it('accepts columns of 2', () => {
    expect(parseGalleryConfig({ config: { ...legacy, columns: 2 } }).errors).toEqual([]);
  });
  it('rejects a non-string layout', () => {
    expect(parseGalleryConfig({ config: { ...legacy, layout: undefined } }).errors).toEqual(['layout must be grid, carousel or masonry']);
  });
});

describe('parseGalleryConfig media items', () => {
  it('normalizes items into images with the default single layout', () => {
    const items = [{ slug: 'one', alt: 'A', caption: 'C' }];
    const config = { items, cssClass: 'c', htmlAttributes: 'data-x="1"', columns: 1, aspectRatio: '16/9' };
    const parsed = parseGalleryConfig({ config });
    expect(parsed).toEqual({ config: { ...config, mode: 'media', images: items, layout: 'single' }, errors: [], warnings: [] });
    expect(parsed.config!.images).not.toBe(items);
  });
  it('keeps an explicit layout and ignores lightbox validation', () => {
    for (const layout of ['single', 'grid', 'carousel', 'masonry']) {
      expect(parseGalleryConfig({ config: { mode: 'media', items: [], layout, lightbox: 'not validated' } }).config?.layout).toBe(layout);
    }
  });
  it('accepts exactly the item cap and rejects one more', () => {
    expect(parseGalleryConfig({ config: { items: many(MAX_GALLERY_IMAGES, () => ({ slug: 's' })) } }).errors).toEqual([]);
    expect(parseGalleryConfig({ config: { items: many(MAX_GALLERY_IMAGES + 1, () => ({ slug: 's' })) } })).toEqual({ errors: ['items must be an array of at most 50 slug items'], warnings: [] });
  });
  it('reports mode, string option, item and option errors in order', () => {
    const config = { mode: 'other', htmlAttributes: 1, cssClass: 2, items: [3, { slug: '', src: 'x', alt: 1, caption: 2 }, { slug: 's', mediaId: 'm' }], layout: 'slider', columns: 0, aspectRatio: 'x' };
    expect(parseGalleryConfig({ config })).toEqual({
      errors: [
        'mode must be media or html',
        'htmlAttributes must be a string',
        'cssClass must be a string',
        'items[0] must be an object',
        'items[1].slug must be a nonempty slug of at most 200 characters without slashes or whitespace',
        'items[1] uses slug, never src or mediaId',
        'items[1].alt must be a string',
        'items[1].caption must be a string',
        'items[2] uses slug, never src or mediaId',
        'layout must be single, grid, carousel or masonry',
        'columns must be an integer between 1 and 6',
        'aspectRatio must be a positive number or ratio such as 16/9',
      ],
      warnings: [],
    });
  });
  it('rejects columns above 6', () => {
    expect(parseGalleryConfig({ config: { items: [], columns: 7 } }).errors).toEqual(['columns must be an integer between 1 and 6']);
  });
  it('drops mode and string option errors when items is not an array (reported, not fixed)', () => {
    expect(parseGalleryConfig({ config: { mode: 'other', cssClass: 1 } })).toEqual({ errors: ['items must be an array of at most 50 slug items'], warnings: [] });
  });
});

describe('parseGalleryConfig html mode', () => {
  it('infers html mode from an html field', () => {
    const config = { html: '<p></p>', cssClass: 'c' };
    expect(parseGalleryConfig({ config })).toEqual({ config: { ...config, mode: 'html', images: [], layout: 'single' }, errors: [], warnings: [] });
  });
  it('accepts html of exactly 65536 characters', () => {
    expect(parseGalleryConfig({ config: { html: 'a'.repeat(65536) } }).errors).toEqual([]);
  });
  it('rejects oversized html with the string option errors first', () => {
    expect(parseGalleryConfig({ config: { html: 'a'.repeat(65537), htmlAttributes: 1 } })).toEqual({ errors: ['htmlAttributes must be a string', 'html must be a string of at most 65536 characters'], warnings: [] });
  });
  it('rejects an explicit html mode without html text', () => {
    expect(parseGalleryConfig({ config: { mode: 'html' } }).errors).toEqual(['html must be a string of at most 65536 characters']);
  });
});

describe('galleryMediaReferences', () => {
  it('prefers items over images and reads slug before mediaId', () => {
    const config = { items: [{ slug: 's', mediaId: 'm' }, { mediaId: 'm2' }, null, { slug: 'a/b' }], images: [{ mediaId: 'ignored' }] };
    expect(galleryMediaReferences({ config })).toEqual([{ mediaId: 's', index: 0 }, { mediaId: 'm2', index: 1 }]);
  });
  it('falls back to images, then to no list', () => {
    expect(galleryMediaReferences({ config: { images: [{ mediaId: 'i' }] } })).toEqual([{ mediaId: 'i', index: 0 }]);
    expect(galleryMediaReferences({ config: { items: 'x', images: 'y' } })).toEqual([]);
  });
  it('indexes only the first image-cap items', () => {
    const refs = galleryMediaReferences({ config: { items: many(MAX_GALLERY_IMAGES + 1, index => ({ slug: `s${index}` })) } });
    expect(refs).toHaveLength(MAX_GALLERY_IMAGES);
    expect(refs.at(-1)).toEqual({ mediaId: 's49', index: 49 });
  });
  it('appends html slugs indexed by running count, then nested content with its own indexes', () => {
    const config = { items: [{ slug: 'a' }], html: '{{media:b}}', content: { items: [{ slug: 'c' }] } };
    expect(galleryMediaReferences({ config })).toEqual([{ mediaId: 'a', index: 0 }, { mediaId: 'b', index: 1 }, { mediaId: 'c', index: 0 }]);
  });
  it('ignores non-string html and non-record content', () => {
    expect(galleryMediaReferences({ config: { html: 1, content: [] } })).toEqual([]);
  });
});

describe('mediaHtmlSlugs', () => {
  it('reads tokens then every data-media-slug quoting style, decoding and filtering keys', () => {
    const html = `{{media:a&amp;b}}{{media:x y}}<i data-media-slug="d"></i><i DATA-MEDIA-SLUG = 's'></i><i data-media-slug=bare></i><i data-media-slug=""></i>`;
    expect(mediaHtmlSlugs({ html })).toEqual(['a&b', 'd', 's', 'bare']);
  });
});

