/** Direct boundary certification of `resolveSeoImageDetails` and `seoImageRefRefusal` (media.ts). */
import assert from "node:assert/strict";
import { test } from "vitest";

import { resolveSeoImageDetails, seoImageRefRefusal, type ResolveSeoImageRefDeps } from "../media.js";
import type { SeoFeaturedImagePort } from "../ports.js";
import type { MediaRecord } from "../../media/types.js";
import type { TransformDefinitionRecord, TransformParams } from "../../media/transform-types.js";

const WS = "w";
const now = "2026-10-20T00:00:00.000Z";
const asset: MediaRecord = { id: "asset-id", workspaceId: WS, slug: "cover", title: "Cover", alt: "", caption: "", credit: "", source: { sha256: "abc" }, status: "active", createdAt: now, updatedAt: now, version: 1, width: 1, height: 1, cssClass: null, htmlAttributes: null };

function definition(name: string, version: number, params: TransformParams): TransformDefinitionRecord {
  return { id: `${name}-${version}`, workspaceId: WS, name, version, params, owner: "core", createdAt: now };
}

/** Typed fake over the real ports; `lookups` records every transform name listed, in order. */
function fakeDeps({ found = asset as MediaRecord | null, definitions = [] as TransformDefinitionRecord[] } = {}) {
  const lookups: string[] = [];
  const featuredImage: SeoFeaturedImagePort = {
    findMediaByIdOrSlug: async () => found,
    mediaUrlKey: ({ asset: a }) => a.slug,
    mediaPublicPath: ({ key, variant }) => `/m/${key}/${variant.name}.v${variant.version}/image.${variant.ext}`,
    resolveFeaturedImageRef: async () => ({ ok: true }),
  };
  const deps: ResolveSeoImageRefDeps = {
    featuredImage,
    transformDefinitionRepo: {
      listByName: async ({ name }) => {
        lookups.push(name);
        return definitions.filter(d => d.name === name);
      },
    },
  };
  return { deps, lookups };
}

const og = definition("og", 2, { format: "jpeg", width: 1200, height: 630, fit: "cover" });
const pub = definition("public", 1, { format: "webp" });

test("a blank ref resolves undefined without any lookup", async () => {
  const { deps, lookups } = fakeDeps({ definitions: [og] });
  assert.equal(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "   " } }), undefined);
  assert.deepEqual(lookups, []);
});

test("an absolute URL passes through without metadata or provenance when no share transform is selected", async () => {
  const { deps } = fakeDeps();
  assert.deepEqual(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: " https://cdn.example/x.jpg " } }), { url: "https://cdn.example/x.jpg" });
});

test("an absolute URL carries its trimmed ref as provenance when a share transform is selected", async () => {
  const { deps } = fakeDeps();
  assert.deepEqual(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "https://cdn.example/x.jpg" } }, { transformName: "og" }), { url: "https://cdn.example/x.jpg", ref: "https://cdn.example/x.jpg" });
});

test("a protocol-relative URL counts as absolute", async () => {
  const { deps } = fakeDeps();
  assert.deepEqual(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "//cdn.example/x.jpg" } }), { url: "//cdn.example/x.jpg" });
});

test.each([":og", "cover:", "nocolon"])("a ref without both halves resolves undefined: %s", async (ref) => {
  const { deps, lookups } = fakeDeps({ definitions: [og] });
  assert.equal(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref } }), undefined);
  assert.deepEqual(lookups, []);
});

test("a missing asset resolves undefined before any transform lookup", async () => {
  const { deps, lookups } = fakeDeps({ found: null, definitions: [og] });
  assert.equal(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "cover:og" } }), undefined);
  assert.deepEqual(lookups, []);
});

test("a trashed asset resolves undefined", async () => {
  const { deps } = fakeDeps({ found: { ...asset, status: "trashed" }, definitions: [og] });
  assert.equal(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "cover:og" } }), undefined);
});

test("a registered share transform replaces the ref's own transform and advertises its exact box", async () => {
  const { deps } = fakeDeps({ definitions: [og, pub] });
  assert.deepEqual(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "cover:public" } }, { transformName: "og" }), {
    url: "/m/cover/og.v2/image.jpg", ref: "cover:public", width: 1200, height: 630, type: "image/jpeg",
  });
});

test("an unregistered share transform falls back to the ref's own transform, keeping provenance", async () => {
  const { deps, lookups } = fakeDeps({ definitions: [pub] });
  assert.deepEqual(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "cover:public" } }, { transformName: "og" }), {
    url: "/m/cover/public.v1/image.webp", ref: "cover:public", type: "image/webp",
  });
  assert.deepEqual(lookups, ["og", "public"]);
});

test("neither the share transform nor the ref's own transform registered resolves undefined", async () => {
  const { deps } = fakeDeps();
  assert.equal(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "cover:public" } }, { transformName: "og" }), undefined);
});

test("a share transform equal to the ref's own unregistered transform is looked up once", async () => {
  const { deps, lookups } = fakeDeps();
  assert.equal(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "cover:og" } }, { transformName: "og" }), undefined);
  assert.deepEqual(lookups, ["og"]);
});

test.each([
  ["inside fit", { format: "png", width: 10, height: 20, fit: "inside" }],
  ["outside fit", { format: "png", width: 10, height: 20, fit: "outside" }],
  ["width only", { format: "png", width: 10 }],
  ["height only", { format: "png", height: 20 }],
] satisfies [string, TransformParams][])("no exact box is advertised for %s", async (_label, params) => {
  const { deps } = fakeDeps({ definitions: [definition("t", 1, params)] });
  assert.deepEqual(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "cover:t" } }), { url: "/m/cover/t.v1/image.png", type: "image/png" });
});

test.each([
  ["no fit", { format: "gif", width: 10, height: 20 }],
  ["contain fit", { format: "gif", width: 10, height: 20, fit: "contain" }],
  ["fill fit", { format: "gif", width: 10, height: 20, fit: "fill" }],
] satisfies [string, TransformParams][])("the exact box is advertised for %s", async (_label, params) => {
  const { deps } = fakeDeps({ definitions: [definition("t", 1, params)] });
  assert.deepEqual(await resolveSeoImageDetails({ deps, input: { workspaceId: WS, ref: "cover:t" } }), { url: "/m/cover/t.v1/image.gif", width: 10, height: 20, type: "image/gif" });
});

/** Refusal fake: records the ref half passed to the featured-image check. */
function refusalDeps(result: Awaited<ReturnType<SeoFeaturedImagePort["resolveFeaturedImageRef"]>>) {
  const { deps } = fakeDeps();
  const seen: string[] = [];
  const featuredImage: SeoFeaturedImagePort = { ...deps.featuredImage, resolveFeaturedImageRef: async ({ ref }) => { seen.push(ref); return result; } };
  return { deps: { featuredImage }, seen };
}

test.each([undefined, null, 42])("a non-string share image value is accepted untouched: %s", async (ref) => {
  const { deps, seen } = refusalDeps({ ok: false, reason: "not-image", contentType: "application/pdf" });
  assert.equal(await seoImageRefRefusal({ deps, input: { workspaceId: WS, field: "ogImage", ref } }), null);
  assert.deepEqual(seen, []);
});

test.each(["  ", "https://cdn.example/x.pdf", "//cdn.example/x.pdf", "nocolon"])("a non-ref string is accepted without a media read: %j", async (ref) => {
  const { deps, seen } = refusalDeps({ ok: false, reason: "not-image", contentType: "application/pdf" });
  assert.equal(await seoImageRefRefusal({ deps, input: { workspaceId: WS, field: "ogImage", ref } }), null);
  assert.deepEqual(seen, []);
});

test("an image asset ref is accepted after checking only its id-or-slug half", async () => {
  const { deps, seen } = refusalDeps({ ok: true });
  assert.equal(await seoImageRefRefusal({ deps, input: { workspaceId: WS, field: "ogImage", ref: " cover:og " } }), null);
  assert.deepEqual(seen, ["cover"]);
});

test("a missing asset ref is accepted (render drops it fail-soft)", async () => {
  const { deps } = refusalDeps({ ok: false, reason: "not-found" });
  assert.equal(await seoImageRefRefusal({ deps, input: { workspaceId: WS, field: "ogImage", ref: "cover:og" } }), null);
});

test("a known non-image asset ref is refused with the field, asset and content type", async () => {
  const { deps } = refusalDeps({ ok: false, reason: "not-image", contentType: "application/pdf" });
  assert.equal(
    await seoImageRefRefusal({ deps, input: { workspaceId: WS, field: "twitterImage", ref: "doc:og" } }),
    "twitterImage: media asset 'doc' is application/pdf, not an image. A social share image must be an image.",
  );
});

src/comments/__tests__/repo.dialects.tes.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { ToolInputError } from "@jini-ai/core";

import { describeEachDialect } from "../../core/__tests__/support/dialect-matrix.js";
import { createTables, tables, tableNames } from "./support/comments-tables.fixture.js";
import type { CommentRepoPort } from "../ports.js";
import { commentRepoFor } from "../sql/index.js";
import type { CommentRecord } from "../types.js";

/**
 * @file The comments repo on every dialect through the kernel's matrix. The two `p_comments__*`
 * tables are dataModule tables, absent from the migrated schema. The source `make` ran the real
 * install (`installCommentsDataModule`, on the kernel) on each dialect; this extraction uses
 * the byte-identical domain DDL fixture instead, leaving migration composition in Tovu.
 */

const WS = "ws-dialects";

// The original per-make setup dropped the dataModule tables and ran the REAL install.
// p1's matrix now creates the same domain DDL once and resets rows per make; migration
// reconciliation itself remains covered by Tovu's data-module-install.test.ts.

function comment(id: string, overrides: Partial<CommentRecord> = {}): CommentRecord {
  return {
    id,
    workspaceId: WS,
    entryId: "entry-1",
    parentId: null,
    threadRootId: id,
    depth: 0,
    status: "pending",
    authorPrincipalId: null,
    authorName: "Visitor",
    authorEmail: null,
    authorUrl: null,
    authorIpHash: null,
    bodyText: "Hello",
    spamScore: 0.25,
    spamProvider: null,
    createdAt: "2026-09-28T00:00:00.000Z",
    updatedAt: "2026-09-28T00:00:00.000Z",
    version: 0,
    ...overrides,
  };
}

describeEachDialect<CommentRepoPort>({
  title: "comments repo",
  options: {
    tables: tableNames,
    createTables,
    make: (kernel) => commentRepoFor({ kernel, tables }, {}),
  },
  body: (makeRepo) => {
    test("create round-trips, with nulls and a real spam score", async () => {
      const repo = makeRepo();
      await repo.create({ record: comment("c1") }, {});
      assert.deepEqual(await repo.findById({ workspaceId: WS, id: "c1" }), comment("c1"));
      assert.equal(await repo.findById({ workspaceId: "other", id: "c1" }), null);
    });

    test("create with a submit log is atomic: a duplicate log id rolls the comment back", async () => {
      const repo = makeRepo();
      const log = (commentId: string) => ({
        id: "log-dup",
        workspaceId: WS,
        commentId,
        actorPrincipalId: "visitor",
        action: "submit" as const,
        fromStatus: null,
        toStatus: "pending" as const,
        at: "2026-09-28T00:00:00.000Z",
        note: null,
      });
      await repo.create({ record: comment("c1") }, { submitLog: log("c1") });
      await assert.rejects(repo.create({ record: comment("c2") }, { submitLog: log("c2") }));
      assert.equal(await repo.findById({ workspaceId: WS, id: "c2" }), null);
      assert.equal((await repo.listModerationLog({ workspaceId: WS, commentId: "c1" })).length, 1);
    });

    test("the moderation queue is keyset-paginated and countByStatus scopes by entry", async () => {
      const repo = makeRepo();
      for (let i = 0; i < 5; i += 1) {
        await repo.create({ record: comment(`c${i}`, { entryId: i < 3 ? "e1" : "e2", createdAt: `2026-09-28T00:0${i}:00.000Z` }) }, {});
      }
      for (const id of ["same-time", "same-time-2", "same-time-3"]) {
        await repo.create({ record: comment(id, { createdAt: "2026-09-28T00:04:00.000Z" }) }, {});
      }
      const page1 = await repo.listModerationQueue({ workspaceId: WS, status: "pending", limit: 2 });
      assert.deepEqual(page1.items.map((c) => c.id), ["c0", "c1"]);
      const page2 = await repo.listModerationQueue({ workspaceId: WS, status: "pending", limit: 2, cursor: page1.nextCursor });
      assert.deepEqual(page2.items.map((c) => c.id), ["c2", "c3"]);
      const page3 = await repo.listModerationQueue({ workspaceId: WS, status: "pending", limit: 2, cursor: page2.nextCursor });
      assert.deepEqual(page3.items.map((c) => c.id), ["c4", "same-time"]);
      const page4 = await repo.listModerationQueue({ workspaceId: WS, status: "pending", limit: 2, cursor: page3.nextCursor });
      assert.deepEqual(page4.items.map((c) => c.id), ["same-time-2", "same-time-3"]);
      assert.equal(page4.nextCursor, null);
      assert.deepEqual([page1, page2, page3, page4].flatMap((p) => p.items.map((c) => c.id)),
        ["c0", "c1", "c2", "c3", "c4", "same-time", "same-time-2", "same-time-3"]);
      assert.equal(await repo.countByStatus({ workspaceId: WS, status: "pending" }), 8);
      assert.equal(await repo.countByStatus({ workspaceId: WS, status: "pending", entryId: "e1" }), 3);
    });

    test("a moderation-queue page resumes after its cursor comment was purged by another moderator", async () => {
      const repo = makeRepo();
      for (let i = 0; i < 4; i += 1) await repo.create({ record: comment(`c${i}`, { createdAt: `2026-09-28T00:0${i}:00.000Z` }) }, {});
      const page1 = await repo.listModerationQueue({ workspaceId: WS, status: "pending", limit: 2 });
      assert.deepEqual(page1.items.map((c) => c.id), ["c0", "c1"]);
      assert.equal((await repo.purge({ workspaceId: WS, id: "c1", actorPrincipalId: "admin", note: null, at: "2026-09-28T01:00:00.000Z" })).ok, true);
      const page2 = await repo.listModerationQueue({ workspaceId: WS, status: "pending", limit: 2, cursor: page1.nextCursor });
      assert.deepEqual(page2.items.map((c) => c.id), ["c2", "c3"]);
      assert.equal(page2.nextCursor, null);
    });

    test("a malformed moderation-queue cursor is refused, not read as page 1", async () => {
      const repo = makeRepo();
      await repo.create({ record: comment("c1") }, {});
      await repo.create({ record: comment("other-ws", { workspaceId: "other" }) }, {});
      // A real comment id (the pre-2026-10-05 cursor format), an unknown id, a non-uuid string (no 500
      // on Postgres), a real id from another workspace, then `createdAt::id` with no id, no createdAt,
      // and a createdAt that is no date.
      const malformed = ["c1", "no-such-comment", "not a uuid ' --", "other-ws", "2026-09-28T00:00:00.000Z::", "::c1", "yesterday::c1"];
      for (const cursor of malformed) {
        await assert.rejects(
          repo.listModerationQueue({ workspaceId: WS, status: "pending", limit: 2, cursor }),
          (err: unknown) => err instanceof ToolInputError && err.message === "invalid cursor"
        );
      }
    });

    test("listThreadForEntry nests replies and an empty status list yields nothing", async () => {
      const repo = makeRepo();
      await repo.create({ record: comment("root", { status: "approved" }) }, {});
      await repo.create({ record: comment("reply", { parentId: "root", threadRootId: "root", depth: 1, status: "approved", createdAt: "2026-09-28T00:01:00.000Z" }) }, {});
      const thread = await repo.listThreadForEntry({ workspaceId: WS, entryId: "entry-1" });
      assert.deepEqual(thread.map((n) => [n.comment.id, n.replies.map((r) => r.comment.id)]), [["root", ["reply"]]]);
      assert.deepEqual(await repo.listThreadForEntry({ workspaceId: WS, entryId: "entry-1", includeStatuses: [] }), []);
    });

    test("applyModeration bumps the version once, logs it, and reports conflict and not-found", async () => {
      const repo = makeRepo();
      await repo.create({ record: comment("c1") }, {});
      const moderation = { workspaceId: WS, id: "c1", expectedVersion: 0, action: "approve" as const, toStatus: "approved" as const, actorPrincipalId: "admin", note: null, at: "2026-09-28T01:00:00.000Z" };
      const ok = await repo.applyModeration(moderation);
      assert.ok(ok.ok && ok.record.status === "approved" && ok.record.version === 1);
      assert.deepEqual(await repo.applyModeration(moderation), { ok: false, reason: "conflict", currentVersion: 1 });
      assert.deepEqual(await repo.applyModeration({ ...moderation, id: "missing" }), { ok: false, reason: "not-found" });
      const log = await repo.listModerationLog({ workspaceId: WS, commentId: "c1" });
      assert.deepEqual(log.map((entry) => [entry.action, entry.fromStatus, entry.toStatus]), [["approve", "pending", "approved"]]);
    });

    test("purge deletes the comment and keeps a purge log row", async () => {
      const repo = makeRepo();
      await repo.create({ record: comment("c1") }, {});
      const purged = await repo.purge({ workspaceId: WS, id: "c1", actorPrincipalId: "admin", note: "spam", at: "2026-09-28T02:00:00.000Z" });
      assert.ok(purged.ok);
      assert.equal(await repo.findById({ workspaceId: WS, id: "c1" }), null);
      assert.deepEqual((await repo.listModerationLog({ workspaceId: WS, commentId: "c1" })).map((e) => e.action), ["purge"]);
      assert.deepEqual(await repo.purge({ workspaceId: WS, id: "c1", actorPrincipalId: "admin", note: null, at: "2026-09-28T03:00:00.000Z" }), { ok: false, reason: "not-found" });
    });
  },
}, {});

src/widgets/__tests__/integration/region.source:
import { widgetHostFixture } from "../support/host.fixture.js";
import assert from "node:assert/strict";
import test from "../support/test-runner.js";

import { InMemoryEntryRefsRepo } from "../support/host.fixture.js";
import { InMemoryContentTypeRepo } from "../../../content-types/index.js";
import { InMemoryEntryRepo } from "../../../entries/index.js";
import { parseWidgetAreaPayload } from "../support/compat/entry-payload.js";
import { WidgetAreaConflictError } from "../../errors.js";
import { createWidgetInstance, type WidgetWriteServiceDeps } from "../../write-service.js";
import { InMemoryWidgetRegionBindingRepo } from "../../repo.memory.js";
import {
  bindWidgetArea,
  mutateWidgetAreaPlacements,
  reconcileWidgetRegionBindings,
  type RegionAreaServiceDeps,
} from "../support/compat/region-area-service.js";
import { InMemoryOutbox } from "../support/host.fixture.js";

/**
 * @file C-006 `widget_area` region composition — SPEC-043 REQ-11..17, AC-06..11, INV-02/03.
 *
 * Call-site note (Programmer stage): restructured to this codebase's real `{ deps, input }`
 * convention (see `write-service.integration.test.ts`'s identical note) — every assertion below is
 * unchanged from the certified stub-era version. Written to mirror
 * `navigation/__tests__/reconcile.test.ts`'s C-009 test shape, since REQ-11/12 deliberately
 * structurally mirror `nav_location_bindings`/`reconcile.ts`.
 */

const WORKSPACE_ID = "ws-1";
const ACTOR = { principalId: "user-1" };

function makeDeps(): RegionAreaServiceDeps & WidgetWriteServiceDeps {
  let counter = 0;
  const entryRepo = new InMemoryEntryRepo();
  const contentTypeRepo = new InMemoryContentTypeRepo();
  const entryRefsRepo = new InMemoryEntryRefsRepo();
  const bindingRepo = new InMemoryWidgetRegionBindingRepo();
  return {
    host: widgetHostFixture,
    entryRepo,
    contentTypeRepo,
    entryRefsRepo,
    bindingRepo,
    clock: { nowMs: () => Date.parse("2026-07-21T00:00:00.000Z") },
    ids: { newId: () => `id-${++counter}` },
    authorize: async () => ({ allowed: true, reason: "test: always allow" }),
    outbox: new InMemoryOutbox(),
  };
}

/** A live, non-trashed widget instance in `deps`' own store — for placement-reference tests. */
async function seedWidget(deps: WidgetWriteServiceDeps, title: string): Promise<string> {
  const { instance } = await createWidgetInstance({
    deps,
    input: { workspaceId: WORKSPACE_ID, actor: ACTOR, widgetType: "text", title, config: { body: title } },
  });
  return instance.id;
}

test("AC-06/REQ-11/12: activating a theme with a footer region and no existing binding seeds exactly one widget_area entry and one binding row", async () => {
  const deps = makeDeps();
  const { areaEntry } = await bindWidgetArea({ deps, input: { workspaceId: WORKSPACE_ID, regionKey: "footer" } });

  assert.equal(areaEntry.regionKey, "footer");
  assert.equal(areaEntry.workspaceId, WORKSPACE_ID);
  assert.deepEqual(areaEntry.doc.placements, []);
});

test("AC-07/INV-02: widget_region_bindings is always derivable, in full, from live widget_area entries alone", async () => {
  const deps = makeDeps();
  const footer = (await bindWidgetArea({ deps, input: { workspaceId: WORKSPACE_ID, regionKey: "footer" } })).areaEntry;
  const sidebar = (await bindWidgetArea({ deps, input: { workspaceId: WORKSPACE_ID, regionKey: "sidebar" } })).areaEntry;
  await bindWidgetArea({ deps, input: { workspaceId: "other-workspace", regionKey: "footer" } });
  const foreign = await deps.bindingRepo.listByWorkspace({ workspaceId: "other-workspace" });
  await deps.bindingRepo.upsert({ workspaceId: WORKSPACE_ID, regionKey: "footer", areaEntryId: "wrong-area", updatedAt: "old" });
  await deps.bindingRepo.upsert({ workspaceId: WORKSPACE_ID, regionKey: "stale", areaEntryId: "missing-area", updatedAt: "old" });
  await deps.bindingRepo.markInactive({ workspaceId: WORKSPACE_ID, regionKey: "sidebar" });
  await reconcileWidgetRegionBindings({ deps, input: { workspaceId: WORKSPACE_ID } });
  assert.deepEqual((await deps.bindingRepo.listByWorkspace({ workspaceId: WORKSPACE_ID })).sort((a, b) => a.regionKey.localeCompare(b.regionKey)), [
    { workspaceId: WORKSPACE_ID, regionKey: "footer", areaEntryId: footer.id, updatedAt: "2026-07-21T00:00:00.000Z" },
    { workspaceId: WORKSPACE_ID, regionKey: "sidebar", areaEntryId: sidebar.id, updatedAt: "2026-07-21T00:00:00.000Z" },
  ]);
  assert.deepEqual(await deps.bindingRepo.listByWorkspace({ workspaceId: "other-workspace" }), foreign);
});



test("AC-10/REQ-16: a placement mutation referencing a widget from a different workspace is rejected, the area entry unchanged", async () => {
  const deps = makeDeps();
  const { areaEntry: seeded } = await bindWidgetArea({ deps, input: { workspaceId: WORKSPACE_ID, regionKey: "footer" } });
  const { instance: foreign } = await createWidgetInstance({ deps, input: {
    workspaceId: "other-workspace", actor: ACTOR, widgetType: "text", title: "Foreign widget", config: { body: "foreign body" },
  } });
  assert.ok(await deps.entryRepo.findById({ workspaceId: "other-workspace", id: foreign.id }));
  const before = structuredClone(await deps.entryRepo.findById({ workspaceId: WORKSPACE_ID, id: seeded.id }));
  const refsBefore = await deps.entryRefsRepo.findBySource({ workspaceId: WORKSPACE_ID, sourceEntryId: seeded.id });

  await assert.rejects(
    () =>
      mutateWidgetAreaPlacements({
        deps,
        input: {
          workspaceId: WORKSPACE_ID,
          actor: ACTOR,
          areaEntryId: seeded.id,
          baseVersion: seeded.version,
          placements: [{ placementId: "plc-1", widgetEntryId: foreign.id, enabled: true }],
        },
      }),
    { name: "WidgetInstanceNotFoundError", message: `placement references widget '${foreign.id}', which does not exist in workspace '${WORKSPACE_ID}'` }
  );
  assert.deepEqual(await deps.entryRepo.findById({ workspaceId: WORKSPACE_ID, id: seeded.id }), before);
  assert.deepEqual(await deps.entryRefsRepo.findBySource({ workspaceId: WORKSPACE_ID, sourceEntryId: seeded.id }), refsBefore);
});

test("EC-02/REQ-15: two concurrent reorders of the same region — one wins under OCC, the other must retry against the new version", async () => {
  const deps = makeDeps();
  const { areaEntry: seeded } = await bindWidgetArea({ deps, input: { workspaceId: WORKSPACE_ID, regionKey: "sidebar" } });
  const widgetA = await seedWidget(deps, "Widget A");
  const widgetB = await seedWidget(deps, "Widget B");

  const [a, b] = await Promise.allSettled([
    mutateWidgetAreaPlacements({
      deps,
      input: {
        workspaceId: WORKSPACE_ID,
        actor: ACTOR,
        areaEntryId: seeded.id,
        baseVersion: seeded.version,
        placements: [{ placementId: "plc-a", widgetEntryId: widgetA, enabled: true }],
      },
    }),
    mutateWidgetAreaPlacements({
      deps,
      input: {
        workspaceId: WORKSPACE_ID,
        actor: ACTOR,
        areaEntryId: seeded.id,
        baseVersion: seeded.version,
        placements: [{ placementId: "plc-b", widgetEntryId: widgetB, enabled: true }],
      },
    }),
  ]);

  const settled = [a, b];
  assert.equal(settled.filter((r) => r.status === "fulfilled").length, 1, "exactly one concurrent reorder must succeed");
  assert.equal(settled.filter((r) => r.status === "rejected").length, 1, "exactly one concurrent reorder must be rejected as a conflict — no silent last-writer-wins");
  const winner = settled.find((result) => result.status === "fulfilled")!;
  const loser = settled.find((result) => result.status === "rejected")!;
  assert.equal(winner.status, "fulfilled");
  assert.equal(loser.status, "rejected");
  if (winner.status !== "fulfilled" || loser.status !== "rejected") throw new Error("invalid settlement");
  assert.ok(loser.reason instanceof WidgetAreaConflictError);
  assert.equal(loser.reason.currentVersion, seeded.version + 1);
  const winningPlacements = a.status === "fulfilled"
    ? [{ placementId: "plc-a", widgetEntryId: widgetA, enabled: true }]
    : [{ placementId: "plc-b", widgetEntryId: widgetB, enabled: true }];
  const losingPlacements = a.status === "rejected"
    ? [{ placementId: "plc-a", widgetEntryId: widgetA, enabled: true }]
    : [{ placementId: "plc-b", widgetEntryId: widgetB, enabled: true }];
  const persisted = await deps.entryRepo.findById({ workspaceId: WORKSPACE_ID, id: seeded.id });
  assert.ok(persisted);
  assert.deepEqual(parseWidgetAreaPayload(persisted.fieldsJson).doc.placements, winningPlacements);
  const retried = await mutateWidgetAreaPlacements({ deps, input: {
    workspaceId: WORKSPACE_ID, actor: ACTOR, areaEntryId: seeded.id, baseVersion: loser.reason.currentVersion, placements: losingPlacements,
  } });
  assert.equal(retried.areaEntry.version, seeded.version + 2);
  assert.deepEqual(parseWidgetAreaPayload((await deps.entryRepo.findById({ workspaceId: WORKSPACE_ID, id: seeded.id }))!.fieldsJson).doc.placements, losingPlacements);
});

