import assert from "node:assert/strict";
import { test } from "vitest";

import {
  buildQueryableFieldIndexName,
  mapFieldKindToCast,
  validateIdentifierGrammar,
} from "../index-provisioning.js";
import { InvalidFieldKindError, InvalidFieldNameGrammarError, InvalidKeyGrammarError } from "../errors.js";

/**
 * @file `index-provisioning.ts`'s fixed `kind`→`CAST` lookup table and
 * field-name/key grammar gate.
 *
 * THIS IS THE HIGHEST-PRIORITY TEST FILE IN THE ENTIRE 5-PACKAGE PIPELINE — DDL-injection
 * prevention is this package's single highest-security-severity property (CIC
 * Downstream Handoff Notes). Per the audit-corrected GOV- and three
 * Binding constraints:
 *
 * - : `kind`->`CAST` is a fixed lookup table, never a template/string-interpolation
 * construction from the `kind` value. (2026-09-05: the table gained a sixth KEY, `relation`,
 * whose value is the already-present literal `TEXT`. The invariant is about the table's VALUE
 * set — the strings that can reach a `CAST` position — which is unchanged. Every assertion in
 * this file is untouched and still passes; the value-set invariant itself is pinned by
 * `field-kind-widening.test.ts`.)
 * - : a field `name` (or content-type `key`) is used in generated DDL only after passing
 * the grammar gate `^[a-z][a-z0-9_]{0,63}$`, and only in an index-name segment or the sanctioned
 * JSON-path-literal key position — never any other position.
 * - : when joining two or more grammar-gated identifiers into one identity string, the
 * delimiter MUST be outside the grammar's own alphabet (`[a-z0-9_]`) — e.g. `/`, never `_` —
 * to prevent namespace-injectivity collisions between distinct `(key, name)` pairs.
 *
 * TDD does not assert private helper names or branch layout — every assertion below is against
 * the exported function's observable return value or thrown typed error (per the CIC's
 * Verification Surface Rule).
 * See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
 */

/** The five original scalars, restated literally on purpose: this file's job is to prove THESE
 *  five still behave exactly as certified, so it must not follow the enum if the enum widens. */
const CLOSED_KIND_ENUM = ["text", "integer", "real", "boolean", "datetime"] as const;

test("U-001-B1: mapFieldKindToCast returns a fixed, hardcoded CAST literal for each of the exactly 5 enum kinds, deterministically (same input, same output, every call)", () => {
  for (const kind of CLOSED_KIND_ENUM) {
    const first = mapFieldKindToCast({ kind: kind });
    const second = mapFieldKindToCast({ kind: kind });
    assert.equal(typeof first, "string");
    assert.ok(first.length > 0);
    assert.equal(first, second, "a fixed lookup table must return the identical literal on every call for the same kind");
    // A fixed-table literal must be a plain SQL type token — no quotes, parens, semicolons, or
    // whitespace, which would be the shape of an interpolated/constructed string rather than a
    // hardcoded table entry.
    assert.equal(/['";()\s]/.test(first), false, `CAST literal for '${kind}' must contain no injection-shaped characters, got: ${first}`);
  }
});

test("U-001-B1 (AC-07): the CAST literal for 'integer' comes only from the fixed table entry, never from any operator-supplied string", () => {
  const castLiteral = mapFieldKindToCast({ kind: "integer" });
  // A fixed lookup table's output for 'integer' must be a specific, unchanging SQL type token
  // (e.g. 'INTEGER') — assert it is a plain identifier-shaped SQL type, not an arbitrary echo.
  assert.match(castLiteral, /^[A-Z]+$/, "expected a plain uppercase SQL type token from the fixed table, not an interpolated string");
});

test("U-001-B1/AC-06 (adversarial): a kind value containing a SQL-injection payload is rejected with InvalidFieldKindError before any DDL-relevant value is produced", () => {
  const injectionPayloads = [
    "text'); DROP TABLE entries;--",
    "integer; DELETE FROM content_types;",
    "TEXT COLLATE NOCASE",
    "'; --",
    "text\" AS x --",
  ];

  for (const payload of injectionPayloads) {
    assert.throws(
      () => mapFieldKindToCast({ kind: payload as never }),
      InvalidFieldKindError,
      `payload '${payload}' must be rejected as InvalidFieldKindError, never silently mapped`
    );
  }
});

test("U-001-B1 (property): for any string not exactly equal to one of the 5 enum values, mapFieldKindToCast always throws InvalidFieldKindError, never returns a value", () => {
  const candidates = [
    "Text", // case-sensitivity
    "texts",
    "int",
    "",
    " text",
    "text ",
    "text;integer",
    "�text",
    "text\n",
  ];

  for (const candidate of candidates) {
    assert.throws(() => mapFieldKindToCast({ kind: candidate as never }), InvalidFieldKindError);
  }
});

test("U-001-B2 (AC-05, EC-02): an adversarial field name containing a quote/DDL metacharacter is rejected by the grammar gate before any DDL is constructed", () => {
  const adversarialNames = [
    'name"; DROP TABLE entries;--',
    "name'; DROP TABLE entries;--",
    "field.name",
    "field name",
    "field-name",
    "field$name",
    "Field",
    "1field",
  ];

  for (const name of adversarialNames) {
    assert.equal(validateIdentifierGrammar({ value: name }), false, `'${name}' must fail the grammar gate`);
    assert.throws(
      () => buildQueryableFieldIndexName({ workspaceId: "ws-1", contentTypeKey: "recipe", fieldName: name }),
      InvalidFieldNameGrammarError
    );
  }
});

test("U-001-B2/INV-03: a valid grammar-conforming field name and content-type key both pass validateIdentifierGrammar", () => {
  for (const value of ["price", "prep_time_minutes", "a", "field_123", "a".repeat(64)]) {
    assert.equal(validateIdentifierGrammar({ value: value }), true, `'${value}' should be grammar-valid`);
  }
});

test("U-001-B2/behavior.spec.md §7: a key/field name of exactly 65 characters is rejected (grammar caps at 64)", () => {
  const tooLong = "a".repeat(65);
  assert.equal(validateIdentifierGrammar({ value: tooLong }), false);
});

test("U-001-B2: a content-type key with SQL-injection-shaped content is rejected by buildQueryableFieldIndexName before any index name is produced", () => {
  assert.throws(
    () => buildQueryableFieldIndexName({ workspaceId: "ws-1", contentTypeKey: "recipe'; DROP TABLE entries;--", fieldName: "price" }),
    InvalidKeyGrammarError
  );
});

test("U-001-B3 (property): no two distinct (contentTypeKey, fieldName) pairs ever encode to the same joined index-identity string", async () => {
  // The classic delimiter-injectivity collision: 'a_b' + 'c' vs 'a' + 'b_c' must NOT collide if
  // the delimiter is outside the grammar alphabet (e.g. '/'), unlike an '_'-joined encoding.
  const pairA = { workspaceId: "ws-1", contentTypeKey: "a_b", fieldName: "c" };
  const pairB = { workspaceId: "ws-1", contentTypeKey: "a", fieldName: "b_c" };

  const nameA = await buildQueryableFieldIndexName(pairA);
  const nameB = await buildQueryableFieldIndexName(pairB);

  assert.notEqual(nameA, nameB, "distinct (key, name) pairs must never collide on index identity (U-001-B3, namespace-injectivity)");
});

test("U-001-B3: the joining delimiter used is outside the grammar's own alphabet ([a-z0-9_])", async () => {
  const name = await buildQueryableFieldIndexName({ workspaceId: "ws-1", contentTypeKey: "recipe", fieldName: "price" });
  // Every segment of the joined identity must itself be grammar-valid; the delimiter between
  // segments must not itself be a character the grammar permits inside an identifier.
  const segments = name.split(/[^a-z0-9_]/).filter(Boolean);
  assert.ok(segments.length >= 2, "expected at least 2 identifier segments joined by a non-grammar delimiter");
  for (const segment of segments) {
    assert.equal(validateIdentifierGrammar({ value: segment }), true);
  }
  assert.equal(name.includes("_/_"), false); // sanity: not literally re-using '_' as the joiner disguised
});

test("AC-10/EC-04 (property): two different workspaces registering the same key + field name produce distinct index identities, never colliding", async () => {
  const nameWorkspaceOne = await buildQueryableFieldIndexName({ workspaceId: "ws-1", contentTypeKey: "recipe", fieldName: "price" });
  const nameWorkspaceTwo = await buildQueryableFieldIndexName({ workspaceId: "ws-2", contentTypeKey: "recipe", fieldName: "price" });

  assert.notEqual(nameWorkspaceOne, nameWorkspaceTwo, "REQ-06: index identity must include a workspace-scoped segment");
});

