import { describe, expect, it } from "vitest";

import type { ContentTypeFieldDef } from "../../content-types/types.js";
import { selectVisibleEntryFields, validateFieldsAgainstSchema } from "../field-validation.js";

/**
 * @file Boundary pins for `validateFieldsAgainstSchema`: every envelope-shape refusal, the scalar
 * kinds the main suites do not exercise, the unknown-kind fallback, and the order in which the
 * per-key and required-field passes report their errors.
 */

function def(name: string, kind: ContentTypeFieldDef["kind"], required = false): ContentTypeFieldDef {
  return { name, kind, required, queryable: false };
}

const ENVELOPE_SITE = {
  valid: false,
  fieldErrors: [{ field: "__envelope__", reason: "fieldsJson must be wrapped in the { ext: { site: {...} } } envelope shape" }],
};

describe("envelope shape", () => {
  it("rejects a null fieldsJson with the envelope error", () => {
    expect(validateFieldsAgainstSchema({ schema: [], fieldsJson: null })).toEqual(ENVELOPE_SITE);
  });

  it("rejects an array fieldsJson with the envelope error", () => {
    expect(validateFieldsAgainstSchema({ schema: [], fieldsJson: [] })).toEqual(ENVELOPE_SITE);
  });

  it("rejects a non-object ext with the envelope error", () => {
    expect(validateFieldsAgainstSchema({ schema: [], fieldsJson: { ext: "site" } })).toEqual(ENVELOPE_SITE);
  });

  it("rejects an ext missing the owner bag with the envelope error", () => {
    expect(validateFieldsAgainstSchema({ schema: [], fieldsJson: { ext: { other: {} } } })).toEqual(ENVELOPE_SITE);
  });

  it("rejects a non-object owner bag with the envelope error", () => {
    expect(validateFieldsAgainstSchema({ schema: [], fieldsJson: { ext: { site: 3 } } })).toEqual(ENVELOPE_SITE);
  });

  it("names a non-default owner in the envelope error", () => {
    expect(validateFieldsAgainstSchema({ schema: [], fieldsJson: { ext: { site: {} } } }, { owner: "widget" })).toEqual({
      valid: false,
      fieldErrors: [{ field: "__envelope__", reason: "fieldsJson must be wrapped in the { ext: { widget: {...} } } envelope shape" }],
    });
  });

  it("accepts an empty owner bag against an empty schema", () => {
    expect(validateFieldsAgainstSchema({ schema: [], fieldsJson: { ext: { site: {} } } })).toEqual({ valid: true, fieldErrors: [] });
  });
});

describe("scalar kinds", () => {
  it("real accepts a fractional number", () => {
    expect(validateFieldsAgainstSchema({ schema: [def("r", "real")], fieldsJson: { ext: { site: { r: 1.5 } } } }).valid).toBe(true);
  });

  it("real rejects a numeric string", () => {
    expect(validateFieldsAgainstSchema({ schema: [def("r", "real")], fieldsJson: { ext: { site: { r: "1.5" } } } }).fieldErrors).toEqual([
      { field: "r", reason: "value does not conform to the declared kind 'real'" },
    ]);
  });

  it("integer rejects a fractional number", () => {
    expect(validateFieldsAgainstSchema({ schema: [def("i", "integer")], fieldsJson: { ext: { site: { i: 1.5 } } } }).fieldErrors).toEqual([
      { field: "i", reason: "value does not conform to the declared kind 'integer'" },
    ]);
  });

  it("boolean accepts false", () => {
    expect(validateFieldsAgainstSchema({ schema: [def("b", "boolean")], fieldsJson: { ext: { site: { b: false } } } }).valid).toBe(true);
  });

  it("boolean rejects the number 0", () => {
    expect(validateFieldsAgainstSchema({ schema: [def("b", "boolean")], fieldsJson: { ext: { site: { b: 0 } } } }).fieldErrors).toEqual([
      { field: "b", reason: "value does not conform to the declared kind 'boolean'" },
    ]);
  });

  it("datetime accepts any string", () => {
    expect(validateFieldsAgainstSchema({ schema: [def("d", "datetime")], fieldsJson: { ext: { site: { d: "not-a-date" } } } }).valid).toBe(true);
  });

  it("rejects every value for a kind this module has no arm for (schema drift from persisted data)", () => {
    // Parsed rather than cast: this is the shape a row written by a newer schema version arrives in.
    const drifted: ContentTypeFieldDef = JSON.parse('{"name":"c","kind":"color","required":false,"queryable":false}');
    expect(validateFieldsAgainstSchema({ schema: [drifted], fieldsJson: { ext: { site: { c: "#fff" } } } }).fieldErrors).toEqual([
      { field: "c", reason: "value does not conform to the declared kind 'color'" },
    ]);
  });
});

describe("json kind edges", () => {
  it("json accepts a null-prototype object", () => {
    const bag = Object.assign(Object.create(null) as Record<string, unknown>, { a: 1 });
    expect(validateFieldsAgainstSchema({ schema: [def("j", "json")], fieldsJson: { ext: { site: { j: bag } } } }).valid).toBe(true);
  });

  it("json rejects an array containing a non-finite number", () => {
    expect(validateFieldsAgainstSchema({ schema: [def("j", "json")], fieldsJson: { ext: { site: { j: [1, Number.NaN] } } } }).fieldErrors).toEqual([
      { field: "j", reason: "value does not conform to the declared kind 'json'" },
    ]);
  });

  it("json accepts exactly 10000 nodes and rejects 10001", () => {
    const ok = new Array<number>(9_999).fill(0);
    const tooMany = new Array<number>(10_000).fill(0);
    expect(validateFieldsAgainstSchema({ schema: [def("j", "json")], fieldsJson: { ext: { site: { j: ok } } } }).valid).toBe(true);
    expect(validateFieldsAgainstSchema({ schema: [def("j", "json")], fieldsJson: { ext: { site: { j: tooMany } } } }).valid).toBe(false);
  });

  it("each json field gets its own node budget", () => {
    const big = new Array<number>(9_999).fill(0);
    const result = validateFieldsAgainstSchema({
      schema: [def("a", "json"), def("b", "json")],
      fieldsJson: { ext: { site: { a: big, b: big } } },
    });
    expect(result).toEqual({ valid: true, fieldErrors: [] });
  });
});

describe("error ordering", () => {
  it("reports per-key errors in submitted-key order, then missing required fields in schema order", () => {
    const result = validateFieldsAgainstSchema({
      schema: [def("req1", "text", true), def("n", "integer"), def("req2", "text", true)],
      fieldsJson: { ext: { site: { zzz: 1, n: "x" } } },
    });
    expect(result).toEqual({
      valid: false,
      fieldErrors: [
        { field: "zzz", reason: "unrecognized field: not present in the current content-type schema" },
        { field: "n", reason: "value does not conform to the declared kind 'integer'" },
        { field: "req1", reason: "required field is missing" },
        { field: "req2", reason: "required field is missing" },
      ],
    });
  });

  it("treats a required field present with a non-conforming value as non-conforming, not missing", () => {
    const result = validateFieldsAgainstSchema({ schema: [def("t", "text", true)], fieldsJson: { ext: { site: { t: 5 } } } });
    expect(result.fieldErrors).toEqual([{ field: "t", reason: "value does not conform to the declared kind 'text'" }]);
  });

  it("treats a required field inherited through the bag's prototype as missing", () => {
    const bag = Object.create({ t: "inherited" }) as Record<string, unknown>;
    const result = validateFieldsAgainstSchema({ schema: [def("t", "text", true)], fieldsJson: { ext: { site: bag } } });
    expect(result.fieldErrors).toEqual([{ field: "t", reason: "required field is missing" }]);
  });
});

describe("selectVisibleEntryFields envelope tolerance", () => {
  const contentType = { fields: [def("title", "text")] };

  it("returns an empty projection for a non-object fieldsJson", () => {
    expect(selectVisibleEntryFields({ entry: { fieldsJson: "x" }, contentType })).toEqual({});
  });

  it("returns an empty projection for a non-object ext", () => {
    expect(selectVisibleEntryFields({ entry: { fieldsJson: { ext: null } }, contentType })).toEqual({});
  });

  it("returns an empty projection for an array site bag", () => {
    expect(selectVisibleEntryFields({ entry: { fieldsJson: { ext: { site: ["title"] } } }, contentType })).toEqual({});
  });

  it("reads only the site namespace, never another owner's bag", () => {
    expect(selectVisibleEntryFields({ entry: { fieldsJson: { ext: { widget: { title: "w" } } } }, contentType })).toEqual({});
  });
});

src/comments/express/__tests__/submit-ha.source:
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import type { Request, Response } from "express";
import { afterEach, test, vi } from "vitest";
import type { CommentIngressResult } from "../../ports.js";
import type { CommentRecord, CommentSubmission } from "../../types.js";
import { createCommentSubmitHandler, type CommentSubmitRequired } from "../index.js";

const SALT = "host-owned-salt";
const CLIENT_IP = "203.0.113.1";
const IP_HASH = createHash("sha256").update(`${CLIENT_IP}:${SALT}`).digest("hex");

const ACCEPTED: CommentRecord = {
  id: "comment-1", workspaceId: "workspace-1", entryId: "entry-1", parentId: null, threadRootId: "comment-1",
  depth: 0, status: "pending", authorPrincipalId: null, authorName: "Ada", authorEmail: null, authorUrl: null,
  authorIpHash: IP_HASH, bodyText: "hello", spamScore: null, spamProvider: null,
  createdAt: "2026-01-01T00:00:00.000Z", updatedAt: "2026-01-01T00:00:00.000Z", version: 1,
};

interface Harness {
  deps: CommentSubmitRequired;
  submissions: CommentSubmission[];
}

function harness(optional: { submit?: () => Promise<CommentIngressResult>; overrides?: Partial<CommentSubmitRequired> } = {}): Harness {
  const submissions: CommentSubmission[] = [];
  const submit = optional.submit ?? (async () => ({ ok: true, comment: ACCEPTED, autoClassified: "pending" }) as const);
  const deps: CommentSubmitRequired = {
    workspaceId: "workspace-1", ipHashSalt: SALT,
    clientIp: () => CLIENT_IP,
    rateLimiter: { check: async () => ({ allowed: true }) },
    ingressPolicy: { submit: async (submission) => { submissions.push(submission); return submit(); } },
    ...optional.overrides,
  };
  return { deps, submissions };
}

async function send(deps: CommentSubmitRequired, body: unknown): Promise<{ status?: number; payload?: unknown }> {
  const out: { status?: number; payload?: unknown } = {};
  const response = {
    status(code: number) { out.status = code; return this; },
    json(payload: unknown) { out.payload = payload; return this; },
  };
  const request = { body, ip: "untrusted-request-ip" } as Request;
  await createCommentSubmitHandler(deps, {})(request, response as Response, () => assert.fail("unexpected next call"));
  return out;
}

afterEach(() => { vi.restoreAllMocks(); });

test("an accepted submission answers 201 with only the comment id and status", async () => {
  const { deps } = harness();
  const out = await send(deps, { entryId: "entry-1", body: "hello" });
  assert.equal(out.status, 201);
  assert.deepEqual(out.payload, { id: "comment-1", status: "pending" });
});

test("a full body is normalized into the submission with lengths clamped", async () => {
  const { deps, submissions } = harness();
  await send(deps, {
    entryId: "entry-1", parentId: "parent-1", body: "hello", website: "bot-filled",
    authorName: "n".repeat(250), authorEmail: "e".repeat(400), authorUrl: "u".repeat(2500),
  });
  assert.deepEqual(submissions, [{
    workspaceId: "workspace-1", entryId: "entry-1", parentId: "parent-1",
    authorName: "n".repeat(200), authorEmail: "e".repeat(320), authorUrl: "u".repeat(2000),
    bodyRaw: "hello", authorPrincipalId: null,
    ingressContext: { authorIpHash: IP_HASH, honeypotValue: "bot-filled" },
  }]);
});

test("an empty body defaults required strings to empty and optional ones to null", async () => {
  const { deps, submissions } = harness();
  await send(deps, {});
  assert.deepEqual(submissions, [{
    workspaceId: "workspace-1", entryId: "", parentId: null, authorName: "", authorEmail: null, authorUrl: null,
    bodyRaw: "", authorPrincipalId: null, ingressContext: { authorIpHash: IP_HASH, honeypotValue: "" },
  }]);
});

test("a non-string honeypot field is treated as empty", async () => {
  const { deps, submissions } = harness();
  await send(deps, { website: 42 });
  assert.equal(submissions[0]?.ingressContext.honeypotValue, "");
});

test("an ingress failure answers a generic 500 and logs the cause", async () => {
  const cause = new Error("store down");
  const log = vi.spyOn(console, "error").mockImplementation(() => {});
  const { deps } = harness({ submit: async () => { throw cause; } });
  const out = await send(deps, { entryId: "entry-1" });
  assert.equal(out.status, 500);
  assert.deepEqual(out.payload, { error: "internal error", code: "INTERNAL_ERROR" });
  assert.deepEqual(log.mock.calls, [["[site/comments-submit] unexpected error", cause]]);
});

test("a rate-limiter failure answers a generic 500", async () => {
  vi.spyOn(console, "error").mockImplementation(() => {});
  const { deps } = harness({ overrides: { rateLimiter: { check: async () => { throw new Error("redis down"); } } } });
  const out = await send(deps, { entryId: "entry-1" });
  assert.deepEqual([out.status, out.payload], [500, { error: "internal error", code: "INTERNAL_ERROR" }]);
});

test("a clientIp policy failure answers a generic 500", async () => {
  vi.spyOn(console, "error").mockImplementation(() => {});
  const { deps } = harness({ overrides: { clientIp: () => { throw new Error("no trusted proxy"); } } });
  const out = await send(deps, { entryId: "entry-1" });
  assert.deepEqual([out.status, out.payload], [500, { error: "internal error", code: "INTERNAL_ERROR" }]);
});

// A request with no parsed body (host forgot a JSON body parser, or a non-JSON content type) is a
// client/host error, yet it surfaces as a 500 rather than a 4xx.
test("a request with no parsed body answers 500, not a 4xx (reported, not fixed)", async () => {
  vi.spyOn(console, "error").mockImplementation(() => {});
  const { deps, submissions } = harness();
  const out = await send(deps, undefined);
  assert.deepEqual([out.status, out.payload], [500, { error: "internal error", code: "INTERNAL_ERROR" }]);
  assert.equal(submissions.length, 0);
});

test('host-selected form redirects use 303 and keep pending/rejected records private', async () => {
  for (const accepted of [true, false]) {
    const { deps } = harness({ submit: async () => accepted
      ? { ok: true, comment: ACCEPTED, autoClassified: 'pending' }
      : { ok: false, reason: 'entry-not-found' } });
    let redirect: unknown;
    const response = { redirect: (status: number, location: string) => { redirect = { status, location }; } };
    await createCommentSubmitHandler(deps, { formRedirect: () => '/entry' })(
      { body: {} } as Request, response as unknown as Response, () => undefined);
    assert.deepEqual(redirect, { status: 303, location: `/entry#${accepted ? 'comment-pending' : 'comment-error'}` });
  }
  const { deps: trapped } = harness({ submit: async () => ({ ok: false, reason: 'honeypot-tripped' }) });
  let trappedRedirect: unknown;
  await createCommentSubmitHandler(trapped, { formRedirect: () => '/entry' })({ body: {} } as Request,
    { redirect: (status: number, location: string) => { trappedRedirect = { status, location }; } } as unknown as Response, () => undefined);
  assert.deepEqual(trappedRedirect, { status: 303, location: '/entry#comment-pending' }, 'a bot cannot tell it was trapped');
  const { deps } = harness();
  let payload: unknown;
  const response = { status() { return response; }, json(value: unknown) { payload = value; } };
  await createCommentSubmitHandler(deps, { formRedirect: () => undefined })({ body: {} } as Request, response as unknown as Response, () => undefined);
  assert.deepEqual(payload, { id: ACCEPTED.id, status: 'pending' });
});

test('trusted-proxy client resolution produces independent salted visitor rate-limit keys', async () => {
  const keys: string[] = [];
  const { deps } = harness({ overrides: { clientIp: ({ request }) => request.ip!, rateLimiter: { check: async ({ key }) => { keys.push(key); return { allowed: true }; } } } });
  const response = { status() { return response; }, json() { return response; } };
  for (const ip of ['203.0.113.1', '203.0.113.2']) await createCommentSubmitHandler(deps)({ body: {}, ip } as Request, response as unknown as Response, () => undefined);
  assert.equal(new Set(keys).size, 2);
  assert.ok(keys.every(key => /^[a-f0-9]{64}$/.test(key)));
});

src/forms/delivery/__tests__/planner.uni.source:
/**
 * @file Unit tests for the planner: which bindings a submission selects, what the frozen child jobs
 * contain, and that a stored plan is reused rather than rebuilt (contract §5).
 */
import { describe, expect, test } from "vitest";
import {
  FORM_DELIVERY_EVENT,
  planFormDeliveries,
  type FormDeliveryBinding,
  type FormDeliveryPlan,
  type FormDeliveryPlannerDeps,
  type FormDeliveryPlanPort,
  type FormDeliverySnapshot,
} from "../index.js";

const NOW = "2026-10-20T12:00:00.000Z";
const binding = (bindingId: string, patch: Partial<FormDeliveryBinding> = {}): FormDeliveryBinding =>
  ({ bindingId, adapterId: "rows", connectionRef: `conn-${bindingId}`, enabled: true, config: { table: bindingId }, ...patch });
const snapshot: FormDeliverySnapshot = {
  form: { slug: "contact", fields: [{ name: "email", required: true, label: "Email", type: "email" }] },
  submission: { id: "s-1", answers: { email: "a@example.test" }, submittedAt: "2026-10-20T11:59:00.000Z" },
};

/** Typed fake of the host plan store: stores the first built plan per (workspace, submission). */
class MemoryPlans implements FormDeliveryPlanPort {
  readonly stored = new Map<string, FormDeliveryPlan>();
  builds = 0;
  async once(required: { workspaceId: string; submissionId: string; build: () => Promise<FormDeliveryPlan> }): Promise<FormDeliveryPlan> {
    const key = JSON.stringify([required.workspaceId, required.submissionId]);
    const existing = this.stored.get(key);
    if (existing) return existing;
    this.builds++;
    const plan = await required.build();
    this.stored.set(key, plan);
    return plan;
  }
}

function setup(bindings: FormDeliveryBinding[], source: FormDeliverySnapshot | null = snapshot) {
  const calls = { snapshot: [] as Array<{ workspaceId: string; submissionId: string; formId: string }>, bindings: [] as string[], now: 0 };
  let id = 0;
  const plans = new MemoryPlans();
  const deps: FormDeliveryPlannerDeps = {
    plans,
    bindings: async ({ workspaceId }) => { calls.bindings.push(workspaceId); return bindings; },
    snapshot: async input => { calls.snapshot.push(input); return source; },
    newId: () => `job-${++id}`,
    nowIso: () => { calls.now++; return NOW; },
  };
  const plan = (submissionId = "s-1") => planFormDeliveries({ deps, workspaceId: "w-1", submissionId, formId: "f-1" });
  return { deps, plans, calls, plan };
}

describe("selection", () => {
  test("a binding without formIds selects every form", async () => {
    const { plan } = setup([binding("all")]);
    expect((await plan()).jobs.map(job => job.payload.binding.bindingId)).toEqual(["all"]);
  });

  test("a binding listing the form selects it", async () => {
    const { plan } = setup([binding("listed", { formIds: ["other", "f-1"] })]);
    expect((await plan()).jobs).toHaveLength(1);
  });

  test("a binding listing only other forms does not select it", async () => {
    const { plan } = setup([binding("elsewhere", { formIds: ["other"] })]);
    expect((await plan()).jobs).toEqual([]);
  });

  test("a binding with an empty formIds list selects no form", async () => {
    const { plan } = setup([binding("none", { formIds: [] })]);
    expect((await plan()).jobs).toEqual([]);
  });

  test("a disabled binding is skipped even when it lists the form", async () => {
    const { plan } = setup([binding("off", { enabled: false, formIds: ["f-1"] })]);
    expect((await plan()).jobs).toEqual([]);
  });

  test("reads bindings of the event's workspace", async () => {
    const { plan, calls } = setup([]);
    await plan();
    expect(calls.bindings).toEqual(["w-1"]);
  });
});

describe("empty selection", () => {
  test("records a plan with no jobs and never reads the snapshot", async () => {
    const { plan, plans, calls } = setup([binding("off", { enabled: false })]);
    expect(await plan()).toEqual({ workspaceId: "w-1", submissionId: "s-1", formId: "f-1", jobs: [] });
    expect(plans.stored.size).toBe(1);
    expect(calls.snapshot).toEqual([]);
  });

  test("a binding added after an empty plan never backfills that submission", async () => {
    const bindings: FormDeliveryBinding[] = [];
    const { plan } = setup(bindings);
    await plan();
    bindings.push(binding("late"));
    expect((await plan()).jobs).toEqual([]);
  });
});

describe("frozen jobs", () => {
  test("one child job per selected binding, with its own id, the event name, and one shared timestamp", async () => {
    const { plan, calls } = setup([binding("a"), binding("skip", { enabled: false }), binding("b")]);
    const result = await plan();
    expect(result.jobs.map(({ id, name, workspaceId, aggregateId, occurredAt }) => ({ id, name, workspaceId, aggregateId, occurredAt }))).toEqual([
      { id: "job-1", name: FORM_DELIVERY_EVENT, workspaceId: "w-1", aggregateId: "s-1", occurredAt: NOW },
      { id: "job-2", name: FORM_DELIVERY_EVENT, workspaceId: "w-1", aggregateId: "s-1", occurredAt: NOW },
    ]);
    expect(calls.now).toBe(1);
  });

  test("each payload carries its binding, the snapshot and a key built from (submissionId, bindingId)", async () => {
    const { plan } = setup([binding("a"), binding("b")]);
    const [first, second] = (await plan()).jobs;
    expect(first!.payload).toEqual({ binding: binding("a"), snapshot, idempotencyKey: '["s-1","a"]' });
    expect(second!.payload.idempotencyKey).toBe('["s-1","b"]');
  });

  test("the key cannot collide when ids contain the separator a joined string would use", async () => {
    // "s-1:x" + "y" and "s-1" + "x:y" would both join to "s-1:x:y".
    const [left] = (await setup([binding("y")]).plan("s-1:x")).jobs;
    const [right] = (await setup([binding("x:y")]).plan("s-1")).jobs;
    expect(left!.payload.idempotencyKey).not.toBe(right!.payload.idempotencyKey);
  });

  test("reads the snapshot for the event's workspace, submission and form", async () => {
    const { plan, calls } = setup([binding("a")]);
    await plan();
    expect(calls.snapshot).toEqual([{ workspaceId: "w-1", submissionId: "s-1", formId: "f-1" }]);
  });

  test("copies only the delivered form and submission fields from a wider host row", async () => {
    // Malformed on purpose: a host reader that returns whole stored rows.
    const wide = {
      form: { ...snapshot.form, notify: { recipients: ["owner@example.test"] }, status: "active" },
      submission: { ...snapshot.submission, sourceIp: "198.51.100.7", formDefinitionId: "f-1" },
      extra: "unexpected",
    } as FormDeliverySnapshot;
    const { plan } = setup([binding("a")], wide);
    expect((await plan()).jobs[0]!.payload.snapshot).toEqual(snapshot);
  });
});

describe("missing source", () => {
  test("throws naming the submission and form when bindings matched but the snapshot is gone", async () => {
    const { plan, plans } = setup([binding("a")], null);
    await expect(plan()).rejects.toThrow(
      "Form delivery planning failed: submission s-1 or form f-1 was not found; the source event will retry.");
    expect(plans.stored.size).toBe(0);
  });
});

describe("replay", () => {
  test("returns the stored plan, unchanged, after the bindings changed", async () => {
    const bindings = [binding("a")];
    const { plan, plans } = setup(bindings);
    const first = await plan();
    bindings.splice(0, 1, binding("b"));
    const replay = await plan();
    expect(replay).toEqual(first);
    expect(replay.jobs.map(job => job.id)).toEqual(["job-1"]);
    expect(plans.builds).toBe(1);
  });

  test("asks the plan store by workspace and submission", async () => {
    const seen: Array<{ workspaceId: string; submissionId: string }> = [];
    const { deps } = setup([]);
    const plans: FormDeliveryPlanPort = { once: async ({ workspaceId, submissionId, build }) => { seen.push({ workspaceId, submissionId }); return build(); } };
    await planFormDeliveries({ deps: { ...deps, plans }, workspaceId: "w-2", submissionId: "s-9", formId: "f-1" });
    expect(seen).toEqual([{ workspaceId: "w-2", submissionId: "s-9" }]);
  });
});

