import assert from "node:assert/strict";
import { test } from "vitest";

import { validateSubmissionPayload } from "../forms.js";
import type { FormDefinitionRecord } from "../types.js";

const NOW = "2026-07-13T00:00:00.000Z";

function definition(overrides: Partial<FormDefinitionRecord> = {}): FormDefinitionRecord {
  return {
    id: "def-1",
    workspaceId: "ws-1",
    name: "Contact",
    slug: "contact",
    fields: [
      { id: "name", label: "Name", type: "text", required: true },
      { id: "email", label: "Email", type: "email", required: true },
      { id: "message", label: "Message", type: "textarea", required: false, maxLength: 100 },
      { id: "subscribe", label: "Subscribe", type: "checkbox", required: false },
    ],
    notify: { enabled: false, recipients: [] },
    status: "active",
    version: 1,
    createdAt: NOW,
    updatedAt: NOW,
    ...overrides,
  };
}

function errorsOf(body: Record<string, unknown>, def: FormDefinitionRecord = definition()) {
  const result = validateSubmissionPayload({ definition: def, body });
  assert.equal(result.valid, false, "expected this body to be rejected");
  return result.valid === false ? result.fieldErrors : [];
}

// ---------------------------------------------------------------------------
// Exact reason codes.
// ---------------------------------------------------------------------------

test("validateSubmissionPayload: each rejecting branch reports its exact reason code", () => {
  assert.deepEqual(errorsOf({ name: "a", email: "b", nope: "x" }), [{ field: "nope", reason: "unregistered_key" }]);

  assert.deepEqual(errorsOf({ email: "b" }), [{ field: "name", reason: "required" }]);

  assert.deepEqual(errorsOf({ name: 42, email: "b" }), [{ field: "name", reason: "must be a string" }]);

  assert.deepEqual(errorsOf({ name: "a", email: "b", subscribe: "yes" }), [
    { field: "subscribe", reason: "must be a boolean" },
  ]);

  assert.deepEqual(errorsOf({ name: "a", email: "b", message: "x".repeat(101) }), [
    { field: "message", reason: "too_long" },
  ]);
});

// ---------------------------------------------------------------------------
// Absence: `null` and `undefined` are the same signal; requiredness decides.
// ---------------------------------------------------------------------------

test("validateSubmissionPayload: an explicit null is treated exactly like an omitted key", () => {
  assert.deepEqual(errorsOf({ name: null, email: "b" }), [{ field: "name", reason: "required" }]);

  const result = validateSubmissionPayload({ definition: definition(), body: { name: "a", email: "b", message: null } });
  assert.deepEqual(result, { valid: true, data: { name: "a", email: "b" } });
});

test("validateSubmissionPayload: an explicit undefined is treated exactly like an omitted key", () => {
  assert.deepEqual(errorsOf({ name: undefined, email: "b" }), [{ field: "name", reason: "required" }]);
});

test("validateSubmissionPayload: a required field present but whitespace-only is 'required', not accepted", () => {
  assert.deepEqual(errorsOf({ name: "   ", email: "b" }), [{ field: "name", reason: "required" }]);
});

test("validateSubmissionPayload: an OPTIONAL field may be the empty string — the trim check is gated on requiredness", () => {
  const result = validateSubmissionPayload({ definition: definition(), body: { name: "a", email: "b", message: "   " } });
  assert.deepEqual(result, { valid: true, data: { name: "a", email: "b", message: "   " } });
});

test("validateSubmissionPayload: a required checkbox submitted as false is accepted — false is a value, not an absence", () => {
  const def = definition({
    fields: [{ id: "agree", label: "Agree", type: "checkbox", required: true }],
  });
  const result = validateSubmissionPayload({ definition: def, body: { agree: false } });
  assert.deepEqual(result, { valid: true, data: { agree: false } });
});

test("validateSubmissionPayload: maxLength is enforced on optional fields too, and the boundary length is accepted", () => {
  assert.deepEqual(errorsOf({ name: "a", email: "b", message: "x".repeat(101) }), [
    { field: "message", reason: "too_long" },
  ]);
  const atLimit = validateSubmissionPayload({
    definition: definition(),
    body: { name: "a", email: "b", message: "x".repeat(100) },
  });
  assert.equal(atLimit.valid, true);
});

// ---------------------------------------------------------------------------
// Ordering and accumulation.
// ---------------------------------------------------------------------------

test("validateSubmissionPayload: every unregistered key is reported before any declared-field error", () => {
  assert.deepEqual(errorsOf({ zzz: "x", aaa: "y", subscribe: "not-a-boolean" }), [
    { field: "zzz", reason: "unregistered_key" },
    { field: "aaa", reason: "unregistered_key" },
    { field: "name", reason: "required" },
    { field: "email", reason: "required" },
    { field: "subscribe", reason: "must be a boolean" },
  ]);
});

test("validateSubmissionPayload: declared fields report in DEFINITION order, not body key order", () => {
  assert.deepEqual(errorsOf({ subscribe: 1, email: 2, name: 3 }), [
    { field: "name", reason: "must be a string" },
    { field: "email", reason: "must be a string" },
    { field: "subscribe", reason: "must be a boolean" },
  ]);
});

test("validateSubmissionPayload: each field contributes at most one error — a too-long required field is not also 'required'", () => {
  const def = definition({
    fields: [{ id: "note", label: "Note", type: "text", required: true, maxLength: 3 }],
  });
  assert.deepEqual(errorsOf({ note: "abcd" }, def), [{ field: "note", reason: "too_long" }]);
});

// ---------------------------------------------------------------------------
// The success shape. See docs/decisions/DR-001-anonymous-submission-containment.md.
// ---------------------------------------------------------------------------

test("validateSubmissionPayload: `_hp` is accepted as a key but never lands in `data`", () => {
  const result = validateSubmissionPayload({
    definition: definition(),
    body: { name: "a", email: "b", _hp: "bot-filled-this" },
  });
  assert.deepEqual(result, { valid: true, data: { name: "a", email: "b" } });
});

test("validateSubmissionPayload: absent optional fields are omitted from `data` rather than set to null/undefined", () => {
  const result = validateSubmissionPayload({ definition: definition(), body: { name: "a", email: "b" } });
  assert.equal(result.valid, true);
  assert.deepEqual(Object.keys(result.valid === true ? result.data : {}), ["name", "email"]);
});

test("validateSubmissionPayload: a fully-populated body returns every declared field in definition order", () => {
  const result = validateSubmissionPayload({
    definition: definition(),
    body: { subscribe: true, message: "hi", email: "e@x.test", name: "A" },
  });
  assert.equal(result.valid, true);
  assert.deepEqual(result.valid === true ? result.data : {}, {
    name: "A",
    email: "e@x.test",
    message: "hi",
    subscribe: true,
  });
  assert.deepEqual(Object.keys(result.valid === true ? result.data : {}), ["name", "email", "message", "subscribe"]);
});

test("validateSubmissionPayload: a rejected payload carries no `data` key at all", () => {
  const result = validateSubmissionPayload({ definition: definition(), body: { email: "b" } });
  assert.deepEqual(result, { valid: false, fieldErrors: [{ field: "name", reason: "required" }] });
});

test("validateSubmissionPayload: a definition with no declared fields accepts an empty body and rejects any key", () => {
  const empty = definition({ fields: [] });
  assert.deepEqual(validateSubmissionPayload({ definition: empty, body: {} }), { valid: true, data: {} });
  assert.deepEqual(errorsOf({ anything: "x" }, empty), [{ field: "anything", reason: "unregistered_key" }]);
});

src/listing/__tests__/paging.test.ts.source:
import { describe, expect, it } from 'vitest';
import { LISTING_AFTER_MAX, arrayListingSource } from '../batch.js';
import {
  LISTING_PAGE_MAX,
  computeListingPage,
  extractListingPageHrefs,
  listingPagePath,
  parseListingPagePath,
  readListingPage,
  renderListingPageNav,
} from '../paging.js';

const rows = (count: number): number[] => Array.from({ length: count }, (_, index) => index);

describe('computeListingPage', () => {
  it('page 1 of several: no prev, next is /page/2', () => {
    expect(computeListingPage({ total: 60, page: 1, pageSize: 24 })).toEqual({
      page: 1, pageSize: 24, total: 60, totalPages: 3, offset: 0, nextHref: '/page/2',
    });
  });

  it('a middle page links both ways; page 2 links back to the bare page path', () => {
    expect(computeListingPage({ total: 60, page: 2, pageSize: 24 }, { pagePath: '/blog' })).toEqual({
      page: 2, pageSize: 24, total: 60, totalPages: 3, offset: 24, prevHref: '/blog', nextHref: '/blog/page/3',
    });
  });

  it('the last page has no next', () => {
    expect(computeListingPage({ total: 60, page: 3, pageSize: 24 }, { pagePath: '/blog/' })).toEqual({
      page: 3, pageSize: 24, total: 60, totalPages: 3, offset: 48, prevHref: '/blog/page/2',
    });
  });

  it('a page past the last, or below 1, is out of range', () => {
    expect(computeListingPage({ total: 60, page: 4, pageSize: 24 })).toBeUndefined();
    expect(computeListingPage({ total: 60, page: 0, pageSize: 24 })).toBeUndefined();
    expect(computeListingPage({ total: 60, page: 1.5, pageSize: 24 })).toBeUndefined();
  });

  it('0 items is one empty page; page 2 of it is out of range', () => {
    expect(computeListingPage({ total: 0, page: 1, pageSize: 24 })).toEqual({ page: 1, pageSize: 24, total: 0, totalPages: 1, offset: 0 });
    expect(computeListingPage({ total: 0, page: 2, pageSize: 24 })).toBeUndefined();
  });

  it('exactly one page of items is one page; one more makes two', () => {
    expect(computeListingPage({ total: 24, page: 1, pageSize: 24 })?.totalPages).toBe(1);
    expect(computeListingPage({ total: 24, page: 1, pageSize: 24 })?.nextHref).toBeUndefined();
    expect(computeListingPage({ total: 25, page: 1, pageSize: 24 })).toMatchObject({ totalPages: 2, nextHref: '/page/2' });
    expect(computeListingPage({ total: 25, page: 2, pageSize: 24 })).toMatchObject({ offset: 24, prevHref: '/' });
  });

  it('a page size below 1 is floored to 1', () => {
    expect(computeListingPage({ total: 2, page: 2, pageSize: 0 })).toMatchObject({ pageSize: 1, totalPages: 2, offset: 1 });
  });
});

describe('listingPagePath / parseListingPagePath', () => {
  it('page 1 is the page itself; later pages hang /page/<n> off it', () => {
    expect(listingPagePath({ pagePath: '/', page: 1 })).toBe('/');
    expect(listingPagePath({ pagePath: '/', page: 2 })).toBe('/page/2');
    expect(listingPagePath({ pagePath: '/blog//', page: 7 })).toBe('/blog/page/7');
  });

  it('parses home and nested pages, with or without a trailing slash', () => {
    expect(parseListingPagePath({ path: '/page/2' })).toEqual({ pagePath: '/', page: 2 });
    expect(parseListingPagePath({ path: '/page/2/' })).toEqual({ pagePath: '/', page: 2 });
    expect(parseListingPagePath({ path: '/blog/page/12' })).toEqual({ pagePath: '/blog', page: 12 });
  });

  it('refuses page 1 (the page itself is canonical), a leading zero, a huge page, and reserved/odd segments', () => {
    expect(parseListingPagePath({ path: '/page/1' })).toBeUndefined();
    expect(parseListingPagePath({ path: '/page/02' })).toBeUndefined();
    expect(parseListingPagePath({ path: `/page/${LISTING_PAGE_MAX + 1}` })).toBeUndefined();
    expect(parseListingPagePath({ path: `/page/${LISTING_PAGE_MAX}` })).toEqual({ pagePath: '/', page: LISTING_PAGE_MAX });
    expect(parseListingPagePath({ path: '/admin/page/2' })).toBeUndefined();
    expect(parseListingPagePath({ path: '/a/../page/2' })).toBeUndefined();
    expect(parseListingPagePath({ path: '/blog/_more/page/2' })).toBeUndefined();
    expect(parseListingPagePath({ path: '/blog/page/x' })).toBeUndefined();
  });
});

describe('readListingPage', () => {
  it('returns the requested page of visible items and the visible total', async () => {
    const page = await readListingPage({ source: arrayListingSource({ rows: rows(10) }), page: 2, pageSize: 3 }, { isVisible: (n) => n % 2 === 0, chunkSize: 2 });
    expect(page).toEqual({ items: [6, 8], page: 2, pageSize: 3, total: 5, totalPages: 2, offset: 3, prevHref: '/' });
  });

  it('defaults to every row visible and links from the given page path', async () => {
    const page = await readListingPage({ source: arrayListingSource({ rows: rows(25) }), page: 1, pageSize: 24 }, { pagePath: '/blog' });
    expect(page?.items).toHaveLength(24);
    expect(page).toMatchObject({ total: 25, totalPages: 2, nextHref: '/blog/page/2' });
  });

  it('is undefined for a page past the last', async () => {
    expect(await readListingPage({ source: arrayListingSource({ rows: rows(24) }), page: 2, pageSize: 24 })).toBeUndefined();
  });

  it('stops scanning at LISTING_AFTER_MAX source rows', async () => {
    let reads = 0;
    const endless = async ({ limit }: { offset: number; limit: number }) => { reads += 1; return rows(limit); };
    const page = await readListingPage({ source: endless, page: 1, pageSize: 1 }, { chunkSize: LISTING_AFTER_MAX / 2 });
    expect(reads).toBe(2);
    expect(page?.total).toBe(LISTING_AFTER_MAX);
  });
});

describe('renderListingPageNav', () => {
  it('renders nothing for a single page', () => {
    expect(renderListingPageNav({ page: { page: 1, pageSize: 24, total: 24, totalPages: 1, offset: 0 } })).toBe('');
  });

  it('renders an accessible nav with rel=prev/next links and a status', () => {
    const html = renderListingPageNav({ page: { page: 2, pageSize: 24, total: 60, totalPages: 3, offset: 24, prevHref: '/', nextHref: '/page/3' } });
    expect(html).toBe(
      '<nav class="jini-pagination" aria-label="Pagination"><a class="jini-pagination-prev" rel="prev" href="/">Newer posts</a> <span class="jini-pagination-status">Page 2 of 3</span> <a class="jini-pagination-next" rel="next" href="/page/3">Older posts</a></nav>'
    );
  });

  it('omits the missing side and escapes custom labels and hrefs', () => {
    const html = renderListingPageNav(
      { page: { page: 1, pageSize: 1, total: 2, totalPages: 2, offset: 0, nextHref: '/a"b' } },
      { label: 'Posts & pages', olderLabel: 'Older <', newerLabel: 'unused' }
    );
    expect(html).toBe('<nav class="jini-pagination" aria-label="Posts &amp; pages"><span class="jini-pagination-status">Page 1 of 2</span> <a class="jini-pagination-next" rel="next" href="/a&quot;b">Older &lt;</a></nav>');
    const last = renderListingPageNav({ page: { page: 2, pageSize: 1, total: 2, totalPages: 2, offset: 1, prevHref: '/' } });
    expect(last).toBe('<nav class="jini-pagination" aria-label="Pagination"><a class="jini-pagination-prev" rel="prev" href="/">Newer posts</a> <span class="jini-pagination-status">Page 2 of 2</span></nav>');
  });
});

describe('extractListingPageHrefs', () => {
  it('collects every rel=prev/next href inside pagination navs only', () => {
    const nav = renderListingPageNav({ page: { page: 2, pageSize: 1, total: 3, totalPages: 3, offset: 1, prevHref: '/blog', nextHref: '/blog/page/3' } });
    const html = `<a rel="next" href="/elsewhere">x</a>${nav}<nav><a rel="next" href="/nope">y</a></nav>`;
    expect(extractListingPageHrefs({ html })).toEqual(['/blog', '/blog/page/3']);
  });

  it('decodes escaped hrefs and returns nothing without a nav', () => {
    expect(extractListingPageHrefs({ html: '<p>none</p>' })).toEqual([]);
    expect(extractListingPageHrefs({ html: '<nav class="jini-pagination"><a rel="next" href="/a&amp;b">n</a></nav>' })).toEqual(['/a&b']);
  });
});

forms/src/__tests__/forms.field-validati.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { validateFieldDescriptors as validateFields } from "../forms.js";
import type { FieldDescriptor } from "../types.js";

function field(overrides: Partial<FieldDescriptor> = {}): FieldDescriptor {
  return { id: "name", label: "Name", type: "text", required: false, ...overrides };
}

test("validateFieldDescriptors: accepts a single valid text field", () => {
  const result = validateFieldDescriptors([field()]);
  assert.equal(result.valid, true);
});

test("validateFieldDescriptors: accepts every vocabulary type (text/email/textarea/checkbox)", () => {
  const fields: FieldDescriptor[] = [
    field({ id: "a", type: "text" }),
    field({ id: "b", type: "email" }),
    field({ id: "c", type: "textarea" }),
    field({ id: "d", type: "checkbox" }),
  ];
  const result = validateFieldDescriptors(fields);
  assert.equal(result.valid, true);
});

test("validateFieldDescriptors: rejects a field type outside the registered vocabulary (AC-03)", () => {
  const result = validateFieldDescriptors([field({ type: "date" as FieldDescriptor["type"] })]);
  assert.equal(result.valid, false);
  if (!result.valid) {
    assert.ok(result.fieldErrors.some((e) => e.field === "name" && e.reason.includes("type")));
  }
});

test("validateFieldDescriptors: rejects zero fields", () => {
  const result = validateFieldDescriptors([]);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: accepts exactly 20 fields (behavior.spec.md §7 boundary)", () => {
  const fields = Array.from({ length: 20 }, (_, i) => field({ id: `f${i}`, label: `Field ${i}` }));
  const result = validateFieldDescriptors(fields);
  assert.equal(result.valid, true);
});

test("validateFieldDescriptors: rejects 21 fields (behavior.spec.md §7 boundary)", () => {
  const fields = Array.from({ length: 21 }, (_, i) => field({ id: `f${i}`, label: `Field ${i}` }));
  const result = validateFieldDescriptors(fields);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: rejects an empty label", () => {
  const result = validateFieldDescriptors([field({ label: "" })]);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: rejects a label over 200 chars", () => {
  const result = validateFieldDescriptors([field({ label: "x".repeat(201) })]);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: accepts a label at exactly 200 chars", () => {
  const result = validateFieldDescriptors([field({ label: "x".repeat(200) })]);
  assert.equal(result.valid, true);
});

test("validateFieldDescriptors: accepts maxLength within 1..5000 for a text field", () => {
  const result = validateFieldDescriptors([field({ maxLength: 100 })]);
  assert.equal(result.valid, true);
});

test("validateFieldDescriptors: rejects maxLength 0", () => {
  const result = validateFieldDescriptors([field({ maxLength: 0 })]);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: rejects maxLength over 5000", () => {
  const result = validateFieldDescriptors([field({ maxLength: 5001 })]);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: rejects maxLength set on a checkbox field (behavior.spec.md §4)", () => {
  const result = validateFieldDescriptors([field({ type: "checkbox", maxLength: 100 })]);
  assert.equal(result.valid, false);
  if (!result.valid) {
    assert.ok(result.fieldErrors.some((e) => e.reason.toLowerCase().includes("checkbox")));
  }
});

test("validateFieldDescriptors: accepts a checkbox field with no maxLength", () => {
  const result = validateFieldDescriptors([field({ type: "checkbox" })]);
  assert.equal(result.valid, true);
});

test("validateFieldDescriptors: rejects duplicate field ids", () => {
  const result = validateFieldDescriptors([field({ id: "dup" }), field({ id: "dup", label: "Dup 2" })]);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: rejects a field id outside ^[a-z][a-z0-9_]*$", () => {
  const result = validateFieldDescriptors([field({ id: "1bad" })]);
  assert.equal(result.valid, false);
});

// ---------------------------------------------------------------------------
// className/attributes (per-field CSS classes + HTML attributes, admin "field attributes" modal).
// See forms.ts's `ATTRIBUTE_NAME_PATTERN` header comment for why attribute NAMES are deny-by-
// default rather than a sanitize pass — an attribute value is inert once escaped, a name is not.
// ---------------------------------------------------------------------------

test("validateFieldDescriptors: accepts a Tailwind-style className string unchanged", () => {
  const result = validateFieldDescriptors([field({ className: "md:col-span-2 w-1/2 focus:ring-2" })]);
  assert.equal(result.valid, true);
});

test("validateFieldDescriptors: rejects a className over the length cap", () => {
  const result = validateFieldDescriptors([field({ className: "x".repeat(301) })]);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: accepts every allowlisted attribute name", () => {
  const allowlisted = [
    "placeholder",
    "autocomplete",
    "inputmode",
    "pattern",
    "title",
    "min",
    "max",
    "step",
    "minlength",
    "spellcheck",
    "readonly",
  ];
  const attributes = Object.fromEntries(allowlisted.map((name) => [name, "value"]));
  const result = validateFieldDescriptors([field({ attributes })]);
  assert.equal(result.valid, true);
});

test("validateFieldDescriptors: accepts aria-* and data-* prefixed attribute names", () => {
  const result = validateFieldDescriptors([
    field({ attributes: { "aria-label": "Email address", "data-testid": "email-field" } }),
  ]);
  assert.equal(result.valid, true);
});

for (const rejected of ["onclick", "onerror", "style", "formaction", "href", "src", "srcdoc", "id", "name", "type"]) {
  test(`validateFieldDescriptors: rejects the '${rejected}' attribute name`, () => {
    const result = validateFieldDescriptors([field({ attributes: { [rejected]: "x" } })]);
    assert.equal(result.valid, false);
    if (!result.valid) {
      assert.ok(result.fieldErrors.some((e) => e.reason.includes(rejected)));
    }
  });
}

for (const rejected of ['data-x onclick', 'data-x"y', 'aria-', 'DATA-Foo', 'data-a=b', 'data-']) {
  test(`validateFieldDescriptors: rejects the malformed '${rejected}' attribute name`, () => {
    assert.deepEqual(validateFieldDescriptors([field({ attributes: { [rejected]: "x" } })]), {
      valid: false,
      fieldErrors: [{ field: "name", reason: `attribute '${rejected}' is not allowed` }],
    });
  });
}

test("validateFieldDescriptors: rejects an attribute name outside the allowlist entirely", () => {
  const result = validateFieldDescriptors([field({ attributes: { colspan: "2" } })]);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: accepts exactly 12 valid attributes", () => {
  const attributes = Object.fromEntries(Array.from({ length: 12 }, (_, i) => [`data-a${i}`, "x"]));
  assert.deepEqual(validateFieldDescriptors([field({ attributes })]), { valid: true });
});

test("validateFieldDescriptors: rejects more than the max attributes per field", () => {
  const attributes = Object.fromEntries(Array.from({ length: 13 }, (_, i) => [`data-a${i}`, "x"]));
  const result = validateFieldDescriptors([field({ attributes })]);
  assert.equal(result.valid, false);
});

test("validateFieldDescriptors: rejects an attribute value over the length cap", () => {
  const result = validateFieldDescriptors([field({ attributes: { title: "x".repeat(301) } })]);
  assert.equal(result.valid, false);
});

function validateFieldDescriptors(fields: import("../types.js").FieldDescriptor[]) { return validateFields({ fields }); }

