import assert from "node:assert/strict";
import { test, vi } from "vitest";
import { submitForm } from "../submit-service.js";
import { registerFormNotifySubscriber } from "../notify-subscriber.js";
import { createFormDefinition, updateFormDefinition } from "../write-service.js";
import { InMemoryFormDefinitionRepo, InMemoryFormSubmissionRepo } from "./repo.fixture.js";
import { InMemoryChangeSetRepo } from "./change-set.fixture.js";
import { InMemoryEventBus, InMemoryOutbox } from "./eventing.fixture.js";
import { executeCommand } from "@jini-ai/cms/core";
import type { AuthorizeFn } from "@jini-ai/cms/core";
import { FormFieldValidationError } from "../errors.js";

function setup() {
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const clock = { nowMs: () => Date.parse("2026-01-01T00:00:00.000Z")};
  let id = 0;
  const idGen = { newId: () => `id-${++id}` };
  const writes = {
    repo: definitionRepo, clock, idGen, executeCommand, changeSets: new InMemoryChangeSetRepo(),
    authorize: vi.fn(async (_required: Parameters<AuthorizeFn>[0]) => ({ allowed: true, reason: "ok" })),
    permission: "tenant.forms.edit", reservedSlugs: new Set<string>(),
  };
  const input = { workspaceId: "workspace", actor: { id: "user", kind: "user" as const },
    name: "Contact", slug: "new", fields: [{ id: "name", label: "Name", type: "text" as const, required: true }] };
  const submitDeps = {
    definitionRepo, submissionRepo, clock, idGen, outbox: new InMemoryOutbox(),
    rateLimiter: { check: vi.fn(async (_required: { key: string }) => ({ allowed: true as const })) },
    dispatcher: { dispatch: vi.fn(async () => {}) }, logger: { warn: vi.fn() },
  };
  return { writes, input, submitDeps };
}

test("host permission and reserved slugs are injected; optional notify is stored", async () => {
  const { writes, input } = setup();
  const { definition } = await createFormDefinition({ deps: writes, input }, { notify: { enabled: true, recipients: ["ops@example.org"] } });
  assert.equal(definition.slug, "new");
  assert.deepEqual(definition.notify, { enabled: true, recipients: ["ops@example.org"] });
  assert.equal(writes.authorize.mock.calls.length, 1);
  assert.equal(writes.authorize.mock.calls[0]![0].permission, "tenant.forms.edit");
  const permissions: string[] = [];
  await updateFormDefinition({ deps: { ...writes, reservedSlugs: new Set(["host-only"]), authorize: async ({ permission }) => { permissions.push(permission); return { allowed: true, reason: "ok" }; } }, input: { workspaceId: "workspace", actor: input.actor, formId: definition.id, patch: { name: "Updated" } } });
  assert.deepEqual(permissions, ["tenant.forms.edit"]);
});

test("an injected command gateway can deny a write before persistence", async () => {
  const { writes, input } = setup();
  const error = new Error("host gateway denied mutation");
  // A rejecting gateway has no result; preserve that instead of specializing TResult in the mock.
  const gateway = vi.fn(async (_required: Parameters<typeof executeCommand>[0]): Promise<never> => { throw error; });
  await assert.rejects(createFormDefinition({ deps: { ...writes, executeCommand: gateway }, input }), (caught) => caught === error);
  assert.equal(gateway.mock.calls.length, 1);
  const command = gateway.mock.calls[0]![0];
  assert.equal(command.command.permission, "tenant.forms.edit");
  assert.equal(command.command.workspaceId, "workspace");
  assert.equal(command.mutation.entityType, "form_definition");
  assert.equal((await writes.repo.list({ workspaceId: "workspace" })).length, 0);
  assert.equal(writes.authorize.mock.calls.length, 0);
});

test("the same slug is accepted or refused solely by the host's reserved-slug policy", async () => {
  const treatment = setup();
  const baseline = setup();
  const accepted = await createFormDefinition({ deps: treatment.writes, input: treatment.input });
  assert.equal(accepted.definition.slug, "new");
  await assert.rejects(createFormDefinition({ deps: { ...baseline.writes, reservedSlugs: new Set(["new"]) }, input: baseline.input }), FormFieldValidationError);
  assert.equal((await baseline.writes.repo.list({ workspaceId: "workspace" })).length, 0);
  // Both runs receive the identical input; only the host's reservation set changes the outcome.
});

test("async rate limiter receives the composite key before persistence", async () => {
  const { writes, input, submitDeps } = setup();
  const { definition } = await createFormDefinition({ deps: writes, input });
  const keys: string[] = [];
  submitDeps.rateLimiter.check = vi.fn(async ({ key }: { key: string }) => { keys.push(key); return { allowed: true as const }; });
  await submitForm({ deps: submitDeps, input: { workspaceId: "workspace", slug: "new", body: { name: "Ada" }, sourceIp: "2001:db8::1" } });
  assert.deepEqual(keys, [`2001:db8::1:${definition.id}`]);
  assert.equal((await submitDeps.submissionRepo.listByDefinition({ workspaceId: "workspace", formDefinitionId: definition.id, limit: 10 })).items.length, 1);
});

test.each(["reject", "throw"])("background dispatcher may %s without rejecting submission", async (failure) => {
  const { writes, input, submitDeps } = setup();
  await createFormDefinition({ deps: writes, input });
  const error = new Error("dispatcher unavailable");
  const deps = { ...submitDeps, dispatcher: { dispatch: failure === "throw" ? () => { throw error; } : async () => { throw error; } } };
  assert.deepEqual(await submitForm({ deps, input: { workspaceId: "workspace", slug: "new", body: { name: "Ada" }, sourceIp: "source" } }), { status: "accepted" });
  await vi.waitFor(() => assert.equal(submitDeps.logger.warn.mock.calls.length, 1));
  assert.deepEqual(submitDeps.logger.warn.mock.calls[0], [{ message: "form outbox dispatch failed" }, { error }]);
});

test("injected sender is used and failed delivery still reaches the next recipient and sibling", async () => {
  const { writes, input, submitDeps } = setup();
  const { definition } = await createFormDefinition({ deps: writes, input }, { notify: { enabled: true, recipients: ["first@example.org", "second@example.org"] } });
  await submitForm({ deps: submitDeps, input: { workspaceId: "workspace", slug: "new", body: { name: "Ada" }, sourceIp: "source" } });
  const bus = new InMemoryEventBus();
  const send = vi.fn(async (required: { message: { from: { email: string }; to: { email: string } } }) => {
    if (required.message.to.email === "first@example.org") throw new Error("mail down");
    return { ok: true as const, providerMessageId: "message", acceptedAt: "now" };
  });
  const unsubscribe = await registerFormNotifySubscriber({ bus, mailer: { send }, sender: { email: "host@example.org" }, logger: { warn: () => { throw new Error("logging down"); } }, formDefinitionRepo: submitDeps.definitionRepo, formSubmissionRepo: submitDeps.submissionRepo });
  let siblingCalls = 0;
  await bus.subscribe({ eventName: "form.submission.received", handler: async () => { siblingCalls++; } });
  const event = submitDeps.outbox.events[0]!;
  await bus.publish(event);
  assert.equal(send.mock.calls.length, 2);
  assert.deepEqual(send.mock.calls.map(([args]) => args.message.from), [{ email: "host@example.org" }, { email: "host@example.org" }]);
  assert.equal(siblingCalls, 1);
  assert.equal(event.payload.formDefinitionId, definition.id);
  await unsubscribe();
  await bus.publish(event);
  assert.equal(send.mock.calls.length, 2);
  assert.equal(siblingCalls, 2);
});

src/widgets/__tests__/integration/region.source:
import { widgetHostFixture, InMemoryEntryRefsRepo, InMemoryOutbox } from "../support/host.fixture.js";
import assert from "node:assert/strict";
import test from "../support/test-runner.js";

import { InMemoryContentTypeRepo } from "../../../content-types/index.js";
import { InMemoryEntryRepo, VersionConflictError } from "../../../entries/index.js";
import { createEntryLockState } from "../../concurrency.js";
import { WidgetAreaConflictError } from "../../errors.js";
import { WIDGET_AREA_CONTENT_TYPE } from "../../types.js";
import { InMemoryWidgetRegionBindingRepo } from "../../repo.memory.js";
import { bindWidgetArea, mutateWidgetAreaPlacements, type RegionAreaServiceDeps } from "../../region-area-service.js";
import { createWidgetInstance, type WidgetWriteServiceDeps } from "../../write-service.js";
import { buildWidgetInstanceFieldsJson } from "../../entry-payload.js";

/**
 * @file `region-area-service.ts` paths the AC-level suite does not reach: re-binding an
 * already-bound region (idempotent), a binding left dangling at a deleted area, a seed write the
 * entries chokepoint refuses, placements naming a trashed widget or a missing area, and both ways an
 * `updateEntry` refusal is reported (a conflict whose row has since vanished, and a non-conflict
 * failure passed through unchanged). Real in-memory adapters throughout; only the host's entries
 * chokepoint is replaced where a refusal has to be produced on purpose.
 */

const WS = "ws-1";
const ACTOR = { principalId: "user-1" };

function makeDeps(overrides: Partial<RegionAreaServiceDeps & WidgetWriteServiceDeps> = {}): RegionAreaServiceDeps & WidgetWriteServiceDeps {
  let counter = 0;
  return {
    host: widgetHostFixture,
    entryRepo: new InMemoryEntryRepo(),
    contentTypeRepo: new InMemoryContentTypeRepo(),
    entryRefsRepo: new InMemoryEntryRefsRepo(),
    bindingRepo: new InMemoryWidgetRegionBindingRepo(),
    clock: { nowMs: () => Date.parse("2026-07-21T00:00:00.000Z") },
    ids: { newId: () => `id-${++counter}` },
    authorize: async () => ({ allowed: true, reason: "test" }),
    outbox: new InMemoryOutbox(),
    ...overrides,
  };
}

async function areaEntries(deps: RegionAreaServiceDeps) {
  return deps.entryRepo.listByWorkspace({ workspaceId: WS }, { type: WIDGET_AREA_CONTENT_TYPE });
}

test("binding an already-bound region returns the bound area and creates nothing new (shared lock state honoured)", async () => {
  const deps = makeDeps({ entryLocks: createEntryLockState({}) });
  const first = await bindWidgetArea({ deps, input: { workspaceId: WS, regionKey: "footer" } });
  const second = await bindWidgetArea({ deps, input: { workspaceId: WS, regionKey: "footer" } });

  assert.deepEqual(second.areaEntry, first.areaEntry);
  assert.equal((await areaEntries(deps)).length, 1);
});

test("a binding left pointing at a deleted area falls back to the region's slug and re-binds to a fresh area", async () => {
  const deps = makeDeps();
  await deps.bindingRepo.upsert({ workspaceId: WS, regionKey: "footer", areaEntryId: "deleted-area", updatedAt: "old" });

  const { areaEntry } = await bindWidgetArea({ deps, input: { workspaceId: WS, regionKey: "footer" } });

  assert.notEqual(areaEntry.id, "deleted-area");
  assert.equal((await deps.bindingRepo.findByRegion({ workspaceId: WS, regionKey: "footer" }))?.areaEntryId, areaEntry.id);
});

test("a seed write the entries chokepoint refuses propagates its error and leaves the region unbound", async () => {
  const refusal = new Error("entries store unavailable");
  const deps = makeDeps({ host: { ...widgetHostFixture, entries: { ...widgetHostFixture.entries, createEntry: async () => ({ ok: false, error: refusal }) } } });

  await assert.rejects(bindWidgetArea({ deps, input: { workspaceId: WS, regionKey: "footer" } }), (error: unknown) => error === refusal);
  assert.equal(await deps.bindingRepo.findByRegion({ workspaceId: WS, regionKey: "footer" }), null);
});

test("a placement naming a trashed (status trash/purged) widget is refused before any write", async () => {
  const deps = makeDeps();
  const { areaEntry } = await bindWidgetArea({ deps, input: { workspaceId: WS, regionKey: "footer" } });
  for (const status of ["trash", "purged"] as const) {
    await deps.entryRepo.save({
      id: `legacy-${status}`, workspaceId: WS, type: "widget", slug: `legacy-${status}`, status: "draft", title: "Old",
      bodyJson: null, fieldsJson: buildWidgetInstanceFieldsJson({ payload: { widgetType: "text", config: { body: "x" }, status } }),
      publishedAt: null, createdAt: "2026-07-21T00:00:00.000Z", updatedAt: "2026-07-21T00:00:00.000Z", version: 1,
    });
    await assert.rejects(
      mutateWidgetAreaPlacements({ deps, input: {
        workspaceId: WS, actor: ACTOR, areaEntryId: areaEntry.id, baseVersion: areaEntry.version,
        placements: [{ placementId: "p", widgetEntryId: `legacy-${status}`, enabled: true }],
      } }),
      { name: "WidgetInstanceNotFoundError", message: `placement references widget 'legacy-${status}', which is trashed` },
    );
  }
  assert.equal((await deps.entryRepo.findById({ workspaceId: WS, id: areaEntry.id }))?.version, areaEntry.version);
});

test("mutating placements of a missing area, or of an entry that is not a widget_area, is WidgetAreaNotFoundError", async () => {
  const deps = makeDeps();
  const { instance } = await createWidgetInstance({ deps, input: { workspaceId: WS, actor: ACTOR, widgetType: "text", title: "W", config: { body: "b" } } });

  for (const areaEntryId of ["no-such-area", instance.id]) {
    await assert.rejects(
      mutateWidgetAreaPlacements({ deps, input: { workspaceId: WS, actor: ACTOR, areaEntryId, baseVersion: 1, placements: [] } }),
      { name: "WidgetAreaNotFoundError", message: `widget_area '${areaEntryId}' was not found` },
    );
  }
});

test("a version conflict whose area vanished before the re-read reports the version the caller last saw", async () => {
  const deps = makeDeps();
  const { areaEntry } = await bindWidgetArea({ deps, input: { workspaceId: WS, regionKey: "footer" } });
  const entryRepo = deps.entryRepo as InMemoryEntryRepo;
  deps.host = {
    ...widgetHostFixture,
    entries: {
      ...widgetHostFixture.entries,
      updateEntry: async () => {
        await entryRepo.hardDelete({ workspaceId: WS, id: areaEntry.id });
        return { ok: false, error: new VersionConflictError({ message: "area changed" }) };
      },
    },
  };

  await assert.rejects(
    mutateWidgetAreaPlacements({ deps, input: { workspaceId: WS, actor: ACTOR, areaEntryId: areaEntry.id, baseVersion: areaEntry.version, placements: [] } }),
    (error: unknown) => error instanceof WidgetAreaConflictError && error.message === "area changed" && error.currentVersion === areaEntry.version,
  );
});

test("a non-conflict updateEntry failure propagates unchanged, never re-typed as a conflict", async () => {
  const deps = makeDeps();
  const { areaEntry } = await bindWidgetArea({ deps, input: { workspaceId: WS, regionKey: "footer" } });
  const refusal = new Error("validation failed downstream");
  deps.host = { ...widgetHostFixture, entries: { ...widgetHostFixture.entries, updateEntry: async () => ({ ok: false, error: refusal }) } };

  await assert.rejects(
    mutateWidgetAreaPlacements({ deps, input: { workspaceId: WS, actor: ACTOR, areaEntryId: areaEntry.id, baseVersion: areaEntry.version, placements: [] } }),
    (error: unknown) => error === refusal,
  );
});

src/entries/__tests__/repo.memory.cov-j2.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { VersionConflictError } from "../errors.js";
import { InMemoryEntryRepo, toEntryOutbox } from "../repo.memory.js";
import type { EntryRecord } from "../types.js";

/**
 * @file The in-memory entry adapter's compare-and-set save, workspace-scoped reads, list filtering,
 * `updatedAt` ordering and limit, and the outbox adapter that widens `{name,payload}` into a full
 * domain event.
 */

function entry(overrides: Partial<EntryRecord> = {}): EntryRecord {
  return {
    id: "entry-1", workspaceId: "ws-1", type: "recipe", slug: "chili", status: "draft", title: "Chili",
    fieldsJson: { ext: { site: {} } }, bodyJson: null, publishedAt: null,
    createdAt: "2026-07-01T00:00:00.000Z", updatedAt: "2026-07-01T00:00:00.000Z", version: 1, ...overrides,
  };
}

test("save with expectedVersion=null creates only when the id is free in every workspace", async () => {
  const repo = new InMemoryEntryRepo();
  await repo.save(entry(), { expectedVersion: null });
  assert.equal((await repo.findById({ workspaceId: "ws-1", id: "entry-1" }))?.version, 1);

  await assert.rejects(
    () => repo.save(entry({ title: "dup" }), { expectedVersion: null }),
    (error: unknown) => error instanceof VersionConflictError && error.message === "expected no entry 'entry-1', found 1",
  );
  await assert.rejects(
    () => repo.save(entry({ workspaceId: "ws-2", title: "foreign" }), { expectedVersion: null }),
    (error: unknown) => error instanceof VersionConflictError && error.message === "expected no entry 'entry-1', found 1",
  );
  assert.equal((await repo.findById({ workspaceId: "ws-1", id: "entry-1" }))?.title, "Chili");
});

test("save with a numeric expectedVersion writes only over the same workspace's row at that version", async () => {
  const repo = new InMemoryEntryRepo();
  await repo.save(entry());

  await repo.save(entry({ title: "v2", version: 2 }), { expectedVersion: 1 });
  assert.equal((await repo.findById({ workspaceId: "ws-1", id: "entry-1" }))?.title, "v2");

  await assert.rejects(
    () => repo.save(entry({ title: "stale", version: 2 }), { expectedVersion: 1 }),
    (error: unknown) => error instanceof VersionConflictError && error.message === "expected version 1 for entry 'entry-1', found 2",
  );
  await assert.rejects(
    () => repo.save(entry({ workspaceId: "ws-2", title: "foreign", version: 3 }), { expectedVersion: 2 }),
    (error: unknown) => error instanceof VersionConflictError && error.message === "expected version 2 for entry 'entry-1', found none",
  );
  await assert.rejects(
    () => repo.save(entry({ id: "missing" }), { expectedVersion: 1 }),
    (error: unknown) => error instanceof VersionConflictError && error.message === "expected version 1 for entry 'missing', found none",
  );
  assert.equal((await repo.findById({ workspaceId: "ws-1", id: "entry-1" }))?.title, "v2");
});

test("findById and findBySlug are workspace-scoped and return copies", async () => {
  const repo = new InMemoryEntryRepo();
  await repo.save(entry());
  await repo.save(entry({ id: "entry-2", slug: "soup" }));

  const bySlug = await repo.findBySlug({ workspaceId: "ws-1", type: "recipe", slug: "soup" });
  assert.equal(bySlug?.id, "entry-2");
  if (bySlug) bySlug.title = "mutated";
  assert.equal((await repo.findById({ workspaceId: "ws-1", id: "entry-2" }))?.title, "Chili");

  assert.equal(await repo.findBySlug({ workspaceId: "ws-1", type: "article", slug: "soup" }), null);
  assert.equal(await repo.findBySlug({ workspaceId: "ws-2", type: "recipe", slug: "soup" }), null);
  assert.equal(await repo.findById({ workspaceId: "ws-2", id: "entry-1" }), null);
  assert.equal(await repo.findById({ workspaceId: "ws-1", id: "nope" }), null);
});

async function seededForListing() {
  const repo = new InMemoryEntryRepo();
  await repo.save(entry({ id: "a", slug: "a", updatedAt: "2026-07-02T00:00:00.000Z" }));
  await repo.save(entry({ id: "b", slug: "b", type: "article", status: "published", updatedAt: "2026-07-03T00:00:00.000Z" }));
  await repo.save(entry({ id: "c", slug: "c", status: "published", updatedAt: "2026-07-01T00:00:00.000Z" }));
  await repo.save(entry({ id: "d", slug: "d", updatedAt: "2026-07-02T00:00:00.000Z" }));
  await repo.save(entry({ id: "z", slug: "z", workspaceId: "ws-2" }));
  return repo;
}

test("listByWorkspace filters by workspace, type, and status", async () => {
  const repo = await seededForListing();

  assert.deepEqual((await repo.listByWorkspace({ workspaceId: "ws-1" })).map((row) => row.id), ["a", "b", "c", "d"]);
  assert.deepEqual((await repo.listByWorkspace({ workspaceId: "ws-1" }, { type: "recipe" })).map((row) => row.id), ["a", "c", "d"]);
  assert.deepEqual((await repo.listByWorkspace({ workspaceId: "ws-1" }, { status: "published" })).map((row) => row.id), ["b", "c"]);
  assert.deepEqual((await repo.listByWorkspace({ workspaceId: "ws-1" }, { type: "recipe", status: "published" })).map((row) => row.id), ["c"]);
});

test("listByWorkspace orders by updatedAt (descending by default, ties keep insertion order) and applies limit last", async () => {
  const repo = await seededForListing();

  assert.deepEqual((await repo.listByWorkspace({ workspaceId: "ws-1" }, { orderBy: "updatedAt" })).map((row) => row.id), ["b", "a", "d", "c"]);
  assert.deepEqual((await repo.listByWorkspace({ workspaceId: "ws-1" }, { orderBy: "updatedAt", orderDirection: "desc" })).map((row) => row.id), ["b", "a", "d", "c"]);
  assert.deepEqual((await repo.listByWorkspace({ workspaceId: "ws-1" }, { orderBy: "updatedAt", orderDirection: "asc" })).map((row) => row.id), ["c", "a", "d", "b"]);
  assert.deepEqual((await repo.listByWorkspace({ workspaceId: "ws-1" }, { orderBy: "updatedAt", orderDirection: "asc", limit: 2 })).map((row) => row.id), ["c", "a"]);
  assert.deepEqual((await repo.listByWorkspace({ workspaceId: "ws-1" }, { limit: 0 })), []);
});

test("listByWorkspace hands out copies", async () => {
  const repo = await seededForListing();
  const [first] = await repo.listByWorkspace({ workspaceId: "ws-1" });
  first!.title = "mutated";
  assert.equal((await repo.findById({ workspaceId: "ws-1", id: "a" }))?.title, "Chili");
});

test("transaction runs the callback and resolves to its value", async () => {
  const repo = new InMemoryEntryRepo();
  assert.equal(await repo.transaction({ fn: async () => { await repo.save(entry()); return "done"; } }), "done");
  assert.ok(await repo.findById({ workspaceId: "ws-1", id: "entry-1" }));
});

test("toEntryOutbox stamps a fresh id, the bound workspace, and the clock's time onto each enqueued event", async () => {
  const delivered: unknown[] = [];
  let n = 0;
  const outbox = toEntryOutbox({
    outbox: { enqueue: async (event) => { delivered.push(event); } },
    clock: { nowMs: () => Date.parse("2026-07-15T12:00:00.000Z") },
    idGen: { newId: () => `evt-${++n}` },
    workspaceId: "ws-1",
  });

  await outbox.enqueue({ name: "entry.published", payload: { entryId: "a" } });
  await outbox.enqueue({ name: "entry.unpublished", payload: { entryId: "a" } });

  assert.deepEqual(delivered, [
    { id: "evt-1", workspaceId: "ws-1", name: "entry.published", occurredAt: "2026-07-15T12:00:00.000Z", payload: { entryId: "a" } },
    { id: "evt-2", workspaceId: "ws-1", name: "entry.unpublished", occurredAt: "2026-07-15T12:00:00.000Z", payload: { entryId: "a" } },
  ]);
});

