import assert from "node:assert/strict";
import { test } from "vitest";
import { OriginNotVerifiedError } from "@jini-ai/http-kit/verified-origin";
import { createSitemapService, SITEMAP_INVALIDATED_EVENT } from "../sitemap.js";
import { setEntrySeoOverrides } from "../write-service.js";
import { SeoFieldValidationError } from "../errors.js";
import { buildPostRecord, InMemoryPostRepo } from "./support/post.fixture.js";
import { InMemorySettingsRepo, seoDeps } from "./support/legacy-api.fixture.js";
import { InMemoryMediaRepo, InMemoryTransformDefinitionRepo } from "../../media/index.js";
import type { EventBusPort, OutboxPort } from "../../core/index.js";

function harness(slug: string) {
  const postRepo = new InMemoryPostRepo([buildPostRecord({ slug })]);
  const deps = seoDeps({ postRepo, settingsRepo: new InMemorySettingsRepo(),
    originRegistry: { canonicalOrigin: async () => { throw new OriginNotVerifiedError({ message: "unverified" }); },
      isAllowedRedirectTarget: async () => false, isAllowedEgressTarget: async () => false },
    media: { mediaRepo: new InMemoryMediaRepo({}, { initialRows: [] }),
      transformDefinitionRepo: new InMemoryTransformDefinitionRepo({}, { initialRows: [] }) } });
  return { deps, postRepo, service: createSitemapService({ deps }) };
}

test("two services isolate hooks, caches, invalidation and unregister for the same workspace", async () => {
  const a = harness("a");
  const b = harness("b");
  const input = { workspaceId: "workspace-1" };
  const unregister = a.service.registerSitemapCollectHook({ hook: { priority: 1, handle: async () => [{ loc: "/a-hook" }] } });
  assert.deepEqual((await a.service.buildSitemap(input)).map(e => e.loc), ["/a", "/a-hook"]);
  assert.deepEqual((await b.service.buildSitemap(input)).map(e => e.loc), ["/b"]);
  await a.postRepo.save(buildPostRecord({ slug: "a-new" }));
  await b.postRepo.save(buildPostRecord({ slug: "b-new" }));
  unregister();
  unregister();
  a.service.invalidateSitemapCache(input);
  assert.deepEqual((await a.service.buildSitemap(input)).map(e => e.loc), ["/a-new"]);
  assert.deepEqual((await b.service.buildSitemap(input)).map(e => e.loc), ["/b"]);
  await b.service.createSeoEventSubscriptions({}).onSitemapInvalidated(input);
  assert.deepEqual((await b.service.buildSitemap(input)).map(e => e.loc), ["/b-new"]);
});

test("an older build cannot publish over a newer build inside one service", async () => {
  const { deps, postRepo, service } = harness("old");
  const input = { workspaceId: "workspace-1" };
  let release!: () => void;
  const held = new Promise<void>(resolve => { release = resolve; });
  let calls = 0;
  const list = deps.postRepo.list;
  deps.postRepo.list = async required => {
    const rows = await list(required);
    if (++calls === 1) await held;
    return rows;
  };
  const oldBuild = service.regenerateSitemapCache(input);
  try {
    await postRepo.save(buildPostRecord({ slug: "new" }));
    await service.regenerateSitemapCache(input);
  } finally {
    release();
    await oldBuild;
  }
  assert.deepEqual((await service.buildSitemap(input)).map(e => e.loc), ["/new"]);
});

test("invalidation clears the local snapshot, enqueues the exact event and calls the dispatch port", async () => {
  const { service, postRepo } = harness("before");
  const input = { workspaceId: "workspace-1" };
  await service.buildSitemap(input);
  await postRepo.save(buildPostRecord({ slug: "after" }));
  const events: unknown[] = [];
  const order: string[] = [];
  const outbox = { enqueue: async (event: unknown) => { events.push(event); order.push("enqueue"); } } as OutboxPort;
  const bus = {} as EventBusPort;
  await service.requestSitemapInvalidation({ input, deps: { outbox, bus,
    clock: { nowIso: () => "2026-10-07T00:00:00.000Z" }, idGen: { newId: () => "event-1" },
    dispatch: async required => {
      assert.equal(required.outbox, outbox);
      assert.equal(required.bus, bus);
      assert.equal(required.clock.nowMs(), Date.parse("2026-10-07T00:00:00.000Z"));
      order.push("dispatch");
    } } });
  assert.deepEqual(order, ["enqueue", "dispatch"]);
  assert.deepEqual(events, [{ id: "event-1", name: SITEMAP_INVALIDATED_EVENT,
    occurredAt: "2026-10-07T00:00:00.000Z", aggregateId: "workspace-1", workspaceId: "workspace-1", payload: {} }]);
  assert.deepEqual((await service.buildSitemap(input)).map(e => e.loc), ["/after"]);
});

test("known non-images are refused through the required featured-image port before any write", async () => {
  const { deps, postRepo } = harness("post");
  const before = await postRepo.findById({ workspaceId: "workspace-1", id: "post-1" });
  await assert.rejects(setEntrySeoOverrides({ deps: { postRepo, clock: { nowMs: () => 0 },
    authorize: async () => ({ allowed: true, reason: "matched" }), invalidateSitemapCache: () => {},
    media: { featuredImage: { ...deps.media.featuredImage,
      resolveFeaturedImageRef: async () => ({ ok: false, reason: "not-image", contentType: "video/mp4" }) } } },
    input: { workspaceId: "workspace-1", entryId: "post-1", callerPrincipalId: "p1", patch: { ogImage: "video:public" } } }),
  (error: unknown) => error instanceof SeoFieldValidationError && error.message === "ogImage: media asset 'video' is video/mp4, not an image. A social share image must be an image.");
  assert.deepEqual(await postRepo.findById({ workspaceId: "workspace-1", id: "post-1" }), before);
  assert.deepEqual(await postRepo.listRevisions({ workspaceId: "workspace-1", postId: "post-1" }), []);
});

test.each(["onEntryPublished", "onEntryUpdated", "onEntryUnpublished"] as const)("the %s subscription invalidates only that workspace's cached sitemap", async (name) => {
  const { postRepo, service } = harness("before");
  const input = { workspaceId: "workspace-1" };
  assert.deepEqual((await service.buildSitemap(input)).map(e => e.loc), ["/before"]);
  await postRepo.save(buildPostRecord({ slug: "after" }));
  assert.deepEqual((await service.buildSitemap(input)).map(e => e.loc), ["/before"], "served from cache before the event");
  await service.createSeoEventSubscriptions({})[name]({ workspaceId: "workspace-1", payload: { entryId: "post-1", contentType: "post" } });
  assert.deepEqual((await service.buildSitemap(input)).map(e => e.loc), ["/after"]);
});

test("the service's computeIndexableEntries lists published entries in id order with their resolved meta", async () => {
  const { postRepo, service } = harness("b-slug");
  await postRepo.save(buildPostRecord({ id: "post-0", slug: "a-slug" }));
  await postRepo.save(buildPostRecord({ id: "post-2", slug: "draft", status: "draft" }));
  const entries = await service.computeIndexableEntries({ workspaceId: "workspace-1" });
  assert.deepEqual(entries.map(e => [e.post.id, e.meta.canonical]), [["post-0", "/a-slug"], ["post-1", "/b-slug"]]);
});

test("the service's buildRobots advertises the relative sitemap URL when no origin is verified", async () => {
  const { service } = harness("a");
  const robots = await service.buildRobots({ workspaceId: "workspace-1" });
  assert.deepEqual(robots.sitemapUrls, ["/sitemap.xml"]);
});

src/forms/__tests__/forms.edge-cases.tes.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { InMemoryEventBus, InMemoryOutbox } from "./eventing.fixture.js";
import { createRateLimiter } from "./support/host-ports.fixture.js";
import { FormDefinitionNotFoundError, FormFieldValidationError } from "../index.js";
import { FORMS_SUBMIT_PROFILE } from "./support/host-ports.fixture.js";
import { InMemoryFormDefinitionRepo, InMemoryFormSubmissionRepo } from "./support/repo-ports.fixture.js";
import { submitForm } from "./support/host-ports.fixture.js";
import { createFormDefinition } from "./support/host-ports.fixture.js";
import { executeCommand, InMemoryChangeSetRepo } from "./support/host-ports.fixture.js";
import type { FormDefinitionRecord } from "../index.js";

/**
 * @file Additional edge-case coverage (tasks.md T046): EC-01 (only-required-fields submission, at
 * the integration level via `submitForm`, not just `validateSubmissionPayload`'s unit test),
 * EC-05 (definition disabled mid-flight of an in-progress submission), and the
 * behavior.spec.md §7 boundary matrix rows not yet covered elsewhere: notify recipients at
 * exactly 10 (accepted) and 11 (rejected).
 */
const NOW = "2026-07-13T00:00:00.000Z";
const WORKSPACE_ID = "ws-1";
const ACTOR = { id: "principal-1", kind: "user" as const };

function makeWriteDeps() {
  const repo = new InMemoryFormDefinitionRepo();
  const clock = { nowIso: () => NOW, nowMs: () => Date.parse(NOW) };
  let counter = 0;
  const idGen = { newId: () => `id-${++counter}` };
  const changeSets = new InMemoryChangeSetRepo();
  const authorize = async () => ({ allowed: true, reason: "ok" });
  return { repo, clock, idGen, changeSets, authorize, executeCommand };
}

test("behavior.spec.md §7 — notify.recipients at exactly 10 is accepted", async () => {
  const deps = makeWriteDeps();
  const recipients = Array.from({ length: 10 }, (_, i) => `r${i}@example.com`);
  const { definition } = await createFormDefinition({
    deps,
    input: {
      workspaceId: WORKSPACE_ID,
      actor: ACTOR,
      name: "Contact",
      slug: "contact",
      fields: [{ id: "name", label: "Name", type: "text", required: true }],
      notify: { enabled: true, recipients },
    },
  });
  assert.equal(definition.notify.recipients.length, 10);
});

test("behavior.spec.md §7 — notify.recipients at 11 is rejected with FormFieldValidationError", async () => {
  const deps = makeWriteDeps();
  const recipients = Array.from({ length: 11 }, (_, i) => `r${i}@example.com`);
  await assert.rejects(
    () =>
      createFormDefinition({
        deps,
        input: {
          workspaceId: WORKSPACE_ID,
          actor: ACTOR,
          name: "Contact",
          slug: "contact",
          fields: [{ id: "name", label: "Name", type: "text", required: true }],
          notify: { enabled: true, recipients },
        },
      }),
    FormFieldValidationError
  );
});

function makeDefinition(overrides: Partial<FormDefinitionRecord> = {}): FormDefinitionRecord {
  return {
    id: "def-1",
    workspaceId: WORKSPACE_ID,
    name: "Contact",
    slug: "contact",
    fields: [
      { id: "name", label: "Name", type: "text", required: true },
      { id: "email", label: "Email", type: "email", required: true },
      { id: "message", label: "Message", type: "textarea", required: false, maxLength: 500 },
    ],
    notify: { enabled: false, recipients: [] },
    status: "active",
    createdAt: NOW,
    updatedAt: NOW,
    version: 1,
    ...overrides,
  };
}

function makeSubmitDeps() {
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const outbox = new InMemoryOutbox();
  const bus = new InMemoryEventBus();
  const clock = { nowIso: () => NOW, nowMs: () => Date.parse(NOW) };
  let counter = 0;
  const idGen = { newId: () => `id-${++counter}` };
  const rateLimiter = createRateLimiter({ profile: FORMS_SUBMIT_PROFILE, clock });
  return { definitionRepo, submissionRepo, outbox, bus, clock, idGen, rateLimiter };
}

test("EC-01: a submission supplying only required fields is accepted; omitted optional fields are absent from data", async () => {
  const deps = makeSubmitDeps();
  await deps.definitionRepo.create(makeDefinition());

  const result = await submitForm({
    deps,
    input: {
      workspaceId: WORKSPACE_ID,
      slug: "contact",
      body: { name: "Ada", email: "ada@example.com" },
      sourceIp: "1.1.1.1",
    },
  });
  assert.equal(result.status, "accepted");

  const page = await deps.submissionRepo.listByDefinition({ workspaceId: WORKSPACE_ID, formDefinitionId: "def-1", limit: 10 });
  assert.ok(page.items[0]);
  assert.deepEqual(page.items[0].data, { name: "Ada", email: "ada@example.com" });
  assert.ok(!("message" in page.items[0].data));
});

test("EC-05: a definition disabled after submitForm's status check still accepts the in-flight submission", async () => {
  // Wraps the real repo so disabling happens exactly between submitForm's `findBySlug` status
  // check and the rest of its work — proving there is no second status re-check later in the
  // control flow (by construction: submitForm reads the definition exactly once).
  const realRepo = new InMemoryFormDefinitionRepo();
  await realRepo.create(makeDefinition());

  let disabledMidFlight = false;
  const interceptingRepo: import("../ports.js").FormDefinitionRepoPort = {
    findById: (input) => realRepo.findById(input),
    list: (input) => realRepo.list(input),
    create: (record) => realRepo.create(record),
    update: (record) => realRepo.update(record),
    isSlugTaken: (target) => realRepo.isSlugTaken(target),
    findBySlug: async (input) => {
      const found = await realRepo.findBySlug(input);
      // Simulate an admin's disable committing right after this read returns.
      if (found) {
        await realRepo.update({ ...found, status: "disabled" });
        disabledMidFlight = true;
      }
      return found;
    },
  };

  const deps = { ...makeSubmitDeps(), definitionRepo: interceptingRepo };

  const result = await submitForm({
    deps,
    input: { workspaceId: WORKSPACE_ID, slug: "contact", body: { name: "Ada", email: "ada@example.com" }, sourceIp: "1.1.1.1" },
  });

  assert.equal(disabledMidFlight, true);
  assert.equal(result.status, "accepted");

  const page = await deps.submissionRepo.listByDefinition({ workspaceId: WORKSPACE_ID, formDefinitionId: "def-1", limit: 10 });
  assert.equal(page.items.length, 1);

  // Confirm the definition really is disabled now — a SUBSEQUENT submission is rejected.
  const definitionNow = await realRepo.findBySlug({ workspaceId: WORKSPACE_ID, slug: "contact" });
  assert.equal(definitionNow?.status, "disabled");
  await assert.rejects(
    () => submitForm({ deps, input: { workspaceId: WORKSPACE_ID, slug: "contact", body: { name: "Grace", email: "grace@example.com" }, sourceIp: "2.2.2.2" } }),
    FormDefinitionNotFoundError
  );
  assert.equal((await deps.submissionRepo.listByDefinition({ workspaceId: WORKSPACE_ID, formDefinitionId: "def-1", limit: 10 })).items.length, 1);
});

