/** Todo 15b: the public submission boundary must enforce native email syntax before writes. */
import assert from "node:assert/strict";
import { test } from "vitest";
import { InMemoryEventBus, InMemoryOutbox } from "./eventing.fixture.js";
import { FormDefinitionNotFoundError, FormSubmissionValidationError, type FormDefinitionRecord } from "../index.js";
import { InMemoryFormDefinitionRepo, InMemoryFormSubmissionRepo } from "./support/repo-ports.fixture.js";
import { submitForm } from "./support/host-ports.fixture.js";
import { assertSubmissionEmails } from "../submission-email-validation.js";

async function fixture(overrides: Partial<FormDefinitionRecord> = {}) {
  const definitionRepo = new InMemoryFormDefinitionRepo();
  const submissionRepo = new InMemoryFormSubmissionRepo();
  const outbox = new InMemoryOutbox();
  const definition: FormDefinitionRecord = {
    id: "f1", workspaceId: "w1", name: "Contact", slug: "contact", version: 1, status: "active",
    fields: [{ id: "email", label: "Email", type: "email", required: true }],
    notify: { enabled: false, recipients: [] }, createdAt: "2026-10-07T00:00:00Z", updatedAt: "2026-10-07T00:00:00Z", ...overrides,
  };
  await definitionRepo.create(definition);
  let rateChecks = 0;
  let ids = 0;
  const deps = { definitionRepo, submissionRepo, outbox, bus: new InMemoryEventBus(), clock: { nowMs: () => 1 }, idGen: { newId: () => `id-${++ids}` }, rateLimiter: { check: async () => { rateChecks++; return { allowed: true as const }; } } };
  return {
    submit: (body: Record<string, unknown>) => submitForm({ deps, input: { workspaceId: "w1", slug: "contact", sourceIp: "127.0.0.1", body } }),
    rows: () => submissionRepo.listByDefinition({ workspaceId: "w1", formDefinitionId: "f1", limit: 10 }),
    checks: () => rateChecks,
  };
}

test("15b rejects malformed email with exact safe errors and no writes or rate check", async () => {
  for (const email of ["not-an-email", "a@@b.com", "a b@example.com", "a@-example.com", "a@example..com", "a@example.com\n", "a@example.com,b@example.com"]) {
    const f = await fixture();
    await assert.rejects(() => f.submit({ email }), (error: unknown) => {
      assert.ok(error instanceof FormSubmissionValidationError);
      assert.equal(error.message, "submission failed field validation");
      assert.deepEqual(error.fieldErrors, [{ field: "email", reason: "invalid_email" }]);
      return true;
    });
    assert.equal((await f.rows()).items.length, 0);
    assert.equal(f.checks(), 0);
  }
});

test("15b accepts browser-valid email including plus addressing and single-label domains", async () => {
  for (const email of ["ada@example.com", "ada+news@sub.example.com", "ada@localhost", "x'y@example.com"]) {
    const f = await fixture();
    assert.deepEqual(await f.submit({ email }), { status: "accepted" });
    const page = await f.rows();
    assert.ok(page.items[0]);
    assert.equal(page.items[0].data.email, email);
  }
});

test("15b optional empty/missing email remains allowed; other field types stay unchanged", async () => {
  for (const body of [{}, { email: "" }]) {
    const f = await fixture({ fields: [{ id: "email", label: "Email", type: "email", required: false }] });
    assert.deepEqual(await f.submit(body), { status: "accepted" });
  }
  const f = await fixture({ fields: [{ id: "email", label: "Text", type: "text", required: true }] });
  assert.deepEqual(await f.submit({ email: "not-an-email" }), { status: "accepted" });
});

test("15b retains required/type/length errors and accumulates multiple email errors", async () => {
  const f = await fixture({ fields: [
    { id: "email", label: "Email", type: "email", required: true },
    { id: "backup", label: "Backup", type: "email", required: false },
    { id: "name", label: "Name", type: "text", required: true },
  ] });
  await assert.rejects(() => f.submit({ email: "bad", backup: "also-bad" }), (error: unknown) => {
    assert.ok(error instanceof FormSubmissionValidationError);
    assert.deepEqual(error.fieldErrors, [{ field: "email", reason: "invalid_email" }, { field: "backup", reason: "invalid_email" }, { field: "name", reason: "required" }]);
    return true;
  });
  for (const [body, reason] of [[{}, "required"], [{ email: 3 }, "must be a string"], [{ email: " " }, "required"], [{ email: "badbad" }, "too_long"]] as const) {
    const g = await fixture({ fields: [{ id: "email", label: "Email", type: "email", required: true, maxLength: 5 }] });
    await assert.rejects(() => g.submit(body), (error: unknown) => {
      assert.ok(error instanceof FormSubmissionValidationError);
      assert.deepEqual(error.fieldErrors, [{ field: "email", reason }]);
      return true;
    });
  }
});

test("15b preserves honeypot silent acceptance and disabled-as-not-found", async () => {
  const f = await fixture();
  assert.deepEqual(await f.submit({ email: "not-an-email", _hp: "bot" }), { status: "accepted" });
  assert.equal((await f.rows()).items.length, 0);
  const disabled = await fixture({ status: "disabled" });
  await assert.rejects(() => disabled.submit({ email: "not-an-email" }), FormDefinitionNotFoundError);
});


test("15b the guard also format-checks an email answer visible only through the body's prototype, in declared field order", () => {
  const definition: FormDefinitionRecord = {
    id: "f1", workspaceId: "w1", name: "Contact", slug: "contact", version: 1, status: "active",
    fields: [
      { id: "email", label: "Email", type: "email", required: false },
      { id: "name", label: "Name", type: "text", required: true },
    ],
    notify: { enabled: false, recipients: [] }, createdAt: "2026-10-07T00:00:00Z", updatedAt: "2026-10-07T00:00:00Z",
  };
  // The payload validator reads own keys only, so an inherited answer is "absent" to it; the guard
  // reads the property the way the old host compatibility check did and still refuses bad syntax.
  const body = Object.assign(Object.create({ email: "not-an-email" }) as Record<string, unknown>, { extra: "x" });
  assert.throws(() => assertSubmissionEmails({ definition, body }, {}), (error: unknown) => {
    assert.ok(error instanceof FormSubmissionValidationError);
    assert.equal(error.message, "submission failed field validation");
    assert.deepEqual(error.fieldErrors.map(({ field, reason }) => [field, reason]), [
      ["extra", "unregistered_key"], ["email", "invalid_email"], ["name", "required"],
    ]);
    return true;
  });
  assert.doesNotThrow(() => assertSubmissionEmails({ definition, body: Object.create({ email: "ada@example.com" }) as Record<string, unknown> }));
});

src/widgets/__tests__/marker-target-pari.source:
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { test } from "vitest";
import ts from "typescript";

import { EMBED_MARKER_TARGET_KEYS, embedMarkerTarget } from "./support/compat/markers-marker.js";
import { PAGE_EMBED_TYPES, isPageEmbedType } from "./support/compat/page-embed-types.js";

/**
 * @file Bug A (2026-09-23 interactive-bugs plan, Slice A1): keeps `EMBED_MARKER_TARGET_KEYS` — the
 * admin-facing table of "which key names this marker type's target" — honest against the server's own
 * page-embed resolver registry. `isPageEmbedType` and `PAGE_EMBED_TYPES` live in an import-safe leaf;
 * reading the actual `HTML_EMBED_RESOLVERS` registrations also catches drift in that leaf without
 * loading the server's DB/media services. Each registered type MUST have a matching target-key row,
 * with slug fallback only where its resolver reads a slug, or the admin placeholder would silently
 * regress to the id-only bug this plan fixes the moment a future resolver is added without a row.
 *
 * `marker.ts` is deliberately import-free (its own file header: PURE, no I/O, no DOM, no resolution) so
 * the admin can safely alias straight to it without pulling in server-only code. The last test
 * below is the boundary guard that keeps that true: it fails loudly the moment anyone adds an `import`
 * line to `marker.ts`.
 */

/** Reads a sibling source file relative to this test. */
function readSource(relativePath: string): string {
  return readFileSync(fileURLToPath(new URL(relativePath, import.meta.url)), "utf8");
}

/**
 * The keys of `resolver-service.ts`'s private `HTML_EMBED_RESOLVERS` literal, read from its source.
 * The registry is private. Read its top-level properties with the existing TypeScript AST library:
 * a regex ending at the first `}` truncates the list at taxonomy's nested `{ refs, deps }` argument,
 * silently omitting the media/post/content registrations that follow it.
 */
function registeredPageEmbedTypes(): string[] {
  const source = readSource("../resolver-service.ts");
  const parsed = ts.createSourceFile("resolver-service.ts", source, ts.ScriptTarget.Latest, true);
  const declaration = parsed.statements
    .filter(ts.isVariableStatement)
    .flatMap((statement) => [...statement.declarationList.declarations])
    .find((node) => ts.isIdentifier(node.name) && node.name.text === "HTML_EMBED_RESOLVERS");
  let initializer = declaration?.initializer;
  assert.ok(initializer, "could not locate HTML_EMBED_RESOLVERS in resolver-service.ts");
  while (ts.isSatisfiesExpression(initializer) || ts.isAsExpression(initializer) || ts.isParenthesizedExpression(initializer)) {
    initializer = initializer.expression;
  }
  assert.ok(ts.isObjectLiteralExpression(initializer), "HTML_EMBED_RESOLVERS must be an object literal");
  return initializer.properties.map((property) => {
    assert.ok(ts.isPropertyAssignment(property) || ts.isShorthandPropertyAssignment(property), "unsupported registry property; update this reader");
    assert.ok(ts.isIdentifier(property.name) || ts.isStringLiteral(property.name), "registry keys must be literal type names");
    return property.name.text;
  });
}

test("marker-target parity: the registry AST finds every type in the import-safe page-embed list", () => {
  assert.deepEqual(registeredPageEmbedTypes().sort(), [...PAGE_EMBED_TYPES].sort());
});

test("marker-target parity: every server-registered page-embed type declares its resolver's target keys", () => {
  for (const type of registeredPageEmbedTypes()) {
    assert.ok(isPageEmbedType(type), `expected "${type}" to be registered in HTML_EMBED_RESOLVERS`);
    const keys = EMBED_MARKER_TARGET_KEYS[type];
    assert.ok(keys, `EMBED_MARKER_TARGET_KEYS is missing an entry for registered type "${type}"`);
    // resolveTaxonomyEmbeds reads only ref.id (an ID or a unique taxonomy name), never ref.slug.
    // The other registered resolvers, including resolveFormTypeEmbeds, read id before slug.
    assert.deepEqual(keys, type === "plugin" ? ["plugin"] : type === "gallery" ? [] : type === "taxonomy" ? ["id"] : ["id", "slug"], `incorrect resolver target keys for "${type}"`);
  }
});

test("marker-target parity: form has slug fallback and taxonomy accepts only the id key", () => {
  assert.deepEqual(embedMarkerTarget("form", { slug: "contact" }), { key: "slug", value: "contact" });
  assert.deepEqual(embedMarkerTarget("form", { id: "form-id", slug: "contact" }), { key: "id", value: "form-id" });
  assert.deepEqual(embedMarkerTarget("taxonomy", { id: "Categories", slug: "categories" }), { key: "id", value: "Categories" });
  assert.equal(embedMarkerTarget("taxonomy", { slug: "categories" }), undefined);
});

test("marker-target parity: the target-value length bound matches html-embeds.ts's MAX_EMBED_ID_LENGTH", () => {
  const source = readSource("../html/html-embeds.ts");
  const bound = Number(/const MAX_EMBED_ID_LENGTH = (\d+);/.exec(source)?.[1]);
  assert.ok(Number.isInteger(bound) && bound > 0, "could not read MAX_EMBED_ID_LENGTH from html-embeds.ts");

  assert.deepEqual(embedMarkerTarget("widget", { slug: "s".repeat(bound) }), { key: "slug", value: "s".repeat(bound) });
  assert.equal(embedMarkerTarget("widget", { slug: "s".repeat(bound + 1) }), undefined);
});

test("marker.ts stays import-free so the admin's alias never pulls in server-only code", () => {
  const source = readSource("../markers/marker.ts");

  const parsed = ts.createSourceFile("marker.ts", source, ts.ScriptTarget.Latest, true);
  const dependencies: string[] = [];
  function visit(node: ts.Node) {
    if (ts.isImportDeclaration(node) || (ts.isExportDeclaration(node) && node.moduleSpecifier)) dependencies.push(node.getText(parsed));
    if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword) dependencies.push(node.getText(parsed));
    if (ts.isImportEqualsDeclaration(node)) dependencies.push(node.getText(parsed));
    ts.forEachChild(node, visit);
  }
  visit(parsed);
  assert.deepEqual(dependencies, [], "marker must not acquire a dependency through imports or re-exports");
});


test("marker-target parity: plugin identity is independent of authored id/slug", () => {
  assert.deepEqual(embedMarkerTarget("plugin", { plugin: "example/login", component: "button", id: "wrong", slug: "wrong" }), { key: "plugin", value: "example/login" });
  assert.equal(embedMarkerTarget("plugin", { component: "button", id: "wrong" }), undefined);
});

src/forms/__tests__/submission-ip-retent.source:
import assert from "node:assert/strict";
import { test } from "vitest";
import { describeEachDialect } from "./support/dialect-matrix.fixture.js";
import { createSubmissionIpRetentionRepo } from "./support/repo-ports.fixture.js";
import type { ContentKernel } from "./support/dialect-matrix.fixture.js";
import { sql } from "kysely";
import type { StorageDialect } from "@jini-ai/db/kernel";
import { eachDialect } from "../../core/__tests__/support/dialect-matrix.js";
import { createTables } from "./support/forms-tables.fixture.js";

/** Owner retention decision 2026-10-04 / DR-002: prove real SQL writes on SQLite and PGlite. */
const NOW = Date.parse("2026-10-04T12:00:00.000Z");
const DAY = 24 * 60 * 60 * 1000;
const CUTOFF = new Date(NOW - 90 * DAY).toISOString();

async function seed(kernel: ContentKernel, rows: { id: string; age: number; workspaceId?: string; trashed?: boolean }[]) {
  await kernel.run(db => db.insertInto("form_definitions").values({
    id: "def", workspace_id: "ws", name: "Contact", slug: "contact", fields_json: "[]", notify_json: "{}",
    status: "active", created_at: CUTOFF, updated_at: CUTOFF, version: 1,
  }).execute());
  await kernel.run(db => db.insertInto("form_submissions").values(rows.map(row => ({
    id: row.id, workspace_id: row.workspaceId ?? "ws", form_definition_id: "def", data_json: '{"message":"preserve me"}',
    source_ip: "203.0.113.8", submitted_at: new Date(NOW - row.age).toISOString(),
    deleted_at: row.trashed ? CUTOFF : null, version: 7,
  }))).execute());
}

describeEachDialect("submission IP retention adapter and migration 0006", {
  tables: ["form_submissions", "form_definitions"], make: kernel => ({ kernel, repo: createSubmissionIpRetentionRepo({ kernel }) }),
}, make => {
  test("bounded batches cover more than 500 records; concurrent passes count each cleared row once", async () => {
    const { kernel, repo } = make();
    await seed(kernel, Array.from({ length: 501 }, (_, i) => ({ id: `s-${i}`, age: 91 * DAY })));
    const counts = await Promise.all([
      repo.clearExpiredIps({ submittedBeforeOrAt: CUTOFF }, { limit: 500 }),
      createSubmissionIpRetentionRepo({ kernel }).clearExpiredIps({ submittedBeforeOrAt: CUTOFF }, { limit: 500 }),
    ]);
    assert.ok(counts.every(count => count <= 500));
    const tail = await repo.clearExpiredIps({ submittedBeforeOrAt: CUTOFF }, { limit: 500 });
    assert.equal(counts.reduce((a, b) => a + b, 0) + tail, 501);
    const rows = await kernel.run(db => db.selectFrom("form_submissions").selectAll().execute());
    assert.equal(rows.length, 501);
    assert.ok(rows.every(row => row.source_ip === null && row.data_json === '{"message":"preserve me"}' && row.version === 7));
    assert.equal(await repo.clearExpiredIps({ submittedBeforeOrAt: CUTOFF }, { limit: 500 }), 0);
  });
});


describeEachDialect("submission IP retention adapter input bounds", {
  tables: ["form_submissions", "form_definitions"], make: kernel => ({ kernel, repo: createSubmissionIpRetentionRepo({ kernel }) }),
}, make => {
  test("a non-positive or non-integer batch limit is refused before any IP is cleared", async () => {
    const { kernel, repo } = make();
    await seed(kernel, [{ id: "old", age: 91 * DAY }]);
    for (const limit of [0, -1, 1.5, Number.NaN]) {
      await assert.rejects(repo.clearExpiredIps({ submittedBeforeOrAt: CUTOFF }, { limit }), RangeError, String(limit));
    }
    const rows = await kernel.run(db => db.selectFrom("form_submissions").select("source_ip").execute());
    assert.deepEqual(rows, [{ source_ip: "203.0.113.8" }]);
    assert.equal(await repo.clearExpiredIps({ submittedBeforeOrAt: CUTOFF }), 1);
  });
});

/** The pre-0006 schema: `source_ip` still NOT NULL, built from the current DDL so nothing else differs. */
async function createPre0006Tables(kernel: ContentKernel, dialect: StorageDialect): Promise<void> {
  await createTables(kernel, dialect);
  await kernel.execute(sql.raw("DROP INDEX idx_form_submissions_ip_retention"));
  if (dialect === "postgres") {
    await kernel.execute(sql.raw("ALTER TABLE form_submissions ALTER COLUMN source_ip SET NOT NULL"));
    return;
  }
  await kernel.execute(sql.raw("DROP TABLE form_submissions"));
  await kernel.execute(sql.raw("CREATE TABLE form_submissions (id text PRIMARY KEY NOT NULL, workspace_id text NOT NULL, form_definition_id text NOT NULL, data_json text NOT NULL, source_ip text NOT NULL, submitted_at text NOT NULL, deleted_at text, version integer DEFAULT 1 NOT NULL)"));
}

/** Migration 0006's effect on each dialect: SQLite rebuilds the table, Postgres drops the constraint. */
async function applyNullableIpMigration(kernel: ContentKernel, dialect: StorageDialect): Promise<void> {
  if (dialect === "postgres") {
    await kernel.execute(sql.raw("ALTER TABLE form_submissions ALTER COLUMN source_ip DROP NOT NULL"));
    return;
  }
  await kernel.execute(sql.raw("CREATE TABLE form_submissions_0006 (id text PRIMARY KEY NOT NULL, workspace_id text NOT NULL, form_definition_id text NOT NULL, data_json text NOT NULL, source_ip text, submitted_at text NOT NULL, deleted_at text, version integer DEFAULT 1 NOT NULL)"));
  await kernel.execute(sql.raw("INSERT INTO form_submissions_0006 SELECT * FROM form_submissions"));
  await kernel.execute(sql.raw("DROP TABLE form_submissions"));
  await kernel.execute(sql.raw("ALTER TABLE form_submissions_0006 RENAME TO form_submissions"));
}

for (const each of eachDialect({ tables: ["form_submissions", "form_definitions"], make: (kernel: ContentKernel) => kernel, createTables: createPre0006Tables }, {})) {
  test(`[${each.name}] before migration 0006 the adapter refuses without writing, and re-probes once the migration lands`, async () => {
    const kernel = each.make();
    const repo = createSubmissionIpRetentionRepo({ kernel });
    await seed(kernel, [{ id: "old", age: 91 * DAY }]);
    for (let pass = 0; pass < 2; pass++) {
      await assert.rejects(repo.clearExpiredIps({ submittedBeforeOrAt: CUTOFF }), /requires the nullable source_ip migration \(0006\)/);
    }
    assert.deepEqual(await kernel.run(db => db.selectFrom("form_submissions").select("source_ip").execute()), [{ source_ip: "203.0.113.8" }]);
    await applyNullableIpMigration(kernel, each.dialect);
    assert.equal(await repo.clearExpiredIps({ submittedBeforeOrAt: CUTOFF }), 1);
    assert.deepEqual(await kernel.run(db => db.selectFrom("form_submissions").select("source_ip").execute()), [{ source_ip: null }]);
  });
}

src/consent/__tests__/request-choices.te.source:
import type { Request } from 'express';
import { describe, expect, it } from 'vitest';
import { readRequestConsentChoices, type ConsentHttpPorts } from '../express/index.js';
import { DENIED_CHOICES, type ConsentConfig, type ConsentRecord } from '../types.js';
import { accepted, config, now } from './fixtures.js';

const ALL = { necessary: true, functional: true, analytics: true, marketing: true };

/** Only `get` is read from the request, so a header map stands in for Express. */
function fakeRequest(headers: Record<string, string> = {}): Request {
  const lower = Object.fromEntries(Object.entries(headers).map(([key, value]) => [key.toLowerCase(), value]));
  return { get: (name: string) => lower[name.toLowerCase()] } as unknown as Request;
}

type FakeOptions = { configOverride?: Partial<ConsentConfig>; records?: ConsentRecord[]; configFails?: boolean };
function fakePorts({ configOverride = {}, records = [], configFails = false }: FakeOptions = {}) {
  const stored = new Map(records.map(record => [record.id, record]));
  const failures: Array<{ operation: string; error: unknown }> = [];
  const ports: Parameters<typeof readRequestConsentChoices>[0]['ports'] = {
    config: { get: async () => { if (configFails) throw new Error('Ledger unavailable'); return { ...config, ...configOverride }; } },
    records: { read: async ({ id }) => stored.get(id) ?? null, save: async () => undefined },
    clock: { nowIso: () => now, nowMs: () => Date.parse(now) },
    readReceiptId: ({ cookieHeader }) => cookieHeader.match(/jini_consent=([a-zA-Z0-9_-]+)/)?.[1] ?? null,
    region: ({ request }) => request.get('x-edge-region') ?? null,
    reportError: failure => { failures.push(failure); },
  };
  return { ports, failures };
}

const rejected: ConsentRecord = { ...accepted, id: 'receipt_rejected_0123456789', action: 'reject', choices: { ...DENIED_CHOICES } };

describe('readRequestConsentChoices', () => {
  it('grants every category when consent is disabled, matching the ungated page path', async () => {
    const { ports, failures } = fakePorts({ configOverride: { enabled: false } });
    expect(await readRequestConsentChoices({ ports, request: fakeRequest({ 'sec-gpc': '1' }) })).toEqual(ALL);
    expect(failures).toEqual([]);
  });

  it('reads an accept receipt from the default cookie as an analytics grant', async () => {
    const { ports, failures } = fakePorts({ records: [accepted] });
    const choices = await readRequestConsentChoices({ ports, request: fakeRequest({ cookie: `jini_consent=${accepted.id}` }) });
    expect(choices).toEqual(ALL);
    expect(failures).toEqual([]);
  });

  it('honours a stored rejection even in an opt-out region', async () => {
    const { ports } = fakePorts({ records: [rejected] });
    const choices = await readRequestConsentChoices({ ports, request: fakeRequest({ cookie: `jini_consent=${rejected.id}`, 'x-edge-region': 'US-CA' }) });
    expect(choices).toEqual(DENIED_CHOICES);
  });

  it('denies optional categories to an opt-in visitor without a cookie', async () => {
    const { ports, failures } = fakePorts();
    const choices = await readRequestConsentChoices({ ports, request: fakeRequest() });
    expect(choices).toEqual(DENIED_CHOICES);
    expect(choices.analytics).toBe(false);
    expect(failures).toEqual([]);
  });

  it('allows optional categories to an opt-out region visitor without a cookie', async () => {
    const { ports } = fakePorts();
    const choices = await readRequestConsentChoices({ ports, request: fakeRequest({ 'x-edge-region': 'US-CA' }) });
    expect(choices).toEqual(ALL);
  });

  it('treats a cookie whose receipt is missing as failed proof, denied even in an opt-out region', async () => {
    const { ports, failures } = fakePorts();
    const choices = await readRequestConsentChoices({ ports, request: fakeRequest({ cookie: 'jini_consent=receipt_evicted_0123456789', 'x-edge-region': 'US-CA' }) });
    expect(choices).toEqual(DENIED_CHOICES);
    expect(failures).toHaveLength(1);
    expect(failures[0]?.operation).toBe('read');
    expect(String(failures[0]?.error)).toContain('unavailable');
  });

  it('lets the Sec-GPC header deny analytics and marketing despite an accept receipt', async () => {
    const { ports } = fakePorts({ records: [accepted] });
    const choices = await readRequestConsentChoices({ ports, request: fakeRequest({ cookie: `jini_consent=${accepted.id}`, 'sec-gpc': '1' }) });
    expect(choices.analytics).toBe(false);
    expect(choices.marketing).toBe(false);
    expect(choices.necessary).toBe(true);
  });

  it('reads a custom cookie name and ignores the default one', async () => {
    const { ports } = fakePorts({ records: [accepted] });
    ports.readReceiptId = ({ cookieHeader }) => cookieHeader.match(/site_consent=([a-zA-Z0-9_-]+)/)?.[1] ?? null;
    const request = fakeRequest({ cookie: `site_consent=${accepted.id}` });
    expect(await readRequestConsentChoices({ ports, request }, { cookieName: 'site_consent' })).toEqual(ALL);
  });

  it('returns a fresh denied object and reports the error when config.get throws', async () => {
    const { ports, failures } = fakePorts({ configFails: true, records: [accepted] });
    const choices = await readRequestConsentChoices({ ports, request: fakeRequest({ cookie: `jini_consent=${accepted.id}`, 'x-edge-region': 'US-CA' }) });
    expect(choices).toEqual(DENIED_CHOICES);
    expect(choices).not.toBe(DENIED_CHOICES);
    expect(Object.isFrozen(choices)).toBe(false);
    expect(failures).toHaveLength(1);
    expect(failures[0]?.operation).toBe('read');
    expect((failures[0]?.error as Error).message).toBe('Ledger unavailable');
  });

  it('never throws when the region port throws; it reports and denies', async () => {
    const { ports, failures } = fakePorts();
    ports.region = () => { throw new Error('Edge header unreadable'); };
    await expect(readRequestConsentChoices({ ports, request: fakeRequest() })).resolves.toEqual(DENIED_CHOICES);
    expect(failures.map(failure => (failure.error as Error).message)).toEqual(['Edge header unreadable']);
  });

  it('accepts a full ConsentHttpPorts bag', async () => {
    const { ports } = fakePorts();
    const full: ConsentHttpPorts = { ...ports, ids: { newId: () => 'unused' }, origin: () => 'https://site.example', allowWrite: async () => true };
    expect(await readRequestConsentChoices({ ports: full, request: fakeRequest() })).toEqual(DENIED_CHOICES);
  });
});

src/navigation/__tests__/dropdown.test.t.source:
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { test } from 'vitest';
import { MENU_DROPDOWN_SCRIPT, injectMenuDropdownScript, renderMenuToggle } from '../index.js';

// Untyped, as in listing/__tests__/see-more-script.test.ts: this package carries no @types/jsdom.
const { JSDOM } = createRequire(import.meta.url)('jsdom');

/** Runs the inline dropdown script in its own JSDOM window (no global DOM, per vitest.config.ts)
 *  over a two-item menu: a split "Blog" parent with a "Tips" flyout, and a link-less "Plan" parent. */
function page() {
  const dom = new JSDOM(
    `<ul class="menu-list depth-0" data-jini-dropdown>
      <li class="menu-item depth-0 has-children"><a href="/blog">Blog</a>${renderMenuToggle({ controlsId: 's1', label: 'Blog' })}
        <ul class="menu-list depth-1" id="s1">
          <li><a href="/blog/a">A</a></li>
          <li class="has-children">${renderMenuToggle({ controlsId: 's3', label: 'Tips' }, { asLabel: true })}<ul id="s3"><li><a href="/tips/1">T1</a></li></ul></li>
          <li><a href="/blog/c">C</a></li>
        </ul></li>
      <li class="menu-item depth-0 has-children">${renderMenuToggle({ controlsId: 's2', label: 'Plan' }, { asLabel: true })}
        <ul class="menu-list depth-1" id="s2"><li><a href="/plan/x">X</a></li></ul></li>
    </ul><button id="out" type="button">Out</button>`,
    { url: 'https://site.test/', runScripts: 'outside-only' }
  );
  const window = dom.window as unknown as Window & typeof globalThis & { eval(code: string): void };
  window.eval(MENU_DROPDOWN_SCRIPT);
  const doc = window.document;
  const $ = <T extends Element = HTMLElement>(sel: string) => doc.querySelector(sel) as unknown as T;
  const key = (el: Element, k: string) => {
    const ev = new window.KeyboardEvent('keydown', { key: k, bubbles: true, cancelable: true });
    el.dispatchEvent(ev);
    return ev.defaultPrevented;
  };
  const blog = $<HTMLButtonElement>('[aria-controls="s1"]');
  const plan = $<HTMLButtonElement>('[aria-controls="s2"]');
  const tips = $<HTMLButtonElement>('[aria-controls="s3"]');
  return { doc, $, key, blog, plan, tips };
}

const isOpen = (b: HTMLButtonElement) => b.getAttribute('aria-expanded') === 'true' && b.parentElement!.classList.contains('jini-menu-open');

test('renderMenuToggle: split toggle is empty with an aria-label; label form carries menu-item-label; both escape', () => {
  assert.equal(
    renderMenuToggle({ controlsId: 'jini-submenu-1', label: 'A "&" <b>' }),
    '<button type="button" class="jini-menu-toggle" aria-expanded="false" aria-controls="jini-submenu-1" aria-label="A &quot;&amp;&quot; &lt;b&gt; submenu"></button>'
  );
  assert.equal(
    renderMenuToggle({ controlsId: 'x"y', label: '<i>Plan</i>' }, { asLabel: true }),
    '<button type="button" class="menu-item-label jini-menu-toggle" aria-expanded="false" aria-controls="x&quot;y">&lt;i&gt;Plan&lt;/i&gt;</button>'
  );
});

test('injectMenuDropdownScript: once, only with a dropdown menu, before </body>', () => {
  const plain = '<html><body><ul class="menu-list"></ul></body></html>';
  assert.equal(injectMenuDropdownScript({ html: plain }), plain);
  const once = injectMenuDropdownScript({ html: '<html><body><ul data-jini-dropdown></ul></body></html>' });
  assert.ok(once.endsWith(`<script data-jini-menu-dropdown-script>${MENU_DROPDOWN_SCRIPT}</script></body></html>`));
  assert.equal(injectMenuDropdownScript({ html: once }), once);
  assert.equal(injectMenuDropdownScript({ html: '<ul data-jini-dropdown></ul>' }), `<ul data-jini-dropdown></ul><script data-jini-menu-dropdown-script>${MENU_DROPDOWN_SCRIPT}</script>`);
});

test('script: marks the root, click toggles aria-expanded + class, opening one closes its sibling, click outside closes', () => {
  const p = page();
  assert.ok(p.$('[data-jini-dropdown]').classList.contains('jini-menu-js'));
  p.blog.click();
  assert.ok(isOpen(p.blog));
  p.blog.click();
  assert.ok(!isOpen(p.blog));
  p.blog.click();
  p.plan.click();
  assert.ok(isOpen(p.plan));
  assert.ok(!isOpen(p.blog));
  p.$('#out').click();
  assert.ok(!isOpen(p.plan));
});

test('script: closing a parent closes its open flyout too', () => {
  const p = page();
  p.blog.click();
  p.tips.click();
  assert.ok(isOpen(p.blog) && isOpen(p.tips));
  p.blog.click();
  assert.ok(!isOpen(p.blog) && !isOpen(p.tips));
});

test('script: Escape closes the nearest open item and returns focus to its toggle', () => {
  const p = page();
  p.blog.click();
  p.tips.click();
  const t1 = p.$('a[href="/tips/1"]');
  t1.focus();
  p.key(t1, 'Escape');
  assert.ok(!isOpen(p.tips) && isOpen(p.blog));
  assert.equal(p.doc.activeElement, p.tips);
  p.key(p.tips, 'Escape');
  assert.ok(!isOpen(p.blog));
  assert.equal(p.doc.activeElement, p.blog);
});

test('script: ArrowDown on a toggle opens and focuses the first item; ArrowDown/Up move within the panel and clamp', () => {
  const p = page();
  p.blog.focus();
  assert.equal(p.key(p.blog, 'ArrowDown'), true);
  assert.ok(isOpen(p.blog));
  assert.equal(p.doc.activeElement, p.$('a[href="/blog/a"]'));
  p.key(p.doc.activeElement!, 'ArrowUp');
  assert.equal(p.doc.activeElement, p.$('a[href="/blog/a"]'));
  p.key(p.doc.activeElement!, 'ArrowDown');
  assert.equal(p.doc.activeElement, p.tips);
  p.key(p.doc.activeElement!, 'ArrowUp');
  assert.equal(p.doc.activeElement, p.$('a[href="/blog/a"]'));
  p.key(p.doc.activeElement!, 'ArrowDown');
  p.key(p.doc.activeElement!, 'ArrowDown'); // on the Tips toggle: opens the flyout
  assert.ok(isOpen(p.tips));
  assert.equal(p.doc.activeElement, p.$('a[href="/tips/1"]'));
});

test('script: ArrowLeft/Right move between top-level items; unhandled keys pass through', () => {
  const p = page();
  const blogLink = p.$('a[href="/blog"]');
  blogLink.focus();
  assert.equal(p.key(blogLink, 'ArrowRight'), true);
  assert.equal(p.doc.activeElement, p.plan);
  p.key(p.plan, 'ArrowRight');
  assert.equal(p.doc.activeElement, p.plan);
  p.key(p.plan, 'ArrowLeft');
  assert.equal(p.doc.activeElement, blogLink);
  assert.equal(p.key(blogLink, 'ArrowDown'), false);
  assert.equal(p.key(blogLink, 'a'), false);
});

test('script: focus moving outside an open item closes it', () => {
  const p = page();
  p.blog.click();
  p.plan.focus();
  assert.ok(!isOpen(p.blog));
  p.plan.click();
  p.$('#out').focus();
  assert.ok(!isOpen(p.plan));
});

