import assert from "node:assert/strict";
import { test } from "vitest";

import { InMemoryOutbox } from "../../redirects/__tests__/support/events.fixture.js";
import { createCommentHookRegistry } from "../hooks.js";
import { InMemoryCommentRepo } from "../repo.memory.js";
import { createCommentWriteService } from "../write-service.js";
import type { CommentRecord } from "../types.js";
import { commentTrashDoubles } from "./comment-trash-doubles.js";

/** @file Remaining comment-domain contracts: swallowed status hooks, the memory repo's upsert,
 * and purge racing a concurrent insert. */

const WS = "ws-misc";
const NOW = "2026-07-16T01:00:00.000Z";

function comment(id: string, overrides: Partial<CommentRecord> = {}): CommentRecord {
  return {
    id, workspaceId: WS, entryId: "entry-1", parentId: null, threadRootId: id, depth: 0, status: "pending",
    authorPrincipalId: null, authorName: "Visitor", authorEmail: null, authorUrl: null, authorIpHash: null,
    bodyText: "Hello", spamScore: 0, spamProvider: null, createdAt: NOW, updatedAt: NOW, version: 0, ...overrides,
  };
}

test("a throwing statusChanged hook is swallowed and later hooks still run", async () => {
  const registry = createCommentHookRegistry();
  const seen: string[] = [];
  registry.registerStatusChangedHook({ hook: async () => { seen.push("first"); throw new Error("hook down"); } }, {});
  registry.registerStatusChangedHook({ hook: async ({ commentId }) => { seen.push(`second:${commentId}`); } }, {});

  await registry.runStatusChangedHooks({ workspaceId: WS, commentId: "c-1", fromStatus: "pending", toStatus: "approved" });
  assert.deepEqual(seen, ["first", "second:c-1"]);
});

test("InMemoryCommentRepo.save inserts a new row and replaces an existing one in place", async () => {
  const repo = new InMemoryCommentRepo({ initialComments: [comment("keep"), comment("c-1")] });
  await repo.save(comment("c-2", { bodyText: "new" }));
  await repo.save(comment("c-1", { status: "trash", version: 3 }));
  await repo.save(comment("c-1", { workspaceId: "other-ws", bodyText: "same id, other workspace" }));

  assert.equal((await repo.findById({ workspaceId: WS, id: "c-2" }))?.bodyText, "new");
  assert.deepEqual(await repo.findById({ workspaceId: WS, id: "c-1" }), comment("c-1", { status: "trash", version: 3 }));
  assert.equal((await repo.findById({ workspaceId: "other-ws", id: "c-1" }))?.bodyText, "same id, other workspace");
  const all = await repo.listThreadForEntry({ workspaceId: WS, entryId: "entry-1", includeStatuses: ["pending", "trash"] });
  assert.deepEqual(all.map((node) => node.comment.id).sort(), ["c-1", "c-2", "keep"], "replacing must not duplicate a row");
});

test("purge of a row that appeared after the pre-read succeeds and forgets it, but emits no event", async () => {
  const repo = new InMemoryCommentRepo();
  const outbox = new InMemoryOutbox();
  const trash = commentTrashDoubles();
  const service = createCommentWriteService({
    repo, outbox, hooks: createCommentHookRegistry(),
    clock: { nowMs: () => Date.parse(NOW) }, idGen: { newId: () => "event-1" },
    ...trash,
    // A concurrent writer commits the row between purge's pre-read and its transaction: the
    // pre-read saw nothing, so there is no entryId/status to describe a `comments.purged` event.
    runInTransaction: async (fn) => { await repo.create({ record: comment("late") }, {}); return fn(); },
  });

  const result = await service.purge({ workspaceId: WS, id: "late", actorPrincipalId: "admin-1", note: null });
  assert.deepEqual(result, { ok: true });
  assert.equal(await repo.findById({ workspaceId: WS, id: "late" }), null);
  assert.deepEqual(trash.forgotten, [{ workspaceId: WS, id: "late" }]);
  assert.deepEqual(await outbox.claimPending({ batchSize: 10, nowIso: NOW }), []);
});

test("purge of an unknown comment reports not-found and touches neither the Trash index nor the outbox", async () => {
  const repo = new InMemoryCommentRepo();
  const outbox = new InMemoryOutbox();
  const trash = commentTrashDoubles();
  const service = createCommentWriteService({
    repo, outbox, hooks: createCommentHookRegistry(),
    clock: { nowMs: () => Date.parse(NOW) }, idGen: { newId: () => "event-1" }, ...trash,
  });

  assert.deepEqual(await service.purge({ workspaceId: WS, id: "missing", actorPrincipalId: "admin-1", note: null }), { ok: false, reason: "not-found" });
  assert.deepEqual(trash.forgotten, []);
  assert.deepEqual(await outbox.claimPending({ batchSize: 10, nowIso: NOW }), []);
});

test("InMemoryCommentRepo moderation queue breaks createdAt ties by id, across pages", async () => {
  const repo = new InMemoryCommentRepo({
    initialComments: [
      comment("c-b", { createdAt: "2026-07-16T00:00:00.000Z" }),
      comment("c-a", { createdAt: "2026-07-16T00:00:00.000Z" }),
      comment("c-early", { createdAt: "2026-07-15T00:00:00.000Z" }),
      comment("c-c", { createdAt: "2026-07-16T00:00:00.000Z" }),
    ],
  });

  const first = await repo.listModerationQueue({ workspaceId: WS, status: "pending", limit: 2 });
  assert.deepEqual(first.items.map((c) => c.id), ["c-early", "c-a"]);
  const second = await repo.listModerationQueue({ workspaceId: WS, status: "pending", limit: 2, cursor: first.nextCursor });
  assert.deepEqual(second.items.map((c) => c.id), ["c-b", "c-c"]);
  assert.equal(second.nextCursor, null);
});

src/seo/__tests__/sitemap.schedule-expir.source:
import assert from "node:assert/strict";
import { test, vi, afterEach } from "vitest";

import { InMemoryPostRepo, type PostRecord } from "./support/post.fixture.js";
import { InMemorySettingsRepo } from "./support/legacy-api.fixture.js";
import { InMemoryAssetRenditionRepo, InMemoryMediaRepo, InMemoryTransformDefinitionRepo } from "../../media/index.js";
import { OriginNotVerifiedError, type OriginRegistryPort } from "@jini-ai/http-kit/verified-origin";
import { ensureSeoSettingDefinitions } from "./support/legacy-api.fixture.js";
import { buildSitemap, invalidateSitemapCache } from "./support/legacy-api.fixture.js";
import { buildPostRecord } from "./support/post.fixture.js";

/**
 * @file Scheduled publishing (2026-10-05): nothing emits an event when a scheduled post goes live,
 * so the cached sitemap carries an expiry at the earliest future `publishAt` and is rebuilt on the
 * first read at or after it. The wall clock is faked with `mock.timers` (Date only), because
 * `currentIso()` reads `new Date()`.
 */

const WORKSPACE = "workspace-sitemap-expiry";
const T0 = Date.parse("2026-10-05T12:00:00.000Z");
const GO_LIVE = "2026-10-05T13:00:00.000Z";
const clock = { nowIso: () => new Date(T0).toISOString() };
let idCounter = 0;
const ids = { newId: () => `sitemap-expiry-id-${++idCounter}` };
const alwaysAllow = async () => ({ allowed: true, reason: "matched" });

function post(overrides: Partial<PostRecord>): PostRecord {
  return buildPostRecord({
    workspaceId: WORKSPACE,
    title: "Post",
    bodyJson: { type: "doc", content: [] },
    status: "published",
    kind: "post",
    updatedAt: "2026-10-01T00:00:00.000Z",
    version: 1,
    seoExtJson: null,
    ...overrides,
  });
}

function originRegistry(): OriginRegistryPort {
  return {
    async canonicalOrigin() {
      throw new OriginNotVerifiedError({ message: "no verified origin registered for this workspace" });
    },
    async isAllowedRedirectTarget() {
      return false;
    },
    async isAllowedEgressTarget() {
      return false;
    },
  };
}

async function makeDeps(posts: PostRecord[]) {
  invalidateSitemapCache({ workspaceId: WORKSPACE });
  const settingsRepo = new InMemorySettingsRepo();
  const settingsDeps = { settingsRepo, clock, ids, authorize: alwaysAllow, principals: { findById: async () => null } as never };
  await ensureSeoSettingDefinitions(settingsDeps, { workspaceId: WORKSPACE, systemPrincipalId: "system-seo" });
  return {
    postRepo: new InMemoryPostRepo(posts),
    settingsRepo,
    media: {
      mediaRepo: new InMemoryMediaRepo({}, { initialRows: [] }),
      assetRenditionRepo: new InMemoryAssetRenditionRepo({}, { initialRows: [] }),
      transformDefinitionRepo: new InMemoryTransformDefinitionRepo({}, { initialRows: [] }),
    },
    originRegistry: originRegistry(),
  };
}

const locs = (entries: ReadonlyArray<{ loc: string }>) => entries.map((entry) => entry.loc).sort();

test("buildSitemap: the cached sitemap expires at a scheduled post's go-live time, and the post appears", async (t) => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(T0);

  const deps = await makeDeps([post({ id: "live", slug: "live" }), post({ id: "later", slug: "later", publishAt: GO_LIVE })]);

  assert.deepEqual(locs(await buildSitemap(deps, { workspaceId: WORKSPACE })), ["/live"], "a scheduled post is not in the sitemap before it goes live");

  // A row written without any invalidation proves the next read is still the cache, not a rebuild.
  await deps.postRepo.save(post({ id: "silent", slug: "silent" }));
  tickDate(Date.parse(GO_LIVE) - T0 - 1);
  assert.deepEqual(locs(await buildSitemap(deps, { workspaceId: WORKSPACE })), ["/live"], "the cache holds until the go-live instant");

  tickDate(1);
  assert.deepEqual(locs(await buildSitemap(deps, { workspaceId: WORKSPACE })), ["/later", "/live", "/silent"], "the cache is rebuilt at go-live");
});

test("buildSitemap: with nothing scheduled the cache has no expiry", async (t) => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(T0);

  const deps = await makeDeps([post({ id: "live", slug: "live" })]);

  assert.deepEqual(locs(await buildSitemap(deps, { workspaceId: WORKSPACE })), ["/live"]);
  await deps.postRepo.save(post({ id: "silent", slug: "silent" }));
  tickDate(365 * 24 * 60 * 60 * 1000);
  assert.deepEqual(locs(await buildSitemap(deps, { workspaceId: WORKSPACE })), ["/live"]);
});

test("buildSitemap: the expiry tracks the EARLIEST future go-live, and a past publishAt sets none", async (t) => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(T0);

  const deps = await makeDeps([
    post({ id: "past", slug: "past", publishAt: "2026-10-01T00:00:00.000Z" }),
    post({ id: "late", slug: "late", publishAt: "2026-10-05T15:00:00.000Z" }),
    post({ id: "soon", slug: "soon", publishAt: GO_LIVE }),
  ]);

  assert.deepEqual(locs(await buildSitemap(deps, { workspaceId: WORKSPACE })), ["/past"]);
  tickDate(Date.parse(GO_LIVE) - T0);
  assert.deepEqual(locs(await buildSitemap(deps, { workspaceId: WORKSPACE })), ["/past", "/soon"]);
  tickDate(2 * 60 * 60 * 1000);
  assert.deepEqual(locs(await buildSitemap(deps, { workspaceId: WORKSPACE })), ["/late", "/past", "/soon"]);
});

function tickDate(ms: number) { vi.setSystemTime(Date.now() + ms); }

afterEach(() => { vi.restoreAllMocks(); vi.useRealTimers(); });

