import assert from "node:assert/strict";
import { test } from "vitest";

import { deriveAvailableFormSlug, slugifyFormName, FORM_SLUG_MAX_LENGTH } from "./support/host-ports.fixture.js";
import { SLUG_PATTERN } from "../index.js";
import { deriveAvailableFormSlug as deriveFormSlug } from "../duplicate-slug.js";

/**
 * @file Certifies the slug derivation `content_duplicate`'s `"form"` resource needs and Forms did
 * not already have.
 *
 * Posts get this for free — `createPost` derives and disambiguates a slug itself when the caller
 * omits one. `createFormDefinition` does not: it REQUIRES an explicit slug and rejects anything
 * outside `^[a-z0-9][a-z0-9-]{0,63}$` (plus the reserved `new`). So duplicating a form has to
 * produce a valid, free slug before it calls create, or every copy of "Contact Us" would collide
 * with the last one. Every case here asserts against `write-service.ts`'s OWN exported
 * `SLUG_PATTERN`, so a change to that pattern breaks these tests rather than silently outdating them.
 */

function takenSet(...slugs: string[]) {
  const taken = new Set(slugs);
  return async (slug: string) => taken.has(slug);
}

const NEVER_TAKEN = async () => false;

test("slugifyFormName lowercases, collapses non-alphanumerics to single hyphens, and trims them from the ends", () => {
  assert.equal(slugifyFormName("Contact Us"), "contact-us");
  assert.equal(slugifyFormName("Copy of Contact Us"), "copy-of-contact-us");
  assert.equal(slugifyFormName("  Newsletter — Signup!!  "), "newsletter-signup");
  // Non-ASCII letters transliterate (`platform/html/slug.ts`, 2026-09-28); they used to become
  // separators, which gave "j-vou-2026".
  assert.equal(slugifyFormName("Já_Vou (2026)"), "ja-vou-2026");
});

test("slugifyFormName truncates to the pattern's own 64-character ceiling without leaving a trailing hyphen", () => {
  const slug = slugifyFormName(`${"a".repeat(60)} bbbbbbbbbb`);
  assert.equal(slug.length, FORM_SLUG_MAX_LENGTH);
  assert.doesNotMatch(slug, /-$/);
  assert.match(slug, SLUG_PATTERN);
});

test("a name with nothing sluggable falls back to a valid slug rather than an empty string", async () => {
  assert.equal(slugifyFormName("!!! ---"), "");
  assert.match(await deriveAvailableFormSlug({ name: "!!! ---" }, { isTaken: NEVER_TAKEN }), SLUG_PATTERN);
});

test("a free derived slug is used as-is", async () => {
  assert.equal(await deriveAvailableFormSlug({ name: "Copy of Contact Us" }, { isTaken: NEVER_TAKEN }), "copy-of-contact-us");
});

test("a taken slug is disambiguated with an incrementing suffix, skipping every taken one", async () => {
  const isTaken = takenSet("copy-of-contact-us", "copy-of-contact-us-2", "copy-of-contact-us-3");
  assert.equal(await deriveAvailableFormSlug({ name: "Copy of Contact Us" }, { isTaken }), "copy-of-contact-us-4");
});

test("the reserved slug 'new' is never produced — it would make the form unreachable at its own admin URL", async () => {
  const slug = await deriveAvailableFormSlug({ name: "New" }, { isTaken: NEVER_TAKEN });
  assert.notEqual(slug, "new");
  assert.match(slug, SLUG_PATTERN);
});

test("a suffix never pushes the slug past the 64-character ceiling", async () => {
  const longName = "a".repeat(FORM_SLUG_MAX_LENGTH);
  const base = slugifyFormName(longName);
  const slug = await deriveAvailableFormSlug({ name: longName }, { isTaken: takenSet(base) });

  assert.ok(slug.length <= FORM_SLUG_MAX_LENGTH, `expected <= ${FORM_SLUG_MAX_LENGTH} characters, got ${slug.length}`);
  assert.notEqual(slug, base);
  assert.match(slug, SLUG_PATTERN);
});

test("every derived slug this function can return satisfies write-service's own SLUG_PATTERN", async () => {
  for (const name of ["Contact Us", "!!!", "New", "a".repeat(200), "Über Größe", "9 Lives", "-leading-hyphen"]) {
    const slug = await deriveAvailableFormSlug({ name }, { isTaken: NEVER_TAKEN });
    assert.match(slug, SLUG_PATTERN, `'${name}' derived an invalid slug '${slug}'`);
  }
});

test("the search gives up rather than looping forever when every candidate is taken", async () => {
  await assert.rejects(
    deriveAvailableFormSlug({ name: "Contact Us" }, { isTaken: async () => true }),
    /no free slug/i,
  );
});

test("a host slugify that emits characters outside SLUG_PATTERN never reaches isTaken or the caller", async () => {
  const probed: string[] = [];
  await assert.rejects(
    deriveFormSlug({
      name: "Contact Us", slugify: (name) => name.replace(/ /g, "_"), maxAttempts: 3, reservedSlugs: new Set(),
      isTaken: async (slug) => { probed.push(slug); return false; },
    }, {}),
    /no free slug could be derived from 'Contact Us' after 3 attempts/,
  );
  assert.deepEqual(probed, []);
});

src/widgets/__tests__/unit/resolvers-tax.source:
import assert from "node:assert/strict";
import test from "../support/test-runner.js";

import type { Taxonomy, TaxonomyListPort, Term, TermListPort } from "../../../taxonomy/index.js";
import type { PageHtmlEmbedRef } from "../../html/html-embeds.js";
import { resolveTaxonomyEmbeds } from "../../resolvers/index.js";

/**
 * @file `taxonomy` embed resolution — id vs. human-readable name targeting (an ambiguous name stays
 * unresolved rather than picking one), trashed/purged taxonomies and terms hidden, one term query per
 * taxonomy per page, and graceful degradation when the host wires no read ports.
 */

const T0 = "2026-01-01T00:00:00.000Z";

function taxonomy(overrides: Partial<Taxonomy> & Pick<Taxonomy, "id" | "name">): Taxonomy {
  return { hierarchical: false, status: "active", updatedAt: T0, version: 1, ...overrides };
}

function term(overrides: Partial<Term> & Pick<Term, "id" | "taxonomyId" | "name">): Term {
  return { parentId: null, status: "active", updatedAt: T0, version: 1, ...overrides };
}

function ref(id: string | null): PageHtmlEmbedRef {
  return { type: "taxonomy", id, slug: null, name: null, variant: null, header: true };
}

function ports(taxonomies: Taxonomy[], terms: Term[]) {
  const termQueries: string[] = [];
  const taxonomyRepo: TaxonomyListPort = { list: async () => taxonomies };
  const termRepo: TermListPort = {
    listByTaxonomy: async ({ taxonomyId }) => { termQueries.push(taxonomyId); return terms; },
  };
  return { taxonomyRepo, termRepo, termQueries };
}

test("without both read ports wired, nothing resolves (every marker degrades to the placeholder)", async () => {
  const { taxonomyRepo, termRepo } = ports([taxonomy({ id: "tx", name: "Topics" })], []);
  assert.equal((await resolveTaxonomyEmbeds({ refs: [ref("tx")], deps: { taxonomyRepo } })).size, 0);
  assert.equal((await resolveTaxonomyEmbeds({ refs: [ref("tx")], deps: { termRepo } })).size, 0);
  assert.equal((await resolveTaxonomyEmbeds({ refs: [ref("tx")], deps: {} })).size, 0);
});

test("a unique name resolves like an id; an ambiguous or unknown name, or a ref without an id, stays unresolved", async () => {
  const { taxonomyRepo, termRepo } = ports(
    [taxonomy({ id: "tx-topics", name: "Topics" }), taxonomy({ id: "tx-a", name: "Tags" }), taxonomy({ id: "tx-b", name: "Tags" })],
    [],
  );
  const resolved = await resolveTaxonomyEmbeds({ refs: [ref("Topics"), ref("Tags"), ref("Nope"), ref(null)], deps: { taxonomyRepo, termRepo } });

  assert.deepEqual([...resolved.keys()], ["Topics"]);
  assert.equal(resolved.get("Topics")!.props.id, "tx-topics");
});

test("an exact id wins over a different taxonomy that happens to be named the same string", async () => {
  const { taxonomyRepo, termRepo } = ports([taxonomy({ id: "News", name: "Press" }), taxonomy({ id: "tx-2", name: "News" })], []);
  const resolved = await resolveTaxonomyEmbeds({ refs: [ref("News")], deps: { taxonomyRepo, termRepo } });

  assert.equal(resolved.get("News")!.props.name, "Press");
});

test("trashed and purged taxonomies cannot be targeted, and their terms' trashed/purged rows are hidden", async () => {
  const { taxonomyRepo, termRepo } = ports(
    [taxonomy({ id: "tx-live", name: "Live" }), taxonomy({ id: "tx-trash", name: "Old", status: "trash" }), taxonomy({ id: "tx-gone", name: "Gone", status: "purged" })],
    [
      term({ id: "t1", taxonomyId: "tx-live", name: "Kept" }),
      term({ id: "t2", taxonomyId: "tx-live", name: "Trashed", status: "trash" }),
      term({ id: "t3", taxonomyId: "tx-live", name: "Purged", status: "purged" }),
      term({ id: "t4", taxonomyId: "tx-other", name: "Foreign" }),
      term({ id: "t5", taxonomyId: "tx-live", name: "Child", parentId: "t1" }),
    ],
  );
  const resolved = await resolveTaxonomyEmbeds({ refs: [ref("tx-live"), ref("tx-trash"), ref("Gone")], deps: { taxonomyRepo, termRepo } });

  assert.deepEqual([...resolved.keys()], ["tx-live"]);
  assert.deepEqual(resolved.get("tx-live"), {
    componentId: "taxonomy-list",
    props: { id: "tx-live", name: "Live", hierarchical: false, terms: [{ id: "t1", name: "Kept", parentId: null }, { id: "t5", name: "Child", parentId: "t1" }] },
  });
});

test("two markers naming the same taxonomy (by id and by name) share one term query", async () => {
  const { taxonomyRepo, termRepo, termQueries } = ports([taxonomy({ id: "tx-1", name: "Topics" })], [term({ id: "t1", taxonomyId: "tx-1", name: "News" })]);
  const resolved = await resolveTaxonomyEmbeds({ refs: [ref("tx-1"), ref("Topics")], deps: { taxonomyRepo, termRepo } });

  assert.deepEqual(termQueries, ["tx-1"]);
  assert.deepEqual(resolved.get("tx-1"), resolved.get("Topics"));
});

src/redirects/__tests__/reserved-destina.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { createVerifiedOrigin } from "@jini-ai/http-kit/verified-origin";
import type { VerifiedOrigin } from "@jini-ai/http-kit/verified-origin";
import { checkSameOriginDestination } from "../reserved-destination.js";

/**
 * @file Pure-function coverage for {@link checkSameOriginDestination} — the one "same-origin
 * destination lands on the admin surface" verdict shared by the read gate (`phase-handler.ts`) and
 * the write gate (`redirects.ts`). `phase-handler.read-path-target.test.ts` and
 * `redirects.reserved-target.test.ts` exercise it through those two callers; this file pins the
 * canonical-side normalization (a mixed-case/trailing-dot STORED origin) neither of those resolver-
 * level tests can reach, plus the full verdict matrix directly (t91 B1, 2026-09-16).
 */

const TRUSTED: VerifiedOrigin = createVerifiedOrigin({
  scheme: "https",
  host: "trusted.example",
  verifiedAt: "2026-07-13T00:00:00.000Z",
  source: "workspace-setting",
});

test("checkSameOriginDestination against a plain canonical origin", () => {
  assert.deepEqual(
    checkSameOriginDestination({ candidate: "https://trusted.example./admin", canonical: TRUSTED, reservedSegments: new Set(["admin", "api"]) }, {}),
    { kind: "reserved", surface: "admin" },
    "a trailing-dot host is still same-origin"
  );
  assert.deepEqual(
    checkSameOriginDestination({ candidate: "https://TRUSTED.EXAMPLE./api/x", canonical: TRUSTED, reservedSegments: new Set(["admin", "api"]) }, {}),
    { kind: "reserved", surface: "api" },
    "upper-cased plus trailing dot is still same-origin"
  );
  assert.deepEqual(checkSameOriginDestination({ candidate: "https://trusted.example/blog", canonical: TRUSTED, reservedSegments: new Set(["admin", "api"]) }, {}), { kind: "ok" });
  assert.deepEqual(
    checkSameOriginDestination({ candidate: "https://trusted.example:8443/admin", canonical: TRUSTED, reservedSegments: new Set(["admin", "api"]) }, {}),
    { kind: "ok" },
    "a different port is cross-origin — not this rule's business"
  );
  assert.deepEqual(
    checkSameOriginDestination({ candidate: "http://trusted.example/admin", canonical: TRUSTED, reservedSegments: new Set(["admin", "api"]) }, {}),
    { kind: "ok" },
    "a different scheme is cross-origin"
  );
  assert.deepEqual(
    checkSameOriginDestination({ candidate: "https://partner.example/admin", canonical: TRUSTED, reservedSegments: new Set(["admin", "api"]) }, {}),
    { kind: "ok" },
    "a genuinely different host is cross-origin"
  );
  assert.deepEqual(
    checkSameOriginDestination({ candidate: "https://trusted.example./%5Cevil.example", canonical: TRUSTED, reservedSegments: new Set(["admin", "api"]) }, {}),
    { kind: "disallowed-character" },
    "a percent-encoded backslash decodes to a path separator the reserved-path rule refuses"
  );
  assert.deepEqual(checkSameOriginDestination({ candidate: "not a url", canonical: TRUSTED, reservedSegments: new Set(["admin", "api"]) }, {}), { kind: "unparseable" });
  assert.deepEqual(
    checkSameOriginDestination({ candidate: "https://user@trusted.example/admin", canonical: TRUSTED, reservedSegments: new Set(["admin", "api"]) }, {}),
    { kind: "unparseable" },
    "userinfo is refused by the oracle's own normalizer — fail closed, not 'cross-origin'"
  );
});

test("checkSameOriginDestination against a canonical origin stored with mixed case and a trailing dot", () => {
  const storedMessy: VerifiedOrigin = createVerifiedOrigin({
    scheme: "https",
    host: "Trusted.Example.",
    verifiedAt: "2026-07-13T00:00:00.000Z",
    source: "workspace-setting",
  });

  assert.deepEqual(
    checkSameOriginDestination({ candidate: "https://trusted.example/admin", canonical: storedMessy, reservedSegments: new Set(["admin", "api"]) }, {}),
    { kind: "reserved", surface: "admin" },
    "the CANONICAL side must normalize too, not just the candidate"
  );
});

test("checkSameOriginDestination against a dev-capability http canonical origin", () => {
  const devLocal: VerifiedOrigin = createVerifiedOrigin({
    scheme: "http",
    host: "localhost",
    port: 3000,
    verifiedAt: "2026-07-13T00:00:00.000Z",
    source: "dev-capability",
  });

  assert.deepEqual(
    checkSameOriginDestination({ candidate: "http://localhost.:3000/admin", canonical: devLocal, reservedSegments: new Set(["admin", "api"]) }, {}),
    { kind: "reserved", surface: "admin" }
  );
  assert.deepEqual(checkSameOriginDestination({ candidate: "http://localhost:3000/new", canonical: devLocal, reservedSegments: new Set(["admin", "api"]) }, {}), { kind: "ok" });
});

