import type { Response } from 'express';
import { describe, expect, it, vi } from 'vitest';
import { captureConsentHtml } from '../express/response.js';

/** Same hand-written response double as response.test.ts, with the native write's backpressure
 * result made configurable. */
function fakeResponse({ type, writeResult = true }: { type: string; writeResult?: boolean }) {
  const headers = new Map<string, unknown>([['content-type', type]]);
  const calls: unknown[][] = [];
  const response = {
    statusCode: 200, statusMessage: '', destroyed: false, emit: vi.fn(() => true),
    getHeader: (name: string) => headers.get(name.toLowerCase()),
    setHeader: (name: string, value: unknown) => { headers.set(name.toLowerCase(), value); return response; },
    removeHeader: (name: string) => { headers.delete(name.toLowerCase()); },
    write(...args: unknown[]) { calls.push(['write', ...args]); return writeResult; },
    end(...args: unknown[]) { calls.push(['end', ...args]); return response; },
    writeHead(...args: unknown[]) { calls.push(['writeHead', ...args]); return response; },
    flushHeaders() { calls.push(['flushHeaders']); },
  };
  return { response: response as unknown as Response & { destroyed: boolean; emit: ReturnType<typeof vi.fn> }, headers, calls };
}
const inertText = 'This page could not be delivered with cookie preferences enforced. Please try again or contact the site owner.';
const settle = () => new Promise<void>(resolve => setTimeout(resolve, 0));
const upper = async ({ body }: { body: Buffer }) => Buffer.from(body.toString('utf8').toUpperCase());

describe('captureConsentHtml overflow policy edges', () => {
  it('a throwing overflow policy is reported and the page completes as inert text under the blocking CSP', async () => {
    const { response, headers, calls } = fakeResponse({ type: 'text/html' });
    const reported: unknown[] = [];
    const policyError = new Error('policy store down');
    captureConsentHtml({ response, transform: upper }, { maxBytes: 10, overflow: async () => { throw policyError; }, reportError: ({ error }) => { reported.push(error); } });

    response.write('<p>more than ten bytes</p>');
    response.end('<p>tail</p>');
    await settle();

    expect(reported).toEqual([policyError]);
    expect(calls).toEqual([['end', Buffer.from(inertText), undefined]]);
    expect(headers.get('content-security-policy')).toContain("script-src 'none'");
  });

  it('a response destroyed before the overflow decision gets no write, callback or drain', async () => {
    const { response, calls } = fakeResponse({ type: 'text/html' });
    let decide!: (body: Buffer | null) => void;
    captureConsentHtml({ response, transform: upper }, { maxBytes: 10, overflow: () => new Promise(resolve => { decide = resolve; }) });
    const written = vi.fn();

    expect(response.write('<p>more than ten bytes</p>', written)).toBe(false);
    response.destroyed = true;
    decide(null);
    await settle();

    expect(calls).toEqual([]);
    expect(written).not.toHaveBeenCalled();
    expect(response.emit).not.toHaveBeenCalled();
  });

  it('under a disabled policy, native backpressure on the flushed prefix leaves drain to the native stream', async () => {
    const { response, calls } = fakeResponse({ type: 'text/html', writeResult: false });
    captureConsentHtml({ response, transform: upper }, { maxBytes: 10, overflow: async () => null });

    expect(response.write('<p>more than ten bytes</p>')).toBe(false);
    await settle();

    expect(calls).toEqual([['write', Buffer.from('<p>more than ten bytes</p>'), undefined]]);
    expect(response.emit).not.toHaveBeenCalled();
  });

  it('under a disabled policy with an accepted write, a synthetic drain resumes the paused producer', async () => {
    const { response, calls } = fakeResponse({ type: 'text/html' });
    captureConsentHtml({ response, transform: upper }, { maxBytes: 10, overflow: async () => null });

    expect(response.write('<p>more than ten bytes</p>')).toBe(false);
    await settle();

    expect(calls).toEqual([['write', Buffer.from('<p>more than ten bytes</p>'), undefined]]);
    expect(response.emit).toHaveBeenCalledWith('drain');
  });
});

src/taxonomy/__tests__/cycle-detection.t.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { wouldCreateCycle } from "../validation-chain.js";

/**
 * @file The cycle-detection algorithm.
 *
 * Assumed seam design:
 *
 * ```ts
 * export interface TermTreeLookup {
 * getParentId(termId: string): string | null; null = root
 * }
 * export function wouldCreateCycle(
 * required: { termId: string; candidateParentId: string; tree: TermTreeLookup },
 * optional?: {}
 * ): boolean; true if termId appears anywhere in candidateParentId's ancestor chain, or candidateParentId === termId
 * ```
 *
 * requires a FULL recursive descendant/ancestor walk, not a fixed-depth or
 * immediate-parent-only comparison — the exact shape a naive implementation gets wrong.
 * See docs/decisions/DR-005-ordered-taxonomy-validation.md.
 */

function treeFromEdges(edges: Record<string, string | null>) {
  return {
    getParentId({ termId }: { termId: string }) {
      return edges[termId] ?? null;
    },
  };
}

test("EC-05a: self-parenting (candidateParentId === termId) is always a cycle, at zero walk depth", () => {
  const tree = treeFromEdges({ "term-1": null });
  assert.equal(wouldCreateCycle({ termId: "term-1", candidateParentId: "term-1", tree }), true);
});

test("2-node cycle: reparenting term-1 under its own direct child is a cycle", () => {
  // term-1 -> (parent) -> term-2   (term-2's parent is term-1)
  const tree = treeFromEdges({ "term-2": "term-1" });
  assert.equal(wouldCreateCycle({ termId: "term-1", candidateParentId: "term-2", tree }), true);
});

test("EC-05b: a 3+-node ancestor cycle is detected via a full recursive walk, not just an immediate-parent check", () => {
  // term-1 -> term-2 -> term-3 -> term-4 (term-4's parent is term-3, term-3's is term-2, term-2's is term-1)
  // Reparenting term-1 under term-4 would create a 4-node cycle back to term-1.
  const tree = treeFromEdges({ "term-2": "term-1", "term-3": "term-2", "term-4": "term-3" });
  assert.equal(
    wouldCreateCycle({ termId: "term-1", candidateParentId: "term-4", tree }),
    true,
    "a naive immediate-parent-only check would miss this 3+-hop cycle"
  );
});

test("no cycle: reparenting to an unrelated branch of the tree is allowed", () => {
  const tree = treeFromEdges({ "term-2": "term-1", "term-3": "term-1", "term-4": null });
  assert.equal(wouldCreateCycle({ termId: "term-2", candidateParentId: "term-4", tree }), false);
});

test("no cycle: reparenting to root (no ancestors) is never a cycle", () => {
  const tree = treeFromEdges({ "term-1": null, "term-2": null });
  assert.equal(wouldCreateCycle({ termId: "term-1", candidateParentId: "term-2", tree }), false);
});

test("U-002-B1 (property): for chains of depth 1 through 10, a candidate parent at any depth in termId's own descendant chain is always detected as a cycle", () => {
  for (let depth = 1; depth <= 10; depth += 1) {
    const edges: Record<string, string | null> = {};
    let prev = "root";
    edges[prev] = null;
    for (let i = 0; i < depth; i += 1) {
      const node = `node-${depth}-${i}`;
      edges[node] = prev;
      prev = node;
    }
    // `prev` is now the deepest descendant of `root`, `depth` hops away.
    const tree = treeFromEdges(edges);
    assert.equal(
      wouldCreateCycle({ termId: "root", candidateParentId: prev, tree }),
      true,
      `depth ${depth}: reparenting root under its own descendant ${depth} hops away must be detected as a cycle`
    );
  }
});

test("U-002-B1 (property): a candidate parent that is NOT in termId's descendant chain, at any comparable depth, is never a false positive", () => {
  for (let depth = 1; depth <= 10; depth += 1) {
    const edges: Record<string, string | null> = { root: null, "sibling-root": null };
    let prev = "sibling-root";
    for (let i = 0; i < depth; i += 1) {
      const node = `sibling-node-${depth}-${i}`;
      edges[node] = prev;
      prev = node;
    }
    const tree = treeFromEdges(edges);
    assert.equal(
      wouldCreateCycle({ termId: "root", candidateParentId: prev, tree }),
      false,
      `depth ${depth}: an unrelated branch must never be a false-positive cycle`
    );
  }
});

src/media/__tests__/hardwiring-ports.tes.source:
import { chmod, mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { expect, it } from 'vitest';
import { createFfmpegVideoFrameExtractor, createVideoExtractionLock, findVideoBinaries } from '../video-frames.ffmpeg.js';
import { createEntryLockState, withEntryLock } from '../../widgets/concurrency.js';

const bytes = new Uint8Array([0, 0, 0, 24, ...Buffer.from('ftypisom'), 0, 0, 2, 0, ...Buffer.from('isomiso2')]);

// hwb #16: no codec runs; the host supplies fake executables and the finder only checks access.
it('discovers only from the supplied environment and platform', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'hwb-video-'));
  try {
    for (const name of ['nice', 'ffmpeg', 'ffprobe']) { await writeFile(join(dir, name), ''); await chmod(join(dir, name), 0o700); }
    expect(await findVideoBinaries({}, { env: { PATH: dir }, platform: 'linux' })).toEqual({ nice: join(dir, 'nice'), ffmpeg: join(dir, 'ffmpeg'), ffprobe: join(dir, 'ffprobe') });
    expect(await findVideoBinaries({}, { env: { PATH: dir }, platform: 'win32' })).toBeUndefined();
  } finally { await rm(dir, { recursive: true, force: true }); }
});

// hwb #16: same host lock stays busy; a separate host can proceed; failure releases the lock.
it('honors injected lock ownership and releases it on unavailable or rejected discovery', async () => {
  const lock = createVideoExtractionLock({});
  let finish!: () => void;
  let started!: () => void;
  const ready = new Promise<void>(resolve => { started = resolve; });
  const findBinaries = () => new Promise<undefined>(resolve => { finish = () => resolve(undefined); started(); });
  const first = createFfmpegVideoFrameExtractor({ lock, findBinaries });
  const pending = first.extract({ bytes }, {});
  await ready;
  try {
    const same = createFfmpegVideoFrameExtractor({ lock, findBinaries: async () => undefined });
    expect(await same.extract({ bytes }, {})).toEqual({ ok: false, reason: 'busy', message: 'Video preview is busy. Try again after the current extraction finishes.' });
    const other = createFfmpegVideoFrameExtractor({ lock: createVideoExtractionLock({}), findBinaries: async () => undefined });
    expect((await other.extract({ bytes }, {})).ok).toBe(false);
    const result = await other.extract({ bytes }, {});
    expect(result).toMatchObject({ reason: 'unavailable' });
  } finally { finish(); await pending; }
  const failed = createFfmpegVideoFrameExtractor({ lock, findBinaries: async () => { throw new Error('probe failed'); } });
  expect(await failed.extract({ bytes }, {})).toMatchObject({ reason: 'invalid' });
  const release = lock.tryAcquire({}, {});
  expect(typeof release).toBe('function');
  release?.();
});

// hwb widgets: deleting a predecessor's newer tail would allow a third caller to overlap the second.
it('serializes waiters, keeps their tail until completion, and prunes failed and idle keys', async () => {
  const locks = createEntryLockState({});
  let release!: () => void;
  const gate = new Promise<void>(resolve => { release = resolve; });
  const order: number[] = [];
  const first = withEntryLock({ key: 'entry', fn: async () => { order.push(1); await gate; } }, { locks });
  const second = withEntryLock({ key: 'entry', fn: async () => { order.push(2); throw new Error('write failed'); } }, { locks });
  const failure = expect(second).rejects.toThrow('write failed');
  const third = withEntryLock({ key: 'entry', fn: async () => { order.push(3); return 'done'; } }, { locks });
  await Promise.resolve();
  expect(order).toEqual([1]);
  expect(locks.size).toBe(1);
  release(); await first; await failure;
  expect(await third).toBe('done');
  expect(order).toEqual([1, 2, 3]);
  expect(locks.size).toBe(0);
});

it('a repeated release cannot unlock a later video extraction', () => {
  const lock = createVideoExtractionLock({});
  const first = lock.tryAcquire({}, {})!;
  first();
  const second = lock.tryAcquire({}, {})!;
  first();
  expect(lock.tryAcquire({}, {})).toBeUndefined();
  second();
  expect(typeof lock.tryAcquire({}, {})).toBe('function');
});

