import { beforeAll, describe, expect, it } from 'vitest';
import fc from 'fast-check';
import { validateSubmissionPayload } from '../../forms.js';
import type { FormDefinitionRecord } from '../../types.js';

const seed = Number(process.env.FC_SEED ?? 20261020);
const options = { seed, numRuns: 150 };
const definition: FormDefinitionRecord = {
  id: 'form-property', workspaceId: 'workspace-property', name: 'Contact', slug: 'contact',
  fields: [
    { id: 'answer', label: 'Answer', type: 'text', required: false, maxLength: 200 },
    { id: 'consent', label: 'Consent', type: 'checkbox', required: false },
  ],
  notify: { enabled: false, recipients: [] }, status: 'active', version: 1,
  createdAt: '2026-10-20T00:00:00.000Z', updatedAt: '2026-10-20T00:00:00.000Z',
};

beforeAll(() => console.info(`[fast-check cms/forms] seed=${seed}, numRuns=${options.numRuns}`));

describe('CMS submission validation properties', () => {
  it('preserves accepted values exactly and never stores the honeypot', () => {
    fc.assert(fc.property(fc.string({ maxLength: 100 }), fc.boolean(), fc.jsonValue(), (answer, consent, hp) => {
      const body = { answer, consent, _hp: hp };
      const before = structuredClone(body);
      expect(validateSubmissionPayload({ definition, body })).toEqual({ valid: true, data: { answer, consent } });
      expect(body).toEqual(before);
    }), options);
  });

  it('rejects every undeclared key, including object-prototype property names', () => {
    const unknownKey = fc.oneof(fc.string({ maxLength: 40 }), fc.constantFrom('__proto__', 'constructor', 'toString'))
      .filter(key => !['answer', 'consent', '_hp'].includes(key));
    fc.assert(fc.property(unknownKey, fc.jsonValue(), (key, value) => {
      expect(validateSubmissionPayload({ definition, body: { [key]: value } })).toEqual({
        valid: false, fieldErrors: [{ field: key, reason: 'unregistered_key' }],
      });
    }), options);
  });

  it('accepts exactly the declared text-length bound and refuses one character beyond', () => {
    fc.assert(fc.property(fc.integer({ min: 1, max: 200 }), maxLength => {
      const bounded = { ...definition, fields: [{ ...definition.fields[0]!, maxLength }] };
      const answer = 'x'.repeat(maxLength);
      expect(validateSubmissionPayload({ definition: bounded, body: { answer } })).toEqual({ valid: true, data: { answer } });
      expect(validateSubmissionPayload({ definition: bounded, body: { answer: answer + 'x' } })).toEqual({
        valid: false, fieldErrors: [{ field: 'answer', reason: 'too_long' }],
      });
    }), options);
  });

  it('native on and JSON true normalize identically while optional false is retained', () => {
    fc.assert(fc.property(fc.string({ maxLength: 100 }), answer => {
      const expected = { valid: true, data: { answer, consent: true } };
      expect(validateSubmissionPayload({ definition, body: { answer, consent: 'on' } })).toEqual(expected);
      expect(validateSubmissionPayload({ definition, body: { answer, consent: true } })).toEqual(expected);
      expect(validateSubmissionPayload({ definition, body: { answer, consent: false } })).toEqual({
        valid: true, data: { answer, consent: false },
      });
    }), options);
  });

  it('requires authored checkbox submissions to equal the configured value', () => {
    fc.assert(fc.property(fc.string({ maxLength: 40 }), fc.string({ maxLength: 40 }), (configured, submitted) => {
      const authored: FormDefinitionRecord = { ...definition, fields: [
        { id: 'consent', label: 'Consent', type: 'checkbox', required: false, checkboxValue: configured },
      ] };
      expect(validateSubmissionPayload({ definition: authored, body: { consent: submitted } })).toEqual(
        submitted === configured ? { valid: true, data: { consent: submitted } }
          : { valid: false, fieldErrors: [{ field: 'consent', reason: 'invalid_option' }] },
      );
    }), options);
  });
});

src/forms/delivery/__tests__/deliver-job.source:
/**
 * @file Unit tests for one delivery attempt: which adapter results count as success, and how every
 * failure shape (result object, malformed result, throw) becomes a ledger-safe FormDeliveryError.
 */
import { describe, expect, test } from "vitest";
import { deliverFormJob, FormDeliveryError, type FormDeliveryJob, type FormDeliveryResult } from "../index.js";

const job: FormDeliveryJob = {
  binding: { bindingId: "b-1", adapterId: "rows", connectionRef: "conn-1", enabled: true, config: { table: "leads" } },
  snapshot: { form: { slug: "contact", fields: [{ name: "email", required: true }] },
    submission: { id: "s-1", answers: { email: "a@example.test" }, submittedAt: "2026-10-20T00:00:00.000Z" } },
  idempotencyKey: JSON.stringify(["s-1", "b-1"]),
};

async function failureOf(result: unknown): Promise<unknown> {
  // `result` is untyped on purpose: plugin adapters are plain `.mjs` and may return anything.
  return deliverFormJob({ job, deliver: async () => result as FormDeliveryResult }).then(() => "resolved", (error: unknown) => error);
}

describe("success", () => {
  test("hands the frozen job to deliver unchanged", async () => {
    const seen: FormDeliveryJob[] = [];
    await deliverFormJob({ job, deliver: async input => { seen.push(input); } });
    expect(seen).toEqual([job]);
    expect(seen[0]).toBe(job);
  });

  test("a legacy adapter that returns nothing succeeds", async () => {
    await expect(deliverFormJob({ job, deliver: async () => undefined })).resolves.toBeUndefined();
  });

  test("{ ok: true } with a reference succeeds", async () => {
    await expect(deliverFormJob({ job, deliver: async () => ({ ok: true, reference: "row-9" }) })).resolves.toBeUndefined();
  });
});

describe("failure from a result", () => {
  test("{ ok: false } with an allowlisted terminal code throws that code as non-retryable", async () => {
    const error = await failureOf({ ok: false, error: { code: "authorization-required", retryable: false } });
    expect(error).toBeInstanceOf(FormDeliveryError);
    expect([(error as FormDeliveryError).code, (error as FormDeliveryError).retryable]).toEqual(["authorization-required", false]);
  });

  test.each([
    ["null", null],
    ["{ ok: false } without an error", { ok: false }],
    ["an error that is a string", { ok: false, error: "quota exceeded for token" }],
    ["a truthy ok that is not true", { ok: "yes" }],
    ["a bare string", "done"],
  ])("%s becomes retryable delivery-failed", async (_label, result) => {
    const error = await failureOf(result);
    expect(error).toBeInstanceOf(FormDeliveryError);
    expect([(error as FormDeliveryError).message, (error as FormDeliveryError).retryable]).toEqual(["delivery-failed", true]);
  });
});

describe("failure from a throw", () => {
  test("a thrown FormDeliveryError passes through as the same instance", async () => {
    const thrown = new FormDeliveryError({ code: "adapter-unavailable", retryable: true });
    const error = await deliverFormJob({ job, deliver: async () => { throw thrown; } }).then(() => undefined, (e: unknown) => e);
    expect(error).toBe(thrown);
  });

  test("a thrown non-Error value becomes retryable delivery-failed", async () => {
    const error = await deliverFormJob({ job, deliver: async () => { throw "socket hang up"; } }).then(() => undefined, (e: unknown) => e);
    expect(error).toBeInstanceOf(FormDeliveryError);
    expect([(error as FormDeliveryError).code, (error as FormDeliveryError).retryable]).toEqual(["delivery-failed", true]);
  });

  test("a deliver that throws synchronously is still normalised", async () => {
    const deliver = (): Promise<void> => { throw new TypeError("adapter.deliver is not a function"); };
    const error = await deliverFormJob({ job, deliver }).then(() => undefined, (e: unknown) => e);
    expect((error as FormDeliveryError).message).toBe("delivery-failed");
  });
});

