import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import type { Request, Response } from "express";
import { test } from "vitest";
import { createCommentSubmitHandler, type CommentSubmitRequired } from "../index.js";

test("comment submit handler refuses every missing required port at construction", () => {
  const complete: CommentSubmitRequired = {
    ingressPolicy: { submit: async () => ({ ok: false, reason: "invalid" }) },
    workspaceId: "workspace-1",
    ipHashSalt: "host-owned-salt",
    rateLimiter: { check: async () => ({ allowed: true }) },
    clientIp: () => "203.0.113.1",
  };
  for (const key of ["ingressPolicy", "workspaceId", "ipHashSalt", "rateLimiter", "clientIp"] as const) {
    const missing: Partial<CommentSubmitRequired> = { ...complete };
    delete missing[key];
    assert.throws(() => createCommentSubmitHandler(missing as CommentSubmitRequired, {}), {
      name: "TypeError", message: `comments submit handler requires ${key}`,
    });
  }
  for (const [key, value] of [
    ["ingressPolicy", {}],
    ["ingressPolicy", null],
    ["workspaceId", ""],
    ["workspaceId", 0],
    ["ipHashSalt", ""],
    ["ipHashSalt", 0],
  ] as const) {
    assert.throws(() => createCommentSubmitHandler({ ...complete, [key]: value } as CommentSubmitRequired, {}), {
      name: "TypeError", message: `comments submit handler requires ${key}`,
    });
  }
  for (const [key, value] of [
    ["rateLimiter", null], ["rateLimiter", {}], ["rateLimiter", { check: true }],
    ["clientIp", null], ["clientIp", {}],
  ] as const) {
    assert.throws(() => createCommentSubmitHandler({ ...complete, [key]: value } as CommentSubmitRequired, {}), {
      name: "TypeError", message: `comments submit handler requires ${key}`,
    });
  }
  assert.throws(() => createCommentSubmitHandler(undefined as never, {}), {
    name: "TypeError", message: "comments submit handler requires ingressPolicy",
  });
  assert.doesNotThrow(() => createCommentSubmitHandler(complete, {}));
});

test.each([true, false])("comment HTTP budget allowed=%s uses the host IP and gates ingress", async (allowed) => {
  const request = { body: { entryId: "entry-1", body: "hello" }, ip: "untrusted-request-ip" } as Request;
  const expectedHash = createHash("sha256").update("203.0.113.1:host-owned-salt").digest("hex");
  const calls: string[] = [];
  let status: number | undefined;
  let payload: unknown;
  const response = {
    status(code: number) { status = code; return this; },
    json(body: unknown) { payload = body; return this; },
  };
  const handler = createCommentSubmitHandler({
    workspaceId: "workspace-1", ipHashSalt: "host-owned-salt",
    clientIp: ({ request: received }) => {
      assert.equal(received, request);
      calls.push("clientIp");
      return "203.0.113.1";
    },
    rateLimiter: { check: async ({ key }) => {
      assert.equal(key, expectedHash);
      calls.push("rateLimiter");
      return allowed ? { allowed: true } : { allowed: false, retryAfterSeconds: 60 };
    } },
    ingressPolicy: { submit: async (submission) => {
      assert.equal(submission.ingressContext.authorIpHash, expectedHash);
      calls.push("ingressPolicy");
      return { ok: false, reason: "invalid" };
    } },
  }, {});
  await handler(request, response as Response, () => assert.fail("unexpected next call"));
  assert.deepEqual(calls, allowed ? ["clientIp", "rateLimiter", "ingressPolicy"] : ["clientIp", "rateLimiter"]);
  assert.equal(status, 422);
  assert.deepEqual(payload, { error: "comment was not accepted", reason: allowed ? "invalid" : "rate-limited" });
});

src/widgets/__tests__/entry-isolation.te.source:
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { dirname, resolve, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { test } from "vitest";
import ts from "typescript";

const DOMAIN = fileURLToPath(new URL("../", import.meta.url));
const CMS = resolve(DOMAIN, "..");

/** Read runtime imports/re-exports, dynamic imports and require calls; erased type edges do not load. */
function runtimeSpecifiers(source: string): string[] {
  const ast = ts.createSourceFile("entry.ts", source, ts.ScriptTarget.Latest, true);
  const specifiers: string[] = [];
  function visit(node: ts.Node): void {
    if (ts.isImportDeclaration(node) && ts.isStringLiteral(node.moduleSpecifier)) {
      const clause = node.importClause;
      const named = clause?.namedBindings;
      const typeOnly = clause?.isTypeOnly || (clause && !clause.name && named && ts.isNamedImports(named) && named.elements.length > 0 && named.elements.every((element) => element.isTypeOnly));
      if (!typeOnly) specifiers.push(node.moduleSpecifier.text);
    } else if (ts.isExportDeclaration(node) && !node.isTypeOnly && node.moduleSpecifier && ts.isStringLiteral(node.moduleSpecifier)) {
      const typeOnly = node.exportClause && ts.isNamedExports(node.exportClause) && node.exportClause.elements.length > 0 && node.exportClause.elements.every((element) => element.isTypeOnly);
      if (!typeOnly) specifiers.push(node.moduleSpecifier.text);
    } else if (ts.isCallExpression(node) && (node.expression.kind === ts.SyntaxKind.ImportKeyword || (ts.isIdentifier(node.expression) && node.expression.text === "require"))) {
      assert.equal(node.arguments.length, 1, "runtime dependencies must be statically enumerable");
      assert.ok(node.arguments[0]);
      assert.ok(ts.isStringLiteral(node.arguments[0]), "computed runtime dependencies must be reviewed explicitly");
      specifiers.push(node.arguments[0].text);
    } else if (ts.isImportEqualsDeclaration(node) && !node.isTypeOnly && ts.isExternalModuleReference(node.moduleReference)) {
      assert.ok(node.moduleReference.expression && ts.isStringLiteral(node.moduleReference.expression));
      specifiers.push(node.moduleReference.expression.text);
    }
    ts.forEachChild(node, visit);
  }
  visit(ast);
  return specifiers;
}

function closure(entry: string): { files: string[]; external: string[] } {
  const visited = new Set<string>();
  const external = new Set<string>();
  const pending = [resolve(DOMAIN, entry)];
  while (pending.length > 0) {
    const file = pending.pop()!;
    if (visited.has(file)) continue;
    visited.add(file);
    for (const specifier of runtimeSpecifiers(readFileSync(file, "utf8"))) {
      if (specifier.startsWith(".")) pending.push(resolve(dirname(file), specifier.replace(/\.js$/, ".ts")));
      else external.add(specifier);
    }
  }
  return { files: [...visited].map((file) => relative(CMS, file)), external: [...external] };
}

test("widgets markers, root and resolvers have isolated universal runtime closures", () => {
  for (const entry of ["markers/index.ts", "index.ts", "resolvers/index.ts"]) {
    const result = closure(entry);
    assert.deepEqual(result.external.filter((name) => /^(?:parse5|kysely|express)(?:\/|$)|^node:|^@jini-ai\/db(?:\/|$)/.test(name)), [], entry);
    assert.deepEqual(result.files.filter((file) => !file.startsWith("widgets/") && !file.startsWith("core/")), [], entry);
    assert.deepEqual(result.files.filter((file) => /^widgets\/(?:sql|html)\//.test(file)), [], entry);
  }
});

