import assert from "node:assert/strict";
import { test } from "vitest";
import { taxonomyAgentToolCatalog } from "../index.js";

/**
 * @file The taxonomy agent-tool catalog's published contract: which tools exist, which are reads,
 * that the destructive merge only runs behind a human confirmation, and that every input schema is
 * closed and self-consistent (a host's registration kit publishes these schemas to the model).
 */

type Schema = { type: string; additionalProperties: boolean; required: string[]; properties: Record<string, { type?: string; enum?: unknown }> };
const byName = new Map(taxonomyAgentToolCatalog.map((tool) => [tool.name, tool]));

test("the catalog publishes exactly the list, four ordinary writes, the merge plan and the confirm-gated merge", () => {
  assert.deepEqual([...byName.keys()], [
    "taxonomy_list", "taxonomy_create_taxonomy", "taxonomy_create_term", "taxonomy_rename_term",
    "taxonomy_assign_terms", "taxonomy_unassign_terms", "taxonomy_plan_merge_term", "taxonomy_execute_merge_term",
  ]);
  assert.equal(byName.has("taxonomy_confirm_merge_term"), false, "an agent can never confirm a gated mutation itself");
});

test("only the list and the merge plan are side-effect free; everything else mutates durable state", () => {
  const reads = taxonomyAgentToolCatalog.filter((tool) => tool.sideEffects === "none").map((tool) => tool.name);
  assert.deepEqual(reads, ["taxonomy_list", "taxonomy_plan_merge_term"]);
  for (const tool of taxonomyAgentToolCatalog) {
    if (!reads.includes(tool.name)) assert.equal(tool.sideEffects, "mutates-durable-state", tool.name);
    assert.deepEqual(tool.authorization, { permission: "admin.taxonomy.manage" }, tool.name);
  }
});

test("the destructive merge is the only tool that requires the human's own confirmation", () => {
  const gated = taxonomyAgentToolCatalog.filter((tool) => tool.actorClassRule !== undefined);
  assert.deepEqual(gated.map((tool) => [tool.name, tool.actorClassRule]), [["taxonomy_execute_merge_term", "confirmer-must-equal-own-delegatedBy"]]);
});

test("every input schema is a closed object whose required keys are all declared properties", () => {
  for (const tool of taxonomyAgentToolCatalog) {
    const schema = tool.inputSchema as Schema;
    assert.equal(schema.type, "object", tool.name);
    assert.equal(schema.additionalProperties, false, tool.name);
    for (const key of schema.required) assert.ok(Object.hasOwn(schema.properties, key), `${tool.name}.${key}`);
    assert.ok(tool.description.length > 0, tool.name);
  }
});

test("contentType is an open string, so a Collection key reaches the write-service's own eligibility policy", () => {
  for (const name of ["taxonomy_assign_terms", "taxonomy_unassign_terms"]) {
    const contentType = (byName.get(name)!.inputSchema as Schema).properties.contentType!;
    assert.equal(contentType.type, "string");
    assert.equal(contentType.enum, undefined, name);
  }
});

test("both merge tools describe their two term ids distinctly while sharing the term-id shape", () => {
  for (const name of ["taxonomy_plan_merge_term", "taxonomy_execute_merge_term"]) {
    const { fromTermId, intoTermId } = (byName.get(name)!.inputSchema as Schema).properties as Record<string, { type: string; minLength: number; description: string }>;
    assert.deepEqual([fromTermId!.type, fromTermId!.minLength, intoTermId!.type, intoTermId!.minLength], ["string", 1, "string", 1]);
    assert.notEqual(fromTermId!.description, intoTermId!.description);
  }
});

src/forms/delivery/__tests__/status.unit.source:
/**
 * @file Pins how a binding's status is read off its outbox row (contract §6). `claimPending`
 * increments `attempts` before an attempt runs, so a `processing` row with attempts 1 is the FIRST
 * attempt in flight, not a retry.
 */
import { describe, expect, test } from "vitest";
import { formDeliveryStatusFromOutbox } from "../index.js";

const due = "2026-10-20T00:05:00.000Z";
const read = (status: "pending" | "processing", attempts: number) =>
  formDeliveryStatusFromOutbox({ row: { status, attempts, nextAttemptAt: due, lastError: null } });

describe("in-flight and waiting rows", () => {
  test("the first attempt in flight (processing, attempts 1) reads pending", () => {
    expect(read("processing", 1)).toEqual({ status: "pending", attempts: 1, nextRetryAt: null, errorCode: null });
  });

  test("a later attempt in flight (processing, attempts 2) reads retrying with no retry time", () => {
    expect(read("processing", 2)).toEqual({ status: "retrying", attempts: 2, nextRetryAt: null, errorCode: null });
  });

  test("a never-claimed row (pending, attempts 0) reads pending", () => {
    expect(read("pending", 0)).toEqual({ status: "pending", attempts: 0, nextRetryAt: null, errorCode: null });
  });

  test("a row waiting after a failed attempt (pending, attempts 1) reads retrying with its due time", () => {
    expect(read("pending", 1)).toEqual({ status: "retrying", attempts: 1, nextRetryAt: due, errorCode: null });
  });
});

describe("settled rows", () => {
  test("a delivered row reads completed and hides any earlier error", () => {
    expect(formDeliveryStatusFromOutbox({ row: { status: "delivered", attempts: 3, nextAttemptAt: due, lastError: "rate-limited" } }))
      .toEqual({ status: "completed", attempts: 3, nextRetryAt: null, errorCode: null });
  });

  test("a failed row reads failed with its safe code and no retry time", () => {
    expect(formDeliveryStatusFromOutbox({ row: { status: "failed", attempts: 1, nextAttemptAt: due, lastError: "authorization-required" } }))
      .toEqual({ status: "failed", attempts: 1, nextRetryAt: null, errorCode: "authorization-required" });
  });

  test("a failed row sealed by the worker's own message reads delivery-failed", () => {
    const row = { status: "failed" as const, attempts: 9, nextAttemptAt: due,
      lastError: "claimed 9 times; the last claim expired with no recorded outcome (its claimer likely died mid-delivery)" };
    expect(formDeliveryStatusFromOutbox({ row }).errorCode).toBe("delivery-failed");
  });
});

describe("error code on unsettled rows", () => {
  test("a waiting retry reports the safe code of its last failure", () => {
    expect(formDeliveryStatusFromOutbox({ row: { status: "pending", attempts: 2, nextAttemptAt: due, lastError: "rate-limited" } }).errorCode)
      .toBe("rate-limited");
  });

  test("a later attempt in flight still reports the previous failure's code", () => {
    expect(formDeliveryStatusFromOutbox({ row: { status: "processing", attempts: 3, nextAttemptAt: due, lastError: "outcome-unknown" } }))
      .toEqual({ status: "retrying", attempts: 3, nextRetryAt: null, errorCode: "outcome-unknown" });
  });

  test("an absent or empty lastError reads as no code", () => {
    expect(formDeliveryStatusFromOutbox({ row: { status: "pending", attempts: 1, nextAttemptAt: due } }).errorCode).toBeNull();
    expect(formDeliveryStatusFromOutbox({ row: { status: "pending", attempts: 1, nextAttemptAt: due, lastError: "" } }).errorCode).toBeNull();
  });
});

src/content-types/__tests__/lifecycle-di.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { CONTENT_TYPE_LIFECYCLE_OPS, parseContentTypeLifecycleOp, type LifecycleDispatchDeps } from "../lifecycle-dispatch.js";
import { InMemoryContentTypeRepo } from "../repo.memory.js";
import type { ContentTypeRecord, ContentTypeStatus } from "../types.js";

/**
 * @file Each entry of the closed lifecycle dispatch table runs its own transition with the
 * dispatcher's deps and input threaded through, and reactivate (which takes no outbox/index deps)
 * never touches either even though the dispatcher holds them.
 */

const NOW = "2026-07-15T00:00:00.000Z";

async function dispatchHarness(status: ContentTypeStatus) {
  const repo = new InMemoryContentTypeRepo();
  const seed: ContentTypeRecord = { workspaceId: "ws-1", key: "recipe", label: "Recipe", fields: [], status, version: 5, tombstonedAt: null };
  await repo.save(seed);
  const events: unknown[] = [];
  const teardowns: unknown[] = [];
  const deps: LifecycleDispatchDeps = {
    repo,
    clock: { nowMs: () => Date.parse(NOW) },
    authorize: async () => ({ allowed: true, reason: "matched" }),
    outbox: { enqueue: async (event) => { events.push(event); } },
    indexProvisioner: { tearDownAllIndexesForContentType: async (call) => { teardowns.push(call); } },
  };
  return { repo, deps, events, teardowns };
}

const input = { workspaceId: "ws-1", actorId: "user-1", key: "recipe", expectedVersion: 5, principalKind: "agent" as const };

function dispatch(op: string, deps: LifecycleDispatchDeps) {
  const parsed = parseContentTypeLifecycleOp({ op });
  assert.ok(parsed, `'${op}' must parse`);
  return CONTENT_TYPE_LIFECYCLE_OPS[parsed]({ deps, input });
}

test("dispatching 'deprecate' flips active -> deprecated, records the principalKind, and enqueues content_type.deprecated", async () => {
  const h = await dispatchHarness("active");

  const result = await dispatch("deprecate", h.deps);

  assert.equal(result.ok, true);
  if (!result.ok) return;
  assert.equal(result.value.contentType.status, "deprecated");
  assert.equal(result.value.contentType.version, 6);
  assert.equal(h.repo.listRevisions()[0]?.principalKind, "agent");
  assert.deepEqual(h.events, [{ name: "content_type.deprecated", payload: { workspaceId: "ws-1", key: "recipe" } }]);
  assert.deepEqual(h.teardowns, []);
});

test("dispatching 'reactivate' flips deprecated -> active without enqueueing an event or touching indexes", async () => {
  const h = await dispatchHarness("deprecated");

  const result = await dispatch("reactivate", h.deps);

  assert.equal(result.ok, true);
  if (!result.ok) return;
  assert.equal(result.value.contentType.status, "active");
  assert.equal((await h.repo.findByKey({ workspaceId: "ws-1", key: "recipe" }))?.status, "active");
  assert.deepEqual(h.events, []);
  assert.deepEqual(h.teardowns, []);
});

test("dispatching 'tombstone' flips deprecated -> tombstone, tears down indexes, and enqueues content_type.tombstoned", async () => {
  const h = await dispatchHarness("deprecated");

  const result = await dispatch("tombstone", h.deps);

  assert.equal(result.ok, true);
  if (!result.ok) return;
  assert.equal(result.value.contentType.status, "tombstone");
  assert.equal(result.value.contentType.tombstonedAt, NOW);
  assert.deepEqual(h.teardowns, [{ workspaceId: "ws-1", contentTypeKey: "recipe" }]);
  assert.deepEqual(h.events, [{ name: "content_type.tombstoned", payload: { workspaceId: "ws-1", key: "recipe" } }]);
});

src/media/__tests__/blob-store.object-st.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import type { ObjectStore, ObjectStorePutOptions } from "@jini-ai/core/object-store";

import { computeBlobStorageKey } from "../blob-key.js";
import { blobStoreFromObjectStore } from "../blob-store.object-store.js";

/** A fake ObjectStore recording each call, keyed exactly as given. */
function fakeObjectStore() {
  const objects = new Map<string, Uint8Array>();
  const calls: Array<{ op: string; key: string; options?: ObjectStorePutOptions }> = [];
  const store: ObjectStore = {
    async put({ key, bytes }, options = {}) {
      calls.push({ op: "put", key, options });
      if (options.ifAbsent && objects.has(key)) return { written: false };
      objects.set(key, bytes);
      return { written: true };
    },
    async get({ key }) { calls.push({ op: "get", key }); return objects.get(key) ?? null; },
    async head({ key }) { calls.push({ op: "head", key }); const bytes = objects.get(key); return bytes ? { size: bytes.byteLength } : null; },
    async delete({ key }) { calls.push({ op: "delete", key }); objects.delete(key); },
  };
  return { store, objects, calls };
}

const workspaceId = "11111111-1111-4111-8111-111111111111";
const sha256 = "ab".padEnd(64, "c");
const bytes = new Uint8Array([1, 2, 3]);

test("keys are computeBlobStorageKey verbatim (no data migration)", async () => {
  const { store, objects } = fakeObjectStore();
  const blobs = blobStoreFromObjectStore({ store });
  const { storageKey } = await blobs.put({ workspaceId, sha256, bytes });
  assert.equal(storageKey, computeBlobStorageKey({ workspaceId, sha256 }));
  assert.equal(storageKey, `ws/${workspaceId}/blobs/ab/${sha256}`);
  assert.deepEqual([...objects.keys()], [storageKey]);
});

test("putIfAbsent maps to the store's atomic ifAbsent write", async () => {
  const { store, calls } = fakeObjectStore();
  const blobs = blobStoreFromObjectStore({ store });
  assert.deepEqual(await blobs.putIfAbsent({ workspaceId, sha256, bytes }), { storageKey: computeBlobStorageKey({ workspaceId, sha256 }), written: true });
  assert.equal((await blobs.putIfAbsent({ workspaceId, sha256, bytes: new Uint8Array([9]) })).written, false);
  assert.deepEqual(calls.filter((c) => c.op === "put").map((c) => c.options), [{ ifAbsent: true }, { ifAbsent: true }]);
});

test("get/sizeOf/exists/remove, with absence mapped to the port's contract", async () => {
  const { store } = fakeObjectStore();
  const blobs = blobStoreFromObjectStore({ store });
  const { storageKey } = await blobs.put({ workspaceId, sha256, bytes });
  assert.deepEqual(await blobs.get({ storageKey }), bytes);
  assert.equal(await blobs.sizeOf!({ storageKey }), 3);
  assert.equal(await blobs.exists({ storageKey }), true);
  await blobs.remove({ storageKey });
  await blobs.remove({ storageKey });
  assert.equal(await blobs.exists({ storageKey }), false);
  assert.equal(await blobs.sizeOf!({ storageKey }), null);
  await assert.rejects(blobs.get({ storageKey }), new Error(`blob '${storageKey}' was not found`));
});

test("store faults propagate (never read as absence)", async () => {
  const { store } = fakeObjectStore();
  const failing: ObjectStore = { ...store, head: async () => { throw new Error("HTTP 503"); } };
  const blobs = blobStoreFromObjectStore({ store: failing });
  await assert.rejects(blobs.exists({ storageKey: "k" }), /HTTP 503/);
  await assert.rejects(blobs.sizeOf!({ storageKey: "k" }), /HTTP 503/);
});

