import assert from "node:assert/strict";
import { test } from "vitest";

import { deleteFormSubmission } from "./support/host-ports.fixture.js";
import type { FormSubmissionRepoPort, RemoveFormSubmissionFn } from "./support/repo-ports.fixture.js";

const required = { workspaceId: "ws-a", form: { id: "form-a", name: "Contact" }, submissionId: "sub-a", actor: { principalId: "owner", pluginId: "operator-tool" } };
const submission = { id: "sub-a", workspaceId: "ws-a", formDefinitionId: "form-a", data: { email: "private@example.com" }, sourceIp: "192.0.2.1", submittedAt: "2026-09-30T10:00:00Z" };
function repo(record: typeof submission | null): FormSubmissionRepoPort {
  return {
    findById: async (query) => query.workspaceId === "ws-a" && query.id === "sub-a" ? record : null,
    create: async () => assert.fail("unexpected create"), transaction: async () => assert.fail("unexpected transaction"), listByDefinition: async () => assert.fail("unexpected list"),
  };
}

for (const outcome of [{ ok: true, version: null }, { ok: false, reason: "not-found" }, { ok: false, reason: "version-changed" }] as const) {
  test(`Trash outcome ${JSON.stringify(outcome)} is forwarded, with exact privacy-safe display and attribution`, async () => {
    const calls: Parameters<RemoveFormSubmissionFn>[0][] = [];
    const result = await deleteFormSubmission(required, { submissionRepo: repo(submission), clock: { nowMs: () => Date.parse("2026-10-01T12:00:00Z") }, remove: async (input) => { calls.push(input); return outcome; } });
    assert.deepEqual(result, outcome.ok ? { ok: true } : outcome);
    // F2.5: remove is the injected domain boundary; route tests exercise actual Trash effects.
    assert.deepEqual(calls, [{ workspaceId: "ws-a", id: "sub-a", display: { title: "Contact", subtitle: "2026-09-30T10:00:00Z" }, at: "2026-10-01T12:00:00.000Z", expectedVersion: null, actor: { principalId: "owner", pluginId: "operator-tool" } }]);
  });
}

for (const record of [null, { ...submission, formDefinitionId: "other-form" }]) {
  test(`a ${record === null ? "missing" : "different-form"} submission cannot reach Trash`, async () => {
    assert.deepEqual(await deleteFormSubmission(required, { submissionRepo: repo(record), clock: { nowMs: () => { assert.fail("clock should not be read"); } }, remove: async () => { assert.fail("submission must not be removed"); } }), { ok: false, reason: "not-found" });
  });
}

for (const stage of ["read", "remove"] as const) {
  test(`a ${stage} storage failure propagates instead of returning a deletion receipt`, async () => {
    // F6.2/F5.5: an unexpected storage failure must never be reported as a successful deletion.
    const fault = new Error(`${stage} unavailable`);
    const submissionRepo = repo(submission);
    if (stage === "read") submissionRepo.findById = async () => { throw fault; };
    await assert.rejects(deleteFormSubmission(required, {
      submissionRepo, clock: { nowMs: () => Date.parse("2026-10-01T12:00:00Z") },
      remove: async () => { if (stage === "read") assert.fail("read failure must stop before removal"); throw fault; },
    }), (error) => error === fault);
  });
}

src/widgets/__tests__/unit/entry-payload.source:
import { widgetHostFixture } from "../support/host.fixture.js";
import assert from "node:assert/strict";
import test from "../support/test-runner.js";

import { ContentTypeAlreadyExistsError, InMemoryContentTypeRepo } from "../../../content-types/index.js";
import type { ContentTypeRecord } from "../../../content-types/index.js";
import { ensureWidgetContentTypesRegistered } from "../support/compat/entry-payload.js";
import { InMemoryOutbox } from "../support/host.fixture.js";

/**
 * S9 (web-high fix plan, 2026-09-24): two concurrent first-widget creates both see `findByKey`
 * return null in `ensureOneContentTypeRegistered`, and the loser's `registerContentType` now
 * refuses with `ContentTypeAlreadyExistsError`. The loser must treat a live row as success, and
 * only a tombstoned key as a failure.
 */
function repoWhereTheSeedCheckLosesTheRace(status: ContentTypeRecord["status"]) {
  const repo = new InMemoryContentTypeRepo();
  const seen = new Set<string>();
  const realFindByKey = repo.findByKey.bind(repo);
  // The first lookup per key is the seed's own check, taken before the winner committed.
  repo.findByKey = async (params) => {
    if (!seen.has(params.key)) {
      seen.add(params.key);
      return null;
    }
    return realFindByKey(params);
  };
  const seedWinner = async (key: string) =>
    repo.save({
      workspaceId: "ws-1",
      key,
      label: key,
      fields: [],
      version: 1,
      status,
      tombstonedAt: status === "tombstone" ? "2026-09-24T00:00:00.000Z" : null,
    } as ContentTypeRecord);
  return { repo, seedWinner };
}

function seedDeps(contentTypeRepo: InMemoryContentTypeRepo) {
  let n = 0;
  return {
    host: widgetHostFixture,
    contentTypeRepo,
    clock: { nowMs: () => Date.parse("2026-09-24T00:00:00.000Z") },
    ids: { newId: () => `id-${++n}` },
    outbox: new InMemoryOutbox(),
  };
}

test("ensureWidgetContentTypesRegistered: losing the first-create race to a live row is success", async () => {
  const { repo, seedWinner } = repoWhereTheSeedCheckLosesTheRace("active");
  await seedWinner("widget");
  await seedWinner("widget_area");

  await ensureWidgetContentTypesRegistered({ deps: seedDeps(repo), workspaceId: "ws-1" });
  for (const key of ["widget", "widget_area"]) {
    const row = await repo.findByKey({ workspaceId: "ws-1", key });
    assert.ok(row);
    assert.equal(row.status, "active");
    assert.equal(row.key, key);
  }
});

test("ensureWidgetContentTypesRegistered: a tombstoned key is still a failure", async () => {
  const { repo, seedWinner } = repoWhereTheSeedCheckLosesTheRace("tombstone");
  await seedWinner("widget");

  await assert.rejects(
    () => ensureWidgetContentTypesRegistered({ deps: seedDeps(repo), workspaceId: "ws-1" }),
    (err: unknown) => {
      assert.ok(err instanceof ContentTypeAlreadyExistsError);
      assert.equal(err.message, "content type 'widget' was permanently deleted; its key can't be reused");
      return true;
    }
  );
});

src/comments/__tests__/spam.heuristic.te.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { HeuristicSpamCheck } from "../spam.heuristic.js";
import type { CommentSubmission } from "../types.js";
import type { SpamCheckPort } from "../ports.js";

function submission(overrides: Partial<CommentSubmission> = {}): CommentSubmission {
  return {
    workspaceId: "workspace-1",
    entryId: "entry-1",
    parentId: null,
    authorName: "Visitor",
    authorEmail: null,
    authorUrl: null,
    bodyRaw: "This is a normal, thoughtful comment about the article.",
    authorPrincipalId: null,
    ingressContext: {},
    ...overrides,
  };
}

test("a normal comment scores low and is not flagged as spam", async () => {
  const check = new HeuristicSpamCheck();
  const verdict = await check.check(submission());
  assert.equal(verdict.isSpam, false);
  assert.ok(verdict.score < 0.5);
  assert.equal(verdict.provider, "heuristic");
});

test("a link-heavy body scores high", async () => {
  const check = new HeuristicSpamCheck();
  const verdict = await check.check(
    submission({ bodyRaw: "check https://a.com https://b.com https://c.com https://d.com" })
  );
  assert.equal(verdict.score, 0.6);
  assert.equal(verdict.isSpam, true);
});

test("a body with spam keywords scores high and is flagged", async () => {
  const check = new HeuristicSpamCheck();
  const verdict = await check.check(submission({ bodyRaw: "buy cheap viagra and cialis now, click here now" }));
  assert.equal(verdict.isSpam, true);
  assert.ok(verdict.score >= 0.5);
});

test("a short body with a link scores higher than the same short body without one", async () => {
  const check = new HeuristicSpamCheck();
  const withoutLink = await check.check(submission({ bodyRaw: "nice!" }));
  const withLink = await check.check(submission({ bodyRaw: "nice! https://x.com" }));
  assert.ok(withLink.score > withoutLink.score);
});

test("report() is a documented no-op that does not throw", async () => {
  // Typed as the port: callers reach report() through SpamCheckPort, whose signature takes the input.
  const check: SpamCheckPort = new HeuristicSpamCheck();
  await assert.doesNotReject(() =>
    check.report!({
      workspaceId: "workspace-1",
      comment: {} as never,
      verdict: "spam",
    })
  );
});

test("long bodies add risk only beyond 4000 characters and only with a link or spam keyword", async () => {
  const check = new HeuristicSpamCheck();
  for (const signal of ["", "https://x.com ", "casino "]) {
    const atThreshold = signal + "x".repeat(4000 - signal.length);
    const before = await check.check(submission({ bodyRaw: atThreshold }));
    const after = await check.check(submission({ bodyRaw: atThreshold + "x" }));
    const baseScore = signal === "casino " ? 0.35 : 0;
    assert.equal(before.score, baseScore);
    assert.equal(after.score, signal ? baseScore + 0.2 : 0);
    assert.equal(before.isSpam, false);
    assert.equal(after.isSpam, signal === "casino ");
  }
});

