src/forms/delivery/__tests__/retry-polic.source:
/**
 * @file Unit tests for the delivery retry policy the outbox resolver hands to the worker (contract §4).
 */
import { describe, expect, test } from "vitest";
import { FormDeliveryError, formDeliveryRetryPolicy } from "../index.js";

const hostBackoff = ({ attempts }: { attempts: number; random: () => number }) => attempts * 10_000;
const policy = formDeliveryRetryPolicy({ backoffMs: hostBackoff, maxAttempts: 8 });
const random = () => 0.5;

describe("cap", () => {
  test("uses the host's maxAttempts", () => {
    expect(policy.maxAttempts).toBe(8);
  });
});

describe("retryable", () => {
  test("an explicit non-retryable delivery error is terminal at once", () => {
    expect(policy.retryable({ error: new FormDeliveryError({ code: "authorization-required", retryable: false }) })).toBe(false);
  });

  test("a retryable delivery error retries", () => {
    expect(policy.retryable({ error: new FormDeliveryError({ code: "rate-limited", retryable: true }) })).toBe(true);
  });

  test("any other error, such as a worker timeout, retries", () => {
    expect(policy.retryable({ error: new Error("delivery timed out after 60000ms") })).toBe(true);
  });
});

describe("backoffMs", () => {
  test("passes attempts and randomness to the host curve", () => {
    const seen: Array<{ attempts: number; random: () => number }> = [];
    const recording = formDeliveryRetryPolicy({ backoffMs: input => { seen.push(input); return 1; }, maxAttempts: 8 });
    recording.backoffMs({ attempts: 3, random, error: new Error("x") });
    expect(seen).toEqual([{ attempts: 3, random }]);
  });

  test("uses the host backoff when the error carries no retry hint", () => {
    expect(policy.backoffMs({ attempts: 2, random, error: new FormDeliveryError({ code: "delivery-failed", retryable: true }) })).toBe(20_000);
  });

  test("uses the host backoff for a non-delivery error", () => {
    expect(policy.backoffMs({ attempts: 2, random, error: new Error("timeout") })).toBe(20_000);
  });

  test("a longer adapter retryAfterMs lengthens the wait", () => {
    const error = new FormDeliveryError({ code: "rate-limited", retryable: true, retryAfterMs: 90_000 });
    expect(policy.backoffMs({ attempts: 2, random, error })).toBe(90_000);
  });

  test("a shorter adapter retryAfterMs never shortens the host backoff", () => {
    const error = new FormDeliveryError({ code: "rate-limited", retryable: true, retryAfterMs: 0 });
    expect(policy.backoffMs({ attempts: 2, random, error })).toBe(20_000);
  });

  test("an adapter cannot push the wait past the one-hour clamp", () => {
    const error = new FormDeliveryError({ code: "rate-limited", retryable: true, retryAfterMs: 86_400_000 });
    expect(policy.backoffMs({ attempts: 1, random, error })).toBe(3_600_000);
  });
});

src/entries/__tests__/lifecycle-dispatch.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import { ENTRY_LIFECYCLE_OPS, parseEntryLifecycleOp } from "../lifecycle-dispatch.js";
import { InMemoryEntryRepo } from "../repo.memory.js";
import type { EntryRecord } from "../types.js";

/**
 * @file Each entry of the closed entry-lifecycle dispatch table runs its own status transition
 * with the dispatcher's deps and input threaded through.
 */

const NOW = "2026-07-15T00:00:00.000Z";

async function dispatchHarness(status: EntryRecord["status"]) {
  const entryRepo = new InMemoryEntryRepo();
  await entryRepo.save({
    id: "entry-1", workspaceId: "ws-1", type: "recipe", slug: "chili", status, title: "Chili",
    fieldsJson: { ext: { site: {} } }, bodyJson: null, publishedAt: null, createdAt: "2026-07-01T00:00:00.000Z", updatedAt: "2026-07-01T00:00:00.000Z", version: 2,
  });
  const events: unknown[] = [];
  const deps = {
    entryRepo,
    contentTypeRepo: { findByKey: async () => ({ workspaceId: "ws-1", key: "recipe", status: "active" as const, fields: [] }) },
    clock: { nowMs: () => Date.parse(NOW) },
    authorize: async () => ({ allowed: true, reason: "matched" }),
    outbox: { enqueue: async (event: unknown) => { events.push(event); } },
  };
  return { entryRepo, deps, events };
}

function dispatch(op: string, deps: Awaited<ReturnType<typeof dispatchHarness>>["deps"]) {
  const parsed = parseEntryLifecycleOp({ op });
  assert.ok(parsed, `'${op}' must parse`);
  return ENTRY_LIFECYCLE_OPS[parsed]({ deps, input: { workspaceId: "ws-1", actorId: "user-1", id: "entry-1", expectedVersion: 2 } });
}

test("dispatching 'publish' flips draft -> published, stamps publishedAt, and enqueues entry.published", async () => {
  const h = await dispatchHarness("draft");

  const result = await dispatch("publish", h.deps);

  assert.equal(result.ok, true);
  if (!result.ok) return;
  assert.equal(result.value.entry.status, "published");
  assert.equal(result.value.entry.publishedAt, NOW);
  assert.equal((await h.entryRepo.findById({ workspaceId: "ws-1", id: "entry-1" }))?.version, 3);
  assert.deepEqual(h.events, [{ name: "entry.published", payload: { workspaceId: "ws-1", entryId: "entry-1" } }]);
});

test("dispatching 'unpublish' flips published -> unpublished and enqueues entry.unpublished", async () => {
  const h = await dispatchHarness("published");

  const result = await dispatch("unpublish", h.deps);

  assert.equal(result.ok, true);
  if (!result.ok) return;
  assert.equal(result.value.entry.status, "unpublished");
  assert.equal((await h.entryRepo.findById({ workspaceId: "ws-1", id: "entry-1" }))?.status, "unpublished");
  assert.deepEqual(h.events, [{ name: "entry.unpublished", payload: { workspaceId: "ws-1", entryId: "entry-1" } }]);
});

