import assert from "node:assert/strict";
import { test } from "vitest";

import { registerContentType } from "../write-service.js";

/**
 * @file every Collections route/tool is gated by exactly one of
 * `admin.collections.read` (read-class operations) or `admin.collections.manage` (mutating
 * operations).
 *
 * Covers: (read-only principal denied on a mutating call), (read-only principal
 * allowed on a read call — asserted here at the write-side negative case; the positive read case
 * is exercised implicitly by every other unit test's use of `alwaysAllow` for read-only actions).
 * See docs/decisions/DR-001-safe-schema-and-index-transitions.md.
 */

const NOW = "2026-07-15T00:00:00.000Z";
const clock = { nowMs: () => Date.parse(NOW)};
let idCounter = 0;
const ids = { newId: () => `ct-perm-${++idCounter}` };

function fakeRepo() {
  const rows: unknown[] = [];
  return {
    rows,
    save: async (row: unknown) => {
      rows.push(row);
    },
    appendRevision: async () => undefined,
    findByKey: async () => null,
    transaction: async <T>({ fn }: { fn: () => Promise<T> }) => fn(),
  };
}

function fakeIndexProvisioner() {
  // `applyFieldIndexTransitions` is a no-op rather than absent: this suite only exercises the
  // register path, which never calls it, but the package typechecks its tests (the host this was
  // ported from did not), so the fake has to satisfy the whole `IndexProvisionerPort`.
  return {
    provisionIndexesForNewContentType: async () => undefined,
    applyFieldIndexTransitions: async () => undefined,
  };
}

const outbox = { enqueue: async () => undefined };

test("AC-36: a principal holding only admin.collections.read is rejected FORBIDDEN when it attempts a content-type create/update/lifecycle call", async () => {
  const readOnlyAuthorize = async (params: { permission: string }) => ({
    allowed: params.permission === "admin.collections.read",
    reason: params.permission === "admin.collections.read" ? "matched" : "insufficient_permission",
  });
  const repo = fakeRepo();

  const result = await registerContentType({
    deps: { repo, clock, ids, authorize: readOnlyAuthorize, indexProvisioner: fakeIndexProvisioner(), outbox },
    input: { workspaceId: "ws-1", actorId: "read-only-user", key: "recipe", label: "Recipe", fields: [{ name: "a", kind: "text", required: false, queryable: false }] },
  });

  assert.equal(result.ok, false);
  assert.equal(repo.rows.length, 0);
});

src/widgets/__tests__/unit/entry-payload.source:
import assert from "node:assert/strict";
import { test } from "vitest";

import {
  buildWidgetAreaFieldsJson,
  buildWidgetInstanceFieldsJson,
  parseWidgetAreaPayload,
  parseWidgetInstancePayload,
} from "../../index.js";

/**
 * @file The `fieldsJson.ext.<owner>.payload` envelope a widget instance / `widget_area` entry is
 * stored in — round trip and every malformed-envelope refusal, through the `widgets` public barrel.
 * A malformed row must fail loudly with a message naming what is missing, never parse as empty.
 */

test("a widget instance payload round-trips through its own ext.widget envelope", () => {
  const payload = { widgetType: "text" as const, config: { body: "hi" }, status: "active" as const };
  const fieldsJson = buildWidgetInstanceFieldsJson({ payload });

  assert.deepEqual(fieldsJson, { ext: { widget: { payload: JSON.stringify(payload) } } });
  assert.deepEqual(parseWidgetInstancePayload({ fieldsJson }), payload);
});

test("a widget_area payload is stored under ext.widgets and is not readable as a widget instance", () => {
  const payload = { regionKey: "sidebar", doc: { schemaVersion: 1 as const, placements: [] } };
  const fieldsJson = buildWidgetAreaFieldsJson({ payload });

  assert.deepEqual(parseWidgetAreaPayload({ fieldsJson }), payload);
  assert.throws(() => parseWidgetInstancePayload({ fieldsJson }), /missing fields\.ext\.widget\.payload/);
});

test("a fieldsJson that is not a plain object is refused as malformed", () => {
  for (const fieldsJson of [null, "payload", 42, ["ext"]]) {
    assert.throws(() => parseWidgetInstancePayload({ fieldsJson }), { message: "widgets: malformed fieldsJson (expected an object)" });
  }
});

test("a fieldsJson object without an ext bag is refused as malformed", () => {
  for (const fieldsJson of [{}, { ext: "nope" }, { ext: [] }]) {
    assert.throws(() => parseWidgetAreaPayload({ fieldsJson }), { message: "widgets: malformed fieldsJson (missing ext)" });
  }
});

test("an ext bag whose owner payload is missing or not a string is refused, naming the owner", () => {
  for (const fieldsJson of [{ ext: {} }, { ext: { widgets: [] } }, { ext: { widgets: { payload: 1 } } }]) {
    assert.throws(() => parseWidgetAreaPayload({ fieldsJson }), { message: "widgets: malformed fieldsJson (missing fields.ext.widgets.payload)" });
  }
});

src/listing/__tests__/paths.test.ts.source:
import { describe, expect, it } from 'vitest';
import { LISTING_AFTER_MAX } from '../batch.js';
import { LISTING_KEY_MAX, listingBatchPath, parseListingBatchPath } from '../paths.js';

describe('listingBatchPath', () => {
  it('strips every trailing slash from the page path', () => {
    expect(listingBatchPath({ pagePath: '/blog//', key: 1, after: 0 })).toBe('/blog/_more/1/0');
  });
});

describe('parseListingBatchPath bounds', () => {
  it('accepts the highest key and cursor', () => {
    expect(parseListingBatchPath({ path: `/_more/${LISTING_KEY_MAX}/${LISTING_AFTER_MAX}` })).toEqual({ pagePath: '/', key: LISTING_KEY_MAX, after: LISTING_AFTER_MAX });
  });

  it('refuses a key one past LISTING_KEY_MAX', () => {
    expect(parseListingBatchPath({ path: `/_more/${LISTING_KEY_MAX + 1}/0` })).toBeUndefined();
  });

  it('refuses a cursor one past LISTING_AFTER_MAX', () => {
    expect(parseListingBatchPath({ path: `/_more/1/${LISTING_AFTER_MAX + 1}` })).toBeUndefined();
  });

  it('normalizes a zero-padded cursor instead of refusing it, so two URLs name one batch (reported, not fixed)', () => {
    expect(parseListingBatchPath({ path: '/blog/_more/1/012' })).toEqual({ pagePath: '/blog', key: 1, after: 12 });
  });
});

describe('parseListingBatchPath page segments', () => {
  it('refuses a single-dot segment', () => {
    expect(parseListingBatchPath({ path: '/./_more/1/0' })).toBeUndefined();
  });

  it('refuses a _more segment inside the page path', () => {
    expect(parseListingBatchPath({ path: '/_more/_more/1/0' })).toBeUndefined();
  });

  it('refuses a reserved page that is the first segment on its own', () => {
    expect(parseListingBatchPath({ path: '/api/_more/1/0' })).toBeUndefined();
  });

  it('accepts a reserved word below the first segment', () => {
    expect(parseListingBatchPath({ path: '/blog/admin/_more/1/0' })).toEqual({ pagePath: '/blog/admin', key: 1, after: 0 });
  });

  it('accepts a first segment that only starts with a reserved word', () => {
    expect(parseListingBatchPath({ path: '/apis/_more/1/0' })).toEqual({ pagePath: '/apis', key: 1, after: 0 });
  });

  it('accepts dots inside a segment', () => {
    expect(parseListingBatchPath({ path: '/v1.2/_more/1/0.json' })).toEqual({ pagePath: '/v1.2', key: 1, after: 0, format: 'json' });
  });
});

