src/forms/__tests__/checkbox-authored-va.source:
import { describe, expect, it } from "vitest";
import { validateSubmissionPayload, validateFieldDescriptors } from "../forms.js";
import type { FieldDescriptor, FormDefinitionRecord } from "../types.js";

describe("authored checkbox values", () => {
  const definition = { fields: [{ id: "consent", label: "Consent", type: "checkbox", required: true, checkboxValue: "yes" }] } as FormDefinitionRecord;
  it("persists the posted string rather than coercing it to a boolean", () => {
    expect(validateSubmissionPayload({ definition, body: { consent: "yes" } })).toEqual({ valid: true, data: { consent: "yes" } });
  });
  it("preserves an explicitly authored empty value and still rejects an omitted required box", () => {
    expect(validateSubmissionPayload({ definition: { ...definition, fields: [{ ...definition.fields[0]!, checkboxValue: "" }] }, body: { consent: "" } })).toEqual({ valid: true, data: { consent: "" } });
    expect(validateSubmissionPayload({ definition, body: {} })).toEqual({ valid: false, fieldErrors: [{ field: "consent", reason: "required" }] });
  });
  it("keeps the native default boolean and refuses arrays/objects", () => {
    const native = { ...definition, fields: definition.fields.map(({ checkboxValue: _, ...field }) => field) };
    expect(validateSubmissionPayload({ definition: native, body: { consent: "on" } })).toEqual({ valid: true, data: { consent: true } });
    for (const consent of [["yes"], { value: "yes" }]) {
      expect(validateSubmissionPayload({ definition, body: { consent } })).toEqual({ valid: false, fieldErrors: [{ field: "consent", reason: "must be a boolean" }] });
    }
  });
  it("rejects invalid authoring metadata instead of widening non-checkbox submission types", () => {
    for (const field of [{ ...definition.fields[0], type: "text" }, { ...definition.fields[0], checkboxValue: null }]) {
      expect(validateFieldDescriptors({ fields: [field as FieldDescriptor] })).toEqual({ valid: false, fieldErrors: [
        { field: "consent", reason: "checkboxValue must be a string on a checkbox field" },
      ] });
    }
  });
});

src/trash/__tests__/cursor.test.ts.source:
import assert from "node:assert/strict";
import { test } from "vitest";
import { decodeTrashCursor, encodeTrashCursor } from "../cursor.js";

// F4.1: literal wire bytes, not a round trip alone, pin encoding and separator.
// PARITY
test("cursor uses UTF-8, NUL separator and unpadded URL-safe base64", () => {
  assert.equal(encodeTrashCursor({ trashedAt: "at", id: "id" }), "YXQAaWQ");
  assert.deepEqual(decodeTrashCursor({ cursor: "YXQAaWQ" }), { trashedAt: "at", id: "id" });
  assert.deepEqual(decodeTrashCursor({ cursor: "YXQA5pel5pys" }), { trashedAt: "at", id: "日本" });
  assert.equal(encodeTrashCursor({ trashedAt: "at", id: "日本" }), "YXQA5pel5pys");
});

// F1.1/F7.7: generated round trips supplement the literal wire-format oracle above.
// PARITY
test("generated nonempty Unicode cursor fields round-trip without losing either identity", () => {
  let seed = 810;
  const alphabet = ["a", "Z", "9", "-", "_", "日", "é", "😀"];
  const field = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    const length = 1 + seed % 24;
    let value = "";
    for (let n = 0; n < length; n++) {
      seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
      value += alphabet[(seed >>> 16) % alphabet.length];
    }
    return value;
  };
  for (let n = 0; n < 100; n++) {
    const input = { trashedAt: field(), id: field() };
    const cursor = encodeTrashCursor(input);
    assert.match(cursor, /^[A-Za-z0-9_-]+$/);
    assert.deepEqual(decodeTrashCursor({ cursor: cursor }), input);
  }
});

// PARITY
test("missing, malformed and empty-sided cursors restart pagination without throwing", () => {
  for (const input of [undefined, null, "", "!not-base64!", "bm8tc2VwYXJhdG9y", "AGlk", "YXQA"]) {
    assert.equal(decodeTrashCursor({ cursor: input }), null, String(input));
  }
});

test("a non-string cursor (an untyped query parser turning ?cursor[a]=1 into an object) restarts pagination instead of throwing", () => {
  const fromUntypedQuery = { a: "1" } as unknown as string;
  assert.equal(decodeTrashCursor({ cursor: fromUntypedQuery }), null);
});

